	case hSep:
		for i, x := range d.xs {
			if i > 0 {
				w++
			}
			w += x.flatWidth()
		}
	case hNest:
		w = d.a.flatWidth()
	case hEmpty:
		w = 0
	}
	d.fw = w
	return w
}

func (d *hdoc) writeFlat(sb *strings.Builder) {
	switch d.kind {
	case hText:
		sb.WriteString(d.s)
	case hBeside:
		d.a.writeFlat(sb)
		if d.space {
			sb.WriteByte(' ')
		}
		d.b.writeFlat(sb)
	case hSep:
		for i, x := range d.xs {
			if i > 0 {
				sb.WriteByte(' ')
			}
			x.writeFlat(sb)
		}
	case hNest:
		d.a.writeFlat(sb)
	}
}

// lead returns width up to first decision point, and whether there is one
func (d *hdoc) lead() (int, bool) {
	if d.ld != 0 {
		return d.lw, d.ld == 2
	}
	var w int
	var dec bool
	switch d.kind {
	case hText:
		w = d.w
	case hBeside:
		la, da := d.a.lead()
		if da {
			w, dec = la, true
		} else {
			lb, db := d.b.lead()
			w = la + lb
			if d.space {
				w++
			}
			dec = db
		}
	case hSep:
		w, _ = d.xs[0].lead()
		dec = true
	case hNest:
		w, dec = d.a.lead()
	}
	d.lw = w
	if dec {
		d.ld = 2
	} else {
		d.ld = 1
	}
	return w, dec
}

type hcont struct {
	stop  bool
	d     *hdoc
	space bool
	next  *hcont
}

var hStop = &hcont{stop: true}

func leadCont(k *hcont) int {
	total := 0
	for k != nil {
		if k.stop {
			return total
		}
		w, dec := k.d.lead()
		if k.space {
			total++
		}
		total += w
		if dec {
			return total
		}
		k = k.next
	}
	return total
}

type hrender struct {
	sb            strings.Builder
	col           int
	lineIndent    int
	atLineStart   bool
	pendingIndent int
	lines         int
	lineLen       int
	ribbon        int
}

func (r *hrender) emit(s string, w int) {
	if r.atLineStart {
		r.sb.WriteString(strings.Repeat(" ", r.pendingIndent))
		r.col = r.pendingIndent
		r.lineIndent = r.pendingIndent
		r.atLineStart = false
	}
	r.sb.WriteString(s)
	r.col += w
}

func (r *hrender) curCol() int {
	if r.atLineStart {
		return r.pendingIndent
	}
	return r.col
}

func (r *hrender) newline(indent int) {
	r.sb.WriteByte('\n')
	r.lines++
	r.atLineStart = true
	r.pendingIndent = indent
}

func (r *hrender) render(d *hdoc, k *hcont) {
	switch d.kind {
	case hEmpty:
	case hText:
		r.emit(d.s, d.w)
	case hNest:
		r.render(d.a, k)
	case hBeside:
		r.render(d.a, &hcont{d: d.b, space: d.space, next: k})
		if d.space {
			r.emit(" ", 1)
		}
		r.render(d.b, k)
	case hSep:
		startCol := r.curCol()
		linesBefore := r.lines
		r.render(stripNestFirst(d.xs[0]), &hcont{stop: true, next: k})
		horizontal := false
		if r.lines == linesBefore {
			look := 0
			for _, x := range d.xs[1:] {
				look += 1 + x.flatWidth()
			}
			look += leadCont(k)
			lineText := r.col - r.lineIndent + look
			lim := r.lineLen - r.lineIndent
			if r.ribbon < lim {
				lim = r.ribbon
			}
			horizontal = lineText <= lim
		}
		if horizontal {
			var sb strings.Builder
			for _, x := range d.xs[1:] {
				sb.WriteByte(' ')
				x.writeFlat(&sb)
			}
			s := sb.String()
			r.emit(s, len([]rune(s)))
		} else {
			n := len(d.xs)
			for i := 1; i < n; i++ {
				x := d.xs[i]
				off := 0
				for x.kind == hNest {
					off += x.k
					x = x.a
				}
				target := startCol + off
				if !r.atLineStart && target > r.col {
					r.emit(strings.Repeat(" ", target-r.col), target-r.col)
				} else {
					r.newline(target)
				}
				var kk *hcont
				if i < n-1 {
					kk = hStop
				} else {
					kk = k
				}
				r.render(x, kk)
			}
		}
	}
}

func stripNestFirst(d *hdoc) *hdoc {
	// nests on the first element of a sep beside text are ignored
	return stripNest(d)
}

func renderHughes(d *hdoc, lineLen int) string {
	ribbon := int(math.RoundToEven(float64(lineLen) / 1.2))
	r := &hrender{lineLen: lineLen, ribbon: ribbon, atLineStart: true}
	r.render(d, nil)
	return r.sb.String()
}
EOF

