func pCon(name string, args ...*pval) *pval { return &pval{kind: vCon, name: name, args: args} }
func pList(xs []*pval) *pval              { return &pval{kind: vList, args: xs} }
func pTuple(xs ...*pval) *pval            { return &pval{kind: vTuple, args: xs} }
func pStr(s string) *pval                 { return &pval{kind: vLit, lit: haskellShowString(s)} }
func pInt(n int) *pval {
	if n < 0 {
		return &pval{kind: vNeg, args: []*pval{{kind: vLit, lit: strconv.Itoa(-n)}}}
	}
	return &pval{kind: vLit, lit: strconv.Itoa(n)}
}
func pFloat(f float64) *pval {
	if f < 0 {
		return &pval{kind: vNeg, args: []*pval{{kind: vLit, lit: haskellShowDouble(-f)}}}
	}
	return &pval{kind: vLit, lit: haskellShowDouble(f)}
}

var asciiTab = []string{"NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL",
	"BS", "HT", "LF", "VT", "FF", "CR", "SO", "SI",
	"DLE", "DC1", "DC2", "DC3", "DC4", "NAK", "SYN", "ETB",
	"CAN", "EM", "SUB", "ESC", "FS", "GS", "RS", "US", "SP"}

func haskellShowString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	rs := []rune(s)
	for i, c := range rs {
		var next rune = -1
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch {
		case c == '"':
			sb.WriteString("\\\"")
		case c == '\\':
			sb.WriteString("\\\\")
		case c > 0x7f:
			sb.WriteString("\\" + strconv.Itoa(int(c)))
			if next >= '0' && next <= '9' {
				sb.WriteString("\\&")
			}
		case c == 0x7f:
			sb.WriteString("\\DEL")
		case c >= ' ':
			sb.WriteRune(c)
		case c == '\a':
			sb.WriteString("\\a")
		case c == '\b':
			sb.WriteString("\\b")
		case c == '\f':
			sb.WriteString("\\f")
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\r':
			sb.WriteString("\\r")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\v':
			sb.WriteString("\\v")
		case c == 0x0e:
			sb.WriteString("\\SO")
			if next == 'H' {
				sb.WriteString("\\&")
			}
		default:
			sb.WriteString("\\" + asciiTab[c])
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func haskellShowDouble(f float64) string {
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	if f == 0 {
		return "0.0"
	}
	// shortest digits
	e := strconv.FormatFloat(f, 'e', -1, 64) // d.ddddde±XX
	mant, expS, _ := strings.Cut(e, "e")
	exp, _ := strconv.Atoi(expS)
	digits := strings.Replace(mant, ".", "", 1)
	// value = 0.digits * 10^(exp+1)
	ex := exp + 1
	if f >= 0.1 && f < 1e7 {
		if ex <= 0 {
			return "0." + strings.Repeat("0", -ex) + digits
		}
		if ex >= len(digits) {
			return digits + strings.Repeat("0", ex-len(digits)) + ".0"
		}
		return digits[:ex] + "." + digits[ex:]
	}
	rest := digits[1:]
	if rest == "" {
		rest = "0"
	}
	return digits[:1] + "." + rest + "e" + strconv.Itoa(ex-1)
}

func isAtom(v *pval) bool {
	switch v.kind {
	case vCon:
		return len(v.args) == 0
	case vNeg:
		return false
	}
	return true
}

func ppBlock(open, close string, ds []*hdoc) *hdoc {
	if len(ds) == 0 {
		return htext(open + close)
	}
	var xs []*hdoc
	xs = append(xs, hbeside(htext(open), ds[0], true))
	for _, d := range ds[1:] {
		xs = append(xs, hbeside(htext(","), d, true))
	}
	xs = append(xs, htext(close))
	return hsepDocs(xs)
}

func ppValue(v *pval) *hdoc {
	switch v.kind {
	case vCon:
		if len(v.args) == 0 {
			return htext(v.name)
		}
		var as []*hdoc
		for _, a := range v.args {
			as = append(as, ppAtom(a))
		}
		return hhang(htext(v.name), 2, hsepDocs(as))
	case vRec:
		var fs []*hdoc
		for _, f := range v.fields {
			fs = append(fs, hhang(hbeside(htext(f.name), htext("="), true), 2, ppValue(f.val)))
		}
		return hhang(htext(v.name), 2, ppBlock("{", "}", fs))
	case vTuple:
		var ds []*hdoc
		for _, a := range v.args {
			ds = append(ds, ppValue(a))
		}
		return ppBlock("(", ")", ds)
	case vList:
		var ds []*hdoc
		for _, a := range v.args {
			ds = append(ds, ppValue(a))
		}
		return ppBlock("[", "]", ds)
	case vNeg:
		return hbeside(htext("-"), ppAtom(v.args[0]), false)
	default:
		return htext(v.lit)
	}
}

func ppAtom(v *pval) *hdoc {
	if isAtom(v) {
		return ppValue(v)
	}
	return hcat(htext("("), ppValue(v), htext(")"))
}

// AST -> pval

func nvAttr(a Attr) *pval {
	var cls []*pval
	for _, c := range a.Classes {
		cls = append(cls, pStr(c))
	}
	var kvs []*pval
	for _, kv := range a.KVs {
		kvs = append(kvs, pTuple(pStr(kv[0]), pStr(kv[1])))
	}
	return pTuple(pStr(a.ID), pList(cls), pList(kvs))
}

func nvInlines(xs []Inline) *pval {
	var vs []*pval
	for _, x := range xs {
		vs = append(vs, nvInline(x))
	}
	return pList(vs)
}

func nvBlocks(xs []Block) *pval {
	var vs []*pval
	for _, x := range xs {
		vs = append(vs, nvBlock(x))
	}
	return pList(vs)
}

func nvTarget(t Target) *pval { return pTuple(pStr(t.URL), pStr(t.Title)) }

func citationModeName(m CitationMode) string {
	switch m {
	case AuthorInText:
		return "AuthorInText"
	case SuppressAuthor:
		return "SuppressAuthor"
	}
	return "NormalCitation"
}

func nvInline(x Inline) *pval {
	switch v := x.(type) {
	case *Str:
		return pCon("Str", pStr(v.Text))
	case *Emph:
		return pCon("Emph", nvInlines(v.Inlines))
	case *Underline:
		return pCon("Underline", nvInlines(v.Inlines))
	case *Strong:
		return pCon("Strong", nvInlines(v.Inlines))
	case *Strikeout:
		return pCon("Strikeout", nvInlines(v.Inlines))
	case *Superscript:
		return pCon("Superscript", nvInlines(v.Inlines))
	case *Subscript:
		return pCon("Subscript", nvInlines(v.Inlines))
	case *SmallCaps:
		return pCon("SmallCaps", nvInlines(v.Inlines))
	case *Quoted:
		qt := "SingleQuote"
		if v.Type == DoubleQuote {
			qt = "DoubleQuote"
		}
		return pCon("Quoted", pCon(qt), nvInlines(v.Inlines))
	case *Cite:
		var cs []*pval
		for _, c := range v.Citations {
			cs = append(cs, &pval{kind: vRec, name: "Citation", fields: []pfield{
				{"citationId", pStr(c.ID)},
				{"citationPrefix", nvInlines(c.Prefix)},
				{"citationSuffix", nvInlines(c.Suffix)},
				{"citationMode", pCon(citationModeName(c.Mode))},
				{"citationNoteNum", pInt(c.NoteNum)},
				{"citationHash", pInt(c.Hash)},
			}})
		}
		return pCon("Cite", pList(cs), nvInlines(v.Inlines))
	case *Code:
		return pCon("Code", nvAttr(v.Attr), pStr(v.Text))
	case *Space:
		return pCon("Space")
	case *SoftBreak:
		return pCon("SoftBreak")
	case *LineBreak:
		return pCon("LineBreak")
	case *Math:
		mt := "InlineMath"
		if v.Type == DisplayMath {
			mt = "DisplayMath"
		}
		return pCon("Math", pCon(mt), pStr(v.Text))
	case *RawInline:
		return pCon("RawInline", pCon("Format", pStr(v.Format)), pStr(v.Text))
	case *Link:
		return pCon("Link", nvAttr(v.Attr), nvInlines(v.Inlines), nvTarget(v.Target))
	case *Image:
		return pCon("Image", nvAttr(v.Attr), nvInlines(v.Inlines), nvTarget(v.Target))
	case *Note:
		return pCon("Note", nvBlocks(v.Blocks))
	case *Span:
		return pCon("Span", nvAttr(v.Attr), nvInlines(v.Inlines))
	}
	panic(fmt.Sprintf("unknown inline %T", x))
}

func listStyleName(s ListNumberStyle) string {
	return [...]string{"DefaultStyle", "Example", "Decimal", "LowerRoman", "UpperRoman", "LowerAlpha", "UpperAlpha"}[s]
}

func listDelimName(d ListNumberDelim) string {
	return [...]string{"DefaultDelim", "Period", "OneParen", "TwoParens"}[d]
}

func alignName(a Alignment) string {
	return [...]string{"AlignLeft", "AlignRight", "AlignCenter", "AlignDefault"}[a]
}

func nvCaption(c Caption) *pval {
	var short *pval
	if c.HasShort {
		short = pCon("Just", nvInlines(c.Short))
	} else {
		short = pCon("Nothing")
	}
	return pCon("Caption", short, nvBlocks(c.Long))
}

func nvRows(rows []Row) *pval {
	var rs []*pval
	for _, r := range rows {
		var cs []*pval
		for _, c := range r.Cells {
			cs = append(cs, pCon("Cell", nvAttr(c.Attr), pCon(alignName(c.Align)),
				pCon("RowSpan", pInt(c.RowSpan)), pCon("ColSpan", pInt(c.ColSpan)), nvBlocks(c.Blocks)))
		}
		rs = append(rs, pCon("Row", nvAttr(r.Attr), pList(cs)))
	}
	return pList(rs)
}

func nvBlock(x Block) *pval {
	switch v := x.(type) {
	case *Plain:
		return pCon("Plain", nvInlines(v.Inlines))
	case *Para:
		return pCon("Para", nvInlines(v.Inlines))
	case *LineBlock:
		var ls []*pval
		for _, l := range v.Lines {
			ls = append(ls, nvInlines(l))
		}
		return pCon("LineBlock", pList(ls))
	case *CodeBlock:
		return pCon("CodeBlock", nvAttr(v.Attr), pStr(v.Text))
	case *RawBlock:
		return pCon("RawBlock", pCon("Format", pStr(v.Format)), pStr(v.Text))
	case *BlockQuote:
		return pCon("BlockQuote", nvBlocks(v.Blocks))
	case *OrderedList:
		var items []*pval
		for _, it := range v.Items {
			items = append(items, nvBlocks(it))
		}
		return pCon("OrderedList", pTuple(pInt(v.Attrs.Start), pCon(listStyleName(v.Attrs.Style)), pCon(listDelimName(v.Attrs.Delim))), pList(items))
	case *BulletList:
		var items []*pval
		for _, it := range v.Items {
			items = append(items, nvBlocks(it))
		}
		return pCon("BulletList", pList(items))
	case *DefinitionList:
		var items []*pval
		for _, it := range v.Items {
			var defs []*pval
			for _, d := range it.Defs {
				defs = append(defs, nvBlocks(d))
			}
			items = append(items, pTuple(nvInlines(it.Term), pList(defs)))
		}
		return pCon("DefinitionList", pList(items))
	case *Header:
		return pCon("Header", pInt(v.Level), nvAttr(v.Attr), nvInlines(v.Inlines))
	case *HorizontalRule:
		return pCon("HorizontalRule")
	case *Table:
		var specs []*pval
		for _, cs := range v.ColSpecs {
			var w *pval
			if cs.HasWidth {
				w = pCon("ColWidth", pFloat(cs.Width))
			} else {
				w = pCon("ColWidthDefault")
			}
			specs = append(specs, pTuple(pCon(alignName(cs.Align)), w))
		}
		var bodies []*pval
		for _, b := range v.Bodies {
			bodies = append(bodies, pCon("TableBody", nvAttr(b.Attr), pCon("RowHeadColumns", pInt(b.RowHeadColumns)), nvRows(b.Head), nvRows(b.Body)))
		}
		return pCon("Table", nvAttr(v.Attr), nvCaption(v.Caption), pList(specs),
			pCon("TableHead", nvAttr(v.Head.Attr), nvRows(v.Head.Rows)),
			pList(bodies),
			pCon("TableFoot", nvAttr(v.Foot.Attr), nvRows(v.Foot.Rows)))
	case *Figure:
		return pCon("Figure", nvAttr(v.Attr), nvCaption(v.Caption), nvBlocks(v.Blocks))
	case *Div:
		return pCon("Div", nvAttr(v.Attr), nvBlocks(v.Blocks))
	}
	panic(fmt.Sprintf("unknown block %T", x))
}

func sortedKeys(m map[string]MetaValue) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func nvMetaMap(m map[string]MetaValue) *pval {
	var kvs []*pval
	for _, k := range sortedKeys(m) {
		kvs = append(kvs, pTuple(pStr(k), nvMeta(m[k])))
	}
	return pCon("fromList", pList(kvs))
}

func nvMeta(m MetaValue) *pval {
	switch v := m.(type) {
	case *MetaMap:
		return pCon("MetaMap", nvMetaMap(v.Map))
	case *MetaList:
		var xs []*pval
		for _, x := range v.Items {
			xs = append(xs, nvMeta(x))
		}
		return pCon("MetaList", pList(xs))
	case *MetaBool:
		if v.Bool {
			return pCon("MetaBool", pCon("True"))
		}
		return pCon("MetaBool", pCon("False"))
	case *MetaString:
		return pCon("MetaString", pStr(v.Text))
	case *MetaInlines:
		return pCon("MetaInlines", nvInlines(v.Inlines))
	case *MetaBlocks:
		return pCon("MetaBlocks", nvBlocks(v.Blocks))
	}
	panic("unknown meta")
}

func writeNative(doc *Pandoc, opts *WriterOptions) string {
	var v *pval
	if opts.Standalone {
		meta := &pval{kind: vRec, name: "Meta", fields: []pfield{{"unMeta", nvMetaMap(doc.Meta)}}}
		v = pCon("Pandoc", meta, nvBlocks(doc.Blocks))
	} else {
		v = nvBlocks(doc.Blocks)
	}
	return renderHughes(ppValue(v), opts.Columns) + "\n"
}
EOF"}

