		w.tagc("DefinitionList", func() {
			w.raw("[")
			for i, it := range v.Items {
				if i > 0 {
					w.raw(",")
				}
				w.raw("[")
				w.inlines(it.Term)
				w.raw(",[")
				for j, d := range it.Defs {
					if j > 0 {
						w.raw(",")
					}
					w.blocks(d)
				}
				w.raw("]]")
			}
			w.raw("]")
		})
	case *Header:
		w.tagc("Header", func() {
			w.raw("[" + strconv.Itoa(v.Level) + ",")
			w.attr(v.Attr)
			w.raw(",")
			w.inlines(v.Inlines)
			w.raw("]")
		})
	case *HorizontalRule:
		w.tag("HorizontalRule")
	case *Table:
		w.tagc("Table", func() {
			w.raw("[")
			w.attr(v.Attr)
			w.raw(",")
			w.caption(v.Caption)
			w.raw(",[")
			for i, cs := range v.ColSpecs {
				if i > 0 {
					w.raw(",")
				}
				w.raw("[")
				w.tag(alignName(cs.Align))
				w.raw(",")
				if cs.HasWidth {
					w.tagc("ColWidth", func() { w.raw(jsonDouble(cs.Width)) })
				} else {
					w.tag("ColWidthDefault")
				}
				w.raw("]")
			}
			w.raw("],[")
			w.attr(v.Head.Attr)
			w.raw(",")
			w.rows(v.Head.Rows)
			w.raw("],[")
			for i, b := range v.Bodies {
				if i > 0 {
					w.raw(",")
				}
				w.raw("[")
				w.attr(b.Attr)
				w.raw("," + strconv.Itoa(b.RowHeadColumns) + ",")
				w.rows(b.Head)
				w.raw(",")
				w.rows(b.Body)
				w.raw("]")
			}
			w.raw("],[")
			w.attr(v.Foot.Attr)
			w.raw(",")
			w.rows(v.Foot.Rows)
			w.raw("]]")
		})
	case *Figure:
		w.tagc("Figure", func() {
			w.raw("[")
			w.attr(v.Attr)
			w.raw(",")
			w.caption(v.Caption)
			w.raw(",")
			w.blocks(v.Blocks)
			w.raw("]")
		})
	case *Div:
		w.tagc("Div", func() {
			w.raw("[")
			w.attr(v.Attr)
			w.raw(",")
			w.blocks(v.Blocks)
			w.raw("]")
		})
	}
}

func (w *jw) metaMap(m map[string]MetaValue) {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	w.raw("{")
	for i, k := range keys {
		if i > 0 {
			w.raw(",")
		}
		w.str(k)
		w.raw(":")
		w.meta(m[k])
	}
	w.raw("}")
}

func (w *jw) meta(m MetaValue) {
	switch v := m.(type) {
	case *MetaMap:
		w.tagc("MetaMap", func() { w.metaMap(v.Map) })
	case *MetaList:
		w.tagc("MetaList", func() {
			w.raw("[")
			for i, x := range v.Items {
				if i > 0 {
					w.raw(",")
				}
				w.meta(x)
			}
			w.raw("]")
		})
	case *MetaBool:
		w.tagc("MetaBool", func() {
			if v.Bool {
				w.raw("true")
			} else {
				w.raw("false")
			}
		})
	case *MetaString:
		w.tagc("MetaString", func() { w.str(v.Text) })
	case *MetaInlines:
		w.tagc("MetaInlines", func() { w.inlines(v.Inlines) })
	case *MetaBlocks:
		w.tagc("MetaBlocks", func() { w.blocks(v.Blocks) })
	}
}

func writeJSON(doc *Pandoc) string {
	w := &jw{}
	w.raw(`{"pandoc-api-version":[1,23,1,2],"meta":`)
	w.metaMap(doc.Meta)
	w.raw(`,"blocks":`)
	w.blocks(doc.Blocks)
	w.raw("}")
	return w.sb.String() + "\n"
}

// ---------- JSON reader ----------

type jsonErr struct{ msg string }

func jget(v interface{}, key string) interface{} {
	if m, ok := v.(map[string]interface{}); ok {
		return m[key]
	}
	return nil
}

func jarr(v interface{}) []interface{} {
	a, _ := v.([]interface{})
	return a
}

func jstr(v interface{}) string {
	s, _ := v.(string)
	return s
}

func jint(v interface{}) int {
	f, _ := v.(float64)
	return int(f)
}

func jtag(v interface{}) string { return jstr(jget(v, "t")) }

func jAttr(v interface{}) Attr {
	a := jarr(v)
	var at Attr
	if len(a) < 3 {
		return at
	}
	at.ID = jstr(a[0])
	for _, c := range jarr(a[1]) {
		at.Classes = append(at.Classes, jstr(c))
	}
	for _, kv := range jarr(a[2]) {
		p := jarr(kv)
		if len(p) == 2 {
			at.KVs = append(at.KVs, [2]string{jstr(p[0]), jstr(p[1])})
		}
	}
	return at
}

func jInlines(v interface{}) []Inline {
	var out []Inline
	for _, x := range jarr(v) {
		if il := jInline(x); il != nil {
			out = append(out, il)
		}
	}
	return out
}

func jBlocks(v interface{}) []Block {
	var out []Block
	for _, x := range jarr(v) {
		if b := jBlock(x); b != nil {
			out = append(out, b)
		}
	}
	return out
}

func jTarget(v interface{}) Target {
	a := jarr(v)
	if len(a) < 2 {
		return Target{}
	}
	return Target{jstr(a[0]), jstr(a[1])}
}

func jInline(v interface{}) Inline {
	c := jget(v, "c")
	ca := jarr(c)
	switch jtag(v) {
	case "Str":
		return &Str{jstr(c)}
	case "Emph":
		return &Emph{jInlines(c)}
	case "Underline":
		return &Underline{jInlines(c)}
	case "Strong":
		return &Strong{jInlines(c)}
	case "Strikeout":
		return &Strikeout{jInlines(c)}
	case "Superscript":
		return &Superscript{jInlines(c)}
	case "Subscript":
		return &Subscript{jInlines(c)}
	case "SmallCaps":
		return &SmallCaps{jInlines(c)}
	case "Quoted":
		qt := SingleQuote
		if jtag(ca[0]) == "DoubleQuote" {
			qt = DoubleQuote
		}
		return &Quoted{qt, jInlines(ca[1])}
	case "Cite":
		var cs []Citation
		for _, x := range jarr(ca[0]) {
			var ct Citation
			ct.ID = jstr(jget(x, "citationId"))
			ct.Prefix = jInlines(jget(x, "citationPrefix"))
			ct.Suffix = jInlines(jget(x, "citationSuffix"))
			switch jtag(jget(x, "citationMode")) {
			case "AuthorInText":
				ct.Mode = AuthorInText
			case "SuppressAuthor":
				ct.Mode = SuppressAuthor
			default:
				ct.Mode = NormalCitation
			}
			ct.NoteNum = jint(jget(x, "citationNoteNum"))
			ct.Hash = jint(jget(x, "citationHash"))
			cs = append(cs, ct)
		}
		return &Cite{cs, jInlines(ca[1])}
	case "Code":
		return &Code{jAttr(ca[0]), jstr(ca[1])}
	case "Space":
		return &Space{}
	case "SoftBreak":
		return &SoftBreak{}
	case "LineBreak":
		return &LineBreak{}
	case "Math":
		mt := InlineMath
		if jtag(ca[0]) == "DisplayMath" {
			mt = DisplayMath
		}
		return &Math{mt, jstr(ca[1])}
	case "RawInline":
		return &RawInline{jstr(ca[0]), jstr(ca[1])}
	case "Link":
		return &Link{jAttr(ca[0]), jInlines(ca[1]), jTarget(ca[2])}
	case "Image":
		return &Image{jAttr(ca[0]), jInlines(ca[1]), jTarget(ca[2])}
	case "Note":
		return &Note{jBlocks(c)}
	case "Span":
		return &Span{jAttr(ca[0]), jInlines(ca[1])}
	}
	return nil
}

func jAlign(v interface{}) Alignment {
	switch jtag(v) {
	case "AlignLeft":
		return AlignLeft
	case "AlignRight":
		return AlignRight
	case "AlignCenter":
		return AlignCenter
	}
	return AlignDefault
}

func jCaption(v interface{}) Caption {
	a := jarr(v)
	var c Caption
	if len(a) < 2 {
		return c
	}
	if a[0] != nil {
		c.HasShort = true
		c.Short = jInlines(a[0])
	}
	c.Long = jBlocks(a[1])
	return c
}

func jRows(v interface{}) []Row {
	var rows []Row
	for _, r := range jarr(v) {
		ra := jarr(r)
		row := Row{Attr: jAttr(ra[0])}
		for _, c := range jarr(ra[1]) {
			cc := jarr(c)
			row.Cells = append(row.Cells, Cell{jAttr(cc[0]), jAlign(cc[1]), jint(cc[2]), jint(cc[3]), jBlocks(cc[4])})
		}
		rows = append(rows, row)
	}
	return rows
}

func jStyle(v interface{}) ListNumberStyle {
	switch jtag(v) {
	case "Example":
		return Example
	case "Decimal":
		return Decimal
	case "LowerRoman":
		return LowerRoman
	case "UpperRoman":
		return UpperRoman
	case "LowerAlpha":
		return LowerAlpha
	case "UpperAlpha":
		return UpperAlpha
	}
	return DefaultStyle
}

func jDelim(v interface{}) ListNumberDelim {
	switch jtag(v) {
	case "Period":
		return Period
	case "OneParen":
		return OneParen
	case "TwoParens":
		return TwoParens
	}
	return DefaultDelim
}

func jBlock(v interface{}) Block {
	c := jget(v, "c")
	ca := jarr(c)
	switch jtag(v) {
	case "Plain":
		return &Plain{jInlines(c)}
	case "Para":
		return &Para{jInlines(c)}
	case "LineBlock":
		var ls [][]Inline
		for _, l := range ca {
			ls = append(ls, jInlines(l))
		}
		return &LineBlock{ls}
	case "CodeBlock":
		return &CodeBlock{jAttr(ca[0]), jstr(ca[1])}
	case "RawBlock":
		return &RawBlock{jstr(ca[0]), jstr(ca[1])}
	case "BlockQuote":
		return &BlockQuote{jBlocks(c)}
	case "OrderedList":
		la := jarr(ca[0])
		attrs := ListAttributes{jint(la[0]), jStyle(la[1]), jDelim(la[2])}
		var items [][]Block
		for _, it := range jarr(ca[1]) {
			items = append(items, jBlocks(it))
		}
		return &OrderedList{attrs, items}
	case "BulletList":
		var items [][]Block
		for _, it := range ca {
			items = append(items, jBlocks(it))
		}
		return &BulletList{items}
	case "DefinitionList":
		var items []DefItem
		for _, it := range ca {
			p := jarr(it)
			var defs [][]Block
			for _, d := range jarr(p[1]) {
				defs = append(defs, jBlocks(d))
			}
			items = append(items, DefItem{jInlines(p[0]), defs})
		}
		return &DefinitionList{items}
	case "Header":
		return &Header{jint(ca[0]), jAttr(ca[1]), jInlines(ca[2])}
	case "HorizontalRule":
		return &HorizontalRule{}
	case "Table":
		t := &Table{Attr: jAttr(ca[0]), Caption: jCaption(ca[1])}
		for _, cs := range jarr(ca[2]) {
			p := jarr(cs)
			spec := ColSpec{Align: jAlign(p[0])}
			if jtag(p[1]) == "ColWidth" {
				spec.HasWidth = true
				spec.Width, _ = jget(p[1], "c").(float64)
			}
			t.ColSpecs = append(t.ColSpecs, spec)
		}
		th := jarr(ca[3])
		t.Head = TableHead{jAttr(th[0]), jRows(th[1])}
		for _, b := range jarr(ca[4]) {
			ba := jarr(b)
			t.Bodies = append(t.Bodies, TableBody{jAttr(ba[0]), jint(ba[1]), jRows(ba[2]), jRows(ba[3])})
		}
		tf := jarr(ca[5])
		t.Foot = TableFoot{jAttr(tf[0]), jRows(tf[1])}
		return t
	case "Figure":
		return &Figure{jAttr(ca[0]), jCaption(ca[1]), jBlocks(ca[2])}
	case "Div":
		return &Div{jAttr(ca[0]), jBlocks(ca[1])}
	}
	return nil
}

func jMeta(v interface{}) MetaValue {
	c := jget(v, "c")
	switch jtag(v) {
	case "MetaMap":
		m := map[string]MetaValue{}
		if mm, ok := c.(map[string]interface{}); ok {
			for k, x := range mm {
				m[k] = jMeta(x)
			}
		}
		return &MetaMap{m}
	case "MetaList":
		var xs []MetaValue
		for _, x := range jarr(c) {
			xs = append(xs, jMeta(x))
		}
		return &MetaList{xs}
	case "MetaBool":
		b, _ := c.(bool)
		return &MetaBool{b}
	case "MetaString":
		return &MetaString{jstr(c)}
	case "MetaInlines":
		return &MetaInlines{jInlines(c)}
	case "MetaBlocks":
		return &MetaBlocks{jBlocks(c)}
	}
	return &MetaString{""}
}

func readJSON(input string) (*Pandoc, error) {
	var v interface{}
	if err := json.Unmarshal([]byte(input), &v); err != nil {
		return nil, err
	}
	doc := &Pandoc{Meta: Meta{}}
	if a, ok := v.([]interface{}); ok {
		// old format [meta, blocks]
		if len(a) == 2 {
			if mm, ok := jget(a[0], "unMeta").(map[string]interface{}); ok {
				for k, x := range mm {
					doc.Meta[k] = jMeta(x)
				}
			}
			doc.Blocks = jBlocks(a[1])
		}
		return doc, nil
	}
	if mm, ok := jget(v, "meta").(map[string]interface{}); ok {
		for k, x := range mm {
			doc.Meta[k] = jMeta(x)
		}
	}
	doc.Blocks = jBlocks(jget(v, "blocks"))
	return doc, nil
}
EOF"}

