package main

import (
	"strings"
	"unicode"
)

// meld-append semantics of pandoc's Inlines monoid

func meldPair(x, y Inline) (Inline, bool) {
	switch a := x.(type) {
	case *Space:
		switch y.(type) {
		case *Space:
			return a, true
		case *SoftBreak:
			return y, true
		case *LineBreak:
			return y, true
		}
	case *SoftBreak:
		switch y.(type) {
		case *Space:
			return a, true
		case *SoftBreak:
			return a, true
		case *LineBreak:
			return y, true
		}
	case *LineBreak:
		switch y.(type) {
		case *Space, *SoftBreak:
			return a, true
		}
	case *Str:
		if b, ok := y.(*Str); ok {
			return &Str{a.Text + b.Text}, true
		}
	case *Emph:
		if b, ok := y.(*Emph); ok {
			return &Emph{concatInl(a.Inlines, b.Inlines)}, true
		}
	case *Underline:
		if b, ok := y.(*Underline); ok {
			return &Underline{concatInl(a.Inlines, b.Inlines)}, true
		}
	case *Strong:
		if b, ok := y.(*Strong); ok {
			return &Strong{concatInl(a.Inlines, b.Inlines)}, true
		}
	case *Subscript:
		if b, ok := y.(*Subscript); ok {
			return &Subscript{concatInl(a.Inlines, b.Inlines)}, true
		}
	case *Superscript:
		if b, ok := y.(*Superscript); ok {
			return &Superscript{concatInl(a.Inlines, b.Inlines)}, true
		}
	case *Strikeout:
		if b, ok := y.(*Strikeout); ok {
			return &Strikeout{concatInl(a.Inlines, b.Inlines)}, true
		}
	}
	return nil, false
}

func concatInl(a, b []Inline) []Inline {
	r := make([]Inline, 0, len(a)+len(b))
	r = append(r, a...)
	return append(r, b...)
}

// appendInl appends y to xs with melding at the junction
func appendInl(xs []Inline, ys ...Inline) []Inline {
	for _, y := range ys {
		if len(xs) > 0 {
			if m, ok := meldPair(xs[len(xs)-1], y); ok {
				// copy-on-write: don't mutate shared slices
				nx := make([]Inline, len(xs))
				copy(nx, xs)
				nx[len(nx)-1] = m
				xs = nx
				continue
			}
		}
		xs = append(xs, y)
	}
	return xs
}

// appendInlMut appends with meld, may mutate xs's backing array
func appendInlMut(xs []Inline, ys ...Inline) []Inline {
	for _, y := range ys {
		if len(xs) > 0 {
			if m, ok := meldPair(xs[len(xs)-1], y); ok {
				xs[len(xs)-1] = m
				continue
			}
		}
		xs = append(xs, y)
	}
	return xs
}

func catInl(parts ...[]Inline) []Inline {
	var r []Inline
	for _, p := range parts {
		for _, x := range p {
			r = appendInlMut(r, x)
		}
	}
	return r
}

func isSpaceLike(x Inline) bool {
	switch x.(type) {
	case *Space, *SoftBreak:
		return true
	}
	return false
}

func trimInlines(xs []Inline) []Inline {
	s := 0
	for s < len(xs) && isSpaceLike(xs[s]) {
		s++
	}
	e := len(xs)
	for e > s && isSpaceLike(xs[e-1]) {
		e--
	}
	return xs[s:e]
}

// textToInlines mimics B.text: splits into Str, Space, SoftBreak
func textToInlines(s string) []Inline {
	var out []Inline
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			out = append(out, &Str{cur.String()})
			cur.Reset()
		}
	}
	rs := []rune(s)
	for i := 0; i < len(rs); {
		c := rs[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			flush()
			nl := false
			for i < len(rs) && (rs[i] == ' ' || rs[i] == '\t' || rs[i] == '\n' || rs[i] == '\r') {
				if rs[i] == '\n' {
					nl = true
				}
				i++
			}
			if nl {
				out = append(out, &SoftBreak{})
			} else {
				out = append(out, &Space{})
			}
			continue
		}
		cur.WriteRune(c)
		i++
	}
	flush()
	return out
}

// stringify like pandoc's Text.Pandoc.Shared.stringify
func stringify(xs []Inline) string {
	var sb strings.Builder
	stringifyTo(&sb, xs)
	return sb.String()
}

func stringifyTo(sb *strings.Builder, xs []Inline) {
	for _, x := range xs {
		switch v := x.(type) {
		case *Str:
			sb.WriteString(v.Text)
		case *Space, *SoftBreak, *LineBreak:
			sb.WriteByte(' ')
		case *Code:
			sb.WriteString(v.Text)
		case *Math:
			sb.WriteString(v.Text)
		case *RawInline:
			if v.Format == "html" && strings.HasPrefix(v.Text, "<br") {
				sb.WriteByte(' ')
			}
		case *Emph:
			stringifyTo(sb, v.Inlines)
		case *Underline:
			stringifyTo(sb, v.Inlines)
		case *Strong:
			stringifyTo(sb, v.Inlines)
		case *Strikeout:
			stringifyTo(sb, v.Inlines)
		case *Superscript:
			stringifyTo(sb, v.Inlines)
		case *Subscript:
			stringifyTo(sb, v.Inlines)
		case *SmallCaps:
			stringifyTo(sb, v.Inlines)
		case *Quoted:
			if v.Type == SingleQuote {
				sb.WriteString("\u2018")
				stringifyTo(sb, v.Inlines)
				sb.WriteString("\u2019")
			} else {
				sb.WriteString("\u201c")
				stringifyTo(sb, v.Inlines)
				sb.WriteString("\u201d")
			}
		case *Cite:
			for _, c := range v.Citations {
				stringifyTo(sb, c.Prefix)
				stringifyTo(sb, c.Suffix)
			}
			stringifyTo(sb, v.Inlines)
		case *Link:
			stringifyTo(sb, v.Inlines)
		case *Image:
			stringifyTo(sb, v.Inlines)
		case *Span:
			stringifyTo(sb, v.Inlines)
		case *Note:
		}
	}
}

func stringifyBlocks(bs []Block) string {
	var parts []string
	for _, b := range bs {
		parts = append(parts, stringifyBlock(b))
