func parseFormatSpec(spec string) (string, *Extensions, error) {
	i := strings.IndexAny(spec, "+-")
	base := spec
	rest := ""
	if i >= 0 {
		base = spec[:i]
		rest = spec[i:]
	}
	exts := defaultExtensions(base)
	supported := map[string]bool{}
	if d, ok := formatExtensions[base]; ok {
		for _, x := range strings.Fields(d[1]) {
			supported[x] = true
		}
	}
	for len(rest) > 0 {
		op := rest[0]
		rest = rest[1:]
		j := strings.IndexAny(rest, "+-")
		name := rest
		if j >= 0 {
			name = rest[:j]
