		p.skipSpaces()
		p.newline()
		p.skipSpaces()
		return p.peek() != '\n'
	})
}

func (p *mdP) spnlTry() bool {
	return p.try(func() bool {
		p.skipSpaces()
		p.newline()
		p.skipSpaces()
		return p.peek() != '\n' || p.eof()
	})
}

func (p *mdP) text(from int) string { return string(p.s[from:p.pos]) }

// subparser over a chunk sharing state
