type mdKey struct {
	url, title string
	attr       Attr
}

type mdPos struct {
	chunk int // 0 = main input, otherwise all chunks share 1 (like pandoc's "chunk")
	line  int
	col   int
}

type mdState struct {
	keys           map[string]mdKey
	headerKeys     map[string]mdKey
	notes          map[string][]Block
	noteNumber     int
	inNote         bool
	headerIds      map[string]bool
	examples       map[string]int
	nextExample    int
	meta           Meta
	metaSet        map[string]bool
	lastStrPos     mdPos
	hasLastStr     bool
	quoteCtx       int
	allowLinks     bool
	inHtmlBlock    string
	fencedDivLevel int
	inList         bool
	exts           *Extensions
	opts           *ReaderOptions
	macros         map[string]latexMacro
	maxNest        int
	abbrevs        map[string]bool
	warnings       []string
}

type ReaderOptions struct {
	Exts                *Extensions
	Standalone          bool
	TabStop             int
	IndentedCodeClasses []string
	DefaultImageExt     string
	StripComments       bool
	TrackChanges        string
	Columns             int
}

type mdP struct {
	s     []rune
	pos   int
	st    *mdState
	chunk int
	lines []int // line start offsets
}

func newMdParser(text string, st *mdState, chunk int) *mdP {
	p := &mdP{s: []rune(text), st: st, chunk: chunk}
	p.lines = []int{0}
	for i, c := range p.s {
		if c == '\n' {
			p.lines = append(p.lines, i+1)
		}
	}
	return p
}

func (p *mdP) ext(name string) bool { return p.st.exts.On(name) }

func (p *mdP) eof() bool { return p.pos >= len(p.s) }

func (p *mdP) peek() rune {
	if p.pos >= len(p.s) {
		return 0
	}
	return p.s[p.pos]
}

func (p *mdP) peekAt(n int) rune {
	if p.pos+n >= len(p.s) || p.pos+n < 0 {
		return 0
	}
	return p.s[p.pos+n]
}

func (p *mdP) srcPos() mdPos {
	// binary search line
	lo, hi := 0, len(p.lines)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if p.lines[mid] <= p.pos {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return mdPos{p.chunk, lo + 1, p.pos - p.lines[lo] + 1}
}

func (p *mdP) column() int {
	// 0-based column
	i := p.pos - 1
	for i >= 0 && p.s[i] != '\n' {
		i--
	}
	return p.pos - i - 1
}

func (p *mdP) atLineStart() bool {
	return p.pos == 0 || p.s[p.pos-1] == '\n'
}

func (p *mdP) char(c rune) bool {
	if p.pos < len(p.s) && p.s[p.pos] == c {
		p.pos++
		return true
	}
	return false
}

func (p *mdP) str(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.s) {
		return false
	}
	for i, c := range rs {
		if p.s[p.pos+i] != c {
			return false
		}
	}
	p.pos += len(rs)
	return true
}

func (p *mdP) lookStr(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.s) {
		return false
	}
	for i, c := range rs {
		if p.s[p.pos+i] != c {
			return false
		}
	}
	return true
}

type mdSnap struct {
	pos        int
	noteNumber int
	lastStrPos mdPos
	hasLastStr bool
	quoteCtx   int
	allowLinks bool
	nextEx     int
}

func (p *mdP) save() mdSnap {
	return mdSnap{p.pos, p.st.noteNumber, p.st.lastStrPos, p.st.hasLastStr, p.st.quoteCtx, p.st.allowLinks, p.st.nextExample}
}

func (p *mdP) restore(s mdSnap) {
	p.pos = s.pos
	p.st.noteNumber = s.noteNumber
	p.st.lastStrPos = s.lastStrPos
	p.st.hasLastStr = s.hasLastStr
	p.st.quoteCtx = s.quoteCtx
	p.st.allowLinks = s.allowLinks
	p.st.nextExample = s.nextEx
}

// try runs f, restoring position/state on failure
func (p *mdP) try(f func() bool) bool {
	s := p.save()
	if f() {
		return true
	}
	p.restore(s)
	return false
}

// lookahead: run f, always restore; return result
func (p *mdP) look(f func() bool) bool {
	s := p.save()
	r := f()
	p.restore(s)
	return r
}

func isSpaceChar(c rune) bool { return c == ' ' || c == '\t' }

func (p *mdP) skipSpaces() {
	for p.pos < len(p.s) && isSpaceChar(p.s[p.pos]) {
		p.pos++
	}
}

func (p *mdP) spaceChar() bool {
	if p.pos < len(p.s) && isSpaceChar(p.s[p.pos]) {
		p.pos++
		return true
	}
	return false
}

func (p *mdP) newline() bool { return p.char('\n') }

// blankline: skipMany spaceChar >> newline
func (p *mdP) blankline() bool {
	return p.try(func() bool {
		p.skipSpaces()
		return p.newline()
	})
}

func (p *mdP) isBlankLineAhead() bool {
	i := p.pos
	for i < len(p.s) && isSpaceChar(p.s[i]) {
		i++
	}
	return i < len(p.s) && p.s[i] == '\n'
}

// blanklines: many1 blankline, returns count
func (p *mdP) blanklines() int {
	n := 0
	for p.blankline() {
		n++
	}
	return n
}

// anyLine: consume up to newline (newline consumed, not returned). fails at eof.
func (p *mdP) anyLine() (string, bool) {
	if p.eof() {
		return "", false
	}
	start := p.pos
	for p.pos < len(p.s) && p.s[p.pos] != '\n' {
		p.pos++
	}
	l := string(p.s[start:p.pos])
	if p.pos < len(p.s) {
		p.pos++
	}
	return l, true
}

// anyLineNewline: line including the newline
func (p *mdP) anyLineNewline() (string, bool) {
	l, ok := p.anyLine()
	if !ok {
		return "", false
	}
	return l + "\n", true
}

// nonindentSpaces: up to 3 spaces; fails if 4+ (like pandoc's nonindentSpaces)
func (p *mdP) nonindentSpaces() (int, bool) {
	n := 0
	for n < len(p.s)-p.pos && p.s[p.pos+n] == ' ' {
		n++
	}
	if n >= 4 {
		// pandoc: count up to tabStop-1 spaces then notFollowedBy space
		return 0, false
	}
	p.pos += n
	return n, true
}

func (p *mdP) skipNonindentSpaces() bool {
	_, ok := p.nonindentSpaces()
	return ok
}

// gobbleSpaces n: consume exactly n spaces (fails otherwise)
func (p *mdP) gobbleSpaces(n int) bool {
	if p.pos+n > len(p.s) {
		return false
	}
	for i := 0; i < n; i++ {
		if p.s[p.pos+i] != ' ' {
			return false
		}
	}
	p.pos += n
	return true
}

func (p *mdP) gobbleAtMostSpaces(n int) int {
	k := 0
	for k < n && p.pos < len(p.s) && p.s[p.pos] == ' ' {
		p.pos++
		k++
	}
	return k
}

func (p *mdP) indentSpaces() bool {
	tab := p.st.opts.TabStop
	if p.gobbleSpaces(tab) {
		return true
	}
	return p.char('\t')
}

func (p *mdP) spnl() {
	// spnl = try $ skipSpaces >> optional newline >> skipSpaces >> notFollowedBy (char '\n')
	p.try(func() bool {
		p.skipSpaces()
		p.newline()
		p.skipSpaces()
		return p.peek() != '\n'
	})
}

