		p.skipSpaces()
		return p.peek() != '\n' || p.eof()
	})
}

func (p *mdP) text(from int) string { return string(p.s[from:p.pos]) }

// subparser over a chunk sharing state
func (p *mdP) sub(text string) *mdP {
	return newMdParser(text, p.st, 1)
}

func (p *mdP) setLastStr() {
	p.st.lastStrPos = p.srcPos()
	p.st.hasLastStr = true
}

func (p *mdP) notAfterString() bool {
	if !p.st.hasLastStr {
		return true
	}
	return p.st.lastStrPos != p.srcPos()
}

