package main

import (
	"strconv"
	"strings"
)

// figure candidate paragraphs
type mdPara struct {
	Para
}

func (p *mdP) parseBlocks() []Block {
	var bs []Block
	for !p.eof() {
		b, ok := p.block()
		if !ok {
			// should not happen; consume a line as plain text
			l, _ := p.anyLine()
			bs = append(bs, &Para{textToInlines(l)})
			continue
		}
		bs = append(bs, b...)
	}
	return bs
}

func (p *mdP) block() ([]Block, bool) {
	if p.blanklines() > 0 {
		return nil, true
	}
	type bp func() ([]Block, bool)
	parsers := []bp{
		p.codeBlockFenced,
		p.yamlMetaBlockP,
		p.bulletList,
		p.divHtml,
		p.divFenced,
		p.header,
		p.htmlBlock,
		p.table,
		p.codeBlockIndented,
		p.rawTeXBlock,
		p.lineBlock,
		p.blockQuote,
		p.hrule,
		p.orderedList,
		p.definitionList,
		p.noteBlock,
		p.referenceKey,
		p.para,
	}
	for _, f := range parsers {
		s := p.save()
		if r, ok := f(); ok {
			return r, true
		}
		p.restore(s)
	}
	return nil, false
}

// ---------- fenced code ----------

func (p *mdP) blockDelimiter(f func(rune) bool, length int) (int, rune, bool) {
	s := p.save()
	if !p.skipNonindentSpaces() {
		p.restore(s)
		return 0, 0, false
	}
	c := p.peek()
	if c == 0 || !f(c) {
		p.restore(s)
		return 0, 0, false
	}
	n := 0
	for p.peek() == c {
		p.pos++
		n++
	}
	if length > 0 {
		if n < length {
			p.restore(s)
			return 0, 0, false
		}
		return length, c, true
	}
	if n < 3 {
		p.restore(s)
		return 0, 0, false
	}
	return n, c, true
}

func toLanguageId(s string) string {
	s = strings.ToLower(s)
	switch s {
	case "c++":
		return "cpp"
	case "objective-c":
		return "objectivec"
	}
	return s
}

func (p *mdP) codeBlockFenced() ([]Block, bool) {
	start := p.pos
	indent, ok := p.nonindentSpaces()
	if !ok {
		return nil, false
	}
	c := p.peek()
	if !((c == '~' && p.ext("fenced_code_blocks")) || (c == '`' && p.ext("backtick_code_blocks"))) {
		return nil, false
	}
	p.pos = start
	size, _, ok := p.blockDelimiter(func(r rune) bool { return r == c }, 0)
	if !ok {
		return nil, false
	}
	p.skipSpaces()
	var attr Attr
	isRaw := false
	rawFmt := ""
	if p.ext("raw_attribute") {
		if f, ok := p.rawAttribute(); ok {
			isRaw = true
			rawFmt = f
		}
	}
	if !isRaw {
		got := false
		if p.ext("fenced_code_attributes") {
			if a, ok := p.attributes(); ok {
				attr = a
				got = true
			}
		}
		if !got {
			st := p.pos
			for p.pos < len(p.s) && !isSpaceH(p.s[p.pos]) {
				p.pos++
			}
			if p.pos > st {
				w := string(p.s[st:p.pos])
				if c == '`' && strings.ContainsRune(w, '`') {
					return nil, false
				}
				attr = Attr{Classes: []string{toLanguageId(w)}}
			}
		}
	}
	if !p.blankline() {
		return nil, false
	}
	var lines []string
	closed := false
	for !p.eof() {
		if _, _, ok := p.blockDelimiterClose(c, size); ok {
			closed = true
			break
		}
		p.gobbleAtMostSpaces(indent)
		l, ok := p.anyLine()
		if !ok {
			break
		}
		lines = append(lines, l)
	}
	_ = closed
	p.blanklines()
	contents := strings.Join(lines, "\n")
	if isRaw {
		return []Block{&RawBlock{rawFmt, contents}}, true
	}
	return []Block{&CodeBlock{attr, contents}}, true
}

func (p *mdP) blockDelimiterClose(c rune, size int) (int, rune, bool) {
	return p.blockDelimiter(func(r rune) bool { return r == c }, size)
}

// rawAttribute: {=format}
func (p *mdP) rawAttribute() (string, bool) {
	s := p.save()
	if !p.char('{') {
		return "", false
	}
	p.skipSpaces()
	if !p.char('=') {
		p.restore(s)
		return "", false
	}
	st := p.pos
	for p.pos < len(p.s) && (isAlphaNumH(p.s[p.pos]) || strings.ContainsRune("-_", p.s[p.pos])) {
		p.pos++
	}
	if p.pos == st {
		p.restore(s)
		return "", false
	}
	f := string(p.s[st:p.pos])
	p.skipSpaces()
	if !p.char('}') {
		p.restore(s)
		return "", false
	}
	return f, true
}

// ---------- attributes ----------

func (p *mdP) identifier() (string, bool) {
	if p.eof() || !isLetterH(p.peek()) {
		return "", false
	}
	st := p.pos
	p.pos++
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if isAlphaNumH(c) || c == '-' || c == '_' || c == ':' || c == '.' {
			p.pos++
		} else {
			break
		}
	}
	return string(p.s[st:p.pos]), true
}

func (p *mdP) attributes() (Attr, bool) {
	var a Attr
	ok := p.try(func() bool {
		if !p.char('{') {
			return false
		}
		p.spnl()
		for {
			if !p.attribute(&a) {
				break
			}
			p.spnl()
		}
		return p.char('}')
	})
	if !ok {
		return Attr{}, false
	}
	return a, true
}

func (p *mdP) attribute(a *Attr) bool {
	s := p.save()
	c := p.peek()
	if c == '#' {
		p.pos++
		if id, ok := p.identifier(); ok {
			a.ID = id
			return true
		}
		p.restore(s)
		return false
	}
	if c == '.' {
		p.pos++
		if cl, ok := p.identifier(); ok {
			a.Classes = append(a.Classes, cl)
			return true
		}
		p.restore(s)
		return false
	}
	if c == '-' {
		// specialAttr
		p.pos++
		a.Classes = append(a.Classes, "unnumbered")
		return true
	}
	// key=val
	if k, ok := p.identifier(); ok {
		if p.char('=') {
			v, ok := p.attrValue()
			if ok {
				switch k {
				case "id":
					a.ID = v
				case "class":
					a.Classes = append(a.Classes, strings.Fields(v)...)
				default:
					a.KVs = append(a.KVs, [2]string{k, v})
				}
				return true
			}
		}
	}
	p.restore(s)
	return false
}

func (p *mdP) attrValue() (string, bool) {
	c := p.peek()
	if c == '"' || c == '\'' {
		s := p.save()
		p.pos++
		var sb strings.Builder
		for !p.eof() && p.peek() != c {
			if p.peek() == '\\' && p.pos+1 < len(p.s) {
				p.pos++
				sb.WriteRune(p.peek())
				p.pos++
				continue
			}
			if p.peek() == '&' {
				if r, ok := p.charEntity(); ok {
					sb.WriteString(r)
					continue
				}
			}
			sb.WriteRune(p.peek())
			p.pos++
		}
		if !p.char(c) {
			p.restore(s)
			return "", false
		}
		return sb.String(), true
	}
	var sb strings.Builder
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '}' {
			break
		}
		if c == '\\' && p.pos+1 < len(p.s) {
			p.pos++
			sb.WriteRune(p.peek())
			p.pos++
			continue
		}
		sb.WriteRune(c)
		p.pos++
	}
	if sb.Len() == 0 {
		return "", false
	}
	return sb.String(), true
}

// ---------- yaml metadata ----------

func (p *mdP) yamlMetaBlockP() ([]Block, bool) {
	if !p.ext("yaml_metadata_block") {
		return nil, false
	}
	if !p.atLineStart() {
		return nil, false
	}
	if !p.str("---") {
		return nil, false
	}
	if !p.blankline() {
		return nil, false
	}
	if p.isBlankLineAhead() {
		return nil, false
	}
	var lines []string
	found := false
	for !p.eof() {
		if p.lookStr("---") || p.lookStr("...") {
			s := p.save()
			p.pos += 3
			if p.blankline() {
				found = true
				break
			}
			p.restore(s)
		}
		l, ok := p.anyLine()
		if !ok {
			break
		}
		lines = append(lines, l)
	}
	if !found {
		return nil, false
	}
	p.blanklines()
	raw := strings.Join(lines, "\n") + "\n"
	m, err := p.yamlToMeta(raw)
	if err != nil {
		p.st.warnings = append(p.st.warnings, err.Error())
		return nil, false
	}
	for k, v := range m {
		if _, exists := p.st.meta[k]; !exists {
			p.st.meta[k] = v
		}
	}
	return nil, true
}

// ---------- headers ----------

func (p *mdP) header() ([]Block, bool) {
	if r, ok := p.setextHeader(); ok {
		return r, true
	}
	return p.atxHeader()
}

func (p *mdP) atxClosing() (Attr, bool) {
	var attr Attr
	ok := p.try(func() bool {
		for p.peek() == '#' {
			p.pos++
		}
		p.skipSpaces()
		if p.ext("header_attributes") {
			if a, ok := p.attributes(); ok {
				attr = a
			}
		}
		return p.blanklines() > 0
	})
	return attr, ok
}

func (p *mdP) atxHeader() ([]Block, bool) {
	level := 0
	for p.peek() == '#' {
		p.pos++
		level++
	}
	if level == 0 || level > 6 {
		return nil, false
	}
	if p.ext("fancy_lists") && (p.peek() == '.' || p.peek() == ')') {
		return nil, false
	}
	if p.ext("space_in_atx_header") {
		c := p.peek()
		if !(c == ' ' || c == '\t' || c == '\n' || c == 0) {
			return nil, false
		}
	}
	p.skipSpaces()
	rawStart := p.pos
	var ils []Inline
	var attr Attr
	for {
		s := p.save()
		if a, ok := p.atxClosing(); ok {
			attr = a
			_ = s
			break
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		ils = appendInlMut(ils, x...)
	}
	_ = rawStart
	ils = trimInlines(ils)
	raw := ""
	return p.finishHeader(level, attr, ils, raw)
}

func (p *mdP) finishHeader(level int, attr Attr, ils []Inline, raw string) ([]Block, bool) {
	attr = p.registerHeader(attr, ils)
	if p.ext("implicit_header_references") {
		p.registerImplicitHeader(ils, attr)
	}
	return []Block{&Header{level, attr, ils}}, true
}

func (p *mdP) setextHeader() ([]Block, bool) {
	// lookahead: anyLine >> many1 (oneOf "=-") >> blankline
	if !p.look(func() bool {
		if _, ok := p.anyLine(); !ok {
			return false
		}
		n := 0
		for p.peek() == '=' || p.peek() == '-' {
			p.pos++
			n++
		}
		return n > 0 && p.blankline()
	}) {
		return nil, false
	}
	p.skipSpaces()
	var ils []Inline
	var attr Attr
	level := 0
	n := 0
	for {
		if a, lv, ok := p.setextHeaderEnd(); ok {
			attr = a
			level = lv
			break
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		n++
		ils = appendInlMut(ils, x...)
	}
	if n == 0 {
		return nil, false
	}
	ils = trimInlines(ils)
	return p.finishHeader(level, attr, ils, "")
}

func (p *mdP) setextHeaderEnd() (Attr, int, bool) {
	var attr Attr
	level := 0
	ok := p.try(func() bool {
		if p.ext("header_attributes") {
			if a, ok := p.attributes(); ok {
				attr = a
			}
		}
		if !p.blankline() {
			return false
		}
		c := p.peek()
		if c == '=' {
			level = 1
		} else if c == '-' {
			level = 2
		} else {
			return false
		}
		for p.peek() == c {
			p.pos++
		}
		return p.blanklines() > 0
	})
	return attr, level, ok
}

func (p *mdP) registerHeader(attr Attr, ils []Inline) Attr {
	if attr.ID == "" && p.ext("auto_identifiers") {
		resolved := resolveInlinesDefault(ils)
		id := uniqueIdent(p.st.exts, resolved, p.st.headerIds)
		id2 := id
		if p.ext("ascii_identifiers") {
			id2 = toAsciiText(id)
		}
		p.st.headerIds[id] = true
		p.st.headerIds[id2] = true
		attr.ID = id2
		return attr
	}
	if attr.ID != "" {
		p.st.headerIds[attr.ID] = true
	}
	return attr
}

func (p *mdP) registerImplicitHeader(ils []Inline, attr Attr) {
	if attr.ID == "" {
		return
	}
	raw := stringify(resolveInlinesDefault(ils))
	key := toKey(raw)
	if _, ok := p.st.headerKeys[key]; !ok {
		p.st.headerKeys[key] = mdKey{url: "#" + attr.ID}
	}
}

func toKey(s string) string {
	s = strings.TrimPrefix(s, "[")
	s = strings.TrimSuffix(s, "]")
	return strings.ToLower(strings.Join(strings.Fields(s), " "))
}

// ---------- indented code ----------

func (p *mdP) indentedLine() (string, bool) {
	s := p.save()
	if !p.indentSpaces() {
		return "", false
	}
	l, ok := p.anyLineNewline()
	if !ok {
		p.restore(s)
		return "", false
	}
	return l, true
}

func (p *mdP) codeBlockIndented() ([]Block, bool) {
	var parts []string
	for {
		if l, ok := p.indentedLine(); ok {
			parts = append(parts, l)
			continue
		}
		s := p.save()
		n := p.blanklines()
		if n > 0 {
			if l, ok := p.indentedLine(); ok {
				parts = append(parts, strings.Repeat("\n", n)+l)
				continue
			}
		}
		p.restore(s)
		break
	}
	if len(parts) == 0 {
		return nil, false
	}
	p.blanklines()
	classes := p.st.opts.IndentedCodeClasses
	return []Block{&CodeBlock{Attr{Classes: classes}, stripTrailingNewlines(strings.Join(parts, ""))}}, true
}

// ---------- hrule ----------

func (p *mdP) hruleCheck() bool {
	p.skipSpaces()
	c := p.peek()
	if c != '*' && c != '-' && c != '_' {
		return false
	}
	p.pos++
	for i := 0; i < 2; i++ {
		p.skipSpaces()
		if !p.char(c) {
			return false
		}
	}
	for p.peek() == c || isSpaceChar(p.peek()) {
		p.pos++
	}
	return p.newline()
}

func (p *mdP) hrule() ([]Block, bool) {
	if !p.hruleCheck() {
		return nil, false
	}
	p.blanklines()
	return []Block{&HorizontalRule{}}, true
}

// ---------- line blocks ----------

func (p *mdP) lineBlockLine() (string, bool) {
	s := p.save()
	if !p.char('|') || !p.char(' ') {
		p.restore(s)
		return "", false
	}
	white := 0
	for p.spaceChar() {
		white++
	}
	if p.peek() == '\n' {
		p.restore(s)
		return "", false
	}
	line, ok := p.anyLine()
	if !ok {
		p.restore(s)
		return "", false
	}
	parts := []string{line}
	for {
		s2 := p.save()
		if p.char(' ') {
			if l, ok := p.anyLine(); ok {
				parts = append(parts, l)
				continue
			}
		}
		p.restore(s2)
		break
	}
	return strings.Repeat("\u00a0", white) + strings.Join(parts, " "), true
}

func (p *mdP) lineBlock() ([]Block, bool) {
	if !p.ext("line_blocks") {
		return nil, false
	}
	var lines []string
	for {
		if l, ok := p.lineBlockLine(); ok {
			lines = append(lines, l)
			continue
		}
		s := p.save()
		if p.char('|') && p.blankline() {
			lines = append(lines, "\n")
			continue
		}
		p.restore(s)
		break
	}
	if len(lines) == 0 {
		return nil, false
	}
	p.blanklines()
	var out [][]Inline
	for _, l := range lines {
		sp := p.sub(l)
		ils := sp.inlines()
		out = append(out, trimInlines(ils))
	}
	return []Block{&LineBlock{out}}, true
}

// ---------- block quotes ----------

func (p *mdP) emailBlockQuoteStart() bool {
	return p.try(func() bool {
		if !p.skipNonindentSpaces() {
			return false
		}
		if !p.char('>') {
			return false
		}
		p.char(' ')
		return true
	})
}

func (p *mdP) blockQuote() ([]Block, bool) {
	if !p.emailBlockQuoteStart() {
		return nil, false
	}
	var raw []string
	emailLine := func() string {
		var sb strings.Builder
		for !p.eof() {
			c := p.peek()
			if c != '\n' {
				sb.WriteRune(c)
				p.pos++
				continue
			}
			// try endline >> notFollowedBy emailBlockQuoteStart
			s := p.save()
			p.pos++
			if p.eof() || p.isBlankLineAhead() {
				p.restore(s)
				break
			}
			if p.look(p.emailBlockQuoteStart) {
				p.restore(s)
				break
			}
			if !p.mdEndlineOK() {
				p.restore(s)
				break
			}
			sb.WriteRune('\n')
		}
		return sb.String()
	}
	raw = append(raw, emailLine())
	for {
		s := p.save()
		if p.newline() && p.emailBlockQuoteStart() {
			raw = append(raw, emailLine())
			continue
		}
		p.restore(s)
		break
	}
	if !p.newline() && !p.eof() {
		return nil, false
	}
	p.blanklines()
	sp := p.sub(strings.Join(raw, "\n") + "\n\n")
	bs := sp.parseBlocks()
	return []Block{&BlockQuote{bs}}, true
}

// conditions for lazy continuation in block quotes (like markdown endline)
func (p *mdP) mdEndlineOK() bool {
	// called positioned at start of next line
	if p.st.inList && p.look(p.listStart) {
		return false
	}
	if p.ext("lists_without_preceding_blankline") && p.look(p.listStart) {
		return false
	}
	if !p.ext("blank_before_header") && p.peek() == '#' {
		return false
	}
	if p.ext("backtick_code_blocks") && p.peek() == '`' && p.look(func() bool { _, ok := p.codeBlockFenced(); return ok }) {
		return false
	}
	if p.followedByHtmlCloser() {
		return false
	}
	if p.followedByDivCloser() {
		return false
	}
	return true
}

// ---------- lists ----------

func isBulletListMarker(c rune) bool { return c == '*' || c == '+' || c == '-' }

func (p *mdP) bulletListStart() bool {
	return p.try(func() bool {
		p.newline() // optional
		startCol := p.column()
		if !p.skipNonindentSpaces() {
			return false
		}
		if p.look(p.hruleCheck) {
			return false
		}
		if !isBulletListMarker(p.peek()) {
			return false
		}
		p.pos++
		return p.listMarkerSpaces(startCol)
	})
}

// after marker: gobbleSpaces 1 or lookahead newline; then up to 3 more spaces if not code
func (p *mdP) listMarkerSpaces(startCol int) bool {
	if p.peek() == '\n' || p.eof() {
		return true
	}
	if !p.gobbleSpaces(1) {
		return false
	}
	// count following spaces
	n := 0
	for p.pos+n < len(p.s) && p.s[p.pos+n] == ' ' {
		n++
	}
	if n < 4 && p.pos+n < len(p.s) && p.s[p.pos+n] != '\n' {
		p.pos += n
	}
	return true
}

func (p *mdP) anyOrderedListStart() (ListAttributes, bool) {
	var la ListAttributes
	ok := p.try(func() bool {
		p.newline()
		startCol := p.column()
		if !p.skipNonindentSpaces() {
			return false
		}
		// notFollowedBy "p." spaceChar digit
		if p.look(func() bool { return p.str("p.") && p.spaceChar() && isDigitH(p.peek()) }) {
			return false
		}
		if !p.ext("fancy_lists") {
			st := p.pos
			for isDigitH(p.peek()) {
				p.pos++
			}
			if p.pos == st || p.pos-st > 9 {
				return false
			}
			n, _ := strconv.Atoi(string(p.s[st:p.pos]))
			if !p.char('.') {
				return false
			}
			la = ListAttributes{n, DefaultStyle, DefaultDelim}
		} else {
			var ok bool
			la, ok = p.anyOrderedListMarker()
			if !ok {
				return false
			}
			if la.Delim == Period && (la.Style == UpperAlpha || (la.Style == UpperRoman && (la.Start == 1 || la.Start == 5 || la.Start == 10 || la.Start == 50 || la.Start == 100 || la.Start == 500 || la.Start == 1000))) {
				// insist on more than one space
				if !p.look(func() bool { return p.spaceChar() && p.spaceChar() }) {
					return false
				}
			}
		}
		return p.listMarkerSpaces(startCol)
	})
	return la, ok
}

func (p *mdP) listStart() bool {
	if p.bulletListStart() {
		return true
	}
	_, ok := p.anyOrderedListStart()
	return ok
}

func romanValue(s string, upper bool) (int, bool) {
	vals := map[rune]int{'i': 1, 'v': 5, 'x': 10, 'l': 50, 'c': 100, 'd': 500, 'm': 1000}
	if upper {
		vals = map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	}
	rs := []rune(s)
	total := 0
	for i, c := range rs {
		v, ok := vals[c]
		if !ok {
			return 0, false
		}
		if i+1 < len(rs) && vals[rs[i+1]] > v {
			total -= v
		} else {
			total += v
		}
	}
	return total, true
}

// romanNumeral parser like pandoc's
func (p *mdP) romanNumeral(upper bool) (int, bool) {
	var one, five, ten, fifty, hundred, fivehundred, thousand rune
	if upper {
		one, five, ten, fifty, hundred, fivehundred, thousand = 'I', 'V', 'X', 'L', 'C', 'D', 'M'
	} else {
		one, five, ten, fifty, hundred, fivehundred, thousand = 'i', 'v', 'x', 'l', 'c', 'd', 'm'
	}
	s := p.save()
	c := p.peek()
	if c != one && c != five && c != ten && c != fifty && c != hundred && c != fivehundred && c != thousand {
		return 0, false
	}
	count := func(ch rune, max int) int {
		n := 0
		for n < max && p.peek() == ch {
			p.pos++
			n++
		}
		return n
	}
	tryStr := func(a, b rune) bool {
		if p.peek() == a && p.peekAt(1) == b {
			p.pos += 2
			return true
		}
		return false
	}
	total := 0
	total += 1000 * count(thousand, 1000)
	if tryStr(hundred, thousand) {
		total += 900
	} else if tryStr(hundred, fivehundred) {
		total += 400
	} else {
		if p.peek() == fivehundred {
			p.pos++
			total += 500
		}
		total += 100 * count(hundred, 3)
	}
	if tryStr(ten, hundred) {
		total += 90
	} else if tryStr(ten, fifty) {
		total += 40
	} else {
		if p.peek() == fifty {
			p.pos++
			total += 50
		}
		total += 10 * count(ten, 3)
	}
	if tryStr(one, ten) {
		total += 9
	} else if tryStr(one, five) {
		total += 4
	} else {
		if p.peek() == five {
			p.pos++
			total += 5
		}
		total += count(one, 3)
	}
	if total == 0 {
		p.restore(s)
		return 0, false
	}
	return total, true
}

func (p *mdP) orderedListMarkerBody() (int, ListNumberStyle, bool) {
	s := p.save()
	// decimal
	if isDigitH(p.peek()) {
		st := p.pos
		for isDigitH(p.peek()) {
			p.pos++
		}
		if p.pos-st <= 9 {
			n, _ := strconv.Atoi(string(p.s[st:p.pos]))
			return n, Decimal, true
		}
		p.restore(s)
		return 0, 0, false
	}
	// example (@label)
	if p.ext("example_lists") && p.peek() == '@' {
		p.pos++
		st := p.pos
		for isAlphaNumH(p.peek()) || p.peek() == '_' || p.peek() == '-' {
			p.pos++
		}
		lab := string(p.s[st:p.pos])
		n := p.st.nextExample
		p.st.nextExample++
		if lab != "" {
			p.st.examples[lab] = n
		}
		return n, Example, true
	}
	// default (#)
	if p.peek() == '#' {
		p.pos++
		return 1, DefaultStyle, true
	}
	// roman before alpha
	if n, ok := p.romanNumeral(false); ok {
		return n, LowerRoman, true
	}
	if n, ok := p.romanNumeral(true); ok {
		return n, UpperRoman, true
	}
	c := p.peek()
	if c >= 'a' && c <= 'z' {
		p.pos++
		return int(c-'a') + 1, LowerAlpha, true
	}
	if c >= 'A' && c <= 'Z' {
		p.pos++
		return int(c-'A') + 1, UpperAlpha, true
	}
	return 0, 0, false
}

func (p *mdP) anyOrderedListMarker() (ListAttributes, bool) {
	s := p.save()
	// inPeriod / inOneParen / inTwoParens
	if p.char('(') {
		n, sty, ok := p.orderedListMarkerBodyNoRomanAmbig()
		if ok && p.char(')') {
			return ListAttributes{n, sty, TwoParens}, true
		}
		p.restore(s)
		return ListAttributes{}, false
	}
	n, sty, ok := p.orderedListMarkerBodyNoRomanAmbig()
	if !ok {
		p.restore(s)
		return ListAttributes{}, false
	}
	if p.char('.') {
		return ListAttributes{n, sty, Period}, true
	}
	if p.char(')') {
		return ListAttributes{n, sty, OneParen}, true
	}
	p.restore(s)
	return ListAttributes{}, false
}

// tries roman numerals; if roman parse doesn't lead to delimiter, try alpha
func (p *mdP) orderedListMarkerBodyNoRomanAmbig() (int, ListNumberStyle, bool) {
	s := p.save()
	n, sty, ok := p.orderedListMarkerBody()
	if !ok {
		return 0, 0, false
	}
	c := p.peek()
	if (sty == LowerRoman || sty == UpperRoman) && !(c == '.' || c == ')') {
		// backtrack and try alpha
		p.restore(s)
		c0 := p.peek()
		if c0 >= 'a' && c0 <= 'z' {
			p.pos++
			return int(c0-'a') + 1, LowerAlpha, true
		}
		if c0 >= 'A' && c0 <= 'Z' {
			p.pos++
			return int(c0-'A') + 1, UpperAlpha, true
		}
		return 0, 0, false
	}
	return n, sty, true
}

// listLineCommon: rest of line until newline, consuming the newline
func (p *mdP) listLineCommon() string {
	var sb strings.Builder
	for !p.eof() && p.peek() != '\n' {
		c := p.peek()
		if c == '`' {
			st := p.pos
			s := p.save()
			if _, ok := p.code(); ok {
				sb.WriteString(string(p.s[st:p.pos]))
				continue
			}
			p.restore(s)
		}
		if c == '<' {
			st := p.pos
			if p.lookStr("<!--") {
				if end := indexRunes(p.s[p.pos:], "-->"); end >= 0 {
					p.pos += end + 3
					sb.WriteString(string(p.s[st:p.pos]))
					continue
				}
			}
		}
		sb.WriteRune(c)
		p.pos++
	}
	p.newline()
	return sb.String()
}

func indexRunes(rs []rune, sub string) int {
	return strings.Index(string(rs), sub) // byte index! convert
}

func (p *mdP) rawListItem(fourSpaceRule bool, start func() bool) (string, int, bool) {
	s := p.save()
	pos1col := p.column()
	if !p.look(func() bool { p.newline(); return true }) {
	}
	// start may consume an optional newline; measure column after start
	startPos := p.pos
	if !start() {
		p.restore(s)
		return "", 0, false
	}
	// compute column relative to the line where marker started
	_ = startPos
	pos2col := p.column()
	if p.pos > startPos && p.s[startPos] == '\n' {
		pos1col = 0
	}
	indent := pos2col - pos1col
	if fourSpaceRule {
		indent = 4
	}
	first := p.listLineCommon()
	lines := []string{first}
	for !p.eof() {
		ss := p.save()
		if p.look(p.listStart) {
			break
		}
		if p.look(func() bool { _, ok := p.codeBlockFenced(); return ok }) {
			break
		}
		if p.isBlankLineAhead() {
			break
		}
		if l, ok := p.listLine(indent); ok {
			lines = append(lines, l)
			continue
		}
		p.restore(ss)
		break
	}
	blanks := 0
	for p.blankline() {
		blanks++
	}
	result := strings.Join(lines, "\n") + "\n" + strings.Repeat("\n", blanks)
	return result, indent, true
}

func (p *mdP) listLine(indent int) (string, bool) {
	s := p.save()
	if p.look(func() bool {
		if !p.gobbleSpaces(indent) {
			return false
		}
		p.skipSpaces()
		return p.listStart()
	}) {
		return "", false
	}
	if p.followedByHtmlCloser() || p.followedByDivCloser() {
		p.restore(s)
		return "", false
	}
	p.gobbleSpaces(indent)
	return p.listLineCommon(), true
}

func (p *mdP) listContinuation(indent int) (string, bool) {
	s := p.save()
	if p.isBlankLineAhead() || p.eof() {
		return "", false
	}
	if p.followedByHtmlCloser() || p.followedByDivCloser() {
		return "", false
	}
	if !p.gobbleSpaces(indent) {
		p.restore(s)
		return "", false
	}
	x, ok := p.anyLineNewline()
	if !ok {
		p.restore(s)
		return "", false
	}
	parts := []string{x}
	for !p.eof() {
		s2 := p.save()
		if p.isBlankLineAhead() {
			break
		}
		if p.followedByHtmlCloser() || p.followedByDivCloser() {
			break
		}
		if !p.gobbleSpaces(indent) {
			if p.look(p.listStart) {
				p.restore(s2)
				break
			}
		}
		l, ok := p.anyLineNewline()
		if !ok {
			p.restore(s2)
			break
		}
		parts = append(parts, l)
	}
	blanks := 0
	for p.blankline() {
		blanks++
	}
	return strings.Join(parts, "") + strings.Repeat("\n", blanks), true
