package main

import (
	"strings"
)

type pendingInl struct {
	f     func() []Inline
	image bool // for figure detection
}

func (*pendingInl) isInline() {}

func one(x Inline) []Inline { return []Inline{x} }

func (p *mdP) inline() ([]Inline, bool) {
	if p.eof() {
		return nil, false
	}
	c := p.peek()
	try := func(f func() ([]Inline, bool)) ([]Inline, bool) {
		s := p.save()
		r, ok := f()
		if !ok {
			p.restore(s)
		}
		return r, ok
	}
	var r []Inline
	ok := false
	switch c {
	case ' ', '\t':
		r, ok = try(p.whitespace)
	case '\n':
		r, ok = try(p.endline)
	case '`':
		r, ok = try(p.code)
	case '_', '*':
		r, ok = try(p.strongOrEmph)
	case '^':
		if r, ok = try(p.superscript); !ok {
			r, ok = try(p.inlineNote)
		}
	case '[':
		for _, f := range []func() ([]Inline, bool){p.noteRef, p.cite, p.bracketedSpan, p.link} {
			if r, ok = try(f); ok {
				break
			}
		}
	case '!':
		r, ok = try(p.image)
	case '$':
		r, ok = try(p.math)
	case '~':
		if r, ok = try(p.strikeout); !ok {
			r, ok = try(p.subscript)
		}
	case '=':
		r, ok = try(p.mark)
	case '<':
		for _, f := range []func() ([]Inline, bool){p.autoLink, p.spanHtml, p.rawHtmlInline, p.ltSign} {
			if r, ok = try(f); ok {
				break
			}
		}
	case '\\':
		for _, f := range []func() ([]Inline, bool){p.math, p.escapedNewline, p.escapedChar, p.rawLaTeXInlineP} {
			if r, ok = try(f); ok {
				break
			}
		}
	case '@':
		if r, ok = try(p.cite); !ok {
			r, ok = try(p.exampleRef)
		}
	case '"', '\'', '\u2018', '\u201c', '-', '.':
		r, ok = try(p.smart)
	case '&':
		r, ok = try(p.charRef)
	case ':':
		r, ok = try(p.emoji)
	}
	if ok {
		return r, true
	}
	if r, ok = try(p.bareURL); ok {
		return r, true
	}
	if r, ok = try(p.strP); ok {
		return r, true
	}
	return p.symbol()
}

func (p *mdP) whitespace() ([]Inline, bool) {
	if !p.spaceChar() {
		return nil, false
	}
	if p.spaceChar() {
		p.skipSpaces()
		s := p.save()
		if _, ok := p.endline(); ok {
			return one(&LineBreak{}), true
		}
		p.restore(s)
		return one(&Space{}), true
	}
	p.skipSpaces()
	return one(&Space{}), true
}

func (p *mdP) endline() ([]Inline, bool) {
	if !p.newline() {
		return nil, false
	}
	if p.isBlankLineAhead() {
		return nil, false
	}
	if p.st.inList && p.look(p.listStart) {
		return nil, false
	}
	if p.ext("lists_without_preceding_blankline") && p.look(p.listStart) {
		return nil, false
	}
	if !p.ext("blank_before_blockquote") && p.look(p.emailBlockQuoteStart) {
		return nil, false
	}
	if !p.ext("blank_before_header") && p.peek() == '#' {
		return nil, false
	}
	if p.ext("backtick_code_blocks") && p.peek() == '`' && p.look(func() bool { _, ok := p.codeBlockFenced(); return ok }) {
		return nil, false
	}
	if p.followedByHtmlCloser() {
		return nil, false
	}
	if p.followedByDivCloser() {
		return nil, false
	}
	if p.eof() {
		return nil, true
	}
	if p.ext("hard_line_breaks") {
		return one(&LineBreak{}), true
	}
	if p.ext("ignore_line_breaks") {
		return nil, true
	}
	p.skipSpaces()
	return one(&SoftBreak{}), true
}

func (p *mdP) strP() ([]Inline, bool) {
	var sb strings.Builder
	for !p.eof() {
		c := p.peek()
		if isAlphaNumH(c) {
			sb.WriteRune(c)
			p.pos++
			continue
		}
		if c == '.' && p.peekAt(1) != '.' {
			sb.WriteRune(c)
			p.pos++
			continue
		}
		break
	}
	if sb.Len() == 0 {
		return nil, false
	}
	result := sb.String()
	p.setLastStr()
	if p.ext("smart") && strings.HasSuffix(result, ".") && p.st.abbrevs[result] {
		s := p.save()
		if ws, ok := p.whitespace(); ok {
			bad := false
			if p.ext("citations") && p.look(func() bool { _, ok := p.cite(); return ok }) {
				bad = true
			}
			if !bad && p.ext("footnotes") && p.look(func() bool { _, ok := p.noteRef(); return ok }) {
				bad = true
			}
			if !bad {
				if len(ws) == 1 {
					if _, isSp := ws[0].(*Space); isSp {
						return []Inline{&Str{result + "\u00a0"}}, true
					}
				}
				return append([]Inline{&Str{result}}, ws...), true
			}
		}
		p.restore(s)
	}
	return one(&Str{result}), true
}

func (p *mdP) symbol() ([]Inline, bool) {
	c := p.peek()
	if c == '<' || c == '\n' || c == '\t' || c == ' ' {
		return nil, false
	}
	if c == '\\' {
		// notFollowedBy' rawTeXBlock
		if p.ext("raw_tex") && p.look(func() bool { _, ok := p.rawTeXBlock(); return ok }) {
			return nil, false
		}
	}
	p.pos++
	return one(&Str{string(c)}), true
}

func (p *mdP) ltSign() ([]Inline, bool) {
	if !p.ext("raw_html") {
		if p.char('<') {
			return one(&Str{"<"}), true
		}
		return nil, false
	}
	// notFollowedBy (htmlTag isBlockTag)
	if p.look(func() bool { _, ok := p.htmlTagP(tagFilterBlock); return ok }) {
		return nil, false
	}
	if p.char('<') {
		return one(&Str{"<"}), true
	}
	return nil, false
}

func (p *mdP) escapedCharP() (rune, bool) {
	if !p.char('\\') {
		return 0, false
	}
	c := p.peek()
	if p.eof() {
		p.pos--
		return 0, false
	}
	if p.ext("all_symbols_escapable") && !isAlphaNumH(c) {
		p.pos++
		return c, true
	}
	if p.ext("angle_brackets_escapable") && strings.ContainsRune("\\`*_{}[]()>#+-.!~\"<>", c) {
		p.pos++
		return c, true
	}
	if p.ext("escaped_line_breaks") && c == '\n' {
		p.pos++
		return c, true
	}
	if strings.ContainsRune("\\`*_{}[]()>#+-.!~\"", c) {
		p.pos++
		return c, true
	}
	p.pos--
	return 0, false
}

func (p *mdP) escapedChar() ([]Inline, bool) {
	c, ok := p.escapedCharP()
	if !ok {
		return nil, false
	}
	switch c {
	case ' ':
		return one(&Str{"\u00a0"}), true
	case '\n':
		if !p.ext("escaped_line_breaks") {
			return nil, false
		}
		return one(&LineBreak{}), true
	}
	return one(&Str{string(c)}), true
}

func (p *mdP) escapedNewline() ([]Inline, bool) {
	// escapedNewline = guardEnabled Ext_escaped_line_breaks >> try (char '\\' >> lookAhead (char '\n') ... )
	if !p.ext("escaped_line_breaks") {
		return nil, false
	}
	if p.peek() == '\\' && p.peekAt(1) == '\n' {
		p.pos += 2
		// endline-like? pandoc: newline >> optional (skipMany spaceChar)? 
		p.skipSpaces()
		return one(&LineBreak{}), true
	}
	return nil, false
}

// litChar: escapedChar' <|> characterReference <|> noneOf "\n" <|> try (newline >> notFollowedBy blankline >> return ' ')
func (p *mdP) litChar() (string, bool) {
	if p.eof() {
		return "", false
	}
	if c, ok := p.escapedCharP(); ok {
		return string(c), true
	}
	if p.peek() == '&' {
		if r, ok := p.charEntity(); ok {
			return r, true
		}
	}
	c := p.peek()
	if c != '\n' {
		p.pos++
		return string(c), true
	}
	s := p.save()
	p.pos++
	if p.isBlankLineAhead() {
		p.restore(s)
		return "", false
	}
	return " ", true
}

func (p *mdP) charEntity() (string, bool) {
	if p.peek() != '&' {
		return "", false
	}
	// find ';'
	end := -1
	for i := p.pos + 1; i < len(p.s) && i < p.pos+40; i++ {
		if p.s[i] == ';' {
			end = i
			break
		}
		c := p.s[i]
		if !(isAlphaNumH(c) || c == '#') {
			break
		}
	}
	if end < 0 {
		return "", false
	}
	name := string(p.s[p.pos+1 : end])
	if r, ok := lookupEntity(name); ok {
		p.pos = end + 1
		return r, true
	}
	return "", false
}

func (p *mdP) charRef() ([]Inline, bool) {
	if r, ok := p.charEntity(); ok {
		return one(&Str{r}), true
	}
	return nil, false
}

// ---------- code ----------

func (p *mdP) code() ([]Inline, bool) {
	n := 0
	for p.peek() == '`' {
		p.pos++
		n++
	}
	if n == 0 {
		return nil, false
	}
	p.skipSpaces()
	var sb strings.Builder
	closed := false
	for !p.eof() {
		// closer?
		s := p.save()
		p.skipSpaces()
		m := 0
		for p.peek() == '`' {
			p.pos++
			m++
		}
		if m == n {
			closed = true
			break
		}
		p.restore(s)
		if p.st.inList && p.look(p.listStart) {
			break
		}
		c := p.peek()
		if c == '`' {
			for p.peek() == '`' {
				sb.WriteRune('`')
				p.pos++
			}
			continue
		}
		if c == '\n' {
			s2 := p.save()
			p.pos++
			if p.isBlankLineAhead() || p.eof() {
				p.restore(s2)
				break
			}
			sb.WriteRune(' ')
			continue
		}
		for !p.eof() && p.peek() != '`' && p.peek() != '\n' {
			sb.WriteRune(p.peek())
			p.pos++
		}
	}
	if !closed {
		return nil, false
	}
	result := sb.String()
	if p.ext("raw_attribute") {
		if f, ok := p.rawAttribute(); ok {
			return one(&RawInline{f, result}), true
		}
	}
	var attr Attr
	if p.ext("inline_code_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	return one(&Code{attr, result}), true
}

// ---------- emphasis ----------

func (p *mdP) strongOrEmph() ([]Inline, bool) {
	c := p.peek()
	if c != '*' && c != '_' {
		return nil, false
	}
	return p.enclosure(c)
}

func (p *mdP) enclosure(c rune) ([]Inline, bool) {
	if c == '_' && p.ext("intraword_underscores") && !p.notAfterString() {
		return nil, false
	}
	n := 0
	for p.peek() == c {
		p.pos++
		n++
	}
	cs := strings.Repeat(string(c), n)
	s := p.save()
	if ws, ok := p.whitespace(); ok {
		return append([]Inline{&Str{cs}}, ws...), true
	}
	p.restore(s)
	if p.st.maxNest <= 0 {
		return one(&Str{cs}), true
	}
	p.st.maxNest--
	defer func() { p.st.maxNest++ }()
	switch n {
	case 3:
		return p.three(c), true
	case 2:
		return p.two(c, nil), true
	case 1:
		return p.one(c, nil), true
	}
	return one(&Str{cs}), true
}

func (p *mdP) ender(c rune, n int) bool {
	return p.try(func() bool {
		for i := 0; i < n; i++ {
			if !p.char(c) {
				return false
			}
		}
		if c == '*' || !p.ext("intraword_underscores") {
			return true
		}
		return !isAlphaNumH(p.peek())
	})
}

func (p *mdP) three(c rune) []Inline {
	var contents []Inline
	for !p.eof() {
		if p.look(func() bool { return p.ender(c, 1) }) {
			break
		}
		s := p.save()
		x, ok := p.inline()
		if !ok {
			p.restore(s)
			break
		}
		contents = appendInlMut(contents, x...)
	}
	if p.ender(c, 3) {
		p.setLastStr()
		return one(&Strong{one(&Emph{contents})})
	}
	if p.ender(c, 2) {
		p.setLastStr()
		return p.one(c, one(&Strong{contents}))
	}
	if p.ender(c, 1) {
		p.setLastStr()
		return p.two(c, one(&Emph{contents}))
	}
	return catInl(one(&Str{strings.Repeat(string(c), 3)}), contents)
}

func (p *mdP) two(c rune, prefix []Inline) []Inline {
	var contents []Inline
	for !p.eof() {
		s := p.save()
		if p.look(func() bool { return p.ender(c, 2) }) {
			break
		}
		x, ok := p.inline()
		if !ok {
			p.restore(s)
			break
		}
		contents = appendInlMut(contents, x...)
	}
	if p.ender(c, 2) {
		p.setLastStr()
		return one(&Strong{catInl(prefix, contents)})
	}
	return catInl(one(&Str{string(c) + string(c)}), prefix, contents)
}

func (p *mdP) one(c rune, prefix []Inline) []Inline {
	var contents []Inline
	for !p.eof() {
		s := p.save()
		if !p.look(func() bool { return p.ender(c, 1) }) {
			x, ok := p.inline()
			if ok {
				contents = appendInlMut(contents, x...)
				continue
			}
			p.restore(s)
		}
		// try (string [c,c] >> notFollowedBy (ender c 1) >> two c mempty)
		ok := p.try(func() bool {
			if !(p.char(c) && p.char(c)) {
				return false
			}
			if p.look(func() bool { return p.ender(c, 1) }) {
				return false
			}
			x := p.two(c, nil)
			contents = appendInlMut(contents, x...)
			return true
		})
		if !ok {
			break
		}
	}
	if p.ender(c, 1) {
		p.setLastStr()
		return one(&Emph{catInl(prefix, contents)})
	}
	return catInl(one(&Str{string(c)}), prefix, contents)
}

// inlinesBetween start end
func (p *mdP) inlinesBetween(start func() bool, end func() bool) ([]Inline, bool) {
	var res []Inline
	ok := p.try(func() bool {
		if !start() {
			return false
		}
		n := 0
		for {
			if p.eof() {
				return false
			}
			if end() {
				break
			}
			// inner = innerSpace <|> (notFollowedBy' whitespace >> inline)
			s := p.save()
			if ws, ok := p.whitespace(); ok {
				if p.look(end) {
					p.restore(s)
					return false
				}
				res = appendInlMut(res, ws...)
				n++
				continue
			}
			p.restore(s)
			x, ok := p.inline()
			if !ok {
				return false
			}
			res = appendInlMut(res, x...)
			n++
		}
		return n > 0
	})
	if !ok {
		return nil, false
	}
	return trimInlines(res), true
}

func (p *mdP) strikeout() ([]Inline, bool) {
	if !p.ext("strikeout") {
		return nil, false
	}
	r, ok := p.inlinesBetween(func() bool {
		if !p.str("~~") {
			return false
		}
		if p.eof() || isSpaceH(p.peek()) {
			return false
		}
		return p.peek() != '~'
	}, func() bool { return p.try(func() bool { return p.str("~~") }) })
	if !ok {
		return nil, false
	}
	return one(&Strikeout{r}), true
}

func (p *mdP) mark() ([]Inline, bool) {
	if !p.ext("mark") {
		return nil, false
	}
	r, ok := p.inlinesBetween(func() bool {
		if !p.str("==") {
			return false
		}
		if p.eof() || isSpaceH(p.peek()) {
			return false
		}
		return p.peek() != '='
	}, func() bool { return p.try(func() bool { return p.str("==") }) })
	if !ok {
		return nil, false
	}
	return one(&Span{Attr{Classes: []string{"mark"}}, r}), true
}

func (p *mdP) supSub(ch rune) ([]Inline, bool) {
	if !p.char(ch) {
		return nil, false
	}
	var res []Inline
	n := 0
	for {
		if p.eof() {
			return nil, false
		}
		if p.char(ch) {
			break
		}
		c := p.peek()
		if isSpaceChar(c) || c == '\n' {
			return nil, false
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		res = appendInlMut(res, x...)
		n++
	}
	if n == 0 {
		return nil, false
	}
	return res, true
}

func (p *mdP) superscript() ([]Inline, bool) {
	if !p.ext("superscript") {
		return nil, false
	}
	r, ok := p.supSub('^')
	if !ok {
		return nil, false
	}
	return one(&Superscript{r}), true
}

func (p *mdP) subscript() ([]Inline, bool) {
	if !p.ext("subscript") {
		return nil, false
	}
	r, ok := p.supSub('~')
	if !ok {
		return nil, false
	}
	return one(&Subscript{r}), true
}

// ---------- math ----------

func (p *mdP) math() ([]Inline, bool) {
	if p.ext("tex_math_dollars") && p.lookStr("$$") {
		s := p.save()
		if r, ok := p.mathDisplayWith("$$", "$$"); ok {
			return one(&Math{DisplayMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	if p.ext("tex_math_single_backslash") && p.lookStr("\\[") {
		s := p.save()
		if r, ok := p.mathDisplayWith("\\[", "\\]"); ok {
			return one(&Math{DisplayMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	if p.ext("tex_math_double_backslash") && p.lookStr("\\\\[") {
		s := p.save()
		if r, ok := p.mathDisplayWith("\\\\[", "\\\\]"); ok {
			return one(&Math{DisplayMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	if p.ext("tex_math_dollars") && p.peek() == '$' {
		s := p.save()
		if r, ok := p.mathInlineWith("$", "$"); ok {
			return one(&Math{InlineMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	if p.ext("tex_math_single_backslash") && p.lookStr("\\(") {
		s := p.save()
		if r, ok := p.mathInlineWith("\\(", "\\)"); ok {
			return one(&Math{InlineMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	if p.ext("tex_math_double_backslash") && p.lookStr("\\\\(") {
		s := p.save()
		if r, ok := p.mathInlineWith("\\\\(", "\\\\)"); ok {
			return one(&Math{InlineMath, p.applyMacros(r)}), true
		}
		p.restore(s)
	}
	return nil, false
}

func (p *mdP) mathDisplayWith(op, cl string) (string, bool) {
	if !p.str(op) {
		return "", false
	}
	var sb strings.Builder
	n := 0
	for {
		if p.eof() {
			return "", false
		}
		if p.str(cl) {
			break
		}
		c := p.peek()
		if c == '\n' {
			p.pos++
			if p.isBlankLineAhead() {
				return "", false
			}
			sb.WriteRune('\n')
			n++
			continue
		}
		sb.WriteRune(c)
		p.pos++
		n++
	}
	if n == 0 {
		return "", false
	}
	return sb.String(), true
}

func (p *mdP) mathInlineWith(op, cl string) (string, bool) {
	if !p.str(op) {
		return "", false
	}
	if op == "$" && (p.eof() || isSpaceH(p.peek())) {
		return "", false
	}
	var sb strings.Builder
	n := 0
	for {
		if p.eof() {
			return "", false
		}
		if n > 0 && p.lookStr(cl) {
			p.str(cl)
			break
		}
		c := p.peek()
		if c == '\\' {
			p.pos++
			if p.lookStr("text") {
				s := p.save()
				p.pos += 4
				if b, ok := p.inBalancedBracesMath(); ok {
					sb.WriteString("\\text" + b)
					n++
					continue
				}
				p.restore(s)
			}
			if p.eof() {
				return "", false
			}
			sb.WriteRune('\\')
			sb.WriteRune(p.peek())
			p.pos++
			n++
			continue
		}
		if isSpaceChar(c) || c == '\n' {
			if c == '\n' {
				s := p.save()
				p.pos++
				if p.isBlankLineAhead() {
					p.restore(s)
					return "", false
				}
			} else {
				p.pos++
				p.skipSpaces()
			}
			if p.peek() == '$' {
				return "", false
			}
			sb.WriteRune(' ')
			n++
			continue
		}
		if !p.lookStr(cl) || n > 0 {
			sb.WriteRune(c)
			p.pos++
			n++
			continue
		}
		return "", false
	}
	if isDigitH(p.peek()) {
		return "", false
	}
	return trimMath(sb.String()), true
}

func trimMath(s string) string {
	// trimMath: remove leading spaces and trailing spaces not preceded by backslash
	s = strings.TrimLeft(s, " \t\n")
	for len(s) > 0 && (s[len(s)-1] == ' ' || s[len(s)-1] == '\t' || s[len(s)-1] == '\n') {
		if len(s) >= 2 && s[len(s)-2] == '\\' {
			break
		}
		s = s[:len(s)-1]
	}
	return s
}

func (p *mdP) inBalancedBracesMath() (string, bool) {
	if p.peek() != '{' {
		return "", false
	}
	st := p.pos
	depth := 0
	for !p.eof() {
		c := p.peek()
		if c == '\\' {
			p.pos += 2
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				p.pos++
				return string(p.s[st:p.pos]), true
			}
		}
		p.pos++
	}
	return "", false
}

// ---------- smart ----------

func (p *mdP) smart() ([]Inline, bool) {
	if !p.ext("smart") {
		return nil, false
	}
	s := p.save()
	if r, ok := p.doubleQuoted(); ok {
		return r, true
	}
	p.restore(s)
	if r, ok := p.singleQuoted(); ok {
		return r, true
	}
	p.restore(s)
	c := p.peek()
	if c == '\'' || c == '\u2019' {
		p.pos++
		return one(&Str{"\u2019"}), true
	}
	if c == '"' {
		p.pos++
		return one(&Str{"\u201d"}), true
	}
	if c == '-' {
		if p.ext("old_dashes") {
			p.pos++
			if p.char('-') {
				return one(&Str{"\u2014"}), true
			}
			if isDigitH(p.peek()) {
				return one(&Str{"\u2013"}), true
			}
			p.restore(s)
			return nil, false
		}
		if p.str("--") {
			if p.char('-') {
				return one(&Str{"\u2014"}), true
			}
			return one(&Str{"\u2013"}), true
		}
		return nil, false
	}
	if p.str("...") {
		return one(&Str{"\u2026"}), true
	}
	return nil, false
}

func (p *mdP) doubleQuoted() ([]Inline, bool) {
	if p.st.quoteCtx == 2 {
		return nil, false
	}
	c := p.peek()
	if c != '"' && c != '\u201c' {
		return nil, false
	}
	p.pos++
	if p.eof() || isSpaceH(p.peek()) {
		return nil, false
	}
	old := p.st.quoteCtx
	p.st.quoteCtx = 2
	var contents []Inline
	n := 0
	ok := false
	s := p.save()
	for !p.eof() {
		if p.peek() == '"' || p.peek() == '\u201d' {
			if n > 0 {
				p.pos++
				ok = true
				break
			}
		}
		x, ok2 := p.inline()
		if !ok2 {
			break
		}
		contents = appendInlMut(contents, x...)
		n++
	}
	p.st.quoteCtx = old
	if !ok {
		p.restore(s)
		p.st.quoteCtx = old
		return one(&Str{"\u201c"}), true
	}
	return one(&Quoted{DoubleQuote, trimInlines(contents)}), true
}

func (p *mdP) singleQuoted() ([]Inline, bool) {
	if p.st.quoteCtx == 1 {
		return nil, false
	}
	if !p.notAfterString() {
		return nil, false
	}
	c := p.peek()
	if c != '\'' && c != '\u2018' {
		return nil, false
	}
	p.pos++
	if p.eof() || isSpaceH(p.peek()) {
		return nil, false
	}
	old := p.st.quoteCtx
	p.st.quoteCtx = 1
	var contents []Inline
	n := 0
	ok := false
	s := p.save()
	for !p.eof() {
		c := p.peek()
		if (c == '\'' || c == '\u2019') && n > 0 {
			if !isAlphaNumH(p.peekAt(1)) {
				p.pos++
				ok = true
				break
			}
		}
		x, ok2 := p.inline()
		if !ok2 {
			break
		}
		contents = appendInlMut(contents, x...)
		n++
	}
	p.st.quoteCtx = old
	if !ok {
		p.restore(s)
		p.st.quoteCtx = old
		return one(&Str{"\u2018"}), true
	}
	return one(&Quoted{SingleQuote, trimInlines(contents)}), true
}

// ---------- emoji / bare urls (mostly disabled by default) ----------

func (p *mdP) emoji() ([]Inline, bool) {
	if !p.ext("emoji") {
		return nil, false
	}
	if !p.char(':') {
		return nil, false
	}
	st := p.pos
	for isAlphaNumH(p.peek()) || p.peek() == '_' || p.peek() == '+' || p.peek() == '-' {
		p.pos++
	}
	name := string(p.s[st:p.pos])
	if name == "" || !p.char(':') {
		return nil, false
	}
	if e, ok := emojiTable[name]; ok {
		return one(&Span{Attr{Classes: []string{"emoji"}, KVs: [][2]string{{"data-emoji", name}}}, one(&Str{e})}), true
	}
	return nil, false
}

func (p *mdP) bareURL() ([]Inline, bool) {
	if !p.ext("autolink_bare_uris") {
		return nil, false
	}
	if !p.notAfterString() {
		return nil, false
	}
	if orig, src, ok := p.uriP(); ok {
		return one(&Link{Attr{Classes: []string{"uri"}}, one(&Str{orig}), Target{src, ""}}), true
	}
	if orig, src, ok := p.emailP(); ok {
		return one(&Link{Attr{Classes: []string{"email"}}, one(&Str{orig}), Target{src, ""}}), true
	}
	return nil, false
}
