// scan balanced brackets, returns inner text
func (p *mdP) balancedBracketsRaw() (string, bool) {
	s := p.save()
	if !p.char('[') {
		return "", false
	}
	st := p.pos
	depth := 1
	for depth > 0 {
		if p.eof() {
			p.restore(s)
			return "", false
		}
		c := p.peek()
		ss := p.save()
		switch c {
		case '\\':
			if _, ok := p.escapedChar(); ok {
				continue
			}
			p.restore(ss)
			if r, ok := p.math(); ok && r != nil {
