			}
			p.restore(ss)
		case '`':
			if _, ok := p.code(); ok {
				continue
			}
			p.restore(ss)
		case '$':
			if _, ok := p.math(); ok {
				continue
			}
			p.restore(ss)
		case '<':
			if _, ok := p.rawHtmlInline(); ok {
				continue
			}
			p.restore(ss)
		case ']':
			depth--
			p.pos++
			continue
		case '[':
			depth++
			p.pos++
			continue
		}
		p.pos++
	}
	return string(p.s[st : p.pos-1]), true
}

func (p *mdP) inlinesInBalancedBrackets() ([]Inline, bool) {
	inner, ok := p.balancedBracketsRaw()
