package main

import (
	"path"
	"strings"
)

// reference: [ ... ] balanced; returns parsed inlines and raw text
func (p *mdP) reference() ([]Inline, bool) {
	if p.ext("footnotes") && p.lookStr("[^") {
		return nil, false
	}
	if p.ext("citations") && p.lookStr("[@") {
		return nil, false
	}
	r, ok := p.inlinesInBalancedBrackets()
	if !ok {
		return nil, false
	}
	return trimInlines(r), true
}

// scan balanced brackets, returns inner text
func (p *mdP) balancedBracketsRaw() (string, bool) {
	s := p.save()
	if !p.char('[') {
		return "", false
	}
	st := p.pos
	depth := 1
	for depth > 0 {
		if p.eof() {
			p.restore(s)
			return "", false
		}
		c := p.peek()
		ss := p.save()
		switch c {
		case '\\':
			if _, ok := p.escapedChar(); ok {
				continue
			}
			p.restore(ss)
			if r, ok := p.math(); ok && r != nil {
				continue
			}
			p.restore(ss)
			if _, ok := p.rawLaTeXInlineP(); ok {
				continue
			}
			p.restore(ss)
		case '`':
			if _, ok := p.code(); ok {
				continue
			}
			p.restore(ss)
		case '$':
			if _, ok := p.math(); ok {
				continue
			}
			p.restore(ss)
		case '<':
			if _, ok := p.rawHtmlInline(); ok {
				continue
			}
			p.restore(ss)
		case ']':
			depth--
			p.pos++
			continue
		case '[':
			depth++
			p.pos++
			continue
		}
		p.pos++
	}
	return string(p.s[st : p.pos-1]), true
}

func (p *mdP) inlinesInBalancedBrackets() ([]Inline, bool) {
	inner, ok := p.balancedBracketsRaw()
	if !ok {
		return nil, false
	}
	sp := p.sub(inner)
	return sp.inlines(), true
}

func (p *mdP) source() (string, string, bool) {
	var src, tit string
	ok := p.try(func() bool {
		if !p.char('(') {
			return false
		}
		p.skipSpaces()
		gotAngle := false
		if p.peek() == '<' {
			s := p.save()
			p.pos++
			var sb strings.Builder
			closed := false
			for !p.eof() {
				if p.peek() == '>' {
					p.pos++
					closed = true
					break
				}
				c, ok := p.litChar()
				if !ok {
					break
				}
				sb.WriteString(c)
			}
			if closed {
				src = sb.String()
				gotAngle = true
			} else {
				p.restore(s)
			}
		}
		if !gotAngle {
			var sb strings.Builder
			for !p.eof() {
				// urlChunk
				if p.peek() == '(' {
					if r, ok := p.parenthesizedChars(); ok {
						sb.WriteString(r)
						continue
					}
				}
				c := p.peek()
				if c != ' ' && c != ')' {
					if r, ok := p.litChar(); ok {
						sb.WriteString(r)
						continue
					}
					break
				}
				if c == ' ' {
					s := p.save()
					st := p.pos
					for p.spaceChar() {
					}
					nc := p.peek()
					if nc == '"' || nc == '\'' || nc == ')' {
						p.restore(s)
						break
					}
					sb.WriteString(string(p.s[st:p.pos]))
					continue
				}
				break
			}
			src = strings.Join(strings.Fields(sb.String()), " ")
		}
		s := p.save()
		okT := p.try(func() bool {
			p.spnl()
			t, ok := p.linkTitle()
			if ok {
				tit = t
			}
			return ok
		})
		if !okT {
			p.restore(s)
		}
		p.skipSpaces()
		return p.char(')')
	})
	if !ok {
		return "", "", false
	}
	return escapeURI(strings.TrimRight(src, " \t\n\r")), tit, true
}

func (p *mdP) parenthesizedChars() (string, bool) {
	var res string
	ok := p.try(func() bool {
		if !p.char('(') {
			return false
		}
		var sb strings.Builder
		sb.WriteRune('(')
		for {
			if p.eof() {
				return false
			}
			if p.peek() == ')' {
				p.pos++
				sb.WriteRune(')')
				res = sb.String()
				return true
			}
			if p.peek() == '(' {
				if r, ok := p.parenthesizedChars(); ok {
					sb.WriteString(r)
					continue
				}
				return false
			}
			c := p.peek()
			if c == ' ' {
				return false
			}
			r, ok := p.litChar()
			if !ok {
				return false
			}
			sb.WriteString(r)
		}
	})
	return res, ok
}

func (p *mdP) linkTitle() (string, bool) {
	if r, ok := p.quotedTitle('"'); ok {
		return r, true
	}
	return p.quotedTitle('\'')
}

func (p *mdP) quotedTitle(c rune) (string, bool) {
	var res string
	ok := p.try(func() bool {
		if !p.char(c) {
			return false
		}
		if p.eof() || isSpaceH(p.peek()) {
			return false
		}
		var sb strings.Builder
		for {
			if p.eof() {
				return false
			}
			// pEnder
			if p.peek() == c && !isAlphaNumH(p.peekAt(1)) {
				p.pos++
				break
			}
			if p.peek() == c {
				if r, ok := p.quotedTitle(c); ok {
					sb.WriteRune(c)
					sb.WriteString(r)
					sb.WriteRune(c)
					continue
				}
			}
			ch := p.peek()
			if ch != '\\' && ch != '\n' && ch != '&' && ch != c {
				sb.WriteRune(ch)
				p.pos++
				continue
			}
			r, ok := p.litChar()
			if !ok {
				return false
			}
			sb.WriteString(r)
		}
		res = strings.Join(strings.Fields(sb.String()), " ")
		return true
	})
	return res, ok
}

func (p *mdP) link() ([]Inline, bool) {
	if !p.st.allowLinks {
		return nil, false
	}
	p.st.allowLinks = false
	rawStart := p.pos
	lab, ok := p.reference()
	p.st.allowLinks = true
	if !ok {
		return nil, false
	}
	raw := string(p.s[rawStart:p.pos])
	s := p.save()
	if r, ok := p.regLink(false, lab); ok {
		return r, true
	}
	p.restore(s)
	return p.referenceLink(false, lab, raw)
}

func (p *mdP) regLink(image bool, lab []Inline) ([]Inline, bool) {
	src, tit, ok := p.source()
	if !ok {
		return nil, false
	}
	var attr Attr
	if p.ext("link_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	if image {
		return one(&Image{attr, lab, Target{p.addImageExt(src), tit}}), true
	}
	return one(&Link{attr, lab, Target{src, tit}}), true
}

func (p *mdP) addImageExt(src string) string {
	ext := p.st.opts.DefaultImageExt
	if ext == "" {
		return src
	}
	if path.Ext(src) == "" {
		if !strings.HasPrefix(ext, ".") {
			ext = "." + ext
		}
		return src + ext
	}
	return src
}

func (p *mdP) referenceLink(image bool, lab []Inline, raw string) ([]Inline, bool) {
	sp := p.peek() == ' '
	raw2 := ""
	s := p.save()
	gotSecond := false
	// lookahead for citation after space? (only when citations enabled)
	citeAhead := false
	if p.ext("citations") {
		citeAhead = p.look(func() bool {
			if p.ext("spaced_reference_links") {
				p.spnl()
			}
			_, ok := p.normalCite()
			return ok
		})
	}
	if !citeAhead {
		ok := p.try(func() bool {
			if p.ext("spaced_reference_links") {
				p.spnl()
			}
			st := p.pos
			if _, ok := p.reference(); !ok {
				return false
			}
			raw2 = string(p.s[st:p.pos])
			return true
		})
		if ok {
			gotSecond = true
		} else {
			p.restore(s)
		}
	}
	_ = gotSecond
	if raw2 == "" && !p.ext("shortcut_reference_links") {
		return nil, false
	}
	labIsRef := raw2 == "" || raw2 == "[]"
	exclam := image
	rawsuffix := raw
	if image {
		rawsuffix = strings.TrimPrefix(raw, "!")
	}
	var key string
	if labIsRef {
		key = toKey(rawsuffix)
	} else {
		key = toKey(raw2)
	}
	// fallback parse
	oldAllow := p.st.allowLinks
	p.st.allowLinks = false
	parsedRaw := p.sub(raw2).inlines()
	fallbackIl := p.sub(rawsuffix).inlines()
	p.st.allowLinks = oldAllow
	implicit := p.ext("implicit_header_references")
	st := p.st
	addExt := p.addImageExt
	mk := func(k mdKey) []Inline {
		if image {
			return one(&Image{k.attr, lab, Target{addExt(k.url), k.title}})
		}
		return one(&Link{k.attr, lab, Target{k.url, k.title}})
	}
	f := func() []Inline {
		if k, ok := st.keys[key]; ok {
			return mk(k)
		}
		if implicit {
			if k, ok := st.headerKeys[key]; ok {
				return mk(mdKey{url: k.url, title: k.title})
			}
		}
		var fb []Inline
		if exclam {
			fb = catInl(one(&Str{"!"}), fallbackIl)
		} else {
			fb = fallbackIl
		}
		if sp && raw != "" && raw2 != "" {
			fb = catInl(fb, one(&Space{}))
		}
		return catInl(fb, parsedRaw)
	}
	return one(&pendingInl{f: f, image: image}), true
}

func (p *mdP) image() ([]Inline, bool) {
	if !p.char('!') {
		return nil, false
	}
	rawStart := p.pos
	lab, ok := p.reference()
	if !ok {
		return nil, false
	}
	raw := string(p.s[rawStart:p.pos])
	s := p.save()
	if r, ok := p.regLink(true, lab); ok {
		return r, true
	}
	p.restore(s)
	return p.referenceLink(true, lab, "!"+raw)
}

func (p *mdP) bracketedSpan() ([]Inline, bool) {
	if !p.ext("bracketed_spans") {
		return nil, false
	}
	lab, ok := p.reference()
	if !ok {
		return nil, false
	}
	attr, ok := p.attributes()
	if !ok {
		return nil, false
	}
	return wrapSpan(attr, lab), true
}

func isSmallCapsFontVariant(s string) bool {
	t := strings.ToLower(strings.Join(strings.Fields(s), ""))
	return strings.Contains(t, "font-variant:small-caps")
}

func wrapSpan(attr Attr, ils []Inline) []Inline {
	var wrappers []func([]Inline) Inline
	kvs := attr.KVs
	if st, ok := attr.Get("style"); ok && isSmallCapsFontVariant(st) {
		var nk [][2]string
		for _, kv := range kvs {
			if kv[0] != "style" {
				nk = append(nk, kv)
			}
		}
		kvs = nk
		wrappers = append(wrappers, func(x []Inline) Inline { return &SmallCaps{x} })
	}
	var classes []string
	for _, c := range attr.Classes {
		switch c {
		case "smallcaps":
			wrappers = append(wrappers, func(x []Inline) Inline { return &SmallCaps{x} })
		case "ul":
			wrappers = append(wrappers, func(x []Inline) Inline { return &Underline{x} })
		default:
			classes = append(classes, c)
		}
	}
	res := ils
	// apply in order: first class innermost? (foldr) -> outermost first in list
	for i := len(wrappers) - 1; i >= 0; i-- {
		res = one(wrappers[i](res))
	}
	if attr.ID == "" && len(classes) == 0 && len(kvs) == 0 {
		if len(wrappers) == 0 {
			return one(&Span{Attr{}, ils})
		}
		return res
	}
	return one(&Span{Attr{attr.ID, classes, kvs}, res})
}

// ---------- notes ----------

func (p *mdP) noteRef() ([]Inline, bool) {
	if !p.ext("footnotes") {
		return nil, false
	}
	ref, ok := p.noteMarker()
	if !ok {
		return nil, false
	}
	p.st.noteNumber++
	noteNum := p.st.noteNumber
	st := p.st
	f := func() []Inline {
		bs, ok := st.notes[ref]
		if !ok {
			return one(&Str{"[^" + ref + "]"})
		}
		// avoid infinite recursion: resolve with notes disabled
		saved := st.notes
		st.notes = map[string][]Block{}
		rb := resolveBlocks(st, bs)
		st.notes = saved
		walkCitesSetNote(rb, noteNum)
		return one(&Note{rb})
	}
	return one(&pendingInl{f: f}), true
}

func walkCitesSetNote(bs []Block, n int) {
	walkInlinesInBlocks(bs, func(x Inline) {
		if c, ok := x.(*Cite); ok {
			for i := range c.Citations {
				c.Citations[i].NoteNum = n
			}
		}
	})
}

func (p *mdP) inlineNote() ([]Inline, bool) {
	if !p.ext("inline_notes") {
		return nil, false
	}
	if !p.char('^') {
		return nil, false
	}
	if p.peek() != '[' {
		return nil, false
	}
	oldIn := p.st.inNote
	p.st.inNote = true
	p.st.noteNumber++
	r, ok := p.inlinesInBalancedBrackets()
	p.st.inNote = oldIn
	if !ok {
		return nil, false
	}
	return one(&Note{[]Block{&Para{r}}}), true
}

// ---------- citations ----------

func (p *mdP) getNoteNumber() int {
	if p.st.inNote {
		return p.st.noteNumber
	}
	p.st.noteNumber++
	return p.st.noteNumber
}

func (p *mdP) citeKey(allowBraced bool) (bool, string, bool) {
	s := p.save()
	if !p.notAfterString() {
		return false, "", false
	}
	suppress := p.char('-')
	if !p.char('@') {
		p.restore(s)
		return false, "", false
	}
	if k, ok := p.simpleCiteIdentifier(); ok {
		return suppress, k, true
	}
	if allowBraced && p.peek() == '{' {
		if k, ok := p.charsInBalancedNoSpace('{', '}'); ok {
			return suppress, k, true
		}
	}
	p.restore(s)
	return false, "", false
}

func (p *mdP) charsInBalancedNoSpace(open, close rune) (string, bool) {
	s := p.save()
	if !p.char(open) {
		return "", false
	}
	var sb strings.Builder
	depth := 1
	for !p.eof() {
		c := p.peek()
		if c == close {
			depth--
			if depth == 0 {
				p.pos++
				return sb.String(), true
			}
		} else if c == open {
			depth++
		} else if isSpaceH(c) {
			break
		}
		sb.WriteRune(c)
		p.pos++
	}
	p.restore(s)
	return "", false
}

// charsInBalanced with litChar (for reference titles in parens)
func (p *mdP) charsInBalancedLit(open, close rune) (string, bool) {
	s := p.save()
	if !p.char(open) {
		return "", false
	}
	var sb strings.Builder
	depth := 1
	for !p.eof() {
		c := p.peek()
		if c == close {
			depth--
			if depth == 0 {
				p.pos++
				return sb.String(), true
			}
			sb.WriteRune(c)
			p.pos++
			continue
		} else if c == open {
			depth++
			sb.WriteRune(c)
			p.pos++
			continue
		}
		r, ok := p.litChar()
		if !ok {
			break
		}
		sb.WriteString(r)
	}
	p.restore(s)
	return "", false
}

func isCiteRegChar(c rune) bool { return isAlphaNumH(c) || c == '_' }

func (p *mdP) simpleCiteIdentifier() (string, bool) {
	c := p.peek()
	if !(isAlphaNumH(c) || c == '_' || c == '*') {
		return "", false
	}
	st := p.pos
	p.pos++
	for !p.eof() {
		c := p.peek()
		if isCiteRegChar(c) {
			p.pos++
			continue
		}
		if strings.ContainsRune(":.#$%&-+?<>~/", c) && isCiteRegChar(p.peekAt(1)) {
			p.pos++
			continue
		}
		if (c == ':' || c == '/') && p.peekAt(1) == '/' {
			p.pos++
			continue
		}
		break
	}
	return string(p.s[st:p.pos]), true
}

func (p *mdP) cite() ([]Inline, bool) {
	if !p.ext("citations") {
		return nil, false
	}
	s := p.save()
	if r, ok := p.textualCite(); ok {
		return r, true
	}
	p.restore(s)
	st := p.pos
	cs, ok := p.normalCite()
	if !ok {
		return nil, false
	}
	raw := string(p.s[st:p.pos])
	return one(&Cite{cs, textToInlines(raw)}), true
}

func (p *mdP) normalCite() ([]Citation, bool) {
	var cs []Citation
	ok := p.try(func() bool {
		if !p.char('[') {
			return false
		}
		p.spnl()
		var ok bool
		cs, ok = p.citeList()
		if !ok {
			return false
		}
		p.spnl()
		return p.char(']')
	})
	return cs, ok
}

func (p *mdP) citeList() ([]Citation, bool) {
	var cs []Citation
	c, ok := p.citation()
	if !ok {
		return nil, false
	}
	cs = append(cs, c)
	for {
		s := p.save()
		if p.char(';') {
			p.spnl()
			if c, ok := p.citation(); ok {
				cs = append(cs, c)
				continue
			}
		}
		p.restore(s)
		break
	}
	return cs, true
}

func (p *mdP) citation() (Citation, bool) {
	var c Citation
	ok := p.try(func() bool {
		pref, ok := p.citePrefix()
		if !ok {
			return false
		}
		sup, key, ok := p.citeKey(true)
		if !ok {
			return false
		}
		suff := p.citeSuffix()
		nn := p.getNoteNumber()
		mode := NormalCitation
		if sup {
			mode = SuppressAuthor
		}
		c = Citation{ID: key, Prefix: pref, Suffix: suff, Mode: mode, NoteNum: nn}
		return true
	})
	return c, ok
}

func (p *mdP) citePrefix() ([]Inline, bool) {
	var res []Inline
	for {
		if p.eof() {
			return nil, false
		}
		if p.peek() == ']' {
			// manyTill ... (char ']' <|> lookahead citeKey): char ']' consumed -> but then citeKey fails later
			p.pos++
			return trimInlines(res), true
		}
		if p.look(func() bool {
			p.try(func() bool { return p.char(';') && func() bool { p.spnl(); return true }() })
			_, _, ok := p.citeKey(true)
			return ok
		}) {
			return trimInlines(res), true
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		res = appendInlMut(res, x...)
	}
}

func (p *mdP) citeSuffix() []Inline {
	var res []Inline
	s := p.save()
	hasSpace := p.eof() || isSpaceH(p.peek())
	p.spnl()
	n := 0
	for !p.eof() {
		c := p.peek()
		if c == ';' || c == ']' {
			break
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		res = appendInlMut(res, x...)
		n++
	}
	_ = s
	rest := trimInlines(res)
	if hasSpace && n > 0 {
		return catInl(one(&Space{}), rest)
	}
	return rest
}

func (p *mdP) textualCite() ([]Inline, bool) {
	sup, key, ok := p.citeKey(true)
	if !ok {
		return nil, false
	}
	if _, isEx := p.st.examples[key]; isEx {
		return nil, false
	}
	nn := p.getNoteNumber()
	mode := AuthorInText
	if sup {
		mode = SuppressAuthor
	}
	first := Citation{ID: key, Mode: mode, NoteNum: nn}
	// try spnl >> normalCite
	s := p.save()
	var rest []Citation
	rawStart := 0
	ok = p.try(func() bool {
		p.spnl()
		rawStart = p.pos
		var ok bool
		rest, ok = p.normalCite()
		return ok
	})
	if ok {
		raw := string(p.s[rawStart:p.pos])
		cs := append([]Citation{first}, rest...)
		return one(&Cite{cs, textToInlines("@" + key + " " + raw)}), true
	}
	p.restore(s)
	// bareloc
	s2 := p.save()
	st := p.pos
	if cs, ok := p.bareloc(first); ok {
		raw := string(p.s[st:p.pos])
		trimmed := strings.TrimLeft(raw, " \t\n")
		spaces := raw[:len(raw)-len(trimmed)]
		inner := strings.TrimSuffix(strings.TrimPrefix(trimmed, "["), "]")
		lab := p.sub(inner).inlines()
		// fallback reference link
		sp2 := p.sub(trimmed)
		fbPending, okRL := sp2.referenceLinkFrom(lab, trimmed)
		stt := p.st
		_ = stt
		f := func() []Inline {
			if okRL {
				fb := resolveInlines(p.st, fbPending)
				if len(fb) > 0 {
					if _, isLink := fb[0].(*Link); isLink {
						var spc []Inline
						if spaces != "" {
							spc = one(&Space{})
						}
						return catInl(one(&Cite{[]Citation{first}, one(&Str{"@" + key})}), spc, fb)
					}
				}
			}
			return one(&Cite{cs, textToInlines("@" + key + " " + raw)})
		}
		return one(&pendingInl{f: f}), true
	}
	p.restore(s2)
	st2 := p.st
	f := func() []Inline {
		if n, ok := st2.examples[key]; ok {
			return one(&Str{itoa(n)})
		}
		return one(&Cite{[]Citation{first}, one(&Str{"@" + key})})
	}
	return one(&pendingInl{f: f}), true
}

// referenceLinkFrom: parse "[...]" text (positioned after it) as reference link fallback
func (p *mdP) referenceLinkFrom(lab []Inline, raw string) ([]Inline, bool) {
	// position the parser at end of the bracket text
	if _, ok := p.balancedBracketsRaw(); !ok {
		return nil, false
	}
	return p.referenceLink(false, lab, raw)
}

func (p *mdP) bareloc(c Citation) ([]Citation, bool) {
	var res []Citation
	ok := p.try(func() bool {
		p.spnl()
		if !p.char('[') {
			return false
		}
		if p.peek() == '@' {
			return false
		}
		suff := p.citeSuffix()
		var rest []Citation
		s := p.save()
		if p.char(';') {
			p.spnl()
			if cs, ok := p.citeList(); ok {
				rest = cs
			} else {
				p.restore(s)
			}
		}
		p.spnl()
		if !p.char(']') {
			return false
		}
		c.Suffix = suff
		res = append([]Citation{c}, rest...)
		return true
	})
	return res, ok
}

func (p *mdP) exampleRef() ([]Inline, bool) {
	if !p.ext("example_lists") {
		return nil, false
	}
	if !p.char('@') {
		return nil, false
	}
	st := p.pos
	for isAlphaNumH(p.peek()) || p.peek() == '_' || p.peek() == '-' {
		p.pos++
	}
	lab := string(p.s[st:p.pos])
	if lab == "" {
		return nil, false
	}
	stt := p.st
	f := func() []Inline {
		if n, ok := stt.examples[lab]; ok {
			return one(&Str{itoa(n)})
		}
		return one(&Str{"@" + lab})
	}
	return one(&pendingInl{f: f}), true
}

// ---------- autolinks ----------

func (p *mdP) autoLink() ([]Inline, bool) {
	if !p.char('<') {
		return nil, false
	}
	var orig, src string
	var ok bool
	var cls string
	if orig, src, ok = p.uriP(); ok {
		cls = "uri"
	} else if orig, src, ok = p.emailP(); ok {
		cls = "email"
	} else {
		return nil, false
	}
	var extra strings.Builder
	for {
		if p.eof() {
			return nil, false
		}
		c := p.peek()
		if c == '>' {
			p.pos++
			break
		}
		if isSpaceH(c) {
			return nil, false
		}
		extra.WriteRune(c)
		p.pos++
	}
	ex := decodeEntities(extra.String())
	var attr Attr
	if p.ext("link_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	attr.Classes = append([]string{cls}, attr.Classes...)
	return one(&Link{attr, one(&Str{orig + ex}), Target{src + escapeURI(ex), ""}}), true
}
