func isHTMLNameStart(c rune) bool { return unicode.IsLetter(c) }
func isHTMLNameChar(c rune) bool {
	return isAlphaNumH(c) || c == '-' || c == '_' || c == ':' || c == '.'
}

func isNameH(s string) bool {
	rs := []rune(s)
	if len(rs) == 0 || !unicode.IsLetter(rs[0]) {
		return false
	}
	for _, c := range rs[1:] {
		if !isHTMLNameChar(c) {
