// scanHTMLTag parses a tag starting at s[pos]=='<'. Returns tag and end index.
func scanHTMLTag(s []rune, pos int) (htmlTag, int, bool) {
	n := len(s)
	if pos >= n || s[pos] != '<' {
		return htmlTag{}, 0, false
	}
	i := pos + 1
	if i >= n {
		return htmlTag{}, 0, false
	}
	// comment
	if i+2 < n && s[i] == '!' && s[i+1] == '-' && s[i+2] == '-' {
		j := i + 3
		for j+2 < n {
			if s[j] == '-' && s[j+1] == '-' && s[j+2] == '>' {
				end := j + 3
				return htmlTag{kind: tkComment, raw: string(s[pos:end])}, end, true
			}
			j++
		}
		return htmlTag{}, 0, false
	}
	if s[i] == '?' {
		// processing instruction
		j := i + 1
		for j < n && s[j] != '>' {
			j++
		}
		if j >= n {
			return htmlTag{}, 0, false
		}
		end := j + 1
		nm := ""
		k := i
		for k < n && !isSpaceH(s[k]) && s[k] != '>' {
			k++
		}
		nm = string(s[i:k])
		return htmlTag{kind: tkPI, name: strings.ToLower(nm), raw: string(s[pos:end])}, end, true
	}
	if s[i] == '!' {
		j := i + 1
		for j < n && s[j] != '>' {
			j++
		}
		if j >= n {
			return htmlTag{}, 0, false
		}
		k := i
		for k < n && !isSpaceH(s[k]) && s[k] != '>' {
			k++
		}
		end := j + 1
		return htmlTag{kind: tkDecl, name: string(s[i:k]), raw: string(s[pos:end])}, end, true
	}
	closing := false
	if s[i] == '/' {
		closing = true
		i++
	}
	if i >= n || !isHTMLNameStart(s[i]) {
		return htmlTag{}, 0, false
	}
	st := i
	for i < n && !isSpaceH(s[i]) && s[i] != '>' && s[i] != '/' {
		i++
	}
	name := string(s[st:i])
	if !isNameH(name) || strings.HasSuffix(name, ":") {
