		}
		if i >= n {
			return htmlTag{}, 0, false
		}
		if s[i] == '>' {
			i++
			break
		}
		if s[i] == '/' {
			if i+1 < n && s[i+1] == '>' {
				tag.selfClosing = true
				i += 2
				break
			}
			i++
			continue
		}
		// attribute name
		as := i
		for i < n && !isSpaceH(s[i]) && s[i] != '>' && s[i] != '=' && !(s[i] == '/' && i+1 < n && s[i+1] == '>') {
			if s[i] == '"' || s[i] == '\'' || s[i] == '<' {
				return htmlTag{}, 0, false
			}
			i++
		}
		aname := string(s[as:i])
		if !isNameH(aname) {
			return htmlTag{}, 0, false
		}
		j := i
		for j < n && isSpaceH(s[j]) {
			j++
		}
		val := ""
		if j < n && s[j] == '=' {
			j++
			for j < n && isSpaceH(s[j]) {
				j++
			}
			if j >= n {
				return htmlTag{}, 0, false
			}
			if s[j] == '"' || s[j] == '\'' {
				q := s[j]
				k := j + 1
				for k < n && s[k] != q {
					k++
				}
				if k >= n {
					return htmlTag{}, 0, false
				}
				val = string(s[j+1 : k])
				i = k + 1
			} else {
				k := j
				for k < n && !isSpaceH(s[k]) && s[k] != '>' {
					k++
				}
				val = string(s[j:k])
				i = k
			}
		}
		tag.attrs = append(tag.attrs, [2]string{strings.ToLower(aname), decodeEntities(val)})
	}
	tag.raw = string(s[pos:i])
	return tag, i, true
}

