	"object", "svg", "video", "source")

func makeSet(xs ...string) map[string]bool {
	m := map[string]bool{}
	for _, x := range xs {
		m[x] = true
	}
	return m
}

func isBlockTagName(n string) bool {
	return blockTagSet[n] || eitherBlockOrInlineSet[n]
}

func isInlineTagName(n string) bool {
	return !blockTagSet[n] || eitherBlockOrInlineSet[n]
}

const (
	tagFilterBlock = iota
	tagFilterInline
	tagFilterAny
	tagFilterComment
)

func tagMatches(t htmlTag, filter int) bool {
	switch filter {
	case tagFilterBlock:
		switch t.kind {
		case tkOpen, tkClose:
			return isBlockTagName(t.name)
		case tkComment:
			return true
		case tkPI, tkDecl:
			return true
		}
	case tagFilterInline:
		switch t.kind {
		case tkOpen, tkClose:
			return isInlineTagName(t.name)
		case tkComment:
			return true
		}
		return false
	case tagFilterAny:
		return true
	case tagFilterComment:
		return t.kind == tkComment
	}
	return false
}

func lookupEntity(name string) (string, bool) {
	if strings.HasPrefix(name, "#") {
		num := name[1:]
		var v int64
		var err error
		if strings.HasPrefix(num, "x") || strings.HasPrefix(num, "X") {
			v, err = strconv.ParseInt(num[1:], 16, 32)
		} else {
			v, err = strconv.ParseInt(num, 10, 32)
		}
		if err != nil || num == "" {
			return "", false
		}
		if v == 0 || v > 0x10ffff || (v >= 0xd800 && v <= 0xdfff) {
			return "\ufffd", true
		}
		return string(rune(v)), true
	}
	if name == "" {
		return "", false
	}
	full := "&" + name + ";"
	r := html.UnescapeString(full)
	if r == full {
		return "", false
	}
	// make sure the whole entity was consumed (no legacy prefix match)
	if strings.HasSuffix(r, ";") && !strings.HasSuffix(name, ";") {
		return "", false
	}
	return r, true
}

// decodeEntities replaces &...; entities in a string
func decodeEntities(s string) string {
	if !strings.Contains(s, "&") {
		return s
	}
	var sb strings.Builder
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		if rs[i] == '&' {
			j := i + 1
			for j < len(rs) && j < i+40 && (isAlphaNumH(rs[j]) || rs[j] == '#') {
				j++
			}
			if j < len(rs) && rs[j] == ';' {
				if r, ok := lookupEntity(string(rs[i+1 : j])); ok {
					sb.WriteString(r)
					i = j
					continue
				}
			}
		}
		sb.WriteRune(rs[i])
	}
	return sb.String()
}
