const (
	tkOpen = iota
	tkClose
	tkComment
	tkPI
	tkDecl
)

type htmlTag struct {
	kind        int
	name        string // lowercased
	origName    string
	attrs       [][2]string
	selfClosing bool
	raw         string
}

func isHTMLNameStart(c rune) bool { return unicode.IsLetter(c) }
func isHTMLNameChar(c rune) bool {
	return isAlphaNumH(c) || c == '-' || c == '_' || c == ':' || c == '.'
}

func isNameH(s string) bool {
	rs := []rune(s)
	if len(rs) == 0 || !unicode.IsLetter(rs[0]) {
		return false
	}
	for _, c := range rs[1:] {
		if !isHTMLNameChar(c) {
			return false
		}
	}
	return true
}

// scanHTMLTag parses a tag starting at s[pos]=='<'. Returns tag and end index.
func scanHTMLTag(s []rune, pos int) (htmlTag, int, bool) {
	n := len(s)
	if pos >= n || s[pos] != '<' {
		return htmlTag{}, 0, false
	}
	i := pos + 1
	if i >= n {
		return htmlTag{}, 0, false
	}
	// comment
	if i+2 < n && s[i] == '!' && s[i+1] == '-' && s[i+2] == '-' {
		j := i + 3
		for j+2 < n {
			if s[j] == '-' && s[j+1] == '-' && s[j+2] == '>' {
				end := j + 3
				return htmlTag{kind: tkComment, raw: string(s[pos:end])}, end, true
			}
			j++
		}
		return htmlTag{}, 0, false
	}
	if s[i] == '?' {
		// processing instruction
		j := i + 1
		for j < n && s[j] != '>' {
			j++
		}
		if j >= n {
			return htmlTag{}, 0, false
		}
		end := j + 1
		nm := ""
		k := i
		for k < n && !isSpaceH(s[k]) && s[k] != '>' {
			k++
		}
		nm = string(s[i:k])
		return htmlTag{kind: tkPI, name: strings.ToLower(nm), raw: string(s[pos:end])}, end, true
	}
	if s[i] == '!' {
		j := i + 1
		for j < n && s[j] != '>' {
			j++
		}
		if j >= n {
			return htmlTag{}, 0, false
		}
		k := i
		for k < n && !isSpaceH(s[k]) && s[k] != '>' {
			k++
		}
		end := j + 1
		return htmlTag{kind: tkDecl, name: string(s[i:k]), raw: string(s[pos:end])}, end, true
	}
	closing := false
	if s[i] == '/' {
		closing = true
		i++
	}
	if i >= n || !isHTMLNameStart(s[i]) {
		return htmlTag{}, 0, false
	}
	st := i
	for i < n && !isSpaceH(s[i]) && s[i] != '>' && s[i] != '/' {
		i++
	}
	name := string(s[st:i])
	if !isNameH(name) || strings.HasSuffix(name, ":") {
		return htmlTag{}, 0, false
	}
	tag := htmlTag{name: strings.ToLower(name), origName: name}
	if closing {
		tag.kind = tkClose
		for i < n && isSpaceH(s[i]) {
			i++
		}
		if i >= n || s[i] != '>' {
			return htmlTag{}, 0, false
		}
		i++
		tag.raw = string(s[pos:i])
		return tag, i, true
	}
	tag.kind = tkOpen
	for {
		for i < n && isSpaceH(s[i]) {
			i++
		}
		if i >= n {
			return htmlTag{}, 0, false
		}
		if s[i] == '>' {
			i++
			break
		}
		if s[i] == '/' {
			if i+1 < n && s[i+1] == '>' {
				tag.selfClosing = true
				i += 2
				break
			}
			i++
			continue
		}
		// attribute name
		as := i
		for i < n && !isSpaceH(s[i]) && s[i] != '>' && s[i] != '=' && !(s[i] == '/' && i+1 < n && s[i+1] == '>') {
			if s[i] == '"' || s[i] == '\'' || s[i] == '<' {
				return htmlTag{}, 0, false
			}
			i++
		}
		aname := string(s[as:i])
		if !isNameH(aname) {
			return htmlTag{}, 0, false
		}
		j := i
		for j < n && isSpaceH(s[j]) {
			j++
		}
		val := ""
		if j < n && s[j] == '=' {
			j++
			for j < n && isSpaceH(s[j]) {
				j++
			}
			if j >= n {
				return htmlTag{}, 0, false
			}
			if s[j] == '"' || s[j] == '\'' {
				q := s[j]
				k := j + 1
				for k < n && s[k] != q {
					k++
				}
				if k >= n {
					return htmlTag{}, 0, false
				}
				val = string(s[j+1 : k])
				i = k + 1
			} else {
				k := j
				for k < n && !isSpaceH(s[k]) && s[k] != '>' {
					k++
				}
				val = string(s[j:k])
				i = k
			}
		}
		tag.attrs = append(tag.attrs, [2]string{strings.ToLower(aname), decodeEntities(val)})
	}
	tag.raw = string(s[pos:i])
	return tag, i, true
}

