func isURIWordChar(c rune) bool {
	switch c {
	case '#', '$', '%', '+', '/', '@', '\\', '_', '-', '&', '=':
		return true
	}
	return isAlphaNumH(c)
}

// uriP parses a URI at current position, returning (orig, escaped)
func (p *mdP) uriP() (string, string, bool) {
	s := p.save()
	// scheme: letters, digits, +, -, .
	st := p.pos
	for !p.eof() {
		c := p.peek()
		if isAlphaNumH(c) && c < 128 || c == '+' || c == '-' || c == '.' {
			p.pos++
			continue
		}
		break
	}
	scheme := string(p.s[st:p.pos])
	if scheme == "" || !uriSchemes[strings.ToLower(scheme)] || !p.char(':') {
		p.restore(s)
		return "", "", false
	}
	c := p.peek()
	if c == '*' || c == '_' || c == ']' {
		p.restore(s)
		return "", "", false
	}
	var sb strings.Builder
	n := 0
	for {
		if r, ok := p.uriChunkBetween('(', ')'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunkBetween('{', '}'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunkBetween('[', ']'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunk(); ok {
			sb.WriteString(r)
			n++
			continue
		}
		break
	}
	if n == 0 {
		p.restore(s)
		return "", "", false
	}
	str := sb.String()
	if p.char('/') {
		str += "/"
	}
	u := scheme + ":" + decodeEntities(str)
	return u, escapeURI(u), true
}

func (p *mdP) uriChunkBetween(l, r rune) (string, bool) {
	s := p.save()
	if !p.char(l) {
		return "", false
	}
	c, ok := p.uriChunk()
	if !ok || !p.char(r) {
		p.restore(s)
		return "", false
	}
	return string(l) + c + string(r), true
}

func (p *mdP) uriChunk() (string, bool) {
	// many1 wordChar
	st := p.pos
	for !p.eof() && isURIWordChar(p.peek()) {
		p.pos++
	}
	if p.pos > st {
		return string(p.s[st:p.pos]), true
	}
	// percent escaped
	if p.peek() == '%' && isHexDigit(p.peekAt(1)) {
		p.pos++
		for isHexDigit(p.peek()) {
			p.pos++
		}
		return string(p.s[st:p.pos]), true
	}
	// entity
	if p.peek() == '&' {
		if r, ok := p.charEntity(); ok {
			return r, true
		}
	}
	// punct followed by wordchar
	s := p.save()
	var punct string
	if p.peek() == ',' {
		for p.peek() == ',' {
			p.pos++
		}
		punct = string(p.s[st:p.pos])
	} else {
		c := p.peek()
		if c == 0 || isSpaceH(c) || c == '<' || c == '>' {
			return "", false
		}
		p.pos++
		punct = string(c)
	}
	nc := p.peek()
	if isURIWordChar(nc) || (nc == '%' && isHexDigit(p.peekAt(1))) {
		return punct, true
	}
	p.restore(s)
	return "", false
}

func isHexDigit(c rune) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func isEmailChar(c rune) bool {
	return isAlphaNumH(c) || strings.ContainsRune("!\"#$%&'*+-/=?^_{|}~;", c)
}

func (p *mdP) emailP() (string, string, bool) {
	s := p.save()
	var words []string
	for {
		if !isAlphaNumH(p.peek()) {
			break
		}
		st := p.pos
		p.pos++
		for isEmailChar(p.peek()) {
			p.pos++
		}
		words = append(words, string(p.s[st:p.pos]))
		if p.peek() == '.' && isAlphaNumH(p.peekAt(1)) {
			p.pos++
			continue
		}
		break
	}
	if len(words) == 0 || !p.char('@') {
		p.restore(s)
		return "", "", false
	}
	var doms []string
	for {
		st := p.pos
		for !p.eof() {
			c := p.peek()
			if isAlphaNumH(c) {
				p.pos++
				continue
			}
			if c == '-' && isAlphaNumH(p.peekAt(1)) {
				p.pos++
				continue
			}
			break
		}
		if p.pos == st {
			break
		}
		doms = append(doms, string(p.s[st:p.pos]))
		if p.peek() == '.' && isAlphaNumH(p.peekAt(1)) {
			p.pos++
			continue
		}
		break
	}
	if len(doms) == 0 {
		p.restore(s)
		return "", "", false
	}
	full := decodeEntities(strings.Join(words, ".") + "@" + strings.Join(doms, "."))
	return full, escapeURI("mailto:" + full), true
}

// ---------- raw html ----------

func (p *mdP) htmlTagP(filter int) (htmlTag, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || !tagMatches(t, filter) {
		return htmlTag{}, false
	}
	p.pos = end
	return t, true
}

func (p *mdP) isCloseBlockTag(t htmlTag) bool {
	return p.st.inHtmlBlock != "" && t.kind == tkClose && t.name == p.st.inHtmlBlock
}

func (p *mdP) rawHtmlInline() ([]Inline, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	mdInHtml := p.ext("markdown_in_html_blocks") || p.ext("markdown_attribute")
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok {
		return nil, false
	}
	if mdInHtml {
		if !tagMatches(t, tagFilterInline) || p.isCloseBlockTag(t) {
			return nil, false
		}
	}
	p.pos = end
	return one(&RawInline{"html", t.raw}), true
}

func (p *mdP) spanHtml() ([]Inline, bool) {
	if !p.ext("native_spans") {
		return nil, false
	}
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || t.name != "span" {
		return nil, false
	}
	p.pos = end
	if t.selfClosing {
		return nil, false
	}
	var contents []Inline
	for {
		if p.eof() {
			return nil, false
		}
		if ct, e2, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == "span" {
			p.pos = e2
			break
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		contents = appendInlMut(contents, x...)
	}
	attr := htmlAttrsToAttr(t.attrs)
	return wrapSpan(attr, trimInlines(contents)), true
}

func htmlAttrsToAttr(attrs [][2]string) Attr {
	var a Attr
	for _, kv := range attrs {
		switch kv[0] {
		case "id":
			a.ID = kv[1]
		case "class":
			a.Classes = append(a.Classes, strings.Fields(kv[1])...)
		default:
			k := kv[0]
			a.KVs = append(a.KVs, [2]string{k, kv[1]})
		}
	}
	return a
}

func (p *mdP) followedByHtmlCloser() bool {
	if p.st.inHtmlBlock == "" {
		return false
	}
	t, _, ok := scanHTMLTag(p.s, p.pos)
	return ok && t.kind == tkClose && t.name == p.st.inHtmlBlock
}

func (p *mdP) htmlDivClose() bool {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if ok && t.kind == tkClose && t.name == "div" {
		p.pos = end
		return true
	}
	return false
}

func (p *mdP) divHtml() ([]Block, bool) {
	if !p.ext("native_divs") {
		return nil, false
	}
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || t.name != "div" {
		return nil, false
	}
	p.pos = end
	// rest of line must be blank? pandoc: optional blanklines after open tag
	oldIn := p.st.inHtmlBlock
	p.st.inHtmlBlock = "div"
	p.blanklines()
	var bs []Block
	closed := false
	for !p.eof() {
		s := p.save()
		p.skipSpaces()
		if p.htmlDivClose() {
			closed = true
			break
		}
		p.restore(s)
		b, ok := p.block()
		if !ok {
			break
		}
		bs = append(bs, b...)
	}
	p.st.inHtmlBlock = oldIn
	if !closed {
		return nil, false
	}
	p.skipSpaces()
	p.blanklines()
	attr := htmlAttrsToAttr(t.attrs)
	return []Block{&Div{attr, bs}}, true
}

var verbatimTags = makeSet("pre", "style", "script", "textarea")

func (p *mdP) htmlBlock() ([]Block, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	t, _, ok := scanHTMLTag(p.s, p.pos)
	if !ok || !tagMatches(t, tagFilterBlock) {
		return nil, false
	}
	if t.kind == tkOpen && !verbatimTags[t.name] {
		md, hasMd := "", false
		for _, kv := range t.attrs {
			if kv[0] == "markdown" {
				md, hasMd = kv[1], true
			}
		}
		if (hasMd && md == "1") || (p.ext("markdown_in_html_blocks") && !(hasMd && md == "0")) {
			s := p.save()
			if r, ok := p.rawHtmlBlocks(); ok {
				return r, true
			}
			p.restore(s)
		}
	}
	return p.htmlBlockPrime()
}

func (p *mdP) htmlBlockPrime() ([]Block, bool) {
	raw, ok := p.htmlElement()
	if !ok {
		return nil, false
	}
	p.skipSpaces()
	p.blanklines()
	if raw == "" {
		return nil, true
	}
	return []Block{&RawBlock{"html", raw}}, true
}

// htmlElement: verbatim block, strict block or single block tag
func (p *mdP) htmlElement() (string, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok {
		return "", false
	}
	if t.kind == tkOpen && verbatimTags[t.name] && !t.selfClosing {
		// find matching close
		st := p.pos
		i := end
		for i < len(p.s) {
			if p.s[i] == '<' {
				if ct, e2, ok := scanHTMLTag(p.s, i); ok && ct.kind == tkClose && ct.name == t.name {
					p.pos = e2
					return string(p.s[st:e2]), true
				}
			}
			i++
		}
		return "", false
	}
	if t.kind == tkOpen && isBlockTagName(t.name) && !t.selfClosing {
		// strictHtmlBlock: htmlInBalanced
		st := p.pos
		if e, ok := htmlInBalanced(p.s, p.pos, t.name); ok {
			p.pos = e
			return string(p.s[st:e]), true
		}
	}
	if !tagMatches(t, tagFilterBlock) {
		return "", false
	}
	p.pos = end
	return t.raw, true
}

// htmlInBalanced finds the end of an element with balanced tags of the same name
func htmlInBalanced(s []rune, pos int, name string) (int, bool) {
	depth := 0
	i := pos
	for i < len(s) {
		if s[i] == '<' {
			if t, e, ok := scanHTMLTag(s, i); ok {
				if t.name == name {
					if t.kind == tkOpen && !t.selfClosing {
						depth++
					} else if t.kind == tkClose {
						depth--
						if depth == 0 {
							return e, true
						}
					}
				}
				i = e
				continue
			}
		}
		i++
	}
	return 0, false
}

func (p *mdP) rawHtmlBlocks() ([]Block, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || !tagMatches(t, tagFilterBlock) {
		return nil, false
	}
	p.pos = end
	raw := t.raw
	selfClosing := strings.HasSuffix(raw, "/>")
	p.skipSpaces()
	indent := 0
	for p.peek() == ' ' {
		p.pos++
		indent++
	}
	oldIn := p.st.inHtmlBlock
	p.st.inHtmlBlock = t.name
	var contents []Block
	if !selfClosing {
		for !p.eof() {
			s := p.save()
			p.gobbleAtMostSpaces(indent)
			if ct, _, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == t.name {
				p.restore(s)
				break
			}
			b, ok := p.block()
			if !ok {
				p.restore(s)
				break
			}
			contents = append(contents, b...)
		}
	}
	var result []Block
	s := p.save()
	p.gobbleAtMostSpaces(indent)
	if ct, e2, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == t.name {
		p.pos = e2
		result = append(result, &RawBlock{"html", stripMarkdownAttribute(raw)})
		result = append(result, contents...)
		result = append(result, &RawBlock{"html", ct.raw})
	} else {
		p.restore(s)
		result = append(result, &RawBlock{"html", raw})
		result = append(result, contents...)
	}
	p.st.inHtmlBlock = oldIn
	return result, true
}

func stripMarkdownAttribute(raw string) string {
	// remove markdown="1" attribute
	for _, a := range []string{` markdown="1"`, ` markdown='1'`, ` markdown=1`} {
		raw = strings.Replace(raw, a, "", 1)
	}
	return raw
}

// ---------- raw tex ----------

type latexMacro struct {
	nargs int
	body  string
	opt   *string
}

var blockLatexCommands = makeSet("section", "subsection", "subsubsection", "paragraph", "subparagraph",
	"chapter", "part", "addchap", "addsec", "maketitle", "tableofcontents", "listoffigures", "listoftables",
	"newpage", "clearpage", "cleardoublepage", "pagebreak", "vspace", "vskip", "hrule", "bibliography",
	"bibliographystyle", "title", "author", "date", "documentclass", "usepackage", "frontmatter",
	"mainmatter", "backmatter", "appendix", "printbibliography", "item", "caption", "centering",
	"setlength", "addtolength", "newcommand", "renewcommand", "providecommand", "newenvironment",
	"renewenvironment", "def", "let", "include", "input", "subfile", "bigskip", "medskip", "smallskip",
	"linebreak", "newline", "nocite", "hline", "toprule", "midrule", "bottomrule", "graphicspath",
	"pagestyle", "thispagestyle", "geometry", "hypersetup", "setcounter", "addcontentsline",
	"onecolumn", "twocolumn", "raggedright", "raggedleft", "flushbottom", "lstset", "label",
	"dedication", "subtitle", "institute", "abstract", "keywords", "thanks", "markboth", "markright",
	"titlepage", "endinput", "makeatletter", "makeatother", "DeclareMathOperator", "newtheorem",
	"theoremstyle", "pagenumbering")

var mathEnvs = makeSet("equation", "equation*", "align", "align*", "gather", "gather*", "multline", "multline*",
	"eqnarray", "eqnarray*", "flalign", "flalign*", "alignat", "alignat*", "math", "displaymath", "dmath", "dmath*")

// scan a LaTeX command at pos (s[pos]=='\\'); returns end
func scanLatexCommand(s []rune, pos int, inline bool) (int, string, bool) {
	n := len(s)
	if pos >= n || s[pos] != '\\' {
		return 0, "", false
	}
	i := pos + 1
	if i >= n || !isLatexLetter(s[i]) {
		return 0, "", false
	}
	st := i
	for i < n && isLatexLetter(s[i]) {
		i++
	}
	name := string(s[st:i])
	if i < n && s[i] == '*' {
		i++
		name += "*"
	}
	// skip spaces after control word (no newline? allow one newline not blank)
	j := i
	for j < n && (s[j] == ' ' || s[j] == '\t') {
		j++
	}
	afterSp := j
	i = j
	// arguments
	for {
		k := i
		for k < n && (s[k] == ' ' || s[k] == '\t') {
			k++
		}
		if k < n && s[k] == '[' {
			e, ok := scanBalanced(s, k, '[', ']')
			if !ok {
				break
			}
			i = e
			for i < n && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			continue
		}
		if i < n && s[i] == '{' {
			e, ok := scanBalanced(s, i, '{', '}')
			if !ok {
				return 0, "", false
			}
			i = e
			continue
		}
		break
	}
	if i == afterSp {
		// no args: include trailing spaces
		return afterSp, name, true
	}
	return i, name, true
}

func isLatexLetter(c rune) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '@' }

func scanBalanced(s []rune, pos int, open, close rune) (int, bool) {
	depth := 0
	i := pos
	for i < len(s) {
		c := s[i]
		if c == '\\' {
			i += 2
			continue
		}
		if c == open {
			depth++
		} else if c == close {
			depth--
			if depth == 0 {
				return i + 1, true
			}
		}
		i++
	}
	return 0, false
}

func scanLatexEnv(s []rune, pos int) (int, string, bool) {
	str := string(s[pos:min(len(s), pos+7)])
	if str != "\\begin{" {
		return 0, "", false
	}
	i := pos + 7
	st := i
	for i < len(s) && s[i] != '}' && s[i] != '\n' {
		i++
	}
	if i >= len(s) || s[i] != '}' {
		return 0, "", false
	}
	name := string(s[st:i])
	endStr := []rune("\\end{" + name + "}")
	beginStr := []rune("\\begin{" + name + "}")
	depth := 1
	j := i + 1
	for j < len(s) {
		if hasRunesAt(s, j, beginStr) {
			depth++
			j += len(beginStr)
			continue
		}
		if hasRunesAt(s, j, endStr) {
			depth--
			j += len(endStr)
			if depth == 0 {
				return j, name, true
			}
			continue
		}
		j++
	}
	return 0, "", false
}

func hasRunesAt(s []rune, pos int, sub []rune) bool {
	if pos+len(sub) > len(s) {
		return false
	}
	for i, c := range sub {
		if s[pos+i] != c {
			return false
		}
	}
	return true
}

func (p *mdP) rawTeXBlock() ([]Block, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	if p.peek() != '\\' || !isLatexLetter(p.peekAt(1)) {
		return nil, false
	}
	var parts []string
	for {
		if p.peek() != '\\' {
			break
		}
		st := p.pos
		if e, name, ok := scanLatexEnv(p.s, p.pos); ok {
			if mathEnvs[name] {
				break
			}
			p.pos = e
		} else if e, name, ok := scanLatexCommand(p.s, p.pos, false); ok {
			if name == "begin" || name == "end" {
				break
			}
			if !blockLatexCommands[strings.TrimSuffix(name, "*")] {
				break
			}
			if p.handleMacroDef(name, string(p.s[st:e])) {
				p.pos = e
				p.spnlRaw()
				parts = append(parts, "")
				continue
			}
			p.pos = e
		} else {
			break
		}
		raw := string(p.s[st:p.pos])
		sp := p.spnlRaw()
		parts = append(parts, raw+sp)
	}
	if len(parts) == 0 {
		return nil, false
	}
	res := strings.TrimSpace(strings.Join(parts, ""))
	p.blanklines()
	if res == "" {
		return nil, true
	}
	return []Block{&RawBlock{"tex", res}}, true
}

func (p *mdP) spnlRaw() string {
	st := p.pos
	p.skipSpaces()
	s := p.save()
	if p.newline() {
		if p.isBlankLineAhead() {
			p.restore(s)
		} else {
			p.skipSpaces()
		}
	}
	return string(p.s[st:p.pos])
}

func (p *mdP) rawLaTeXInlineP() ([]Inline, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	if p.peek() != '\\' {
		return nil, false
	}
	st := p.pos
	if e, _, ok := scanLatexEnv(p.s, p.pos); ok {
		p.pos = e
		return one(&RawInline{"tex", string(p.s[st:e])}), true
	}
	e, name, ok := scanLatexCommand(p.s, p.pos, true)
	if !ok {
		return nil, false
	}
	raw := string(p.s[st:e])
	if m, ok := p.st.macros[name]; ok {
		p.pos = e
		exp := expandMacroUse(m, raw, name)
		return one(&RawInline{"tex", exp}), true
	}
	p.pos = e
	return one(&RawInline{"tex", raw}), true
}

func (p *mdP) handleMacroDef(name, raw string) bool {
	if !p.ext("latex_macros") {
		return false
	}
	if name != "newcommand" && name != "renewcommand" && name != "providecommand" {
		return false
	}
	// \newcommand{\foo}[n]{body}
	rs := []rune(raw)
	i := len([]rune("\\" + name))
	for i < len(rs) && rs[i] == ' ' {
		i++
	}
	var mname string
	if i < len(rs) && rs[i] == '{' {
		e, ok := scanBalanced(rs, i, '{', '}')
		if !ok {
			return false
		}
		mname = strings.TrimSpace(string(rs[i+1 : e-1]))
		i = e
	} else if i < len(rs) && rs[i] == '\\' {
		st := i
		i++
		for i < len(rs) && isLatexLetter(rs[i]) {
			i++
		}
		mname = string(rs[st:i])
	} else {
		return false
	}
	nargs := 0
	if i < len(rs) && rs[i] == '[' {
		e, ok := scanBalanced(rs, i, '[', ']')
		if !ok {
			return false
		}
		nargs, _ = strconv.Atoi(string(rs[i+1 : e-1]))
		i = e
	}
	if i < len(rs) && rs[i] == '{' {
		e, ok := scanBalanced(rs, i, '{', '}')
		if !ok {
			return false
		}
		body := string(rs[i+1 : e-1])
		mname = strings.TrimPrefix(mname, "\\")
		if name == "providecommand" {
			if _, exists := p.st.macros[mname]; exists {
				return true
			}
		}
		p.st.macros[mname] = latexMacro{nargs: nargs, body: body}
		return true
	}
	return false
}

func expandMacroUse(m latexMacro, raw string, name string) string {
	if m.nargs == 0 {
		rest := strings.TrimPrefix(raw, "\\"+name)
		rest = strings.TrimLeft(rest, " ")
		return m.body + rest
	}
	rs := []rune(raw)
	i := len([]rune("\\" + name))
	var args []string
	for len(args) < m.nargs && i < len(rs) {
		for i < len(rs) && rs[i] == ' ' {
			i++
		}
		if i < len(rs) && rs[i] == '{' {
			e, ok := scanBalanced(rs, i, '{', '}')
			if !ok {
				break
			}
			args = append(args, string(rs[i+1:e-1]))
			i = e
		} else {
			break
		}
	}
	body := m.body
	for k, a := range args {
		body = strings.ReplaceAll(body, "#"+itoa(k+1), a)
	}
	return body + string(rs[i:])
}

func (p *mdP) applyMacros(s string) string {
	if len(p.st.macros) == 0 || !p.ext("latex_macros") {
		return s
	}
	rs := []rune(s)
	var sb strings.Builder
	for i := 0; i < len(rs); i++ {
		if rs[i] == '\\' && i+1 < len(rs) && isLatexLetter(rs[i+1]) {
			j := i + 1
			for j < len(rs) && isLatexLetter(rs[j]) {
				j++
			}
			name := string(rs[i+1 : j])
			if m, ok := p.st.macros[name]; ok {
				// collect args
				k := j
				var args []string
				for len(args) < m.nargs && k < len(rs) {
					for k < len(rs) && rs[k] == ' ' {
						k++
					}
					if k < len(rs) && rs[k] == '{' {
						e, ok := scanBalanced(rs, k, '{', '}')
						if !ok {
							break
						}
						args = append(args, string(rs[k+1:e-1]))
						k = e
					} else {
						break
					}
				}
				body := m.body
				for n, a := range args {
					body = strings.ReplaceAll(body, "#"+itoa(n+1), a)
				}
				sb.WriteString(body)
				i = k - 1
				continue
			}
			sb.WriteString(string(rs[i:j]))
			i = j - 1
			continue
		}
		sb.WriteRune(rs[i])
	}
	return sb.String()
}
EOF
echo ok"}

