func isURIWordChar(c rune) bool {
	switch c {
	case '#', '$', '%', '+', '/', '@', '\\', '_', '-', '&', '=':
		return true
	}
	return isAlphaNumH(c)
}

// uriP parses a URI at current position, returning (orig, escaped)
func (p *mdP) uriP() (string, string, bool) {
	s := p.save()
	// scheme: letters, digits, +, -, .
	st := p.pos
	for !p.eof() {
		c := p.peek()
		if isAlphaNumH(c) && c < 128 || c == '+' || c == '-' || c == '.' {
			p.pos++
			continue
		}
		break
	}
	scheme := string(p.s[st:p.pos])
	if scheme == "" || !uriSchemes[strings.ToLower(scheme)] || !p.char(':') {
		p.restore(s)
		return "", "", false
	}
	c := p.peek()
	if c == '*' || c == '_' || c == ']' {
		p.restore(s)
		return "", "", false
	}
	var sb strings.Builder
	n := 0
	for {
		if r, ok := p.uriChunkBetween('(', ')'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunkBetween('{', '}'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunkBetween('[', ']'); ok {
			sb.WriteString(r)
			n++
			continue
		}
		if r, ok := p.uriChunk(); ok {
			sb.WriteString(r)
			n++
			continue
		}
		break
	}
	if n == 0 {
		p.restore(s)
		return "", "", false
	}
	str := sb.String()
	if p.char('/') {
		str += "/"
	}
	u := scheme + ":" + decodeEntities(str)
	return u, escapeURI(u), true
}

func (p *mdP) uriChunkBetween(l, r rune) (string, bool) {
	s := p.save()
	if !p.char(l) {
		return "", false
	}
	c, ok := p.uriChunk()
	if !ok || !p.char(r) {
		p.restore(s)
		return "", false
	}
	return string(l) + c + string(r), true
}

func (p *mdP) uriChunk() (string, bool) {
	// many1 wordChar
	st := p.pos
	for !p.eof() && isURIWordChar(p.peek()) {
		p.pos++
	}
	if p.pos > st {
		return string(p.s[st:p.pos]), true
	}
	// percent escaped
	if p.peek() == '%' && isHexDigit(p.peekAt(1)) {
		p.pos++
		for isHexDigit(p.peek()) {
			p.pos++
		}
		return string(p.s[st:p.pos]), true
	}
	// entity
	if p.peek() == '&' {
		if r, ok := p.charEntity(); ok {
			return r, true
		}
	}
	// punct followed by wordchar
	s := p.save()
	var punct string
	if p.peek() == ',' {
		for p.peek() == ',' {
			p.pos++
		}
		punct = string(p.s[st:p.pos])
	} else {
		c := p.peek()
		if c == 0 || isSpaceH(c) || c == '<' || c == '>' {
			return "", false
		}
		p.pos++
		punct = string(c)
	}
	nc := p.peek()
	if isURIWordChar(nc) || (nc == '%' && isHexDigit(p.peekAt(1))) {
		return punct, true
	}
	p.restore(s)
	return "", false
}

func isHexDigit(c rune) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func isEmailChar(c rune) bool {
	return isAlphaNumH(c) || strings.ContainsRune("!\"#$%&'*+-/=?^_{|}~;", c)
}

func (p *mdP) emailP() (string, string, bool) {
	s := p.save()
	var words []string
	for {
		if !isAlphaNumH(p.peek()) {
			break
		}
		st := p.pos
		p.pos++
		for isEmailChar(p.peek()) {
			p.pos++
		}
		words = append(words, string(p.s[st:p.pos]))
		if p.peek() == '.' && isAlphaNumH(p.peekAt(1)) {
			p.pos++
			continue
		}
		break
	}
	if len(words) == 0 || !p.char('@') {
		p.restore(s)
		return "", "", false
	}
	var doms []string
	for {
		st := p.pos
		for !p.eof() {
			c := p.peek()
			if isAlphaNumH(c) {
				p.pos++
				continue
			}
			if c == '-' && isAlphaNumH(p.peekAt(1)) {
				p.pos++
				continue
			}
			break
		}
		if p.pos == st {
			break
		}
		doms = append(doms, string(p.s[st:p.pos]))
		if p.peek() == '.' && isAlphaNumH(p.peekAt(1)) {
			p.pos++
			continue
		}
		break
	}
	if len(doms) == 0 {
		p.restore(s)
		return "", "", false
	}
	full := decodeEntities(strings.Join(words, ".") + "@" + strings.Join(doms, "."))
	return full, escapeURI("mailto:" + full), true
}

