func (p *mdP) htmlTagP(filter int) (htmlTag, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || !tagMatches(t, filter) {
		return htmlTag{}, false
	}
	p.pos = end
	return t, true
}

func (p *mdP) isCloseBlockTag(t htmlTag) bool {
	return p.st.inHtmlBlock != "" && t.kind == tkClose && t.name == p.st.inHtmlBlock
}

func (p *mdP) rawHtmlInline() ([]Inline, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	mdInHtml := p.ext("markdown_in_html_blocks") || p.ext("markdown_attribute")
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok {
		return nil, false
	}
	if mdInHtml {
		if !tagMatches(t, tagFilterInline) || p.isCloseBlockTag(t) {
			return nil, false
		}
	}
	p.pos = end
	return one(&RawInline{"html", t.raw}), true
}

func (p *mdP) spanHtml() ([]Inline, bool) {
	if !p.ext("native_spans") {
		return nil, false
	}
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || t.name != "span" {
		return nil, false
	}
	p.pos = end
	if t.selfClosing {
		return nil, false
	}
	var contents []Inline
	for {
		if p.eof() {
			return nil, false
		}
		if ct, e2, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == "span" {
			p.pos = e2
			break
		}
		x, ok := p.inline()
		if !ok {
			return nil, false
		}
		contents = appendInlMut(contents, x...)
	}
	attr := htmlAttrsToAttr(t.attrs)
	return wrapSpan(attr, trimInlines(contents)), true
}

func htmlAttrsToAttr(attrs [][2]string) Attr {
	var a Attr
	for _, kv := range attrs {
		switch kv[0] {
		case "id":
			a.ID = kv[1]
		case "class":
			a.Classes = append(a.Classes, strings.Fields(kv[1])...)
		default:
			k := kv[0]
			a.KVs = append(a.KVs, [2]string{k, kv[1]})
		}
	}
	return a
}

func (p *mdP) followedByHtmlCloser() bool {
	if p.st.inHtmlBlock == "" {
		return false
	}
	t, _, ok := scanHTMLTag(p.s, p.pos)
	return ok && t.kind == tkClose && t.name == p.st.inHtmlBlock
}

func (p *mdP) htmlDivClose() bool {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if ok && t.kind == tkClose && t.name == "div" {
		p.pos = end
		return true
	}
	return false
}

func (p *mdP) divHtml() ([]Block, bool) {
	if !p.ext("native_divs") {
		return nil, false
	}
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || t.name != "div" {
		return nil, false
	}
	p.pos = end
	// rest of line must be blank? pandoc: optional blanklines after open tag
	oldIn := p.st.inHtmlBlock
	p.st.inHtmlBlock = "div"
	p.blanklines()
	var bs []Block
	closed := false
	for !p.eof() {
		s := p.save()
		p.skipSpaces()
		if p.htmlDivClose() {
			closed = true
			break
		}
		p.restore(s)
		b, ok := p.block()
		if !ok {
			break
		}
		bs = append(bs, b...)
	}
	p.st.inHtmlBlock = oldIn
	if !closed {
		return nil, false
	}
	p.skipSpaces()
	p.blanklines()
	attr := htmlAttrsToAttr(t.attrs)
	return []Block{&Div{attr, bs}}, true
}

var verbatimTags = makeSet("pre", "style", "script", "textarea")

func (p *mdP) htmlBlock() ([]Block, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	t, _, ok := scanHTMLTag(p.s, p.pos)
	if !ok || !tagMatches(t, tagFilterBlock) {
		return nil, false
	}
	if t.kind == tkOpen && !verbatimTags[t.name] {
		md, hasMd := "", false
		for _, kv := range t.attrs {
			if kv[0] == "markdown" {
				md, hasMd = kv[1], true
			}
		}
		if (hasMd && md == "1") || (p.ext("markdown_in_html_blocks") && !(hasMd && md == "0")) {
			s := p.save()
			if r, ok := p.rawHtmlBlocks(); ok {
				return r, true
			}
			p.restore(s)
		}
	}
	return p.htmlBlockPrime()
}

func (p *mdP) htmlBlockPrime() ([]Block, bool) {
	raw, ok := p.htmlElement()
	if !ok {
		return nil, false
	}
	p.skipSpaces()
	p.blanklines()
	if raw == "" {
		return nil, true
	}
	return []Block{&RawBlock{"html", raw}}, true
}

// htmlElement: verbatim block, strict block or single block tag
func (p *mdP) htmlElement() (string, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok {
		return "", false
	}
	if t.kind == tkOpen && verbatimTags[t.name] && !t.selfClosing {
		// find matching close
		st := p.pos
		i := end
		for i < len(p.s) {
			if p.s[i] == '<' {
				if ct, e2, ok := scanHTMLTag(p.s, i); ok && ct.kind == tkClose && ct.name == t.name {
					p.pos = e2
					return string(p.s[st:e2]), true
				}
			}
			i++
		}
		return "", false
	}
	if t.kind == tkOpen && isBlockTagName(t.name) && !t.selfClosing {
		// strictHtmlBlock: htmlInBalanced
		st := p.pos
		if e, ok := htmlInBalanced(p.s, p.pos, t.name); ok {
			p.pos = e
			return string(p.s[st:e]), true
		}
	}
	if !tagMatches(t, tagFilterBlock) {
		return "", false
	}
	p.pos = end
	return t.raw, true
}

// htmlInBalanced finds the end of an element with balanced tags of the same name
func htmlInBalanced(s []rune, pos int, name string) (int, bool) {
	depth := 0
	i := pos
	for i < len(s) {
		if s[i] == '<' {
			if t, e, ok := scanHTMLTag(s, i); ok {
				if t.name == name {
					if t.kind == tkOpen && !t.selfClosing {
						depth++
					} else if t.kind == tkClose {
						depth--
						if depth == 0 {
							return e, true
						}
					}
				}
				i = e
				continue
			}
		}
		i++
	}
	return 0, false
}

func (p *mdP) rawHtmlBlocks() ([]Block, bool) {
	t, end, ok := scanHTMLTag(p.s, p.pos)
	if !ok || t.kind != tkOpen || !tagMatches(t, tagFilterBlock) {
		return nil, false
	}
	p.pos = end
	raw := t.raw
	selfClosing := strings.HasSuffix(raw, "/>")
	p.skipSpaces()
	indent := 0
	for p.peek() == ' ' {
		p.pos++
		indent++
	}
	oldIn := p.st.inHtmlBlock
	p.st.inHtmlBlock = t.name
	var contents []Block
	if !selfClosing {
		for !p.eof() {
			s := p.save()
			p.gobbleAtMostSpaces(indent)
			if ct, _, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == t.name {
				p.restore(s)
				break
			}
			b, ok := p.block()
			if !ok {
				p.restore(s)
				break
			}
			contents = append(contents, b...)
		}
	}
	var result []Block
	s := p.save()
	p.gobbleAtMostSpaces(indent)
	if ct, e2, ok := scanHTMLTag(p.s, p.pos); ok && ct.kind == tkClose && ct.name == t.name {
		p.pos = e2
		result = append(result, &RawBlock{"html", stripMarkdownAttribute(raw)})
		result = append(result, contents...)
		result = append(result, &RawBlock{"html", ct.raw})
	} else {
		p.restore(s)
		result = append(result, &RawBlock{"html", raw})
		result = append(result, contents...)
	}
	p.st.inHtmlBlock = oldIn
	return result, true
}

func stripMarkdownAttribute(raw string) string {
	// remove markdown="1" attribute
	for _, a := range []string{` markdown="1"`, ` markdown='1'`, ` markdown=1`} {
		raw = strings.Replace(raw, a, "", 1)
	}
	return raw
}

