// scan a LaTeX command at pos (s[pos]=='\\'); returns end
func scanLatexCommand(s []rune, pos int, inline bool) (int, string, bool) {
	n := len(s)
	if pos >= n || s[pos] != '\\' {
		return 0, "", false
	}
	i := pos + 1
	if i >= n || !isLatexLetter(s[i]) {
		return 0, "", false
	}
	st := i
	for i < n && isLatexLetter(s[i]) {
		i++
	}
	name := string(s[st:i])
	if i < n && s[i] == '*' {
		i++
		name += "*"
	}
	// skip spaces after control word (no newline? allow one newline not blank)
	j := i
	for j < n && (s[j] == ' ' || s[j] == '\t') {
		j++
	}
	afterSp := j
	i = j
	// arguments
	for {
		k := i
		for k < n && (s[k] == ' ' || s[k] == '\t') {
			k++
		}
		if k < n && s[k] == '[' {
			e, ok := scanBalanced(s, k, '[', ']')
			if !ok {
				break
			}
			i = e
			for i < n && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			continue
		}
		if i < n && s[i] == '{' {
			e, ok := scanBalanced(s, i, '{', '}')
			if !ok {
				return 0, "", false
			}
			i = e
			continue
		}
		break
	}
	if i == afterSp {
		// no args: include trailing spaces
		return afterSp, name, true
	}
	return i, name, true
}

func isLatexLetter(c rune) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '@' }

func scanBalanced(s []rune, pos int, open, close rune) (int, bool) {
	depth := 0
	i := pos
	for i < len(s) {
		c := s[i]
		if c == '\\' {
			i += 2
			continue
		}
		if c == open {
			depth++
		} else if c == close {
			depth--
			if depth == 0 {
				return i + 1, true
			}
		}
		i++
	}
	return 0, false
}

func scanLatexEnv(s []rune, pos int) (int, string, bool) {
	str := string(s[pos:min(len(s), pos+7)])
	if str != "\\begin{" {
		return 0, "", false
	}
	i := pos + 7
	st := i
	for i < len(s) && s[i] != '}' && s[i] != '\n' {
		i++
	}
	if i >= len(s) || s[i] != '}' {
		return 0, "", false
	}
	name := string(s[st:i])
	endStr := []rune("\\end{" + name + "}")
	beginStr := []rune("\\begin{" + name + "}")
	depth := 1
	j := i + 1
	for j < len(s) {
		if hasRunesAt(s, j, beginStr) {
			depth++
			j += len(beginStr)
			continue
		}
		if hasRunesAt(s, j, endStr) {
			depth--
			j += len(endStr)
			if depth == 0 {
				return j, name, true
			}
			continue
		}
		j++
	}
	return 0, "", false
}

func hasRunesAt(s []rune, pos int, sub []rune) bool {
	if pos+len(sub) > len(s) {
		return false
	}
	for i, c := range sub {
		if s[pos+i] != c {
			return false
		}
	}
	return true
}

func (p *mdP) rawTeXBlock() ([]Block, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	if p.peek() != '\\' || !isLatexLetter(p.peekAt(1)) {
		return nil, false
	}
	var parts []string
	for {
		if p.peek() != '\\' {
			break
		}
		st := p.pos
		if e, name, ok := scanLatexEnv(p.s, p.pos); ok {
			if mathEnvs[name] {
				break
			}
			p.pos = e
		} else if e, name, ok := scanLatexCommand(p.s, p.pos, false); ok {
			if name == "begin" || name == "end" {
				break
			}
			if !blockLatexCommands[strings.TrimSuffix(name, "*")] {
				break
			}
			if p.handleMacroDef(name, string(p.s[st:e])) {
				p.pos = e
				p.spnlRaw()
				parts = append(parts, "")
				continue
			}
			p.pos = e
		} else {
			break
		}
		raw := string(p.s[st:p.pos])
		sp := p.spnlRaw()
		parts = append(parts, raw+sp)
	}
	if len(parts) == 0 {
		return nil, false
	}
	res := strings.TrimSpace(strings.Join(parts, ""))
	p.blanklines()
	if res == "" {
		return nil, true
	}
	return []Block{&RawBlock{"tex", res}}, true
}

func (p *mdP) spnlRaw() string {
	st := p.pos
	p.skipSpaces()
	s := p.save()
	if p.newline() {
		if p.isBlankLineAhead() {
			p.restore(s)
		} else {
			p.skipSpaces()
		}
	}
	return string(p.s[st:p.pos])
}

func (p *mdP) rawLaTeXInlineP() ([]Inline, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	if p.peek() != '\\' {
		return nil, false
	}
	st := p.pos
	if e, _, ok := scanLatexEnv(p.s, p.pos); ok {
		p.pos = e
		return one(&RawInline{"tex", string(p.s[st:e])}), true
	}
	e, name, ok := scanLatexCommand(p.s, p.pos, true)
	if !ok {
		return nil, false
	}
	raw := string(p.s[st:e])
	if m, ok := p.st.macros[name]; ok {
		p.pos = e
		exp := expandMacroUse(m, raw, name)
		return one(&RawInline{"tex", exp}), true
	}
	p.pos = e
	return one(&RawInline{"tex", raw}), true
}

func (p *mdP) handleMacroDef(name, raw string) bool {
	if !p.ext("latex_macros") {
		return false
	}
	if name != "newcommand" && name != "renewcommand" && name != "providecommand" {
		return false
	}
	// \newcommand{\foo}[n]{body}
	rs := []rune(raw)
	i := len([]rune("\\" + name))
	for i < len(rs) && rs[i] == ' ' {
		i++
	}
	var mname string
	if i < len(rs) && rs[i] == '{' {
		e, ok := scanBalanced(rs, i, '{', '}')
		if !ok {
			return false
		}
		mname = strings.TrimSpace(string(rs[i+1 : e-1]))
		i = e
	} else if i < len(rs) && rs[i] == '\\' {
		st := i
		i++
		for i < len(rs) && isLatexLetter(rs[i]) {
			i++
		}
		mname = string(rs[st:i])
	} else {
		return false
	}
	nargs := 0
	if i < len(rs) && rs[i] == '[' {
		e, ok := scanBalanced(rs, i, '[', ']')
		if !ok {
			return false
		}
		nargs, _ = strconv.Atoi(string(rs[i+1 : e-1]))
		i = e
	}
	if i < len(rs) && rs[i] == '{' {
		e, ok := scanBalanced(rs, i, '{', '}')
		if !ok {
			return false
		}
		body := string(rs[i+1 : e-1])
		mname = strings.TrimPrefix(mname, "\\")
		if name == "providecommand" {
			if _, exists := p.st.macros[mname]; exists {
				return true
			}
		}
		p.st.macros[mname] = latexMacro{nargs: nargs, body: body}
		return true
	}
	return false
}

func expandMacroUse(m latexMacro, raw string, name string) string {
	if m.nargs == 0 {
		rest := strings.TrimPrefix(raw, "\\"+name)
		rest = strings.TrimLeft(rest, " ")
		return m.body + rest
	}
	rs := []rune(raw)
	i := len([]rune("\\" + name))
	var args []string
	for len(args) < m.nargs && i < len(rs) {
		for i < len(rs) && rs[i] == ' ' {
			i++
		}
		if i < len(rs) && rs[i] == '{' {
			e, ok := scanBalanced(rs, i, '{', '}')
			if !ok {
				break
			}
			args = append(args, string(rs[i+1:e-1]))
			i = e
		} else {
			break
		}
	}
	body := m.body
	for k, a := range args {
		body = strings.ReplaceAll(body, "#"+itoa(k+1), a)
	}
	return body + string(rs[i:])
}

func (p *mdP) applyMacros(s string) string {
	if len(p.st.macros) == 0 || !p.ext("latex_macros") {
		return s
	}
	rs := []rune(s)
	var sb strings.Builder
	for i := 0; i < len(rs); i++ {
		if rs[i] == '\\' && i+1 < len(rs) && isLatexLetter(rs[i+1]) {
			j := i + 1
			for j < len(rs) && isLatexLetter(rs[j]) {
				j++
			}
			name := string(rs[i+1 : j])
			if m, ok := p.st.macros[name]; ok {
				// collect args
				k := j
				var args []string
				for len(args) < m.nargs && k < len(rs) {
					for k < len(rs) && rs[k] == ' ' {
						k++
					}
					if k < len(rs) && rs[k] == '{' {
						e, ok := scanBalanced(rs, k, '{', '}')
						if !ok {
							break
						}
						args = append(args, string(rs[k+1:e-1]))
						k = e
					} else {
						break
					}
				}
				body := m.body
				for n, a := range args {
					body = strings.ReplaceAll(body, "#"+itoa(n+1), a)
				}
				sb.WriteString(body)
				i = k - 1
				continue
			}
			sb.WriteString(string(rs[i:j]))
			i = j - 1
			continue
		}
		sb.WriteRune(rs[i])
	}
	return sb.String()
}
