// find mapping key colon in a line content; returns key, rest, ok
func splitMapKey(s string) (string, string, bool) {
	if len(s) == 0 {
		return "", "", false
	}
	if s[0] == '"' || s[0] == '\'' {
		q := s[0]
		i := 1
		for i < len(s) {
			if s[i] == '\\' && q == '"' {
				i += 2
				continue
			}
			if s[i] == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			i++
		}
		if i >= len(s) {
			return "", "", false
		}
		key := s[:i+1]
		rest := strings.TrimLeft(s[i+1:], " ")
		if strings.HasPrefix(rest, ":") && (len(rest) == 1 || rest[1] == ' ') {
			return unquoteYAML(key), strings.TrimLeft(rest[1:], " "), true
		}
		return "", "", false
	}
	if s[0] == '[' || s[0] == '{' || s[0] == '#' || s[0] == '|' || s[0] == '>' {
		return "", "", false
	}
	if strings.HasPrefix(s, "- ") || s == "-" {
		return "", "", false
	}
	for i := 0; i < len(s); i++ {
		if s[i] == ':' && (i+1 == len(s) || s[i+1] == ' ') {
			return strings.TrimRight(s[:i], " "), strings.TrimLeft(s[i+1:], " "), true
		}
		if s[i] == '#' && i > 0 && s[i-1] == ' ' {
			return "", "", false
		}
	}
	return "", "", false
}

func unquoteYAML(s string) string {
	if len(s) >= 2 && s[0] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	if len(s) >= 2 && s[0] == '"' {
		return unescapeDouble(s[1 : len(s)-1])
	}
	return s
}

func unescapeDouble(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			sb.WriteByte(c)
			continue
		}
		i++
		switch s[i] {
		case 'n':
			sb.WriteByte('\n')
		case 't':
			sb.WriteByte('\t')
		case 'r':
			sb.WriteByte('\r')
		case '0':
			sb.WriteByte(0)
		case 'a':
			sb.WriteByte(7)
		case 'b':
			sb.WriteByte(8)
		case 'e':
			sb.WriteByte(27)
		case 'f':
			sb.WriteByte(12)
		case 'v':
			sb.WriteByte(11)
		case ' ':
			sb.WriteByte(' ')
		case '/':
			sb.WriteByte('/')
		case '"':
			sb.WriteByte('"')
		case '\\':
			sb.WriteByte('\\')
		case 'N':
			sb.WriteString("\u0085")
		case '_':
			sb.WriteString("\u00a0")
		case 'L':
			sb.WriteString("\u2028")
		case 'P':
			sb.WriteString("\u2029")
		case 'x', 'u', 'U':
			n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[s[i]]
			if i+n < len(s)+0 && i+1+n <= len(s) {
				v, err := strconv.ParseUint(s[i+1:i+1+n], 16, 32)
				if err == nil {
					sb.WriteRune(rune(v))
					i += n
					continue
				}
			}
			sb.WriteByte('\\')
			sb.WriteByte(s[i])
		case '\n':
			// line continuation
		default:
			sb.WriteByte('\\')
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func (y *yparser) parseBlock(indent int) *ynode {
	y.skipBlank()
	if y.ln >= len(y.lines) {
		return &ynode{kind: ynNull}
	}
	l := y.lines[y.ln]
	ind := y.indentOf(l)
	content := l[ind:]
	if strings.HasPrefix(content, "- ") || content == "-" {
		return y.parseSeq(ind)
	}
	if _, _, ok := splitMapKey(content); ok {
		return y.parseMap(ind)
	}
	// scalar / flow
	return y.parseInlineValue(content, ind, indent-1)
}

func (y *yparser) parseSeq(ind int) *ynode {
	n := &ynode{kind: ynSeq}
	for {
		y.skipBlank()
		if y.ln >= len(y.lines) {
			break
		}
		l := y.lines[y.ln]
		i := y.indentOf(l)
		if i != ind {
			if i > ind {
				y.fail("bad indentation in sequence")
			}
			break
		}
		content := l[i:]
		if !(strings.HasPrefix(content, "- ") || content == "-") {
			break
		}
		rest := strings.TrimLeft(content[1:], " ")
		if rest == "" || strings.HasPrefix(rest, "#") {
			y.ln++
			y.skipBlank()
			if y.ln < len(y.lines) && y.indentOf(y.lines[y.ln]) > ind {
				n.items = append(n.items, y.parseBlock(ind+1))
			} else {
				n.items = append(n.items, &ynode{kind: ynNull})
			}
			continue
		}
		// item content begins at column
		col := ind + (len(content) - len(rest))
		// rewrite current line so that nested structure parses with proper indentation
		y.lines[y.ln] = strings.Repeat(" ", col) + rest
		if strings.HasPrefix(rest, "- ") || rest == "-" {
			n.items = append(n.items, y.parseSeq(col))
			continue
		}
		if _, _, ok := splitMapKey(rest); ok {
			n.items = append(n.items, y.parseMap(col))
			continue
		}
		n.items = append(n.items, y.parseInlineValue(rest, col, ind))
	}
	return n
