func (y *yparser) parseMap(ind int) *ynode {
	n := &ynode{kind: ynMap}
	for {
		y.skipBlank()
		if y.ln >= len(y.lines) {
			break
		}
		l := y.lines[y.ln]
		i := y.indentOf(l)
		if i != ind {
			if i > ind {
				y.fail("bad indentation of a mapping entry")
			}
			break
		}
		content := l[i:]
		key, rest, ok := splitMapKey(content)
		if !ok {
			y.fail(fmt.Sprintf("could not find expected ':'"))
		}
		var val *ynode
		if rest == "" || strings.HasPrefix(rest, "#") {
			y.ln++
			y.skipBlank()
			if y.ln < len(y.lines) {
				ni := y.indentOf(y.lines[y.ln])
				nc := y.lines[y.ln][ni:]
				if ni > ind || (ni == ind && (strings.HasPrefix(nc, "- ") || nc == "-")) {
					val = y.parseBlock(ind + 1)
				} else {
					val = &ynode{kind: ynNull}
				}
			} else {
				val = &ynode{kind: ynNull}
			}
		} else {
			val = y.parseInlineValue(rest, ind+len(content)-len(rest), ind)
		}
