		found := false
		for k, kk := range n.keys {
			if kk == key {
				n.vals[k] = val
				found = true
			}
		}
		if !found {
			n.keys = append(n.keys, key)
			n.vals = append(n.vals, val)
		}
	}
	return n
}

// parseInlineValue: value text starting on current line (y.ln) at column col; parent indentation pind
func (y *yparser) parseInlineValue(rest string, col int, pind int) *ynode {
	// anchors / tags
	anchor := ""
	for {
		if strings.HasPrefix(rest, "&") {
			sp := strings.IndexByte(rest, ' ')
			if sp < 0 {
				anchor = rest[1:]
				rest = ""
			} else {
				anchor = rest[1:sp]
				rest = strings.TrimLeft(rest[sp:], " ")
			}
			continue
		}
		if strings.HasPrefix(rest, "!") {
			sp := strings.IndexByte(rest, ' ')
			if sp < 0 {
				rest = ""
			} else {
				rest = strings.TrimLeft(rest[sp:], " ")
			}
			continue
		}
		break
	}
	var res *ynode
	if rest == "" {
		y.ln++
		y.skipBlank()
		if y.ln < len(y.lines) && y.indentOf(y.lines[y.ln]) > pind {
			res = y.parseBlock(pind + 1)
		} else {
			res = &ynode{kind: ynNull}
		}
	} else if strings.HasPrefix(rest, "*") {
		name := strings.TrimSpace(rest[1:])
		y.ln++
		if a, ok := y.anchors[name]; ok {
			res = a
		} else {
			y.fail("unknown alias")
		}
	} else if rest[0] == '|' || rest[0] == '>' {
		res = y.parseBlockScalar(rest, pind)
	} else if rest[0] == '[' || rest[0] == '{' {
		res = y.parseFlow(rest)
	} else if rest[0] == '"' || rest[0] == '\'' {
		res = y.parseQuoted(rest, pind)
	} else {
		res = y.parsePlain(rest, pind)
	}
	if anchor != "" {
		y.anchors[anchor] = res
	}
	return res
}

func stripComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && (i == 0 || s[i-1] == ' ') {
			return strings.TrimRight(s[:i], " ")
		}
	}
	return s
}

func (y *yparser) parsePlain(rest string, pind int) *ynode {
	parts := []string{strings.TrimRight(stripComment(rest), " ")}
	hadComment := stripComment(rest) != rest
	y.ln++
	if !hadComment {
		for y.ln < len(y.lines) {
			l := y.lines[y.ln]
			if strings.TrimSpace(l) == "" {
				// blank line inside plain scalar -> newline
				// look ahead for continuation
				j := y.ln
				for j < len(y.lines) && strings.TrimSpace(y.lines[j]) == "" {
					j++
				}
				if j < len(y.lines) && y.indentOf(y.lines[j]) > pind && !isBlankOrComment(y.lines[j]) {
					nc := strings.TrimLeft(y.lines[j], " ")
					if _, _, ok := splitMapKey(nc); ok && y.indentOf(y.lines[j]) <= pind {
						break
					}
					for k := y.ln; k < j; k++ {
						parts = append(parts, "\n")
					}
					y.ln = j
					continue
				}
				break
			}
			i := y.indentOf(l)
			if i <= pind {
				break
			}
			c := strings.TrimSpace(l)
			if strings.HasPrefix(c, "#") {
				break
			}
			sc := stripComment(c)
			parts = append(parts, sc)
			y.ln++
			if sc != c {
				break
			}
		}
	}
