	var sb strings.Builder
	for i, p := range parts {
		if p == "\n" {
			sb.WriteString("\n")
			continue
		}
		if i > 0 && parts[i-1] != "\n" {
			sb.WriteString(" ")
		}
		sb.WriteString(p)
	}
	return &ynode{kind: ynScalar, value: sb.String(), style: 'p'}
}

func (y *yparser) parseQuoted(rest string, pind int) *ynode {
	q := rest[0]
	// accumulate text until closing quote, possibly over lines
	buf := rest[1:]
	y.ln++
	for {
		// search closing quote in buf
		i := 0
		closed := -1
		for i < len(buf) {
			if q == '"' && buf[i] == '\\' {
				i += 2
				continue
			}
			if buf[i] == q {
				if q == '\'' && i+1 < len(buf) && buf[i+1] == '\'' {
					i += 2
					continue
				}
				closed = i
				break
			}
			i++
		}
		if closed >= 0 {
			body := buf[:closed]
			// fold lines
			lines := strings.Split(body, "\n")
			var sb strings.Builder
			for k, l := range lines {
				if k > 0 {
					l = strings.TrimLeft(l, " ")
				}
				if k < len(lines)-1 {
					l = strings.TrimRight(l, " ")
				}
				if k > 0 {
					if lines[k-1] == "" || strings.TrimSpace(lines[k-1]) == "" && k-1 > 0 {
						sb.WriteString("\n")
					} else if l == "" {
					} else {
						sb.WriteString(" ")
					}
				}
				sb.WriteString(l)
