		}
		if y.ln >= len(y.lines) {
			y.fail("unterminated quoted scalar")
		}
		buf += "\n" + y.lines[y.ln]
		y.ln++
	}
}

func (y *yparser) parseBlockScalar(header string, pind int) *ynode {
	style := header[0]
	chomp := byte(0)
	explicit := 0
	for _, c := range header[1:] {
		if c == '+' || c == '-' {
			chomp = byte(c)
		} else if c >= '1' && c <= '9' {
			explicit = int(c - '0')
		} else if c == ' ' || c == '#' {
			break
		}
	}
	y.ln++
	// determine indentation
	ind := -1
	if explicit > 0 {
		ind = pind + explicit
		if pind < 0 {
			ind = explicit
		}
	}
	var lines []string
	for y.ln < len(y.lines) {
		l := y.lines[y.ln]
		if strings.TrimSpace(l) == "" {
			lines = append(lines, "")
			y.ln++
			continue
		}
		i := y.indentOf(l)
		if ind < 0 {
			if i <= pind {
				break
			}
			ind = i
		}
		if i < ind {
			break
		}
		lines = append(lines, l[ind:])
		y.ln++
	}
	// trailing blank lines
	trail := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trail++
	}
	var body string
	if style == '|' {
		body = strings.Join(lines, "\n")
	} else {
		var sb strings.Builder
		for k, l := range lines {
			if k > 0 {
				prev := lines[k-1]
				if l == "" || prev == "" || strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
					sb.WriteString("\n")
				} else {
					sb.WriteString(" ")
				}
			}
			sb.WriteString(l)
		}
		body = sb.String()
		// folded: blank lines produce newlines; handled roughly
		body = strings.ReplaceAll(body, "\n\n", "\n")
		_ = body
		body = foldBlock(lines)
	}
	if len(lines) > 0 {
		switch chomp {
		case '-':
		case '+':
			body += "\n" + strings.Repeat("\n", trail)
		default:
			body += "\n"
		}
	}
	return &ynode{kind: ynScalar, value: body, style: style}
}

func foldBlock(lines []string) string {
	var sb strings.Builder
	for k, l := range lines {
		if k > 0 {
			prev := lines[k-1]
			if l == "" {
				sb.WriteString("\n")
				continue
			}
			if prev == "" {
				// already wrote newline(s)
			} else if strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
				sb.WriteString("\n")
			} else {
				sb.WriteString(" ")
			}
		}
		sb.WriteString(l)
	}
	return sb.String()
}

// flow collections
type yflow struct {
	s   string
	pos int
}

func (y *yparser) parseFlow(rest string) *ynode {
	buf := rest
	y.ln++
	for {
		f := &yflow{s: buf}
		var res *ynode
		ok := func() (ok bool) {
			defer func() {
				if r := recover(); r != nil {
					ok = false
				}
			}()
			res = f.value()
			return true
		}()
		if ok {
			return res
		}
		if y.ln >= len(y.lines) {
			y.fail("unterminated flow collection")
		}
		buf += "\n" + y.lines[y.ln]
		y.ln++
	}
}

func (f *yflow) ws() {
	for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\n' || f.s[f.pos] == '\t') {
		f.pos++
	}
	if f.pos < len(f.s) && f.s[f.pos] == '#' {
		for f.pos < len(f.s) && f.s[f.pos] != '\n' {
			f.pos++
		}
		f.ws()
	}
}

func (f *yflow) value() *ynode {
	f.ws()
	if f.pos >= len(f.s) {
		panic("eof")
	}
	c := f.s[f.pos]
	switch c {
	case '[':
		f.pos++
		n := &ynode{kind: ynSeq}
		for {
			f.ws()
			if f.pos >= len(f.s) {
				panic("eof")
			}
			if f.s[f.pos] == ']' {
				f.pos++
				return n
			}
			v := f.value()
			f.ws()
			// single pair mapping in sequence
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				val := f.value()
				m := &ynode{kind: ynMap, keys: []string{v.value}, vals: []*ynode{val}}
				v = m
				f.ws()
			}
			n.items = append(n.items, v)
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
				continue
			}
			f.ws()
			if f.pos < len(f.s) && f.s[f.pos] == ']' {
				f.pos++
				return n
			}
			panic("bad")
		}
	case '{':
		f.pos++
		n := &ynode{kind: ynMap}
		for {
			f.ws()
			if f.pos >= len(f.s) {
				panic("eof")
			}
			if f.s[f.pos] == '}' {
				f.pos++
				return n
			}
			k := f.value()
			f.ws()
			var v *ynode
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				f.ws()
				if f.pos < len(f.s) && (f.s[f.pos] == ',' || f.s[f.pos] == '}') {
					v = &ynode{kind: ynNull}
				} else {
					v = f.value()
				}
			} else {
				v = &ynode{kind: ynNull}
			}
			n.keys = append(n.keys, k.value)
			n.vals = append(n.vals, v)
			f.ws()
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
				continue
			}
			if f.pos < len(f.s) && f.s[f.pos] == '}' {
				f.pos++
				return n
			}
			panic("bad")
		}
	case '"', '\'':
		q := c
		i := f.pos + 1
		for i < len(f.s) {
			if q == '"' && f.s[i] == '\\' {
				i += 2
				continue
			}
			if f.s[i] == q {
				if q == '\'' && i+1 < len(f.s) && f.s[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			i++
		}
		if i >= len(f.s) {
			panic("eof")
		}
		raw := f.s[f.pos : i+1]
		f.pos = i + 1
		body := raw[1 : len(raw)-1]
		body = strings.Join(strings.Fields(strings.ReplaceAll(body, "\n", " ")), " ")
		if q == '\'' {
			body = strings.ReplaceAll(body, "''", "'")
		} else {
			body = unescapeDouble(body)
		}
		return &ynode{kind: ynScalar, value: body, style: q}
	default:
		st := f.pos
		for f.pos < len(f.s) {
			ch := f.s[f.pos]
			if ch == ',' || ch == ']' || ch == '}' || ch == '[' || ch == '{' {
				break
			}
			if ch == ':' && (f.pos+1 >= len(f.s) || strings.ContainsRune(" \n,]}", rune(f.s[f.pos+1]))) {
				break
			}
			if ch == '#' && f.pos > 0 && f.s[f.pos-1] == ' ' {
				break
			}
			f.pos++
		}
		v := strings.Join(strings.Fields(f.s[st:f.pos]), " ")
		if v == "" {
			return &ynode{kind: ynNull}
		}
		return &ynode{kind: ynScalar, value: v, style: 'p'}
	}
}

var yamlBools = map[string]bool{
	"y": true, "Y": true, "yes": true, "Yes": true, "YES": true,
	"n": false, "N": false, "no": false, "No": false, "NO": false,
	"true": true, "True": true, "TRUE": true, "false": false, "False": false, "FALSE": false,
	"on": true, "On": true, "ON": true, "off": false, "Off": false, "OFF": false,
}

func isYamlNull(s string) bool {
	return s == "" || s == "~" || s == "null" || s == "Null" || s == "NULL"
}

// yamlToMeta converts parsed yaml to Meta using markdown parsing for strings
func (p *mdP) yamlToMeta(raw string) (Meta, error) {
	n, err := parseYAML(raw)
	if err != nil {
		return nil, err
	}
	m := Meta{}
	if n.kind == ynNull {
		return m, nil
	}
	if n.kind != ynMap {
		return m, nil
	}
	for i, k := range n.keys {
		if strings.HasSuffix(k, "_") {
			continue
		}
		m[k] = p.yamlNodeToMeta(n.vals[i])
	}
	return m, nil
}

func (p *mdP) yamlNodeToMeta(n *ynode) MetaValue {
	switch n.kind {
	case ynNull:
		return &MetaString{""}
	case ynSeq:
		var xs []MetaValue
		for _, it := range n.items {
			xs = append(xs, p.yamlNodeToMeta(it))
		}
		return &MetaList{xs}
	case ynMap:
		mm := map[string]MetaValue{}
		for i, k := range n.keys {
			if strings.HasSuffix(k, "_") {
				continue
			}
			mm[k] = p.yamlNodeToMeta(n.vals[i])
		}
		return &MetaMap{mm}
	}
	if n.style == 'p' {
		if b, ok := yamlBools[n.value]; ok {
			return &MetaBool{b}
		}
		if isYamlNull(n.value) {
			return &MetaString{""}
		}
	}
	return p.metaValueFromString(n.value)
}

func (p *mdP) metaValueFromString(x string) MetaValue {
	if strings.HasSuffix(strings.TrimRight(x, " \t"), "\n") {
		sp := p.sub(x + "\n")
		bs := sp.parseBlocks()
		return &MetaBlocks{bs}
	}
	sp := p.sub(x)
	ils := sp.inlinesAll()
	return &MetaInlines{trimInlines(ils)}
}

// inlinesAll parses inlines until eof, treating blank lines as spaces
func (p *mdP) inlinesAll() []Inline {
	var ils []Inline
	for !p.eof() {
		x, ok := p.inline()
		if !ok {
			// skip a char
			if p.peek() == '\n' {
				p.pos++
				ils = appendInlMut(ils, &SoftBreak{})
				continue
			}
			ils = appendInlMut(ils, &Str{string(p.peek())})
			p.pos++
			continue
		}
		ils = appendInlMut(ils, x...)
	}
	return ils
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > yaml.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

const (
	ynScalar = iota
	ynSeq
	ynMap
	ynNull
)

type ynode struct {
	kind   int
	value  string
	style  byte // 'p' plain, 's' single, 'd' double, '|' literal, '>' folded
	items  []*ynode
	keys   []string
	vals   []*ynode
}

type yparser struct {
	lines []string
	ln    int
	anchors map[string]*ynode
}

type yamlError struct{ msg string }

func (e *yamlError) Error() string { return e.msg }

func parseYAML(src string) (*ynode, error) {
	src = strings.ReplaceAll(src, "\r\n", "\n")
	src = strings.ReplaceAll(src, "\t", "    ")
	lines := strings.Split(src, "\n")
	// drop document markers
	var ls []string
	for _, l := range lines {
		t := strings.TrimRight(l, " ")
		if t == "---" || t == "..." {
			continue
		}
		ls = append(ls, l)
	}
	y := &yparser{lines: ls, anchors: map[string]*ynode{}}
	var res *ynode
	var err error
	func() {
		defer func() {
			if r := recover(); r != nil {
				if ye, ok := r.(*yamlError); ok {
					err = ye
				} else {
					panic(r)
				}
			}
		}()
		y.skipBlank()
		if y.ln >= len(y.lines) {
			res = &ynode{kind: ynNull}
			return
		}
		res = y.parseBlock(y.indentOf(y.lines[y.ln]))
	}()
	return res, err
}

func (y *yparser) fail(msg string) {
	panic(&yamlError{msg})
}

func (y *yparser) indentOf(l string) int {
	n := 0
	for n < len(l) && l[n] == ' ' {
		n++
	}
	return n
}

func isBlankOrComment(l string) bool {
	t := strings.TrimLeft(l, " ")
	return t == "" || strings.HasPrefix(t, "#")
}

func (y *yparser) skipBlank() {
	for y.ln < len(y.lines) && isBlankOrComment(y.lines[y.ln]) {
		y.ln++
	}
}

// find mapping key colon in a line content; returns key, rest, ok
func splitMapKey(s string) (string, string, bool) {
	if len(s) == 0 {
		return "", "", false
	}
	if s[0] == '"' || s[0] == '\'' {
		q := s[0]
		i := 1
		for i < len(s) {
			if s[i] == '\\' && q == '"' {
				i += 2
				continue
			}
			if s[i] == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			i++
		}
		if i >= len(s) {
			return "", "", false
		}
		key := s[:i+1]
		rest := strings.TrimLeft(s[i+1:], " ")
		if strings.HasPrefix(rest, ":") && (len(rest) == 1 || rest[1] == ' ') {
			return unquoteYAML(key), strings.TrimLeft(rest[1:], " "), true
		}
		return "", "", false
	}
	if s[0] == '[' || s[0] == '{' || s[0] == '#' || s[0] == '|' || s[0] == '>' {
		return "", "", false
	}
	if strings.HasPrefix(s, "- ") || s == "-" {
		return "", "", false
	}
	for i := 0; i < len(s); i++ {
		if s[i] == ':' && (i+1 == len(s) || s[i+1] == ' ') {
			return strings.TrimRight(s[:i], " "), strings.TrimLeft(s[i+1:], " "), true
		}
		if s[i] == '#' && i > 0 && s[i-1] == ' ' {
			return "", "", false
		}
	}
	return "", "", false
}

func unquoteYAML(s string) string {
	if len(s) >= 2 && s[0] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	if len(s) >= 2 && s[0] == '"' {
		return unescapeDouble(s[1 : len(s)-1])
	}
	return s
}

func unescapeDouble(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			sb.WriteByte(c)
			continue
		}
		i++
		switch s[i] {
		case 'n':
			sb.WriteByte('\n')
		case 't':
			sb.WriteByte('\t')
		case 'r':
			sb.WriteByte('\r')
		case '0':
			sb.WriteByte(0)
		case 'a':
			sb.WriteByte(7)
		case 'b':
			sb.WriteByte(8)
		case 'e':
			sb.WriteByte(27)
		case 'f':
			sb.WriteByte(12)
		case 'v':
			sb.WriteByte(11)
		case ' ':
			sb.WriteByte(' ')
		case '/':
			sb.WriteByte('/')
		case '"':
			sb.WriteByte('"')
		case '\\':
			sb.WriteByte('\\')
		case 'N':
			sb.WriteString("\u0085")
		case '_':
			sb.WriteString("\u00a0")
		case 'L':
			sb.WriteString("\u2028")
		case 'P':
			sb.WriteString("\u2029")
		case 'x', 'u', 'U':
			n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[s[i]]
			if i+n < len(s)+0 && i+1+n <= len(s) {
				v, err := strconv.ParseUint(s[i+1:i+1+n], 16, 32)
				if err == nil {
					sb.WriteRune(rune(v))
					i += n
					continue
				}
			}
			sb.WriteByte('\\')
			sb.WriteByte(s[i])
		case '\n':
			// line continuation
		default:
			sb.WriteByte('\\')
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func (y *yparser) parseBlock(indent int) *ynode {
	y.skipBlank()
	if y.ln >= len(y.lines) {
		return &ynode{kind: ynNull}
	}
	l := y.lines[y.ln]
	ind := y.indentOf(l)
	content := l[ind:]
	if strings.HasPrefix(content, "- ") || content == "-" {
		return y.parseSeq(ind)
	}
	if _, _, ok := splitMapKey(content); ok {
		return y.parseMap(ind)
	}
	// scalar / flow
	return y.parseInlineValue(content, ind, indent-1)
}

func (y *yparser) parseSeq(ind int) *ynode {
	n := &ynode{kind: ynSeq}
	for {
		y.skipBlank()
		if y.ln >= len(y.lines) {
			break
		}
		l := y.lines[y.ln]
		i := y.indentOf(l)
		if i != ind {
			if i > ind {
				y.fail("bad indentation in sequence")
			}
			break
		}
		content := l[i:]
		if !(strings.HasPrefix(content, "- ") || content == "-") {
			break
		}
		rest := strings.TrimLeft(content[1:], " ")
		if rest == "" || strings.HasPrefix(rest, "#") {
			y.ln++
			y.skipBlank()
			if y.ln < len(y.lines) && y.indentOf(y.lines[y.ln]) > ind {
				n.items = append(n.items, y.parseBlock(ind+1))
			} else {
				n.items = append(n.items, &ynode{kind: ynNull})
			}
			continue
		}
		// item content begins at column
		col := ind + (len(content) - len(rest))
		// rewrite current line so that nested structure parses with proper indentation
		y.lines[y.ln] = strings.Repeat(" ", col) + rest
		if strings.HasPrefix(rest, "- ") || rest == "-" {
			n.items = append(n.items, y.parseSeq(col))
			continue
		}
		if _, _, ok := splitMapKey(rest); ok {
			n.items = append(n.items, y.parseMap(col))
			continue
		}
		n.items = append(n.items, y.parseInlineValue(rest, col, ind))
	}
	return n
}

func (y *yparser) parseMap(ind int) *ynode {
	n := &ynode{kind: ynMap}
	for {
		y.skipBlank()
		if y.ln >= len(y.lines) {
			break
		}
		l := y.lines[y.ln]
		i := y.indentOf(l)
		if i != ind {
			if i > ind {
				y.fail("bad indentation of a mapping entry")
			}
			break
		}
		content := l[i:]
		key, rest, ok := splitMapKey(content)
		if !ok {
			y.fail(fmt.Sprintf("could not find expected ':'"))
		}
		var val *ynode
		if rest == "" || strings.HasPrefix(rest, "#") {
			y.ln++
			y.skipBlank()
			if y.ln < len(y.lines) {
				ni := y.indentOf(y.lines[y.ln])
				nc := y.lines[y.ln][ni:]
				if ni > ind || (ni == ind && (strings.HasPrefix(nc, "- ") || nc == "-")) {
					val = y.parseBlock(ind + 1)
				} else {
					val = &ynode{kind: ynNull}
				}
			} else {
				val = &ynode{kind: ynNull}
			}
		} else {
			val = y.parseInlineValue(rest, ind+len(content)-len(rest), ind)
		}
		// replace existing key
		found := false
		for k, kk := range n.keys {
			if kk == key {
				n.vals[k] = val
				found = true
			}
		}
		if !found {
			n.keys = append(n.keys, key)
			n.vals = append(n.vals, val)
		}
	}
	return n
}

// parseInlineValue: value text starting on current line (y.ln) at column col; parent indentation pind
func (y *yparser) parseInlineValue(rest string, col int, pind int) *ynode {
	// anchors / tags
	anchor := ""
	for {
		if strings.HasPrefix(rest, "&") {
			sp := strings.IndexByte(rest, ' ')
			if sp < 0 {
				anchor = rest[1:]
				rest = ""
			} else {
				anchor = rest[1:sp]
				rest = strings.TrimLeft(rest[sp:], " ")
			}
			continue
		}
		if strings.HasPrefix(rest, "!") {
			sp := strings.IndexByte(rest, ' ')
			if sp < 0 {
				rest = ""
			} else {
				rest = strings.TrimLeft(rest[sp:], " ")
			}
			continue
		}
		break
	}
	var res *ynode
	if rest == "" {
		y.ln++
		y.skipBlank()
		if y.ln < len(y.lines) && y.indentOf(y.lines[y.ln]) > pind {
			res = y.parseBlock(pind + 1)
		} else {
			res = &ynode{kind: ynNull}
		}
	} else if strings.HasPrefix(rest, "*") {
		name := strings.TrimSpace(rest[1:])
		y.ln++
		if a, ok := y.anchors[name]; ok {
			res = a
		} else {
			y.fail("unknown alias")
		}
	} else if rest[0] == '|' || rest[0] == '>' {
		res = y.parseBlockScalar(rest, pind)
	} else if rest[0] == '[' || rest[0] == '{' {
		res = y.parseFlow(rest)
	} else if rest[0] == '"' || rest[0] == '\'' {
		res = y.parseQuoted(rest, pind)
	} else {
		res = y.parsePlain(rest, pind)
	}
	if anchor != "" {
		y.anchors[anchor] = res
	}
	return res
}

func stripComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && (i == 0 || s[i-1] == ' ') {
			return strings.TrimRight(s[:i], " ")
		}
	}
	return s
}

func (y *yparser) parsePlain(rest string, pind int) *ynode {
	parts := []string{strings.TrimRight(stripComment(rest), " ")}
	hadComment := stripComment(rest) != rest
	y.ln++
	if !hadComment {
		for y.ln < len(y.lines) {
			l := y.lines[y.ln]
			if strings.TrimSpace(l) == "" {
				// blank line inside plain scalar -> newline
				// look ahead for continuation
				j := y.ln
				for j < len(y.lines) && strings.TrimSpace(y.lines[j]) == "" {
					j++
				}
				if j < len(y.lines) && y.indentOf(y.lines[j]) > pind && !isBlankOrComment(y.lines[j]) {
					nc := strings.TrimLeft(y.lines[j], " ")
					if _, _, ok := splitMapKey(nc); ok && y.indentOf(y.lines[j]) <= pind {
						break
					}
					for k := y.ln; k < j; k++ {
						parts = append(parts, "\n")
					}
					y.ln = j
					continue
				}
				break
			}
			i := y.indentOf(l)
			if i <= pind {
				break
			}
			c := strings.TrimSpace(l)
			if strings.HasPrefix(c, "#") {
				break
			}
			sc := stripComment(c)
			parts = append(parts, sc)
			y.ln++
			if sc != c {
				break
			}
		}
	}
	// fold
	var sb strings.Builder
	for i, p := range parts {
		if p == "\n" {
			sb.WriteString("\n")
			continue
		}
		if i > 0 && parts[i-1] != "\n" {
			sb.WriteString(" ")
		}
		sb.WriteString(p)
	}
	return &ynode{kind: ynScalar, value: sb.String(), style: 'p'}
}

func (y *yparser) parseQuoted(rest string, pind int) *ynode {
	q := rest[0]
	// accumulate text until closing quote, possibly over lines
	buf := rest[1:]
	y.ln++
	for {
		// search closing quote in buf
		i := 0
		closed := -1
		for i < len(buf) {
			if q == '"' && buf[i] == '\\' {
				i += 2
				continue
			}
			if buf[i] == q {
				if q == '\'' && i+1 < len(buf) && buf[i+1] == '\'' {
					i += 2
					continue
				}
				closed = i
				break
			}
			i++
		}
		if closed >= 0 {
			body := buf[:closed]
			// fold lines
			lines := strings.Split(body, "\n")
			var sb strings.Builder
			for k, l := range lines {
				if k > 0 {
					l = strings.TrimLeft(l, " ")
				}
				if k < len(lines)-1 {
					l = strings.TrimRight(l, " ")
				}
				if k > 0 {
					if lines[k-1] == "" || strings.TrimSpace(lines[k-1]) == "" && k-1 > 0 {
						sb.WriteString("\n")
					} else if l == "" {
					} else {
						sb.WriteString(" ")
					}
				}
				sb.WriteString(l)
			}
			v := sb.String()
			if q == '\'' {
				v = strings.ReplaceAll(v, "''", "'")
			} else {
				v = unescapeDouble(v)
			}
			return &ynode{kind: ynScalar, value: v, style: q}
		}
		if y.ln >= len(y.lines) {
			y.fail("unterminated quoted scalar")
		}
		buf += "\n" + y.lines[y.ln]
		y.ln++
	}
}

func (y *yparser) parseBlockScalar(header string, pind int) *ynode {
	style := header[0]
	chomp := byte(0)
	explicit := 0
	for _, c := range header[1:] {
		if c == '+' || c == '-' {
			chomp = byte(c)
		} else if c >= '1' && c <= '9' {
			explicit = int(c - '0')
		} else if c == ' ' || c == '#' {
			break
		}
	}
	y.ln++
	// determine indentation
	ind := -1
	if explicit > 0 {
		ind = pind + explicit
		if pind < 0 {
			ind = explicit
		}
	}
	var lines []string
	for y.ln < len(y.lines) {
		l := y.lines[y.ln]
		if strings.TrimSpace(l) == "" {
			lines = append(lines, "")
			y.ln++
			continue
		}
		i := y.indentOf(l)
		if ind < 0 {
			if i <= pind {
				break
			}
			ind = i
		}
		if i < ind {
			break
		}
		lines = append(lines, l[ind:])
		y.ln++
	}
	// trailing blank lines
	trail := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trail++
	}
	var body string
	if style == '|' {
		body = strings.Join(lines, "\n")
	} else {
		var sb strings.Builder
		for k, l := range lines {
			if k > 0 {
				prev := lines[k-1]
				if l == "" || prev == "" || strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
					sb.WriteString("\n")
				} else {
					sb.WriteString(" ")
				}
			}
			sb.WriteString(l)
		}
		body = sb.String()
		// folded: blank lines produce newlines; handled roughly
		body = strings.ReplaceAll(body, "\n\n", "\n")
		_ = body
		body = foldBlock(lines)
	}
	if len(lines) > 0 {
		switch chomp {
		case '-':
		case '+':
			body += "\n" + strings.Repeat("\n", trail)
		default:
			body += "\n"
		}
	}
	return &ynode{kind: ynScalar, value: body, style: style}
}

func foldBlock(lines []string) string {
	var sb strings.Builder
	for k, l := range lines {
		if k > 0 {
			prev := lines[k-1]
			if l == "" {
				sb.WriteString("\n")
				continue
			}
			if prev == "" {
				// already wrote newline(s)
			} else if strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
				sb.WriteString("\n")
			} else {
				sb.WriteString(" ")
			}
		}
		sb.WriteString(l)
	}
	return sb.String()
}

// flow collections
type yflow struct {
	s   string
	pos int
}

func (y *yparser) parseFlow(rest string) *ynode {
	buf := rest
	y.ln++
	for {
		f := &yflow{s: buf}
		var res *ynode
		ok := func() (ok bool) {
			defer func() {
				if r := recover(); r != nil {
					ok = false
				}
			}()
			res = f.value()
			return true
		}()
		if ok {
			return res
		}
		if y.ln >= len(y.lines) {
			y.fail("unterminated flow collection")
		}
		buf += "\n" + y.lines[y.ln]
		y.ln++
	}
}

func (f *yflow) ws() {
	for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\n' || f.s[f.pos] == '\t') {
		f.pos++
	}
	if f.pos < len(f.s) && f.s[f.pos] == '#' {
		for f.pos < len(f.s) && f.s[f.pos] != '\n' {
			f.pos++
		}
		f.ws()
	}
}

func (f *yflow) value() *ynode {
	f.ws()
	if f.pos >= len(f.s) {
		panic("eof")
	}
	c := f.s[f.pos]
	switch c {
	case '[':
		f.pos++
		n := &ynode{kind: ynSeq}
		for {
			f.ws()
			if f.pos >= len(f.s) {
				panic("eof")
			}
			if f.s[f.pos] == ']' {
				f.pos++
				return n
			}
			v := f.value()
			f.ws()
			// single pair mapping in sequence
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				val := f.value()
				m := &ynode{kind: ynMap, keys: []string{v.value}, vals: []*ynode{val}}
				v = m
				f.ws()
			}
			n.items = append(n.items, v)
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
				continue
			}
			f.ws()
			if f.pos < len(f.s) && f.s[f.pos] == ']' {
				f.pos++
				return n
			}
			panic("bad")
		}
	case '{':
		f.pos++
		n := &ynode{kind: ynMap}
		for {
			f.ws()
			if f.pos >= len(f.s) {
				panic("eof")
			}
			if f.s[f.pos] == '}' {
				f.pos++
				return n
			}
			k := f.value()
			f.ws()
			var v *ynode
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
				f.ws()
				if f.pos < len(f.s) && (f.s[f.pos] == ',' || f.s[f.pos] == '}') {
					v = &ynode{kind: ynNull}
				} else {
					v = f.value()
				}
			} else {
				v = &ynode{kind: ynNull}
			}
			n.keys = append(n.keys, k.value)
			n.vals = append(n.vals, v)
			f.ws()
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
				continue
			}
			if f.pos < len(f.s) && f.s[f.pos] == '}' {
				f.pos++
				return n
			}
			panic("bad")
		}
	case '"', '\'':
		q := c
		i := f.pos + 1
		for i < len(f.s) {
			if q == '"' && f.s[i] == '\\' {
				i += 2
				continue
			}
			if f.s[i] == q {
				if q == '\'' && i+1 < len(f.s) && f.s[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			i++
		}
		if i >= len(f.s) {
			panic("eof")
		}
		raw := f.s[f.pos : i+1]
		f.pos = i + 1
		body := raw[1 : len(raw)-1]
		body = strings.Join(strings.Fields(strings.ReplaceAll(body, "\n", " ")), " ")
		if q == '\'' {
			body = strings.ReplaceAll(body, "''", "'")
		} else {
			body = unescapeDouble(body)
		}
		return &ynode{kind: ynScalar, value: body, style: q}
	default:
		st := f.pos
		for f.pos < len(f.s) {
			ch := f.s[f.pos]
			if ch == ',' || ch == ']' || ch == '}' || ch == '[' || ch == '{' {
				break
			}
			if ch == ':' && (f.pos+1 >= len(f.s) || strings.ContainsRune(" \n,]}", rune(f.s[f.pos+1]))) {
				break
			}
			if ch == '#' && f.pos > 0 && f.s[f.pos-1] == ' ' {
				break
			}
			f.pos++
		}
		v := strings.Join(strings.Fields(f.s[st:f.pos]), " ")
		if v == "" {
			return &ynode{kind: ynNull}
		}
		return &ynode{kind: ynScalar, value: v, style: 'p'}
	}
}

var yamlBools = map[string]bool{
	"y": true, "Y": true, "yes": true, "Yes": true, "YES": true,
	"n": false, "N": false, "no": false, "No": false, "NO": false,
	"true": true, "True": true, "TRUE": true, "false": false, "False": false, "FALSE": false,
	"on": true, "On": true, "ON": true, "off": false, "Off": false, "OFF": false,
}

func isYamlNull(s string) bool {
	return s == "" || s == "~" || s == "null" || s == "Null" || s == "NULL"
}

// yamlToMeta converts parsed yaml to Meta using markdown parsing for strings
func (p *mdP) yamlToMeta(raw string) (Meta, error) {
	n, err := parseYAML(raw)
	if err != nil {
		return nil, err
	}
	m := Meta{}
	if n.kind == ynNull {
		return m, nil
	}
	if n.kind != ynMap {
		return m, nil
	}
	for i, k := range n.keys {
		if strings.HasSuffix(k, "_") {
			continue
		}
		m[k] = p.yamlNodeToMeta(n.vals[i])
	}
	return m, nil
}

func (p *mdP) yamlNodeToMeta(n *ynode) MetaValue {
	switch n.kind {
	case ynNull:
		return &MetaString{""}
	case ynSeq:
		var xs []MetaValue
		for _, it := range n.items {
			xs = append(xs, p.yamlNodeToMeta(it))
		}
		return &MetaList{xs}
	case ynMap:
		mm := map[string]MetaValue{}
		for i, k := range n.keys {
			if strings.HasSuffix(k, "_") {
				continue
			}
			mm[k] = p.yamlNodeToMeta(n.vals[i])
		}
		return &MetaMap{mm}
	}
	if n.style == 'p' {
		if b, ok := yamlBools[n.value]; ok {
			return &MetaBool{b}
		}
		if isYamlNull(n.value) {
			return &MetaString{""}
		}
	}
	return p.metaValueFromString(n.value)
}

func (p *mdP) metaValueFromString(x string) MetaValue {
	if strings.HasSuffix(strings.TrimRight(x, " \t"), "\n") {
		sp := p.sub(x + "\n")
		bs := sp.parseBlocks()
		return &MetaBlocks{bs}
	}
	sp := p.sub(x)
	ils := sp.inlinesAll()
	return &MetaInlines{trimInlines(ils)}
}

// inlinesAll parses inlines until eof, treating blank lines as spaces
func (p *mdP) inlinesAll() []Inline {
	var ils []Inline
	for !p.eof() {
		x, ok := p.inline()
		if !ok {
			// skip a char
			if p.peek() == '\n' {
				p.pos++
				ils = appendInlMut(ils, &SoftBreak{})
				continue
			}
			ils = appendInlMut(ils, &Str{string(p.peek())})
			p.pos++
			continue
		}
		ils = appendInlMut(ils, x...)
	}
	return ils
}
