		maxNest:     6,
		abbrevs:     defaultAbbrevs,
	}
}

func readMarkdown(input string, opts *ReaderOptions) (*Pandoc, error) {
	st := newMdState(opts)
	p := newMdParser(input+"\n\n", st, 0)
	if st.exts.On("pandoc_title_block") {
		p.titleBlock()
	}
	if st.exts.On("mmd_title_block") {
		p.mmdTitleBlock()
	}
	bs := p.parseBlocks()
	bs = resolveBlocks(st, bs)
	meta := Meta{}
	for k, v := range st.meta {
		meta[k] = resolveMeta(st, v)
	}
	return &Pandoc{meta, bs}, nil
}

// ---------- title block ----------

func (p *mdP) titleBlock() {
	if !p.lookStr("%") {
		return
	}
	s := p.save()
	titleLine := func() (string, bool) {
		if !p.char('%') {
			return "", false
		}
		p.skipSpaces()
		var lines []string
		l, _ := p.anyLine()
		lines = append(lines, l)
		for !p.eof() && isSpaceChar(p.peek()) && !p.isBlankLineAhead() {
			p.skipSpaces()
			l, _ := p.anyLine()
			lines = append(lines, l)
		}
		return strings.Join(lines, "\n"), true
	}
	title, ok := titleLine()
	if !ok {
		p.restore(s)
		return
	}
	var author, date string
	hasAuthor, hasDate := false, false
	if p.peek() == '%' {
		author, _ = titleLine()
		hasAuthor = true
		if p.peek() == '%' {
			date, _ = titleLine()
			hasDate = true
		}
	}
	p.blanklines()
	if strings.TrimSpace(title) != "" {
		ils := trimInlines(p.sub(title).inlines())
		if _, ok := p.st.meta["title"]; !ok {
			p.st.meta["title"] = &MetaInlines{ils}
		}
	}
	if hasAuthor && strings.TrimSpace(author) != "" {
		// authors separated by ; or newlines
		var parts []string
		for _, a := range strings.FieldsFunc(author, func(r rune) bool { return r == ';' || r == '\n' }) {
			if strings.TrimSpace(a) != "" {
				parts = append(parts, a)
			}
		}
		var ms []MetaValue
		for _, a := range parts {
			ms = append(ms, &MetaInlines{trimInlines(p.sub(strings.TrimSpace(a)).inlines())})
		}
		if _, ok := p.st.meta["author"]; !ok {
			p.st.meta["author"] = &MetaList{ms}
		}
	}
	if hasDate && strings.TrimSpace(date) != "" {
		if _, ok := p.st.meta["date"]; !ok {
			p.st.meta["date"] = &MetaInlines{trimInlines(p.sub(date).inlines())}
		}
	}
}

func (p *mdP) mmdTitleBlock() {}

// ---------- resolution ----------

func resolveInlines(st *mdState, xs []Inline) []Inline {
	var out []Inline
	prevPending := false
	for _, x := range xs {
		if pi, ok := x.(*pendingInl); ok {
			r := resolveInlines(st, pi.f())
			for _, y := range r {
				out = appendInlMut(out, y)
			}
			prevPending = true
			continue
		}
		y := resolveInline(st, x)
		if prevPending {
			out = appendInlMut(out, y)
		} else {
			out = append(out, y)
		}
		prevPending = false
	}
	return out
}

func resolveInline(st *mdState, x Inline) Inline {
	switch v := x.(type) {
	case *Emph:
		return &Emph{resolveInlines(st, v.Inlines)}
	case *Underline:
		return &Underline{resolveInlines(st, v.Inlines)}
	case *Strong:
		return &Strong{resolveInlines(st, v.Inlines)}
	case *Strikeout:
		return &Strikeout{resolveInlines(st, v.Inlines)}
	case *Superscript:
		return &Superscript{resolveInlines(st, v.Inlines)}
	case *Subscript:
		return &Subscript{resolveInlines(st, v.Inlines)}
	case *SmallCaps:
		return &SmallCaps{resolveInlines(st, v.Inlines)}
	case *Quoted:
		return &Quoted{v.Type, resolveInlines(st, v.Inlines)}
	case *Cite:
		cs := make([]Citation, len(v.Citations))
		for i, c := range v.Citations {
			c.Prefix = resolveInlines(st, c.Prefix)
			c.Suffix = resolveInlines(st, c.Suffix)
			cs[i] = c
		}
		return &Cite{cs, resolveInlines(st, v.Inlines)}
	case *Link:
		return &Link{v.Attr, resolveInlines(st, v.Inlines), v.Target}
	case *Image:
		return &Image{v.Attr, resolveInlines(st, v.Inlines), v.Target}
	case *Note:
		return &Note{resolveBlocks(st, v.Blocks)}
	case *Span:
		return &Span{v.Attr, resolveInlines(st, v.Inlines)}
	}
	return x
}

func resolveBlocks(st *mdState, bs []Block) []Block {
	out := make([]Block, 0, len(bs))
	for _, b := range bs {
		out = append(out, resolveBlock(st, b))
	}
	return out
}

func resolveItems(st *mdState, items [][]Block) [][]Block {
	out := make([][]Block, len(items))
	for i, it := range items {
		out[i] = resolveBlocks(st, it)
	}
	return out
}

func resolveRows(st *mdState, rows []Row) []Row {
	out := make([]Row, len(rows))
	for i, r := range rows {
		cells := make([]Cell, len(r.Cells))
		for j, c := range r.Cells {
			c.Blocks = resolveBlocks(st, c.Blocks)
			cells[j] = c
		}
		out[i] = Row{r.Attr, cells}
	}
	return out
}

func resolveCaption(st *mdState, c Caption) Caption {
	return Caption{resolveInlines(st, c.Short), c.HasShort, resolveBlocks(st, c.Long)}
}

func resolveBlock(st *mdState, b Block) Block {
	switch v := b.(type) {
	case *mdPara:
		ils := resolveInlines(st, v.Inlines)
		if len(ils) == 1 {
			if img, ok := ils[0].(*Image); ok && len(img.Inlines) > 0 {
				imgAttr := Attr{"", img.Attr.Classes, img.Attr.KVs}
				return &Figure{Attr{ID: img.Attr.ID}, Caption{Long: []Block{&Plain{img.Inlines}}},
					[]Block{&Plain{[]Inline{&Image{imgAttr, img.Inlines, img.Target}}}}}
			}
		}
		return &Para{ils}
	case *Para:
		return &Para{resolveInlines(st, v.Inlines)}
	case *Plain:
		return &Plain{resolveInlines(st, v.Inlines)}
	case *Header:
		return &Header{v.Level, v.Attr, resolveInlines(st, v.Inlines)}
	case *LineBlock:
		ls := make([][]Inline, len(v.Lines))
		for i, l := range v.Lines {
			ls[i] = resolveInlines(st, l)
		}
		return &LineBlock{ls}
	case *BlockQuote:
		return &BlockQuote{resolveBlocks(st, v.Blocks)}
	case *Div:
		return &Div{v.Attr, resolveBlocks(st, v.Blocks)}
	case *BulletList:
		return &BulletList{resolveItems(st, v.Items)}
	case *OrderedList:
		return &OrderedList{v.Attrs, resolveItems(st, v.Items)}
	case *DefinitionList:
		items := make([]DefItem, len(v.Items))
		for i, it := range v.Items {
			items[i] = DefItem{resolveInlines(st, it.Term), resolveItems(st, it.Defs)}
		}
		return &DefinitionList{items}
	case *Table:
		t := *v
		t.Caption = resolveCaption(st, v.Caption)
		t.Head = TableHead{v.Head.Attr, resolveRows(st, v.Head.Rows)}
		t.Bodies = make([]TableBody, len(v.Bodies))
		for i, tb := range v.Bodies {
			t.Bodies[i] = TableBody{tb.Attr, tb.RowHeadColumns, resolveRows(st, tb.Head), resolveRows(st, tb.Body)}
		}
		t.Foot = TableFoot{v.Foot.Attr, resolveRows(st, v.Foot.Rows)}
		return &t
	case *Figure:
		return &Figure{v.Attr, resolveCaption(st, v.Caption), resolveBlocks(st, v.Blocks)}
	}
	return b
}

func resolveMeta(st *mdState, m MetaValue) MetaValue {
	switch v := m.(type) {
	case *MetaInlines:
		return &MetaInlines{resolveInlines(st, v.Inlines)}
	case *MetaBlocks:
		return &MetaBlocks{resolveBlocks(st, v.Blocks)}
	case *MetaList:
