// ---------- identifiers ----------

func uniqueIdent(exts *Extensions, title []Inline, used map[string]bool) string {
	base := inlineListToIdentifier(exts, title)
	if base == "" {
		base = "section"
	}
	if !used[base] {
		return base
	}
	for i := 1; i <= 60000; i++ {
		c := base + "-" + strconv.Itoa(i)
		if !used[c] {
			return c
		}
	}
	return base
}

func inlineListToIdentifier(exts *Extensions, xs []Inline) string {
	return textToIdentifier(exts, stringify(xs))
}

func textToIdentifier(exts *Extensions, s string) string {
	gfm := exts.On("gfm_auto_identifiers")
	s = strings.ToLower(s)
	isAllowedPunct := func(c rune) bool {
		if gfm {
			return c == '-' || c == '_' || unicode.In(c, unicode.Mn, unicode.Mc, unicode.Me, unicode.Pc)
		}
		return c == '_' || c == '-' || c == '.'
	}
	var sb strings.Builder
	for _, c := range s {
		if isSpaceH(c) || isAlphaNumH(c) || isAllowedPunct(c) {
			sb.WriteRune(c)
		}
	}
	t := sb.String()
	if gfm {
		var sb2 strings.Builder
		for _, c := range t {
			if isSpaceH(c) {
				sb2.WriteRune('-')
			} else {
				sb2.WriteRune(c)
			}
		}
		t = sb2.String()
	} else {
		t = strings.Join(strings.FieldsFunc(t, isSpaceH), "-")
	}
	if exts.On("ascii_identifiers") {
		var sb3 strings.Builder
		for _, c := range toAsciiText(t) {
			if c < 128 {
				sb3.WriteRune(c)
			}
		}
		t = sb3.String()
	}
	if !gfm {
		rs := []rune(t)
		i := 0
		for i < len(rs) && !unicode.IsLetter(rs[i]) {
			i++
		}
		t = string(rs[i:])
	}
	return t
}

func toAsciiText(s string) string {
	var sb strings.Builder
	for _, c := range s {
		if c < 128 {
			sb.WriteRune(c)
			continue
		}
		if r, ok := asciiMap[c]; ok {
			sb.WriteString(r)
		}
	}
	return sb.String()
}

