func walkInlines(xs []Inline, f func(Inline)) {
	for _, x := range xs {
		f(x)
		switch v := x.(type) {
		case *Emph:
			walkInlines(v.Inlines, f)
		case *Underline:
			walkInlines(v.Inlines, f)
		case *Strong:
			walkInlines(v.Inlines, f)
		case *Strikeout:
			walkInlines(v.Inlines, f)
		case *Superscript:
			walkInlines(v.Inlines, f)
		case *Subscript:
			walkInlines(v.Inlines, f)
		case *SmallCaps:
			walkInlines(v.Inlines, f)
		case *Quoted:
			walkInlines(v.Inlines, f)
		case *Cite:
			for _, c := range v.Citations {
				walkInlines(c.Prefix, f)
				walkInlines(c.Suffix, f)
			}
			walkInlines(v.Inlines, f)
		case *Link:
			walkInlines(v.Inlines, f)
		case *Image:
			walkInlines(v.Inlines, f)
		case *Span:
			walkInlines(v.Inlines, f)
		case *Note:
			walkInlinesInBlocks(v.Blocks, f)
		}
	}
}

func walkInlinesInBlock(b Block, f func(Inline)) {
	switch v := b.(type) {
	case *Plain:
		walkInlines(v.Inlines, f)
	case *Para:
		walkInlines(v.Inlines, f)
	case *mdPara:
		walkInlines(v.Inlines, f)
	case *Header:
		walkInlines(v.Inlines, f)
	case *LineBlock:
		for _, l := range v.Lines {
			walkInlines(l, f)
		}
	case *BlockQuote:
		walkInlinesInBlocks(v.Blocks, f)
	case *Div:
		walkInlinesInBlocks(v.Blocks, f)
	case *BulletList:
		for _, it := range v.Items {
			walkInlinesInBlocks(it, f)
		}
	case *OrderedList:
		for _, it := range v.Items {
			walkInlinesInBlocks(it, f)
		}
	case *DefinitionList:
		for _, it := range v.Items {
			walkInlines(it.Term, f)
			for _, d := range it.Defs {
				walkInlinesInBlocks(d, f)
			}
		}
	case *Table:
		walkInlines(v.Caption.Short, f)
		walkInlinesInBlocks(v.Caption.Long, f)
		for _, r := range v.Head.Rows {
			for _, c := range r.Cells {
				walkInlinesInBlocks(c.Blocks, f)
			}
		}
		for _, tb := range v.Bodies {
			for _, r := range append(append([]Row{}, tb.Head...), tb.Body...) {
				for _, c := range r.Cells {
					walkInlinesInBlocks(c.Blocks, f)
				}
			}
		}
		for _, r := range v.Foot.Rows {
			for _, c := range r.Cells {
				walkInlinesInBlocks(c.Blocks, f)
			}
		}
	case *Figure:
		walkInlinesInBlocks(v.Caption.Long, f)
		walkInlinesInBlocks(v.Blocks, f)
	}
}
