package main

import (
	"sort"
	"strings"
	"unicode/utf8"
)

type tableParts struct {
	aligns []Alignment
	widths []float64
	heads  [][]Block
	rows   [][][]Block
	// for grid tables with spans
	cells *gridResult
}

func (p *mdP) table() ([]Block, bool) {
	var frontCap []Inline
	var frontAttr Attr
	hasFront := false
	{
		s := p.save()
		if c, a, ok := p.tableCaption(); ok {
			frontCap, frontAttr, hasFront = c, a, true
		} else {
			p.restore(s)
		}
	}
	var tp *tableParts
	tries := []func() (*tableParts, bool){}
	if p.ext("pipe_tables") {
		tries = append(tries, func() (*tableParts, bool) {
			if !p.scanForPipe() {
				return nil, false
			}
			return p.pipeTable()
		})
	}
	if p.ext("multiline_tables") {
		tries = append(tries, func() (*tableParts, bool) { return p.multilineTable(false) })
	}
	if p.ext("simple_tables") {
		tries = append(tries, func() (*tableParts, bool) {
			s := p.save()
			if r, ok := p.simpleTable(true); ok {
				return r, true
			}
			p.restore(s)
			return p.simpleTable(false)
		})
	}
	if p.ext("multiline_tables") {
		tries = append(tries, func() (*tableParts, bool) { return p.multilineTable(true) })
	}
	if p.ext("grid_tables") {
		tries = append(tries, func() (*tableParts, bool) {
			return p.gridTable()
		})
	}
	for _, f := range tries {
		s := p.save()
		if r, ok := f(); ok {
			tp = r
			break
		}
		p.restore(s)
	}
	if tp == nil {
		return nil, false
	}
	p.blanklines()
	capIls := frontCap
	attr := frontAttr
	if !hasFront {
		s := p.save()
		if c, a, ok := p.tableCaption(); ok {
			capIls, attr = c, a
		} else {
			p.restore(s)
		}
	}
	total := 0.0
	for _, w := range tp.widths {
		total += w
	}
	widths := tp.widths
	if total >= 1 {
		widths = make([]float64, len(tp.widths))
		for i, w := range tp.widths {
			widths[i] = w / total
		}
	}
	var specs []ColSpec
	for i, a := range tp.aligns {
		cs := ColSpec{Align: a}
		if i < len(widths) && widths[i] > 0 {
			cs.Width = widths[i]
			cs.HasWidth = true
		}
		specs = append(specs, cs)
	}
	var cap Caption
	if len(capIls) > 0 {
		cap.Long = []Block{&Plain{capIls}}
	}
	t := &Table{Attr: attr, Caption: cap, ColSpecs: specs}
	if tp.cells != nil {
		t.Head = TableHead{Rows: tp.cells.head}
		t.Bodies = []TableBody{{Body: tp.cells.body}}
		t.Foot = TableFoot{Rows: tp.cells.foot}
	} else {
		if len(tp.heads) > 0 {
			t.Head = TableHead{Rows: []Row{simpleRow(tp.heads)}}
		}
		var rows []Row
		for _, r := range tp.rows {
			rows = append(rows, simpleRow(r))
		}
		t.Bodies = []TableBody{{Body: rows}}
	}
	normalizeTable(t)
	return []Block{t}, true
}

func simpleRow(cells [][]Block) Row {
	var r Row
	for _, c := range cells {
		r.Cells = append(r.Cells, Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1, Blocks: c})
	}
	return r
}

func emptyCell() Cell { return Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1} }

// normalizeTable pads/clips rows to table width (pandoc-types B.table)
func normalizeTable(t *Table) {
	w := len(t.ColSpecs)
	t.Head.Rows = normalizeRows(w, t.Head.Rows)
	for i := range t.Bodies {
		t.Bodies[i].Head = normalizeRows(w, t.Bodies[i].Head)
		t.Bodies[i].Body = normalizeRows(w, t.Bodies[i].Body)
	}
	t.Foot.Rows = normalizeRows(w, t.Foot.Rows)
}

func normalizeRows(w int, rows []Row) []Row {
	// track row spans
	pending := make([]int, w) // remaining rowspan occupancy per column
	var out []Row
	for _, r := range rows {
		var cells []Cell
		col := 0
		ci := 0
		for col < w {
			if pending[col] > 0 {
				pending[col]--
				col++
				continue
			}
			if ci >= len(r.Cells) {
				cells = append(cells, emptyCell())
				col++
				continue
			}
			c := r.Cells[ci]
			ci++
			// clip colspan
			cs := c.ColSpan
			if cs < 1 {
				cs = 1
			}
			// available contiguous free columns
			avail := 0
			for k := col; k < w && pending[k] == 0 && avail < cs; k++ {
				avail++
			}
			if cs > avail {
				cs = avail
			}
			c.ColSpan = cs
			if c.RowSpan < 1 {
				c.RowSpan = 1
			}
			for k := col; k < col+cs; k++ {
				pending[k] = c.RowSpan - 1
			}
			cells = append(cells, c)
			col += cs
		}
		out = append(out, Row{r.Attr, cells})
	}
	return out
}

func (p *mdP) tableCaption() ([]Inline, Attr, bool) {
	if !p.ext("table_captions") {
		return nil, Attr{}, false
	}
	var ils []Inline
	var attr Attr
	ok := p.try(func() bool {
		if !p.skipNonindentSpaces() {
			return false
		}
		if p.char(':') {
			if isPunctH(p.peek()) {
				return false
			}
		} else if (p.peek() == 'T' || p.peek() == 't') && p.lookStr(string(p.peek())+"able:") {
			p.pos += 6
		} else {
			return false
		}
		var res []Inline
		n := 0
		for !p.eof() {
			if p.ext("table_attributes") {
				s := p.save()
				p.skipSpaces()
				if a, ok := p.attributes(); ok {
					if p.look(func() bool { return p.blanklines() > 0 }) {
						attr = a
						break
					}
				}
				p.restore(s)
			}
			x, ok := p.inline()
			if !ok {
				break
			}
			res = appendInlMut(res, x...)
			n++
		}
		if n == 0 {
			return false
		}
		ils = trimInlines(res)
		return p.blanklines() > 0
	})
	return ils, attr, ok
}

// ---------- pipe tables ----------

func (p *mdP) scanForPipe() bool {
	for i := p.pos; i < len(p.s); i++ {
		if p.s[i] == '\n' {
			return false
		}
		if p.s[i] == '|' {
			return true
		}
	}
	return false
}

func (p *mdP) sepPipe() bool {
	return p.try(func() bool {
		if !(p.char('|') || p.char('+')) {
			return false
		}
		return !p.isBlankLineAhead()
	})
}

func (p *mdP) pipeTableRow() ([]string, bool) {
	var cells []string
	ok := p.try(func() bool {
		if !p.scanForPipe() {
			return false
		}
		p.skipSpaces()
		openPipe := p.sepPipe()
		for {
			st := p.pos
			for !p.eof() {
				c := p.peek()
				if c == '|' || c == '\n' || c == '\r' {
					break
				}
				s := p.save()
				switch c {
				case '`':
					if _, ok := p.code(); ok {
						continue
					}
				case '$':
					if _, ok := p.math(); ok {
						continue
					}
				case '<':
					if _, ok := p.rawHtmlInline(); ok {
						continue
					}
				case '\\':
					if _, ok := p.escapedChar(); ok {
						continue
					}
					p.restore(s)
					if _, ok := p.rawLaTeXInlineP(); ok {
						continue
					}
				}
				p.restore(s)
				p.pos++
			}
			cells = append(cells, string(p.s[st:p.pos]))
			if !p.sepPipe() {
				break
			}
		}
		p.skipSpaces()
		closePipe := p.char('|')
		if !(openPipe || closePipe || len(cells) > 1) {
			return false
		}
		return p.blankline()
	})
	return cells, ok
}

func (p *mdP) pipeTableHeaderPart() (Alignment, int, bool) {
	var a Alignment
	n := 0
	ok := p.try(func() bool {
		p.skipSpaces()
		left := p.char(':')
		d := 0
		for p.char('-') {
			d++
		}
		if d == 0 {
			return false
		}
		right := p.char(':')
		p.skipSpaces()
		n = d
		if left {
			n++
		}
		if right {
			n++
		}
		switch {
		case left && right:
			a = AlignCenter
		case left:
			a = AlignLeft
		case right:
			a = AlignRight
		default:
			a = AlignDefault
		}
		return true
	})
	return a, n, ok
}

func (p *mdP) pipeBreak() ([]Alignment, []int, bool) {
	var aligns []Alignment
	var lens []int
	ok := p.try(func() bool {
		if !p.skipNonindentSpaces() {
			return false
		}
		openPipe := false
		if p.peek() == '|' && !isSpaceH(p.peekAt(1)) && p.peekAt(1) != 0 {
			p.pos++
			openPipe = true
		}
		a, l, ok := p.pipeTableHeaderPart()
		if !ok {
			return false
		}
		aligns = append(aligns, a)
		lens = append(lens, l)
		for {
			s := p.save()
			if !p.sepPipe() {
				break
			}
			a, l, ok := p.pipeTableHeaderPart()
			if !ok {
				p.restore(s)
				break
			}
			aligns = append(aligns, a)
			lens = append(lens, l)
		}
		if len(aligns) == 1 && !openPipe {
			return false
		}
		p.char('|')
		return p.blankline()
	})
	return aligns, lens, ok
}

func (p *mdP) pipeTableCell(raw string) []Block {
	t := strings.TrimSpace(raw)
	sp := p.sub(t)
	ils, ok := sp.inlines1()
	if !ok {
		return nil
	}
	return []Block{&Plain{ils}}
}

func (p *mdP) pipeTable() (*tableParts, bool) {
	if !p.skipNonindentSpaces() {
		return nil, false
	}
	if p.eof() || isSpaceH(p.peek()) {
		return nil, false
	}
	heads, ok := p.pipeTableRow()
	if !ok {
		return nil, false
	}
	aligns, seplens, ok := p.pipeBreak()
	if !ok {
		return nil, false
	}
	numcols := len(aligns)
	if len(heads) > numcols {
		heads = heads[:numcols]
	}
	var lines [][]string
	var rawLines []string
	for {
		st := p.pos
		r, ok := p.pipeTableRow()
		if !ok {
			break
		}
		rawLines = append(rawLines, string(p.s[st:p.pos]))
		if len(r) > numcols {
			r = r[:numcols]
		}
		lines = append(lines, r)
	}
	maxlen := 0
	all := append([][]string{heads}, lines...)
	for _, row := range all {
		// length of the raw row text
		l := 0
		for i, c := range row {
			if i > 0 {
				l++
			}
			l += utf8.RuneCountInString(c)
		}
		if l > maxlen {
			maxlen = l
		}
	}
	_ = rawLines
	widths := make([]float64, numcols)
	if maxlen > p.st.opts.Columns {
		tot := 0
		for _, l := range seplens {
			tot += l
		}
		for i, l := range seplens {
			widths[i] = float64(l) / float64(tot)
		}
	}
	var headCells [][]Block
	for _, h := range heads {
		headCells = append(headCells, p.pipeTableCell(h))
	}
	var rows [][][]Block
	for _, l := range lines {
		var r [][]Block
		for _, c := range l {
			r = append(r, p.pipeTableCell(c))
		}
		rows = append(rows, r)
	}
	return &tableParts{aligns: aligns, widths: widths, heads: headCells, rows: rows}, true
}

// ---------- simple & multiline tables ----------

func (p *mdP) dashedLine(ch rune) (int, int, bool) {
	d := 0
	for p.char(ch) {
		d++
	}
	if d == 0 {
		return 0, 0, false
	}
	sp := 0
	for p.spaceChar() {
		sp++
	}
	return d, d + sp, true
}

func (p *mdP) dashedLines() ([]int, []int, bool) {
	var lengths, lines []int
	for {
		l, t, ok := p.dashedLine('-')
		if !ok {
			break
		}
		lengths = append(lengths, l)
		lines = append(lines, t)
	}
	return lengths, lines, len(lengths) > 0
}

func splitByIndices(ind []int, s string) []string {
	rs := []rune(s)
	var out []string
	prev := 0
	for _, i := range ind {
		if i > len(rs) {
			i = len(rs)
		}
		if i < prev {
			i = prev
		}
		out = append(out, string(rs[prev:i]))
		prev = i
	}
	out = append(out, string(rs[prev:]))
	return out
}

// splitTextByIndices with East Asian width handling (pandoc uses char width)
func splitTextByIndices(ind []int, s string) []string {
	// convert display-column indices into rune indices
	rs := []rune(s)
	var out []string
	prevRune := 0
	col := 0
	ri := 0
	for _, target := range ind {
		for ri < len(rs) && col+charWidth(rs[ri]) <= target {
			col += charWidth(rs[ri])
			ri++
		}
		if ri < len(rs) && col < target {
			// wide char straddles boundary: include it
			col += charWidth(rs[ri])
			ri++
		}
		out = append(out, string(rs[prevRune:ri]))
		prevRune = ri
	}
	out = append(out, string(rs[prevRune:]))
	return out
}

func alignType(strs []string, length int) Alignment {
	var nonempties []string
	for _, s := range strs {
		t := strings.TrimRight(s, " \t\n\r")
		if t != "" {
			nonempties = append(nonempties, t)
		}
	}
	if len(strs) == 0 || len(nonempties) == 0 {
		return AlignDefault
	}
	sort.SliceStable(nonempties, func(i, j int) bool {
		return utf8.RuneCountInString(nonempties[i]) < utf8.RuneCountInString(nonempties[j])
	})
	x := nonempties[0]
	left := x[0] == ' ' || x[0] == '\t'
	right := utf8.RuneCountInString(x) < length
	switch {
	case left && !right:
		return AlignRight
	case !left && right:
		return AlignLeft
	case left && right:
		return AlignCenter
	}
	return AlignDefault
}

func widthsFromIndices(numColumns int, indices []int) []float64 {
	if len(indices) == 0 {
		return nil
	}
	last := indices[len(indices)-1]
	if last > numColumns {
		numColumns = last
	}
	lengths := make([]int, len(indices))
	prev := 0
	for i, x := range indices {
		lengths[i] = x - prev
		prev = x
	}
	if len(lengths) >= 2 {
		x := lengths[len(lengths)-1]
		y := lengths[len(lengths)-2]
		if x < y && y-x <= 2 {
			lengths[len(lengths)-1] = y
		}
	}
	tot := 0
	for _, l := range lengths {
		tot += l
	}
	q := float64(numColumns)
	if tot > numColumns {
		q = float64(tot)
	}
	fr := make([]float64, len(lengths))
	for i, l := range lengths {
		fr[i] = float64(l) / q
	}
	return fr[1:]
}

func (p *mdP) blanklinesP() bool {
	// blanklines' = blanklines <|> eof-ish
	if p.blanklines() > 0 {
		return true
	}
	return p.eof()
}

func (p *mdP) tableFooter() bool {
	return p.try(func() bool {
		if !p.skipNonindentSpaces() {
			return false
		}
		if _, _, ok := p.dashedLines(); !ok {
			return false
		}
		return p.blanklinesP()
	})
}

func (p *mdP) tableSep() bool {
	return p.try(func() bool {
		if !p.skipNonindentSpaces() {
			return false
		}
		if _, _, ok := p.dashedLines(); !ok {
			return false
		}
		return p.newline()
	})
}

func (p *mdP) rawTableLine(indices []int) ([]string, bool) {
	s := p.save()
	if p.look(func() bool { return p.blanklinesP() }) || p.look(p.tableFooter) {
		return nil, false
	}
	if p.eof() {
		return nil, false
	}
	st := p.pos
	for !p.eof() && p.peek() != '\n' {
		p.pos++
	}
	if p.pos == st || !p.newline() {
		p.restore(s)
		return nil, false
	}
	line := string(p.s[st : p.pos-1])
	var ind []int
	if len(indices) > 0 {
		ind = indices[:len(indices)-1]
	}
	parts := splitTextByIndices(ind, line)
	var out []string
	for _, x := range parts[1:] {
		out = append(out, strings.TrimSpace(x))
	}
	return out, true
}

func (p *mdP) plainCell(raw string) []Block {
	sp := p.sub(raw)
	var bs []Block
	for !sp.eof() {
		if sp.blanklines() > 0 {
			continue
		}
		ils, ok := sp.inlines1()
		if !ok {
			break
		}
		bs = append(bs, &Plain{trimInlines(ils)})
	}
	// mconcat <$> many plain : adjacent Plains? pandoc's plain = many1 inline then
	return mergePlains(bs)
}

func mergePlains(bs []Block) []Block {
	return bs
}

func (p *mdP) tableLine(indices []int) ([][]Block, bool) {
	raw, ok := p.rawTableLine(indices)
	if !ok {
		return nil, false
	}
	var out [][]Block
	for _, r := range raw {
		out = append(out, p.plainCell(r))
	}
	return out, true
}

func (p *mdP) multilineRow(indices []int) ([][]Block, bool) {
	var colLines [][]string
	for {
		r, ok := p.rawTableLine(indices)
		if !ok {
			break
		}
		colLines = append(colLines, r)
	}
	if len(colLines) == 0 {
		return nil, false
	}
	ncols := 0
	for _, l := range colLines {
		if len(l) > ncols {
			ncols = len(l)
		}
	}
	var out [][]Block
	for c := 0; c < ncols; c++ {
		var sb strings.Builder
		for _, l := range colLines {
			if c < len(l) {
				sb.WriteString(l[c])
			}
			sb.WriteString("\n")
		}
		out = append(out, p.plainCell(sb.String()))
	}
	return out, true
}

func (p *mdP) simpleTableHeader(headless bool) ([][]Block, []Alignment, []int, bool) {
	var heads [][]Block
	var aligns []Alignment
	var indices []int
	ok := p.try(func() bool {
		rawContent := ""
		if !headless {
			l, ok := p.anyLine()
			if !ok {
				return false
			}
			rawContent = l
		}
		initSp, ok := p.nonindentSpaces()
		if !ok {
			return false
		}
		lengths, lines, ok := p.dashedLines()
		if !ok {
			return false
		}
		if !p.newline() {
			return false
		}
		indices = []int{initSp}
		acc := initSp
		for _, l := range lines {
			acc += l
			indices = append(indices, acc)
		}
		var rawHeads []string
		var line string
		if headless {
			s := p.save()
			l, _ := p.anyLine()
			p.restore(s)
			line = l
		} else {
			line = rawContent
		}
		parts := splitTextByIndices(indices[:len(indices)-1], line)
		rawHeads = parts[1:]
		for i, l := range lengths {
			var hs []string
			if i < len(rawHeads) {
				hs = []string{rawHeads[i]}
			}
			aligns = append(aligns, alignType(hs, l))
		}
		if !headless {
			for _, h := range rawHeads {
				heads = append(heads, p.plainCell(strings.TrimSpace(h)))
			}
		}
		return true
	})
	return heads, aligns, indices, ok
}

func (p *mdP) simpleTable(headless bool) (*tableParts, bool) {
	var res *tableParts
	ok := p.try(func() bool {
		heads, aligns, indices, ok := p.simpleTableHeader(headless)
		if !ok {
			return false
		}
		var rows [][][]Block
		for {
			r, ok := p.tableLine(indices)
			if !ok {
				break
			}
			rows = append(rows, r)
		}
		if len(rows) == 0 {
			return false
		}
		if headless {
			if !p.tableFooter() {
				return false
			}
		} else {
			if !p.tableFooter() && !p.blanklinesP() {
				return false
			}
		}
		res = &tableParts{aligns: aligns, widths: make([]float64, len(aligns)), heads: heads, rows: rows}
		return true
	})
	return res, ok
}

func (p *mdP) multilineTableHeader(headless bool) ([][]Block, []Alignment, []int, bool) {
	var heads [][]Block
	var aligns []Alignment
	var indices []int
	ok := p.try(func() bool {
		if !headless {
			if !p.tableSep() {
				return false
			}
			if p.isBlankLineAhead() {
				return false
			}
		}
		var rawContent []string
		if !headless {
			for {
				if p.look(p.tableSep) {
					break
				}
				st := p.pos
				for !p.eof() && p.peek() != '\n' {
					p.pos++
				}
				if p.pos == st || !p.newline() {
					break
				}
				rawContent = append(rawContent, string(p.s[st:p.pos-1]))
			}
			if len(rawContent) == 0 {
				return false
			}
		}
		initSp, ok := p.nonindentSpaces()
		if !ok {
			return false
		}
		lengths, lines, ok := p.dashedLines()
		if !ok {
			return false
		}
		if !p.newline() {
			return false
		}
		indices = []int{initSp}
		acc := initSp
		for _, l := range lines {
			acc += l
			indices = append(indices, acc)
		}
		var rawHeadsList [][]string
		if headless {
			s := p.save()
			l, _ := p.anyLine()
			p.restore(s)
			parts := splitTextByIndices(indices[:len(indices)-1], l)
			for _, x := range parts[1:] {
				rawHeadsList = append(rawHeadsList, []string{x})
			}
		} else {
			ncols := len(indices)
			rawHeadsList = make([][]string, ncols-1)
			for _, rc := range rawContent {
				parts := splitTextByIndices(indices[:len(indices)-1], rc)[1:]
				for i := range rawHeadsList {
					if i < len(parts) {
						rawHeadsList[i] = append(rawHeadsList[i], parts[i])
					} else {
						rawHeadsList[i] = append(rawHeadsList[i], "")
					}
				}
			}
		}
		for i, l := range lengths {
			var hs []string
			if i < len(rawHeadsList) {
				hs = rawHeadsList[i]
			}
			aligns = append(aligns, alignType(hs, l))
		}
		if !headless {
			for _, hl := range rawHeadsList {
				var ts []string
				for _, h := range hl {
					ts = append(ts, strings.TrimSpace(h))
				}
				raw := strings.TrimSpace(strings.Join(ts, "\n") + "\n")
				heads = append(heads, p.plainCell(raw))
			}
		}
		return true
	})
	return heads, aligns, indices, ok
}

func (p *mdP) multilineTable(headless bool) (*tableParts, bool) {
	var res *tableParts
	ok := p.try(func() bool {
		heads, aligns, indices, ok := p.multilineTableHeader(headless)
		if !ok {
			return false
		}
		var rows [][][]Block
		for {
			r, ok := p.multilineRow(indices)
			if !ok {
				break
			}
			rows = append(rows, r)
			if p.blanklines() == 0 {
				break
			}
		}
		if len(rows) == 0 {
			return false
		}
		if !p.tableFooter() {
			return false
		}
		widths := widthsFromIndices(p.st.opts.Columns, indices)
		res = &tableParts{aligns: aligns, widths: widths, heads: heads, rows: rows}
		return true
	})
	return res, ok
}

// ---------- grid tables ----------

type gridResult struct {
	head, body, foot []Row
}

func (p *mdP) gridTable() (*tableParts, bool) {
	s := p.save()
	// collect lines
	var lines []string
	indent := -1
	for !p.eof() {
		st := p.pos
		n := 0
		for p.peek() == ' ' && n < 3 {
			p.pos++
			n++
		}
		c := p.peek()
		if c != '+' && c != '|' {
			p.pos = st
			break
		}
		if indent < 0 {
			indent = n
		}
		l, _ := p.anyLine()
		lines = append(lines, strings.TrimRight(l, " \t"))
	}
	if len(lines) < 2 || !strings.HasPrefix(lines[0], "+") {
		p.restore(s)
		return nil, false
	}
	tp, ok := p.parseGrid(lines)
	if !ok {
		p.restore(s)
		return nil, false
	}
	return tp, true
}

func isGridSepLine(l string) bool {
	if !strings.HasPrefix(l, "+") {
		return false
	}
	for _, c := range l {
		if c != '+' && c != '-' && c != '=' && c != ':' {
			return false
		}
	}
	return true
}

func (p *mdP) parseGrid(lines []string) (*tableParts, bool) {
	grid := make([][]rune, len(lines))
	width := 0
	for i, l := range lines {
		grid[i] = []rune(l)
		if len(grid[i]) > width {
			width = len(grid[i])
		}
	}
	for i := range grid {
		for len(grid[i]) < width {
			grid[i] = append(grid[i], ' ')
		}
	}
	top := grid[0]
	if !isGridSepLine(lines[0]) {
		return nil, false
	}
	last := lines[len(lines)-1]
	if !isGridSepLine(last) {
		return nil, false
	}
	// column boundaries: union of '+' positions in all separator lines
	colSet := map[int]bool{}
	for i, l := range lines {
		if isGridSepLine(l) {
			for j, c := range grid[i] {
				if c == '+' {
					colSet[j] = true
				}
			}
		}
	}
	_ = top
	var cols []int
	for j := range colSet {
		cols = append(cols, j)
	}
	sort.Ints(cols)
	if len(cols) < 2 {
		return nil, false
	}
	ncols := len(cols) - 1
	// row separators
	var seps []int
	headSep := -1
	footSep := -1
	for i, l := range lines {
		if isGridSepLine(l) {
			seps = append(seps, i)
			if strings.Contains(l, "=") {
				if headSep < 0 && i != len(lines)-1 {
					headSep = i
				} else {
					footSep = i
				}
			}
		} else {
			// content lines must have | at col boundaries 0
			if grid[i][0] != '|' {
				return nil, false
			}
		}
	}
	if headSep >= 0 && footSep < 0 && headSep == len(lines)-1 {
		headSep = -1
	}
	// alignments from header separator or first line
	alignLine := grid[0]
	if headSep >= 0 {
		alignLine = grid[headSep]
	}
	aligns := make([]Alignment, ncols)
	for c := 0; c < ncols; c++ {
		a, b := cols[c], cols[c+1]
		left := a+1 < len(alignLine) && alignLine[a+1] == ':'
		right := b-1 >= 0 && alignLine[b-1] == ':'
		switch {
		case left && right:
			aligns[c] = AlignCenter
		case left:
			aligns[c] = AlignLeft
		case right:
			aligns[c] = AlignRight
		default:
			aligns[c] = AlignDefault
		}
	}
	// widths
	tot := 0
	ws := make([]int, ncols)
	for c := 0; c < ncols; c++ {
		ws[c] = cols[c+1] - cols[c]
		tot += ws[c]
	}
	q := float64(p.st.opts.Columns)
	if float64(tot) > q {
		q = float64(tot)
	}
	widths := make([]float64, ncols)
	for c := range ws {
		widths[c] = float64(ws[c]) / q
	}
	// cell extraction with spans: for each cell top-left corner, determine extent
	type cellInfo struct {
		r0, r1 int // line indices (separator lines) top & bottom
		c0, c1 int // column boundary indices
	}
	// owner map for each (sepRowIndex, col)
	nrows := len(seps) - 1
	sepIdx := map[int]int{}
	for k, li := range seps {
		sepIdx[li] = k
	}
	used := make([][]bool, nrows)
	for i := range used {
		used[i] = make([]bool, ncols)
	}
	type gcell struct {
		row, col, rowspan, colspan int
		text                       string
	}
	var cells []gcell
	isVert := func(r rune) bool { return r == '|' || r == '+' }
	for ri := 0; ri < nrows; ri++ {
		for ci := 0; ci < ncols; ci++ {
			if used[ri][ci] {
				continue
			}
			topLine := seps[ri]
			// extend columns: move right until a vertical border found on the first content line
			firstContent := topLine + 1
			c1 := ci + 1
			for c1 < ncols {
				x := cols[c1]
				if x < len(grid[firstContent]) && isVert(grid[firstContent][x]) {
					break
				}
				c1++
			}
			// extend rows: move down until bottom border line has '-'/'=' across the cell
			r1 := ri + 1
			for r1 < nrows {
				li := seps[r1]
				x := cols[ci] + 1
				if x < len(grid[li]) && (grid[li][x] == '-' || grid[li][x] == '=' || grid[li][x] == ':') {
					break
				}
				r1++
			}
			for a := ri; a < r1; a++ {
				for b := ci; b < c1; b++ {
					used[a][b] = true
				}
			}
			// extract text
			var tl []string
			for li := seps[ri] + 1; li < seps[r1]; li++ {
				if isGridSepLine(lines[li]) {
					continue
				}
				x0, x1 := cols[ci]+1, cols[c1]
				row := grid[li]
				if x1 > len(row) {
					x1 = len(row)
				}
				if x0 > x1 {
					x0 = x1
				}
				tl = append(tl, strings.TrimRight(string(row[x0:x1]), " "))
			}
			// lines within spanned rows that are partial separators
			allSp := true
			for _, t := range tl {
				if t != "" && !strings.HasPrefix(t, " ") {
					allSp = false
				}
			}
			if allSp {
				for i := range tl {
					if tl[i] != "" {
						tl[i] = tl[i][1:]
					}
				}
			}
			cells = append(cells, gcell{ri, ci, r1 - ri, c1 - ci, strings.Join(tl, "\n")})
		}
	}
	// build rows
	rowsByIdx := make([][]Cell, nrows)
	for _, c := range cells {
		raw := c.text + "\n"
		bs := p.sub(raw).parseBlocks()
		rowsByIdx[c.row] = append(rowsByIdx[c.row], Cell{Align: AlignDefault, RowSpan: c.rowspan, ColSpan: c.colspan, Blocks: bs})
	}
	gr := &gridResult{}
	headRows := 0
	if headSep >= 0 {
		headRows = sepIdx[headSep]
	}
	footStart := nrows
	if footSep >= 0 {
		footStart = sepIdx[footSep]
	}
	for i := 0; i < nrows; i++ {
		r := Row{Cells: rowsByIdx[i]}
		if i < headRows {
			gr.head = append(gr.head, r)
		} else if i >= footStart {
			gr.foot = append(gr.foot, r)
		} else {
			gr.body = append(gr.body, r)
		}
	}
	return &tableParts{aligns: aligns, widths: widths, cells: gr}, true
}
EOF
