package main

import (
	"strings"
)

const (
	dkEmpty = iota
	dkText
	dkBlock
	dkVFill
	dkPrefixed
	dkBeforeNonBlank
	dkFlush
	dkSpace
	dkAfterBreak
	dkCR
	dkNewLine
	dkBlankLines
	dkConcat
)

type Doc struct {
	k     int
	s     string
	w     int
	n     int
	lines []string
	kids  []*Doc
	d     *Doc
}

var dEmpty = &Doc{k: dkEmpty}
var dSpace = &Doc{k: dkSpace}
var dCR = &Doc{k: dkCR}
var dNL = &Doc{k: dkNewLine}
var dBlank = &Doc{k: dkBlankLines, n: 1}

func strWidth(s string) int {
	w := 0
	for _, c := range s {
		w += charWidth(c)
	}
	return w
}

// Lit creates literal text; embedded newlines become NewLine
func Lit(s string) *Doc {
	if s == "" {
		return dEmpty
	}
	if !strings.Contains(s, "\n") {
		return &Doc{k: dkText, s: s, w: strWidth(s)}
	}
	parts := strings.Split(s, "\n")
	var ds []*Doc
	for i, p := range parts {
		if i > 0 {
			ds = append(ds, dNL)
		}
		if p != "" {
			ds = append(ds, &Doc{k: dkText, s: p, w: strWidth(p)})
		}
	}
	return Cat(ds...)
}

func Cat(ds ...*Doc) *Doc {
	var kids []*Doc
	for _, d := range ds {
		if d == nil || d.k == dkEmpty {
			continue
		}
		if d.k == dkConcat {
			kids = append(kids, d.kids...)
		} else {
			kids = append(kids, d)
		}
	}
	if len(kids) == 0 {
		return dEmpty
	}
	if len(kids) == 1 {
		return kids[0]
	}
	return &Doc{k: dkConcat, kids: kids}
}

func BlankLines(n int) *Doc { return &Doc{k: dkBlankLines, n: n} }

func Prefixed(pref string, d *Doc) *Doc {
	if d.k == dkEmpty {
		return d
	}
	return &Doc{k: dkPrefixed, s: pref, d: d}
}

func Nest(n int, d *Doc) *Doc { return Prefixed(strings.Repeat(" ", n), d) }

func Hang(n int, start, d *Doc) *Doc { return Cat(start, Nest(n, d)) }

func Flush(d *Doc) *Doc {
	if d.k == dkEmpty {
		return d
	}
	return &Doc{k: dkFlush, d: d}
}

func BeforeNonBlank(d *Doc) *Doc { return &Doc{k: dkBeforeNonBlank, d: d} }

func AfterBreak(s string) *Doc { return &Doc{k: dkAfterBreak, s: s} }

func VFill(s string) *Doc { return &Doc{k: dkVFill, s: s, w: strWidth(s)} }

func (d *Doc) IsEmpty() bool {
	switch d.k {
	case dkEmpty:
		return true
	case dkConcat:
		for _, k := range d.kids {
			if !k.IsEmpty() {
				return false
			}
		}
		return true
	}
	return false
}

// a <+> b
func SpaceSep(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, dSpace, b)
}

// a $$ b
func Above(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, dCR, b)
}

// a $+$ b
func AboveBlank(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, dBlank, b)
}

func Vcat(ds []*Doc) *Doc {
	r := dEmpty
	for _, d := range ds {
		r = Above(r, d)
	}
	return r
}

func Vsep(ds []*Doc) *Doc {
	r := dEmpty
	for _, d := range ds {
		r = AboveBlank(r, d)
	}
	return r
}

func Hsep(ds []*Doc) *Doc {
	r := dEmpty
	for _, d := range ds {
		r = SpaceSep(r, d)
	}
	return r
}

// flatten into list
func (d *Doc) unfold(out []*Doc) []*Doc {
	switch d.k {
	case dkEmpty:
		return out
	case dkConcat:
		for _, k := range d.kids {
			out = k.unfold(out)
		}
		return out
	}
	return append(out, d)
}

// Chomp removes trailing blank lines / spaces / CRs
func Chomp(d *Doc) *Doc {
	l := d.unfold(nil)
	for len(l) > 0 {
		last := l[len(l)-1]
		switch last.k {
		case dkBlankLines, dkCR, dkNewLine, dkSpace:
			l = l[:len(l)-1]
			continue
		case dkPrefixed:
			l[len(l)-1] = Prefixed(last.s, Chomp(last.d))
		case dkFlush:
			l[len(l)-1] = Flush(Chomp(last.d))
		}
		break
	}
	return Cat(l...)
}

// NoWrap replaces breaking spaces with literal spaces
func NoWrap(d *Doc) *Doc {
	switch d.k {
	case dkSpace:
		return &Doc{k: dkText, s: " ", w: 1}
	case dkConcat:
		var ks []*Doc
		for _, k := range d.kids {
			ks = append(ks, NoWrap(k))
		}
		return &Doc{k: dkConcat, kids: ks}
	case dkPrefixed:
		return Prefixed(d.s, NoWrap(d.d))
	case dkFlush:
		return Flush(NoWrap(d.d))
	case dkBeforeNonBlank:
		return BeforeNonBlank(NoWrap(d.d))
	}
	return d
}

func normalizeDocs(xs []*Doc) []*Doc {
	out := make([]*Doc, 0, len(xs))
	for i := 0; i < len(xs); i++ {
		x := xs[i]
		out = append(out, x)
		// fix up tail repeatedly
		for len(out) >= 1 {
			n := len(out)
			if n == 1 {
				break
			}
			a, b := out[n-2], out[n-1]
			merged := (*Doc)(nil)
			switch {
			case a.k == dkBlankLines && b.k == dkBlankLines:
				m := a.n
				if b.n > m {
					m = b.n
				}
				merged = BlankLines(m)
			case a.k == dkBlankLines && (b.k == dkSpace || b.k == dkCR || b.k == dkNewLine):
				merged = a
			case a.k == dkNewLine && b.k == dkBlankLines:
				merged = b
			case a.k == dkNewLine && (b.k == dkSpace || b.k == dkCR):
				merged = a
			case a.k == dkCR && b.k == dkCR:
				merged = a
			case a.k == dkCR && (b.k == dkNewLine || b.k == dkBlankLines):
				merged = b
			case a.k == dkCR && b.k == dkSpace:
				merged = a
			case a.k == dkSpace && (b.k == dkCR || b.k == dkNewLine || b.k == dkBlankLines):
				merged = b
			case a.k == dkSpace && b.k == dkSpace:
				merged = a
			}
			if merged == nil {
				break
			}
			out = out[:n-2]
			out = append(out, merged)
		}
	}
	if len(out) > 0 {
		last := out[len(out)-1]
		switch last.k {
		case dkNewLine, dkBlankLines:
			if len(out) == 1 || true {
				out[len(out)-1] = dCR
			}
		case dkSpace:
			out = out[:len(out)-1]
		}
	}
	return out
}

type renderState struct {
	out       strings.Builder
	prefix    string
	usePrefix bool
	lineLen   int // <=0 means no wrapping
	column    int
	newlines  int
}

func (st *renderState) newline() {
	if st.column == 0 && st.usePrefix && st.prefix != "" {
		pref := strings.TrimRight(st.prefix, " \t\n\r")
		st.out.WriteString(pref)
		st.column += strWidth(pref)
	}
	st.out.WriteByte('\n')
	st.column = 0
	st.newlines++
}

func (st *renderState) outp(off int, s string) {
	if st.column == 0 && st.usePrefix && st.prefix != "" {
		st.out.WriteString(st.prefix)
		st.column += strWidth(st.prefix)
	}
	st.out.WriteString(s)
	st.column += off
	st.newlines = 0
}

func offsetOf(d *Doc) int {
	switch d.k {
	case dkText, dkBlock, dkVFill:
		return d.w
	case dkSpace:
		return 1
	}
	return 0
}

func isBlankDoc(d *Doc) bool {
	switch d.k {
	case dkSpace, dkCR, dkNewLine, dkBlankLines:
		return true
	case dkText:
		return strings.TrimSpace(d.s) == ""
	}
	return false
}

func (st *renderState) renderDoc(d *Doc) {
	st.renderList(normalizeDocs(d.unfold(nil)))
}

func (st *renderState) renderList(xs []*Doc) {
	for i := 0; i < len(xs); i++ {
		x := xs[i]
		rest := xs[i+1:]
		switch x.k {
		case dkEmpty:
		case dkText:
			st.outp(x.w, x.s)
		case dkPrefixed:
			old := st.prefix
			st.prefix = st.prefix + x.s
			st.renderDoc(x.d)
			st.prefix = old
		case dkFlush:
			old := st.usePrefix
			st.usePrefix = false
			st.renderDoc(x.d)
			st.usePrefix = old
		case dkBeforeNonBlank:
			if len(rest) > 0 && !isBlankDoc(rest[0]) {
				st.renderDoc(x.d)
			}
		case dkBlankLines:
			// merge following
			num := x.n
			j := i + 1
			for j < len(xs) {
				y := xs[j]
				if y.k == dkBlankLines {
					if y.n > num {
						num = y.n
					}
					j++
					continue
				}
				if y.k == dkSpace || y.k == dkCR || y.k == dkNewLine {
					j++
					continue
				}
				break
			}
			i = j - 1
			if j >= len(xs) {
				// trailing blanklines: nothing
				return
			}
			if st.newlines <= num {
				for k := 0; k < 1+num-st.newlines; k++ {
					st.newline()
				}
			}
		case dkCR:
			// CR followed by blanklines or space
			j := i + 1
			skip := false
			for j < len(xs) {
				y := xs[j]
				if y.k == dkBlankLines {
					skip = true
					break
				}
				if y.k == dkSpace {
					j++
					continue
				}
				break
			}
			if skip {
				i = j - 1
				continue
			}
			i = j - 1
			if st.newlines > 0 || j >= len(xs) {
				continue
			}
			st.newline()
		case dkNewLine:
			st.newline()
		case dkSpace:
			if len(rest) > 0 {
				nk := rest[0].k
				if nk == dkCR || nk == dkNewLine || nk == dkBlankLines || nk == dkSpace {
					continue
				}
			}
			off := 0
			for _, y := range rest {
				if y.k == dkText || y.k == dkBlock || y.k == dkAfterBreak || y.k == dkVFill {
					off += offsetOf(y)
					continue
				}
				break
			}
			if st.lineLen > 0 && st.column+1+off > st.lineLen {
				st.newline()
			} else if st.column > 0 {
				st.outp(1, " ")
			}
		case dkAfterBreak:
			if st.newlines > 0 {
				st.outp(strWidth(x.s), x.s)
			}
		case dkBlock, dkVFill:
			j := i + 1
			for j < len(xs) && (xs[j].k == dkBlock || xs[j].k == dkVFill) {
				j++
			}
			bs := xs[i:j]
			maxh := 0
			for _, b := range bs {
				h := 1
				if b.k == dkBlock {
					h = len(b.lines)
				}
				if h > maxh {
					maxh = h
				}
			}
			toSpec := func(b *Doc) (int, []string) {
				if b.k == dkBlock {
					return b.w, b.lines
				}
				ls := make([]string, maxh)
				for k := range ls {
					ls[k] = b.s
				}
				return b.w, ls
			}
			w, lns := toSpec(bs[0])
			lns = padLines(lns, maxh)
			for _, b := range bs[1:] {
				w2, l2 := toSpec(b)
				l2 = padLines(l2, maxh)
				merged := make([]string, maxh)
				for k := 0; k < maxh; k++ {
					l1 := lns[k]
					pad := w - strWidth(l1)
					if pad < 0 {
						pad = 0
					}
					merged[k] = l1 + strings.Repeat(" ", pad) + l2[k]
				}
				lns = merged
				w += w2
			}
			oldPref := st.prefix
			n := st.column - strWidth(oldPref)
			if n > 0 {
				st.prefix = oldPref + strings.Repeat(" ", n)
			}
			var ds []*Doc
			for k, l := range lns {
				if k > 0 {
					ds = append(ds, dCR)
				}
				ds = append(ds, Lit(l))
			}
			st.renderList(normalizeDocs(Cat(ds...).unfold(nil)))
			st.prefix = oldPref
			i = j - 1
		}
	}
}

func padLines(ls []string, h int) []string {
	if len(ls) >= h {
		return ls[:h]
	}
	out := make([]string, h)
	copy(out, ls)
	return out
}

// Render renders a doc with optional line length (<=0: no wrap)
func Render(d *Doc, lineLen int) string {
	st := &renderState{usePrefix: true, lineLen: lineLen, newlines: 2}
	st.renderDoc(d)
	return st.out.String()
}

// block constructors

func chopLines(n int, s string) []string {
	lines := strings.Split(s, "\n")
	// remove final empty lines
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var out []string
	for _, l := range lines {
		if strWidth(l) <= n {
			out = append(out, l)
			continue
		}
		// chop into pieces of width n
		var cur strings.Builder
		cw := 0
		for _, c := range l {
			w := charWidth(c)
			if cw+w > n && cw > 0 {
				out = append(out, cur.String())
				cur.Reset()
				cw = 0
			}
			cur.WriteRune(c)
			cw += w
		}
		out = append(out, cur.String())
	}
	return out
}

func mkBlock(filler func(string) string, width int, d *Doc) *Doc {
	if width < 1 && !d.IsEmpty() {
		width = 1
	}
	ls := chopLines(width, Render(d, width))
	for i, l := range ls {
		ls[i] = filler(l)
	}
	return &Doc{k: dkBlock, w: width, lines: ls}
}

func LBlock(w int, d *Doc) *Doc { return mkBlock(func(s string) string { return s }, w, d) }
func RBlock(w int, d *Doc) *Doc {
	return mkBlock(func(s string) string {
		p := w - strWidth(s)
		if p < 0 {
			p = 0
		}
		return strings.Repeat(" ", p) + s
	}, w, d)
}
func CBlock(w int, d *Doc) *Doc {
	return mkBlock(func(s string) string {
		p := (w - strWidth(s)) / 2
		if p < 0 {
			p = 0
		}
		return strings.Repeat(" ", p) + s
	}, w, d)
}

// Height: number of lines when rendered without wrap
func (d *Doc) Height() int {
	s := Render(d, 0)
	if s == "" {
		return 0
	}
	return len(strings.Split(strings.TrimRight(s, "\n"), "\n"))
}

// Offset: width of widest line (no wrap)
func (d *Doc) Offset() int {
	s := Render(d, 0)
	m := 0
	for _, l := range strings.Split(s, "\n") {
		if w := strWidth(l); w > m {
			m = w
		}
	}
	return m
}

// MinOffset: width when rendered with minimal line length (longest word)
func (d *Doc) MinOffset() int {
	s := Render(d, 1)
	m := 0
	for _, l := range strings.Split(s, "\n") {
		if w := strWidth(l); w > m {
			m = w
		}
	}
	return m
}

func DText(s string) *Doc { return Lit(s) }
