func highlightLines(lang, code string) [][]hlTok {
	lines := strings.Split(code, "\n")
	var out [][]hlTok
	for _, l := range lines {
		if l == "" {
			out = append(out, nil)
		} else {
			out = append(out, tokenizeLine(lang, l))
		}
	}
	return out
}

func tokenizeLine(lang, l string) []hlTok {
	return []hlTok{{"", l}}
}
