func escHTML(s string, attr bool) string {
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		case '"':
			if attr {
				sb.WriteString("&quot;")
			} else {
				sb.WriteRune(c)
			}
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

// text with breaking spaces
func (w *htmlWriter) textDoc(s string) *Doc {
	e := escHTML(s, false)
	if !strings.Contains(e, " ") {
		return Lit(e)
	}
	parts := strings.Split(e, " ")
	var ds []*Doc
	for i, p := range parts {
		if i > 0 {
			ds = append(ds, dSpace)
		}
		ds = append(ds, Lit(p))
	}
	return Cat(ds...)
}

type hattr struct{ k, v string }

func attrDoc(attrs []hattr) *Doc {
	var ds []*Doc
	for _, a := range attrs {
		ds = append(ds, dSpace, Lit(a.k+"=\""+escHTML(a.v, true)+"\""))
	}
	return Cat(ds...)
}

func tagOpen(name string, attrs []hattr) *Doc {
	return Cat(Lit("<"+name), attrDoc(attrs), Lit(">"))
}

func tagSelf(name string, attrs []hattr, html5 bool) *Doc {
	return Cat(Lit("<"+name), attrDoc(attrs), Lit(" />"))
}

func inTag(name string, attrs []hattr, content *Doc) *Doc {
	return Cat(tagOpen(name, attrs), content, Lit("</"+name+">"))
}

func (w *htmlWriter) kvAttrs(kvs [][2]string) []hattr {
	var out []hattr
	for _, kv := range kvs {
		k := kv[0]
		if w.html5 {
			if html5AttrSet[k] || strings.Contains(k, ":") || strings.HasPrefix(k, "data-") || strings.HasPrefix(k, "aria-") {
				out = append(out, hattr{k, kv[1]})
			} else {
				out = append(out, hattr{"data-" + k, kv[1]})
			}
		} else {
			out = append(out, hattr{k, kv[1]})
		}
	}
	return out
}

func (w *htmlWriter) prefixedID(id string) string {
	return w.opts.IDPrefix + id
}

// standard attribute order: id, class, kvs
func (w *htmlWriter) stdAttrs(a Attr) []hattr {
	var out []hattr
	if a.ID != "" {
		out = append(out, hattr{"id", w.prefixedID(a.ID)})
	}
	if len(a.Classes) > 0 {
		out = append(out, hattr{"class", strings.Join(a.Classes, " ")})
	}
	return append(out, w.kvAttrs(a.KVs)...)
}

func (w *htmlWriter) blocks(bs []Block) *Doc {
	var ds []*Doc
	for _, b := range bs {
		d := w.block(b)
		if d.IsEmpty() {
			continue
		}
		if len(ds) > 0 {
			ds = append(ds, dNL)
		}
		ds = append(ds, d)
	}
	return Cat(ds...)
}

func (w *htmlWriter) inlines(xs []Inline) *Doc {
	var ds []*Doc
	for _, x := range xs {
		ds = append(ds, w.inline(x))
	}
	return Cat(ds...)
}

func (w *htmlWriter) block(b Block) *Doc {
	switch v := b.(type) {
	case *Plain:
		return w.inlines(v.Inlines)
	case *Para:
		c := w.inlines(v.Inlines)
		if c.IsEmpty() && !w.opts.Exts.On("empty_paragraphs") {
			return dEmpty
		}
		return inTag("p", nil, c)
	case *LineBlock:
		var ils []Inline
		for i, l := range v.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return inTag("div", []hattr{{"class", "line-block"}}, w.inlines(ils))
	case *Div:
		return w.div(v)
	case *RawBlock:
		if isRawHTMLFormat(v.Format, w) {
			return Lit(v.Text)
		}
		if (v.Format == "latex" || v.Format == "tex") && w.allowsMathEnv() && isMathEnvironment(v.Text) {
			w.math = true
			return w.block(&Plain{[]Inline{&Math{DisplayMath, v.Text}}})
		}
		return dEmpty
	case *HorizontalRule:
		return Lit("<hr />")
	case *CodeBlock:
		return w.codeBlock(v)
	case *BlockQuote:
		c := w.blocks(v.Blocks)
		return Cat(Lit("<blockquote>"), dNL, c, dNL, Lit("</blockquote>"))
	case *Header:
		return w.header(v)
	case *BulletList:
		var items []*Doc
		for _, it := range v.Items {
			items = append(items, w.listItem(it))
		}
		var attrs []hattr
		if len(v.Items) > 0 && allTaskItems(v.Items) {
			attrs = append(attrs, hattr{"class", "task-list"})
		}
		return w.listDoc("ul", attrs, items)
	case *OrderedList:
		var items []*Doc
		for _, it := range v.Items {
			items = append(items, w.listItem(it))
		}
		var attrs []hattr
		if v.Attrs.Start != 1 {
			attrs = append(attrs, hattr{"start", strconv.Itoa(v.Attrs.Start)})
		}
		if v.Attrs.Style == Example {
			attrs = append(attrs, hattr{"class", "example"})
		}
		if v.Attrs.Style != DefaultStyle {
			if w.html5 {
				t := "1"
				switch v.Attrs.Style {
				case LowerAlpha:
					t = "a"
				case UpperAlpha:
					t = "A"
				case LowerRoman:
					t = "i"
				case UpperRoman:
					t = "I"
				}
				attrs = append(attrs, hattr{"type", t})
			} else {
				st := "decimal"
				switch v.Attrs.Style {
				case LowerAlpha:
					st = "lower-alpha"
				case UpperAlpha:
					st = "upper-alpha"
				case LowerRoman:
					st = "lower-roman"
				case UpperRoman:
					st = "upper-roman"
				}
				attrs = append(attrs, hattr{"style", "list-style-type: " + st})
			}
		}
		return w.listDoc("ol", attrs, items)
	case *DefinitionList:
		var ds []*Doc
		for _, it := range v.Items {
			term := inTag("dt", nil, w.inlines(it.Term))
			var parts []*Doc
			parts = append(parts, dNL, term, dNL)
			for i, d := range it.Defs {
				if i > 0 {
					parts = append(parts, dNL)
				}
				parts = append(parts, Cat(Lit("<dd>"), dNL, w.blocks(d), dNL, Lit("</dd>")))
			}
			ds = append(ds, Cat(parts...))
		}
		return Cat(Lit("<dl>"), Cat(ds...), dNL, Lit("</dl>"))
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

func isRawHTMLFormat(f string, w *htmlWriter) bool {
	switch f {
	case "html", "html5", "html4":
		return true
	}
	if w.slideVariant == "revealjs" && f == "revealjs" {
		return true
	}
	return false
}

func (w *htmlWriter) allowsMathEnv() bool {
	switch w.opts.HTMLMathMethod {
	case "mathjax", "katex":
		return true
	}
	return false
}

var mathEnvNames = makeSet("align", "align*", "alignat", "alignat*", "aligned", "alignedat", "array", "Bmatrix", "bmatrix", "cases", "CD", "eqnarray", "eqnarray*", "equation", "equation*", "gather", "gather*", "gathered", "matrix", "multline", "multline*", "pmatrix", "smallmatrix", "split", "subarray", "Vmatrix", "vmatrix")

func isMathEnvironment(s string) bool {
	t := strings.TrimLeft(s, " \t\n")
	if !strings.HasPrefix(t, "\\begin{") {
		return false
	}
	t = t[7:]
	i := strings.IndexByte(t, '}')
	if i < 0 {
		return false
	}
	return mathEnvNames[t[:i]]
}

func allTaskItems(items [][]Block) bool {
	for _, it := range items {
		if !isTaskItem(it) {
			return false
		}
	}
	return true
}

func isTaskItem(it []Block) bool {
	if len(it) == 0 {
		return false
	}
	var ils []Inline
	switch b := it[0].(type) {
	case *Plain:
		ils = b.Inlines
	case *Para:
		ils = b.Inlines
	default:
		return false
	}
	if len(ils) > 0 {
		if s, ok := ils[0].(*Str); ok {
			return strings.HasPrefix(s.Text, "\u2610") || strings.HasPrefix(s.Text, "\u2612")
		}
	}
	return false
}

func (w *htmlWriter) listDoc(tag string, attrs []hattr, items []*Doc) *Doc {
	var ds []*Doc
	for _, it := range items {
		ds = append(ds, dNL, it)
	}
	return Cat(tagOpen(tag, attrs), Cat(ds...), dNL, Lit("</"+tag+">"))
}

func (w *htmlWriter) listItem(bs []Block) *Doc {
	// task list handling
	if isTaskItem(bs) {
		return w.taskListItem(bs)
	}
	c := w.blocks(bs)
	return Cat(Lit("<li>"), c, Lit("</li>"))
}

func (w *htmlWriter) taskListItem(bs []Block) *Doc {
	var ils []Inline
	isPara := false
	switch b := bs[0].(type) {
	case *Plain:
		ils = b.Inlines
	case *Para:
		ils = b.Inlines
		isPara = true
	}
	s := ils[0].(*Str)
	checked := strings.HasPrefix(s.Text, "\u2612")
	rest := strings.TrimPrefix(strings.TrimPrefix(s.Text, "\u2610"), "\u2612")
	var newIls []Inline
	if rest != "" {
		newIls = append(newIls, &Str{rest})
	}
	newIls = append(newIls, ils[1:]...)
	// drop leading space
	if len(newIls) > 0 {
		if _, ok := newIls[0].(*Space); ok {
			newIls = newIls[1:]
		}
	}
	cb := `<input type="checkbox" disabled="" />`
	if checked {
		cb = `<input type="checkbox" disabled="" checked="" />`
	}
	label := Cat(Lit("<label>"), Lit(cb), w.inlines(newIls), Lit("</label>"))
	var first *Doc
	if isPara {
		first = inTag("p", nil, label)
	} else {
		first = label
	}
	restDoc := w.blocks(bs[1:])
	var c *Doc
	if restDoc.IsEmpty() {
		c = first
	} else {
		c = Cat(first, dNL, restDoc)
	}
	return Cat(Lit("<li>"), c, Lit("</li>"))
}

func (w *htmlWriter) div(v *Div) *Doc {
	classes := v.Attr.Classes
	var kvs [][2]string
	for _, kv := range v.Attr.KVs {
		if kv[0] != "width" {
			kvs = append(kvs, kv)
		}
	}
	if v.Attr.HasClass("column") {
		for _, kv := range v.Attr.KVs {
			if kv[0] == "width" {
				kvs = append(kvs, [2]string{"style", "width:" + kv[1] + ";"})
			}
		}
	}
	bs := v.Blocks
	if v.Attr.HasClass("column") || v.Attr.HasClass("columns") {
		nb := make([]Block, len(bs))
		for i, b := range bs {
			if p, ok := b.(*Para); ok {
				nb[i] = &Plain{p.Inlines}
			} else {
				nb[i] = b
			}
		}
		bs = nb
	}
	var contents *Doc
	if v.Attr.HasClass("columns") {
		var ds []*Doc
		for _, b := range bs {
			ds = append(ds, w.block(b))
		}
		contents = Cat(ds...)
	} else {
		contents = w.blocks(bs)
	}
	tag := "div"
	if w.html5 && v.Attr.HasClass("section") {
		tag = "section"
		var nc []string
		for _, c := range classes {
			if c != "section" {
				nc = append(nc, c)
			}
		}
		classes = nc
	}
	attrs := w.stdAttrs(Attr{v.Attr.ID, classes, kvs})
	return Cat(tagOpen(tag, attrs), dNL, contents, dNL, Lit("</"+tag+">"))
}

func (w *htmlWriter) header(v *Header) *Doc {
	c := w.inlines(v.Inlines)
	if w.opts.NumberSections && !v.Attr.HasClass("unnumbered") {
		if num, ok := v.Attr.Get("number"); ok && num != "" {
			c = Cat(inTag("span", []hattr{{"class", "header-section-number"}}, Lit(escHTML(num, false))), dSpace, c)
		}
	}
	var kvs [][2]string
	if w.html5 {
		kvs = v.Attr.KVs
	} else {
		for _, kv := range v.Attr.KVs {
			switch kv[0] {
			case "lang", "dir", "title", "style", "align":
				kvs = append(kvs, kv)
			default:
				if strings.HasPrefix(kv[0], "on") {
					kvs = append(kvs, kv)
				}
			}
		}
	}
	var attrs []hattr
	if len(v.Attr.Classes) > 0 {
		attrs = append(attrs, hattr{"class", strings.Join(v.Attr.Classes, " ")})
	}
	attrs = append(attrs, w.kvAttrs(kvs)...)
	if v.Attr.ID != "" {
		attrs = append(attrs, hattr{"id", w.prefixedID(v.Attr.ID)})
	}
	lvl := v.Level
	if lvl < 1 {
		lvl = 1
	}
	if lvl > 6 {
		return inTag("p", attrs, c)
	}
	return inTag("h"+strconv.Itoa(lvl), attrs, c)
}

func (w *htmlWriter) codeBlock(v *CodeBlock) *Doc {
	id := v.Attr.ID
	lang := ""
	for _, c := range v.Attr.Classes {
		if l := canonicalLang(c); l != "" {
			lang = l
			break
		}
	}
	if lang == "" || !w.opts.Highlight {
		attrs := w.stdAttrs(v.Attr)
		code := escHTML(v.Text, false)
		return Cat(tagOpen("pre", attrs), Lit("<code>"), Flush(Lit(code)), Lit("</code></pre>"))
	}
	w.highlighting = true
	w.cbCounter++
	if id == "" {
		id = "cb" + strconv.Itoa(w.cbCounter)
	}
	pid := w.prefixedID(id)
	// classes: sourceCode + lang + other classes
	var classes []string
	classes = append(classes, "sourceCode")
	classes = append(classes, lang)
	for _, c := range v.Attr.Classes {
		if c != lang && !strings.EqualFold(c, lang) {
			classes = append(classes, c)
		}
	}
	lines := highlightLines(lang, v.Text)
	var sb strings.Builder
	numberLines := v.Attr.HasClass("numberLines") || v.Attr.HasClass("number-lines")
	for i, toks := range lines {
		if i > 0 {
			sb.WriteString("\n")
		}
		lid := fmt.Sprintf("%s-%d", pid, i+1)
		sb.WriteString(`<span id="` + lid + `"><a href="#` + lid + `" aria-hidden="true" tabindex="-1"></a>`)
		for _, t := range toks {
			if t.cls == "" {
				sb.WriteString(escHTML(t.text, false))
			} else {
				sb.WriteString(`<span class="` + t.cls + `">` + escHTML(t.text, false) + `</span>`)
			}
		}
		sb.WriteString("</span>")
	}
	preClasses := strings.Join(classes, " ")
	preAttrs := []hattr{{"class", preClasses}}
	if numberLines {
		if st, ok := v.Attr.Get("startFrom"); ok {
			preAttrs = append(preAttrs, hattr{"style", "counter-reset: source-line " + itoaSub1(st) + ";"})
		}
	}
	codeClasses := "sourceCode " + lang
	codeAttrs := []hattr{{"class", codeClasses}}
	divAttrs := []hattr{{"class", "sourceCode"}, {"id", pid}}
	var kvs [][2]string
	for _, kv := range v.Attr.KVs {
		if kv[0] != "startFrom" || !numberLines {
			kvs = append(kvs, kv)
		}
	}
	divAttrs = append(divAttrs, w.kvAttrs(kvs)...)
	if numberLines {
		if st, ok := v.Attr.Get("startFrom"); ok {
			_ = st
		}
	}
	return Cat(tagOpen("div", divAttrs), tagOpen("pre", preAttrs), tagOpen("code", codeAttrs), Flush(Lit(sb.String())), Lit("</code></pre></div>"))
}

func itoaSub1(s string) string {
	n, err := strconv.Atoi(s)
	if err != nil {
		return s
	}
	return strconv.Itoa(n - 1)
}

func (w *htmlWriter) figure(v *Figure) *Doc {
	attrs := w.stdAttrs(v.Attr)
	old := w.inFigure
	w.inFigure = true
	body := w.blocks(v.Blocks)
	w.inFigure = old
	capDoc := dEmpty
	if len(v.Caption.Long) > 0 {
		var cc *Doc
		// single Plain/Para -> inline content
		if len(v.Caption.Long) == 1 {
			switch p := v.Caption.Long[0].(type) {
			case *Plain:
				cc = w.inlines(p.Inlines)
			case *Para:
				cc = w.inlines(p.Inlines)
			}
		}
		if cc == nil {
			cc = w.blocks(v.Caption.Long)
		}
		// aria-hidden when caption equals image alt
		capAttrs := []hattr{}
		if isSimpleFigure(v) {
			capAttrs = append(capAttrs, hattr{"aria-hidden", "true"})
		}
		if w.html5 {
			capDoc = inTag("figcaption", capAttrs, cc)
		} else {
			capDoc = inTag("p", []hattr{{"class", "caption"}}, cc)
		}
	}
	tag := "figure"
	if !w.html5 {
		tag = "div"
		attrs = append([]hattr{}, attrs...)
		found := false
		for i, a := range attrs {
			if a.k == "class" {
				attrs[i].v = "figure " + a.v
				found = true
			}
		}
		if !found {
			attrs = append(attrs, hattr{"class", "figure"})
		}
	}
	parts := []*Doc{tagOpen(tag, attrs), dNL, body}
	if !capDoc.IsEmpty() {
		parts = append(parts, dNL, capDoc)
	}
	parts = append(parts, dNL, Lit("</"+tag+">"))
	return Cat(parts...)
}

// figure whose caption equals the image alt text
func isSimpleFigure(v *Figure) bool {
	if len(v.Blocks) != 1 {
		return false
	}
	pl, ok := v.Blocks[0].(*Plain)
	if !ok || len(pl.Inlines) != 1 {
		return false
	}
	img, ok := pl.Inlines[0].(*Image)
	if !ok {
		return false
	}
	if len(v.Caption.Long) != 1 {
		return false
	}
	var capIls []Inline
	switch c := v.Caption.Long[0].(type) {
	case *Plain:
		capIls = c.Inlines
	case *Para:
		capIls = c.Inlines
	default:
		return false
	}
	return stringify(capIls) == stringify(img.Inlines)
}

func (w *htmlWriter) inline(x Inline) *Doc {
	switch v := x.(type) {
	case *Str:
		return w.textDoc(v.Text)
	case *Space:
		return dSpace
	case *SoftBreak:
		switch w.opts.Wrap {
		case WrapPreserve:
			return dNL
		}
		return dSpace
	case *LineBreak:
		return Cat(Lit("<br />"), dNL)
	case *Emph:
		return inTag("em", nil, w.inlines(v.Inlines))
	case *Underline:
		return inTag("u", nil, w.inlines(v.Inlines))
	case *Strong:
		return inTag("strong", nil, w.inlines(v.Inlines))
	case *Strikeout:
		return inTag("del", nil, w.inlines(v.Inlines))
	case *Superscript:
		return inTag("sup", nil, w.inlines(v.Inlines))
	case *Subscript:
		return inTag("sub", nil, w.inlines(v.Inlines))
	case *SmallCaps:
		return inTag("span", []hattr{{"class", "smallcaps"}}, w.inlines(v.Inlines))
	case *Quoted:
		if w.opts.HTMLQTags {
			return inTag("q", nil, w.inlines(v.Inlines))
		}
		if v.Type == SingleQuote {
			return Cat(Lit("\u2018"), w.inlines(v.Inlines), Lit("\u2019"))
		}
		return Cat(Lit("\u201c"), w.inlines(v.Inlines), Lit("\u201d"))
	case *Code:
		return w.inlineCode(v)
	case *Math:
		return w.mathInline(v)
	case *RawInline:
		if isRawHTMLFormat(v.Format, w) {
			return Lit(v.Text)
		}
		if (v.Format == "latex" || v.Format == "tex") && w.allowsMathEnv() && isMathEnvironment(v.Text) {
			return w.mathInline(&Math{DisplayMath, v.Text})
		}
		return dEmpty
	case *Link:
		return w.link(v)
	case *Image:
		return w.image(v)
	case *Note:
		return w.noteRef(v)
	case *Span:
		return w.span(v)
	case *Cite:
		return w.cite(v)
	}
	return dEmpty
}

func (w *htmlWriter) span(v *Span) *Doc {
	c := w.inlines(v.Inlines)
	a := v.Attr
	var classes []string
	isSC := false
	for _, cl := range a.Classes {
		if cl == "csl-no-emph" || cl == "csl-no-strong" || cl == "csl-no-smallcaps" {
			continue
		}
		classes = append(classes, cl)
	}
	_ = isSC
	if a.ID == "" && len(classes) == 0 && len(a.KVs) == 0 {
		return inTag("span", nil, c)
	}
	return inTag("span", w.stdAttrs(Attr{a.ID, classes, a.KVs}), c)
}

func (w *htmlWriter) cite(v *Cite) *Doc {
	c := w.inlines(v.Inlines)
	var ids []string
	for _, ct := range v.Citations {
		ids = append(ids, ct.ID)
	}
	return inTag("span", []hattr{{"class", "citation"}, {"data-cites", strings.Join(ids, " ")}}, c)
}

func (w *htmlWriter) inlineCode(v *Code) *Doc {
	lang := ""
	for _, c := range v.Attr.Classes {
		if l := canonicalLang(c); l != "" {
			lang = l
			break
		}
	}
	if lang == "" || !w.opts.Highlight {
		attrs := w.stdAttrs(v.Attr)
		return Cat(tagOpen("code", attrs), Lit(escHTML(v.Text, false)), Lit("</code>"))
	}
	w.highlighting = true
	toks := highlightLines(lang, v.Text)
	var sb strings.Builder
	for i, line := range toks {
		if i > 0 {
			sb.WriteString("\n")
		}
		for _, t := range line {
			if t.cls == "" {
				sb.WriteString(escHTML(t.text, false))
			} else {
				sb.WriteString(`<span class="` + t.cls + `">` + escHTML(t.text, false) + `</span>`)
			}
		}
	}
	var classes []string
	classes = append(classes, "sourceCode", lang)
	for _, c := range v.Attr.Classes {
		if !strings.EqualFold(c, lang) {
			classes = append(classes, c)
		}
	}
	attrs := []hattr{{"class", strings.Join(classes, " ")}}
	if v.Attr.ID != "" {
		attrs = append(attrs, hattr{"id", w.prefixedID(v.Attr.ID)})
	}
	attrs = append(attrs, w.kvAttrs(v.Attr.KVs)...)
	return Cat(tagOpen("code", attrs), Lit(sb.String()), Lit("</code>"))
}

func (w *htmlWriter) link(v *Link) *Doc {
	if strings.HasPrefix(v.Target.URL, "mailto:") && w.opts.EmailObfuscation != "none" && w.opts.EmailObfuscation != "" {
		// obfuscation not default
	}
	c := w.inlines(v.Inlines)
	attrs := []hattr{{"href", v.Target.URL}}
	if v.Attr.ID != "" {
		attrs = append(attrs, hattr{"id", w.prefixedID(v.Attr.ID)})
	}
	if len(v.Attr.Classes) > 0 {
		attrs = append(attrs, hattr{"class", strings.Join(v.Attr.Classes, " ")})
	}
	attrs = append(attrs, w.kvAttrs(v.Attr.KVs)...)
	if v.Target.Title != "" {
		attrs = append(attrs, hattr{"title", v.Target.Title})
	}
	return inTag("a", attrs, c)
}

func (w *htmlWriter) image(v *Image) *Doc {
	attrs := []hattr{{"src", v.Target.URL}}
	if v.Target.Title != "" {
		attrs = append(attrs, hattr{"title", v.Target.Title})
	}
	var kvs [][2]string
	var styles []string
	for _, kv := range v.Attr.KVs {
		if (kv[0] == "width" || kv[0] == "height") && !w.html5 {
			kvs = append(kvs, kv)
			continue
		}
		if kv[0] == "width" || kv[0] == "height" {
			val := kv[1]
			if isAllDigits(val) {
				kvs = append(kvs, kv)
			} else if strings.HasSuffix(val, "px") && isAllDigits(strings.TrimSuffix(val, "px")) {
				kvs = append(kvs, [2]string{kv[0], strings.TrimSuffix(val, "px")})
			} else {
				styles = append(styles, kv[0]+":"+val)
			}
			continue
		}
		kvs = append(kvs, kv)
	}
	if v.Attr.ID != "" {
		attrs = append(attrs, hattr{"id", w.prefixedID(v.Attr.ID)})
	}
	if len(v.Attr.Classes) > 0 {
		attrs = append(attrs, hattr{"class", strings.Join(v.Attr.Classes, " ")})
	}
	attrs = append(attrs, w.kvAttrs(kvs)...)
	if len(styles) > 0 {
		attrs = append(attrs, hattr{"style", strings.Join(styles, ";")})
	}
	attrs = append(attrs, hattr{"alt", stringify(v.Inlines)})
	return tagSelf("img", attrs, w.html5)
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (w *htmlWriter) noteRef(v *Note) *Doc {
	n := len(w.notes) + 1
	ref := strconv.Itoa(n)
	// render note contents
	old := w.inNote
	w.inNote = true
	backlink := Cat(Lit(`<a href="#`+w.prefixedID("fnref"+ref)+`"`), dSpace, Lit(`class="footnote-back"`), dSpace, Lit(`role="doc-backlink">`), Lit("\u21a9\ufe0e"), Lit("</a>"))
	bs := addBacklink(v.Blocks)
	_ = bs
	content := w.noteBlocks(v.Blocks, backlink)
	w.inNote = old
	w.notes = append(w.notes, Cat(tagOpen("li", []hattr{{"id", w.prefixedID("fn" + ref)}}), content, Lit("</li>")))
	return Cat(tagOpen("a", []hattr{{"href", "#" + w.prefixedID("fn"+ref)}, {"class", "footnote-ref"}, {"id", w.prefixedID("fnref" + ref)}, {"role", "doc-noteref"}}), Lit("<sup>"+ref+"</sup>"), Lit("</a>"))
}

func addBacklink(bs []Block) []Block { return bs }

// render note blocks, adding backlink to the last paragraph
func (w *htmlWriter) noteBlocks(bs []Block, backlink *Doc) *Doc {
	if len(bs) == 0 {
		return backlink
	}
	last := bs[len(bs)-1]
	init := bs[:len(bs)-1]
	var lastDoc *Doc
	switch p := last.(type) {
	case *Para:
		lastDoc = inTag("p", nil, Cat(w.inlines(p.Inlines), backlink))
	case *Plain:
		lastDoc = Cat(w.inlines(p.Inlines), backlink)
	default:
		lastDoc = Cat(w.block(last), dNL, backlink)
	}
	d := w.blocks(init)
	if d.IsEmpty() {
		return lastDoc
	}
	return Cat(d, dNL, lastDoc)
}

func (w *htmlWriter) footnoteSection() *Doc {
	if len(w.notes) == 0 {
		return dEmpty
	}
	var items []*Doc
	for i, n := range w.notes {
		if i > 0 {
			items = append(items, dNL)
		}
		items = append(items, n)
	}
	var attrs []hattr
	tag := "section"
	if w.html5 {
		attrs = []hattr{{"id", w.prefixedID("footnotes")}, {"class", "footnotes footnotes-end-of-document"}, {"role", "doc-endnotes"}}
	} else {
		tag = "div"
		attrs = []hattr{{"class", "footnotes footnotes-end-of-document"}}
	}
	return Cat(tagOpen(tag, attrs), dNL, Lit("<hr />"), dNL, Lit("<ol>"), dNL, Cat(items...), dNL, Lit("</ol>"), dNL, Lit("</"+tag+">"))
}

func (w *htmlWriter) mathInline(v *Math) *Doc {
	w.math = true
	cls := "math inline"
	if v.Type == DisplayMath {
		cls = "math display"
	}
	switch w.opts.HTMLMathMethod {
	case "mathjax":
		var s string
		if v.Type == DisplayMath {
			s = "\\[" + v.Text + "\\]"
		} else {
			s = "\\(" + v.Text + "\\)"
		}
		return inTag("span", []hattr{{"class", cls}}, Lit(escHTML(s, false)))
	case "katex":
		return inTag("span", []hattr{{"class", cls}}, Lit(escHTML(v.Text, false)))
	case "webtex":
		url := w.opts.MathURL
		alt := v.Text
		pre := ""
		if v.Type == DisplayMath {
			pre = "\\displaystyle "
		}
		src := url + urlEncodeMath(pre+v.Text)
		return tagSelf("img", []hattr{{"style", "vertical-align:middle"}, {"src", src}, {"alt", alt}, {"title", alt}, {"class", cls}}, w.html5)
	case "gladtex":
		return inTag("eq", []hattr{{"env", map[bool]string{true: "displaymath", false: "math"}[v.Type == DisplayMath]}}, Lit(escHTML(v.Text, false)))
	}
	// plain math via texmath
	ils := texToInlines(v.Text, v.Type == DisplayMath)
	if ils == nil {
		s := v.Text
		if v.Type == DisplayMath {
			s = "$$" + s + "$$"
		} else {
			s = "$" + s + "$"
		}
		return inTag("span", []hattr{{"class", cls}}, Lit(escHTML(s, false)))
	}
	return inTag("span", []hattr{{"class", cls}}, w.inlines(ils))
}

func urlEncodeMath(s string) string {
	var sb strings.Builder
	for _, b := range []byte(s) {
		c := rune(b)
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || strings.ContainsRune("-_.~", c) {
			sb.WriteByte(b)
		} else {
			sb.WriteString(fmt.Sprintf("%%%02X", b))
		}
	}
	return sb.String()
}

// ---------- tables ----------

func alignStyle(a Alignment) string {
	switch a {
	case AlignLeft:
		return "left"
	case AlignRight:
		return "right"
	case AlignCenter:
		return "center"
	}
	return ""
}

func (w *htmlWriter) table(t *Table) *Doc {
	var parts []*Doc
	attrs := w.stdAttrs(t.Attr)
	parts = append(parts, tagOpen("table", attrs))
	// caption
	if len(t.Caption.Long) > 0 {
		var cc *Doc
		if len(t.Caption.Long) == 1 {
			switch p := t.Caption.Long[0].(type) {
			case *Plain:
				cc = w.inlines(p.Inlines)
			case *Para:
				cc = w.inlines(p.Inlines)
			}
		}
		if cc == nil {
			cc = w.blocks(t.Caption.Long)
		}
		parts = append(parts, dNL, inTag("caption", nil, cc))
	}
	// colgroup
	hasWidths := false
	for _, cs := range t.ColSpecs {
		if cs.HasWidth {
			hasWidths = true
		}
	}
	if hasWidths {
		var cols []*Doc
		for _, cs := range t.ColSpecs {
			var a []hattr
			if cs.HasWidth {
				a = append(a, hattr{"style", "width: " + percent(cs.Width)})
			}
			cols = append(cols, dNL, tagSelf("col", a, w.html5))
		}
		parts = append(parts, dNL, Lit("<colgroup>"), Cat(cols...), dNL, Lit("</colgroup>"))
	}
	// head
	if len(t.Head.Rows) > 0 {
		var rows []*Doc
		for _, r := range t.Head.Rows {
			rows = append(rows, dNL, w.tableRow(r, t.ColSpecs, true, 0))
		}
		parts = append(parts, dNL, tagOpen("thead", w.stdAttrs(t.Head.Attr)), Cat(rows...), dNL, Lit("</thead>"))
	}
	for _, b := range t.Bodies {
		var rows []*Doc
		for _, r := range b.Head {
			rows = append(rows, dNL, w.tableRow(r, t.ColSpecs, true, 0))
		}
		for _, r := range b.Body {
			rows = append(rows, dNL, w.tableRow(r, t.ColSpecs, false, b.RowHeadColumns))
		}
		parts = append(parts, dNL, tagOpen("tbody", w.stdAttrs(b.Attr)), Cat(rows...), dNL, Lit("</tbody>"))
	}
	if len(t.Foot.Rows) > 0 {
		var rows []*Doc
		for _, r := range t.Foot.Rows {
			rows = append(rows, dNL, w.tableRow(r, t.ColSpecs, false, 0))
		}
		parts = append(parts, dNL, tagOpen("tfoot", w.stdAttrs(t.Foot.Attr)), Cat(rows...), dNL, Lit("</tfoot>"))
	}
	parts = append(parts, dNL, Lit("</table>"))
	return Cat(parts...)
}

func percent(f float64) string {
	v := f * 100
	s := strconv.FormatFloat(v, 'f', -1, 64)
	// pandoc uses showFFloat (Just 0)? produce like 50% or 33%
	r := int(v + 0.5)
	if float64(int(v)) == v {
		return strconv.Itoa(int(v)) + "%"
	}
	_ = s
	return strconv.Itoa(r) + "%"
}

func (w *htmlWriter) tableRow(r Row, specs []ColSpec, header bool, rowHeads int) *Doc {
	var cells []*Doc
	col := 0
	for i, c := range r.Cells {
		tag := "td"
		if header || i < rowHeads {
			tag = "th"
		}
		var attrs []hattr
		if c.Attr.ID != "" {
			attrs = append(attrs, hattr{"id", w.prefixedID(c.Attr.ID)})
		}
		if len(c.Attr.Classes) > 0 {
			attrs = append(attrs, hattr{"class", strings.Join(c.Attr.Classes, " ")})
		}
		al := c.Align
		if al == AlignDefault && col < len(specs) {
			al = specs[col].Align
		}
		kvs := c.Attr.KVs
		if c.RowSpan > 1 {
			attrs = append(attrs, hattr{"rowspan", strconv.Itoa(c.RowSpan)})
		}
		if c.ColSpan > 1 {
			attrs = append(attrs, hattr{"colspan", strconv.Itoa(c.ColSpan)})
		}
		if s := alignStyle(al); s != "" {
			attrs = append(attrs, hattr{"style", "text-align: " + s + ";"})
		}
		attrs = append(attrs, w.kvAttrs(kvs)...)
		cells = append(cells, dNL, inTag(tag, attrs, w.cellContent(c.Blocks)))
		col += max(1, c.ColSpan)
	}
	return Cat(tagOpen("tr", w.stdAttrs(r.Attr)), Cat(cells...), dNL, Lit("</tr>"))
}

func (w *htmlWriter) cellContent(bs []Block) *Doc {
	if len(bs) == 1 {
		if p, ok := bs[0].(*Plain); ok {
			return w.inlines(p.Inlines)
		}
	}
	if len(bs) == 0 {
		return dEmpty
	}
	return Cat(dNL, w.blocks(bs), dNL)
}

// ---------- entry ----------

func writeHTMLBody(doc *Pandoc, opts *WriterOptions, html5 bool) (*Doc, *htmlWriter) {
	w := &htmlWriter{opts: opts, html5: html5, usedIDs: map[string]bool{}}
	bs := doc.Blocks
	if opts.SectionDivs {
		bs = makeSections(opts.NumberSections, nil, bs)
	} else if opts.NumberSections {
		bs = numberHeaders(bs, opts.NumberOffset)
	}
	body := w.blocks(bs)
	fn := w.footnoteSection()
	if !fn.IsEmpty() {
		body = Cat(body, dNL, fn)
	}
	return body, w
}

func writeHTML(doc *Pandoc, opts *WriterOptions, html5 bool) string {
	body, w := writeHTMLBody(doc, opts, html5)
	cols := opts.Columns
	if opts.Wrap == WrapNone || opts.Wrap == WrapPreserve {
		cols = 0
	}
	out := Render(body, cols)
	if !opts.Standalone {
		return out + "\n"
	}
	return htmlStandalone(doc, opts, w, out, html5)
}
