actions.command:
cd /workspace && cat > template.go <<'EOF'
package main

import (
	"embed"
	"sort"
	"strconv"
	"strings"
)

//go:embed data
var dataFS embed.FS

func readDataFile(name string) (string, bool) {
	b, err := dataFS.ReadFile("data/" + name)
	if err != nil {
		return "", false
	}
	return string(b), true
}

// template values: string, []tval, map[string]tval (tmap), bool
type tval interface{}
type tmap map[string]tval

const (
	tnLit = iota
	tnVar
	tnIf
	tnFor
	tnNested
	tnBreak
	tnNewline
)

type tpipe struct {
	name string
	args []string
}

type tnode struct {
	kind    int
	text    string
	path    string
	partial string
	pipes   []tpipe
	litSep  *string
	then    []*tnode
	els     []*tnode
	body    []*tnode
	sep     []*tnode
	alone   bool // variable alone on a line (auto-nesting)
	col     int  // column of variable start
}

type tparser struct {
	s    []rune
	pos  int
	name string
	err  string
}

func parseTemplate(src string) ([]*tnode, error) {
	p := &tparser{s: []rune(src)}
	nodes, end := p.parseNodes(nil)
	if end != "" {
		return nodes, &templateError{"unexpected " + end}
	}
	return nodes, nil
}

type templateError struct{ msg string }

func (e *templateError) Error() string { return e.msg }

// directive scanning: returns content string and end pos, or ok=false
func (p *tparser) scanDirective(at int) (string, int, bool) {
	s := p.s
	if at >= len(s) || s[at] != '$' {
		return "", 0, false
	}
	if at+1 < len(s) && s[at+1] == '{' {
		j := at + 2
		for j < len(s) && s[j] != '}' && s[j] != '\n' {
			j++
		}
		if j >= len(s) || s[j] != '}' {
			return "", 0, false
		}
		return strings.TrimSpace(string(s[at+2 : j])), j + 1, true
	}
	j := at + 1
	for j < len(s) && s[j] != '$' && s[j] != '\n' {
		j++
	}
	if j >= len(s) || s[j] != '$' {
		return "", 0, false
	}
	return strings.TrimSpace(string(s[at+1 : j])), j + 1, true
}

func isControl(c string) bool {
	return strings.HasPrefix(c, "if(") || strings.HasPrefix(c, "elseif(") || c == "else" || c == "endif" ||
		strings.HasPrefix(c, "for(") || c == "sep" || c == "endfor"
}

// lineStartAt returns start index of line containing pos
func (p *tparser) lineStart(pos int) int {
	i := pos
	for i > 0 && p.s[i-1] != '\n' {
		i--
	}
	return i
}

func (p *tparser) onlyWSBefore(pos int) bool {
	for i := p.lineStart(pos); i < pos; i++ {
		if p.s[i] != ' ' && p.s[i] != '\t' {
			return false
		}
	}
	return true
}

func (p *tparser) onlyWSAfter(pos int) (int, bool) {
	i := pos
	for i < len(p.s) && (p.s[i] == ' ' || p.s[i] == '\t') {
		i++
	}
	if i >= len(p.s) {
		return i, true
	}
	if p.s[i] == '\n' {
		return i + 1, true
	}
	return 0, false
}

// parseNodes parses until one of the terminators (else, elseif, endif, sep, endfor)
func (p *tparser) parseNodes(terms []string) ([]*tnode, string) {
	var nodes []*tnode
	var lit strings.Builder
	flush := func() {
		if lit.Len() > 0 {
			nodes = append(nodes, &tnode{kind: tnLit, text: lit.String()})
			lit.Reset()
		}
	}
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c != '$' {
			lit.WriteRune(c)
			p.pos++
			continue
		}
		// $$ escape
		if p.pos+1 < len(p.s) && p.s[p.pos+1] == '$' {
			lit.WriteRune('$')
			p.pos += 2
			continue
		}
		// comment
		if p.pos+2 < len(p.s) && p.s[p.pos+1] == '-' && p.s[p.pos+2] == '-' {
			// remove to end of line, including newline; if line only comment, drop whole line
			start := p.pos
			j := p.pos
			for j < len(p.s) && p.s[j] != '\n' {
				j++
			}
			if j < len(p.s) {
				j++
			}
			if p.onlyWSBefore(start) {
				// drop leading whitespace already in lit
				ls := lit.String()
				k := len(ls)
				for k > 0 && (ls[k-1] == ' ' || ls[k-1] == '\t') {
					k--
				}
				lit.Reset()
				lit.WriteString(ls[:k])
			}
			p.pos = j
			continue
		}
		content, end, ok := p.scanDirective(p.pos)
		if !ok {
			lit.WriteRune(c)
			p.pos++
			continue
		}
		start := p.pos
		if isControl(content) || content == "^" || content == "~" {
			alone := false
			if isControl(content) && p.onlyWSBefore(start) {
				if e2, ok := p.onlyWSAfter(end); ok {
					alone = true
					// strip leading ws from lit
					ls := lit.String()
					k := len(ls)
					for k > 0 && (ls[k-1] == ' ' || ls[k-1] == '\t') {
						k--
					}
					lit.Reset()
					lit.WriteString(ls[:k])
					end = e2
				}
			}
			_ = alone
			// terminators
			base := content
			if i := strings.IndexByte(base, '('); i >= 0 {
				base = base[:i]
			}
			for _, t := range terms {
				if base == t {
					flush()
					p.pos = end
					if base == "elseif" {
						p.pendingElseif = content
					}
					return nodes, base
				}
			}
			p.pos = end
			switch {
			case strings.HasPrefix(content, "if("):
				flush()
				v := strings.TrimSuffix(strings.TrimPrefix(content, "if("), ")")
				nodes = append(nodes, p.parseIf(strings.TrimSpace(v)))
			case strings.HasPrefix(content, "for("):
				flush()
				v := strings.TrimSuffix(strings.TrimPrefix(content, "for("), ")")
				n := &tnode{kind: tnFor, path: strings.TrimSpace(v)}
				body, term := p.parseNodes([]string{"sep", "endfor"})
				n.body = body
				if term == "sep" {
					sep, _ := p.parseNodes([]string{"endfor"})
					n.sep = sep
				}
				nodes = append(nodes, n)
			case content == "^":
				flush()
				nodes = append(nodes, &tnode{kind: tnNested})
			case content == "~":
				flush()
				nodes = append(nodes, &tnode{kind: tnBreak})
			default:
				// stray else/endif etc: ignore
			}
			continue
		}
		// variable / partial
		n := parseVarDirective(content)
		if n == nil {
			lit.WriteRune(c)
			p.pos++
			continue
		}
		// alone on line?
		if p.onlyWSBefore(start) {
			if _, ok := p.onlyWSAfter(end); ok {
				n.alone = true
			}
		}
		n.col = start - p.lineStart(start)
		flush()
		nodes = append(nodes, n)
		p.pos = end
	}
	flush()
	return nodes, ""
}

func (p *tparser) parseIf(v string) *tnode {
	n := &tnode{kind: tnIf, path: v}
	then, term := p.parseNodes([]string{"else", "elseif", "endif"})
	n.then = then
	switch term {
	case "else":
		els, _ := p.parseNodes([]string{"endif"})
		n.els = els
	case "elseif":
		c := p.pendingElseif
		p.pendingElseif = ""
		v2 := strings.TrimSuffix(strings.TrimPrefix(c, "elseif("), ")")
		n.els = []*tnode{p.parseIf(strings.TrimSpace(v2))}
	}
	return n
}

func parseVarDirective(c string) *tnode {
	n := &tnode{kind: tnVar}
	// separator [..] at end
	rest := c
	// pipes split by '/', but quoted args may contain /
	// first: name and optional :partial()
	i := 0
	rs := []rune(rest)
	for i < len(rs) && (isAlphaNumH(rs[i]) || rs[i] == '_' || rs[i] == '-' || rs[i] == '.') {
		i++
	}
	name := string(rs[:i])
	rest = string(rs[i:])
	if strings.HasPrefix(rest, "()") {
		// bare partial
		n.partial = name
		n.path = ""
		rest = rest[2:]
	} else {
		if name == "" {
			return nil
		}
		n.path = name
		if strings.HasPrefix(rest, ":") {
			rs2 := []rune(rest[1:])
			j := 0
			for j < len(rs2) && (isAlphaNumH(rs2[j]) || rs2[j] == '_' || rs2[j] == '-' || rs2[j] == '.') {
				j++
			}
			pn := string(rs2[:j])
			r2 := string(rs2[j:])
			if !strings.HasPrefix(r2, "()") {
				return nil
			}
			n.partial = pn
			rest = r2[2:]
		}
	}
	if strings.HasPrefix(rest, "[") {
		k := strings.LastIndex(rest, "]")
		if k > 0 {
			sep := rest[1:k]
			n.litSep = &sep
			rest = rest[k+1:]
		}
	}
	for strings.HasPrefix(rest, "/") {
		rest = rest[1:]
		// pipe name and args until next / not inside quotes
		var sb strings.Builder
		inQ := false
		j := 0
		for j < len(rest) {
			ch := rest[j]
			if ch == '\\' && inQ && j+1 < len(rest) {
				sb.WriteByte(ch)
				sb.WriteByte(rest[j+1])
				j += 2
				continue
			}
			if ch == '"' {
				inQ = !inQ
			}
			if ch == '/' && !inQ {
				break
			}
			sb.WriteByte(ch)
			j++
		}
		rest = rest[j:]
		n.pipes = append(n.pipes, parsePipe(sb.String()))
	}
	if strings.TrimSpace(rest) != "" {
		return nil
	}
	if isControl(n.path) || n.path == "it" && false {
		return nil
	}
	return n
}

func parsePipe(s string) tpipe {
	s = strings.TrimSpace(s)
	var args []string
	var name string
	i := strings.IndexByte(s, ' ')
	if i < 0 {
		return tpipe{name: s}
	}
	name = s[:i]
	rest := s[i:]
	for {
		rest = strings.TrimLeft(rest, " ")
		if rest == "" {
			break
		}
		if rest[0] == '"' {
			var sb strings.Builder
			j := 1
			for j < len(rest) && rest[j] != '"' {
				if rest[j] == '\\' && j+1 < len(rest) {
					j++
				}
				sb.WriteByte(rest[j])
				j++
			}
			args = append(args, sb.String())
			rest = rest[min(j+1, len(rest)):]
		} else {
			k := strings.IndexByte(rest, ' ')
			if k < 0 {
				args = append(args, rest)
				rest = ""
			} else {
				args = append(args, rest[:k])
				rest = rest[k:]
			}
		}
	}
	return tpipe{name: name, args: args}
}

// ---------- evaluation ----------

type tctx struct {
	vars     []tmap // stack, innermost last
	partials func(name string) (string, bool)
	tplExt   string
}

func (c *tctx) lookup(path string) (tval, bool) {
	parts := strings.Split(path, ".")
	for i := len(c.vars) - 1; i >= 0; i-- {
		if v, ok := c.vars[i][parts[0]]; ok {
			return descend(v, parts[1:])
		}
	}
	return nil, false
}

func descend(v tval, parts []string) (tval, bool) {
	for _, p := range parts {
		m, ok := v.(tmap)
		if !ok {
			return nil, false
		}
		v, ok = m[p]
		if !ok {
			return nil, false
		}
	}
	return v, true
}

func truthy(v tval) bool {
	switch x := v.(type) {
	case nil:
		return false
	case string:
		return x != ""
	case bool:
		return x
	case tmap:
		return true
	case []tval:
		for _, e := range x {
			if truthy(e) {
				return true
			}
		}
		return false
	}
	return false
}

func valToString(v tval) string {
	switch x := v.(type) {
	case string:
		return x
	case bool:
		if x {
			return "true"
		}
		return ""
	case tmap:
		return "true"
	case []tval:
		var sb strings.Builder
		for _, e := range x {
			sb.WriteString(valToString(e))
		}
		return sb.String()
	}
	return ""
}

type tout struct {
	sb  strings.Builder
	col int
}

func (o *tout) write(s string) {
	o.sb.WriteString(s)
	if i := strings.LastIndexByte(s, '\n'); i >= 0 {
		o.col = strWidth(s[i+1:])
	} else {
		o.col += strWidth(s)
	}
}

func indentLines(s string, n int) string {
	if n <= 0 || !strings.Contains(s, "\n") {
		return s
	}
	pad := strings.Repeat(" ", n)
	lines := strings.Split(s, "\n")
	for i := 1; i < len(lines); i++ {
		if lines[i] != "" {
			lines[i] = pad + lines[i]
		}
	}
	return strings.Join(lines, "\n")
}

func (c *tctx) render(nodes []*tnode, o *tout, nestCol int) {
	for i := 0; i < len(nodes); i++ {
		n := nodes[i]
		switch n.kind {
		case tnLit:
			o.write(indentLines(n.text, nestCol))
		case tnNested:
			// rest of nodes nested at current column
			sub := &tout{col: o.col}
			c.render(nodes[i+1:], sub, 0)
			o.write(indentLines(sub.sb.String(), o.col))
			return
		case tnBreak:
		case tnVar:
			s := c.evalVar(n)
			if n.alone || strings.Contains(s, "\n") {
				col := 0
				if n.alone {
					col = o.col
				}
				s = indentLines(s, col)
			}
			o.write(indentLines(s, nestCol))
		case tnIf:
			v, _ := c.lookup(n.path)
			if truthy(v) {
				c.render(n.then, o, nestCol)
			} else {
				c.render(n.els, o, nestCol)
			}
		case tnFor:
			v, ok := c.lookup(n.path)
			if !ok {
				continue
			}
			var items []tval
			switch x := v.(type) {
			case []tval:
				items = x
			case nil:
			default:
				items = []tval{x}
			}
			first := true
			for _, it := range items {
				if !first {
					c.render(n.sep, o, nestCol)
				}
				first = false
				binding := tmap{"it": it}
				setPath(binding, n.path, it)
				c.vars = append(c.vars, binding)
				c.render(n.body, o, nestCol)
				c.vars = c.vars[:len(c.vars)-1]
			}
		}
	}
}

// setPath binds a dotted path in a map (for loops over foo.bar)
func setPath(m tmap, path string, v tval) {
	parts := strings.Split(path, ".")
	cur := m
	for i, p := range parts {
		if i == len(parts)-1 {
			cur[p] = v
			return
		}
		nm := tmap{}
		cur[p] = nm
		cur = nm
	}
}

func (c *tctx) evalVar(n *tnode) string {
	var v tval
	if n.path != "" {
		var ok bool
		v, ok = c.lookup(n.path)
		if !ok {
			v = nil
		}
	}
	// apply pipes to value first if no partial
	if n.partial != "" {
		ptxt, ok := c.partials(n.partial)
		if !ok {
			return ""
		}
		pnodes, _ := parseTemplate(strings.TrimRight(ptxt, "\n"))
		apply := func(it tval) string {
			o := &tout{}
			if n.path != "" {
				c.vars = append(c.vars, tmap{"it": it})
				c.render(pnodes, o, 0)
				c.vars = c.vars[:len(c.vars)-1]
			} else {
				c.render(pnodes, o, 0)
			}
			return o.sb.String()
		}
		var s string
		if n.path == "" {
			s = apply(nil)
		} else if lst, ok := v.([]tval); ok {
			var parts []string
			for _, it := range lst {
				parts = append(parts, apply(it))
			}
			sep := ""
			if n.litSep != nil {
				sep = *n.litSep
			}
			s = strings.Join(parts, sep)
		} else if v == nil {
			s = ""
		} else {
			s = apply(v)
		}
		return applyStrPipes(s, n.pipes)
	}
	v = applyValPipes(v, n.pipes)
	if lst, ok := v.([]tval); ok && n.litSep != nil {
		var parts []string
		for _, e := range lst {
			parts = append(parts, valToString(e))
		}
		return applyStrPipes(strings.Join(parts, *n.litSep), n.pipes)
	}
	return applyStrPipes(valToString(v), n.pipes)
}

func applyValPipes(v tval, pipes []tpipe) tval {
	for _, p := range pipes {
		switch p.name {
		case "pairs":
			switch x := v.(type) {
			case tmap:
				var keys []string
				for k := range x {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				var out []tval
				for _, k := range keys {
					out = append(out, tmap{"key": k, "value": x[k]})
				}
				v = out
			case []tval:
				var out []tval
				for i, e := range x {
					out = append(out, tmap{"key": strconv.Itoa(i + 1), "value": e})
				}
				v = out
			}
		case "first":
			if x, ok := v.([]tval); ok && len(x) > 0 {
				v = x[0]
			}
		case "last":
			if x, ok := v.([]tval); ok && len(x) > 0 {
				v = x[len(x)-1]
			}
		case "rest":
			if x, ok := v.([]tval); ok && len(x) > 0 {
				v = x[1:]
			}
		case "allbutlast":
			if x, ok := v.([]tval); ok && len(x) > 0 {
				v = x[:len(x)-1]
			}
		case "reverse":
			if x, ok := v.([]tval); ok {
				r := make([]tval, len(x))
				for i := range x {
					r[i] = x[len(x)-1-i]
				}
				v = r
			}
		case "length":
			switch x := v.(type) {
			case []tval:
				v = strconv.Itoa(len(x))
			case tmap:
				v = strconv.Itoa(len(x))
			case string:
				v = strconv.Itoa(len([]rune(x)))
			}
		}
	}
	return v
}

func applyStrPipes(s string, pipes []tpipe) string {
	for _, p := range pipes {
		switch p.name {
		case "uppercase":
			s = strings.ToUpper(s)
		case "lowercase":
			s = strings.ToLower(s)
		case "chomp":
			s = strings.TrimRight(s, "\n ")
		case "alpha":
			if n, err := strconv.Atoi(s); err == nil {
				s = string(rune('a' + (n-1)%26))
			}
		case "roman":
			if n, err := strconv.Atoi(s); err == nil {
				s = toRoman(n, false)
			}
		case "reverse":
			rs := []rune(s)
			for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
				rs[i], rs[j] = rs[j], rs[i]
			}
			s = string(rs)
		case "left", "right", "center":
			w := 0
			if len(p.args) > 0 {
				w, _ = strconv.Atoi(p.args[0])
			}
			lb, rb := "", ""
			if len(p.args) > 1 {
				lb = p.args[1]
			}
			if len(p.args) > 2 {
				rb = p.args[2]
			}
			pad := w - strWidth(s)
			if pad < 0 {
				pad = 0
			}
			switch p.name {
			case "left":
				s = lb + s + strings.Repeat(" ", pad) + rb
			case "right":
				s = lb + strings.Repeat(" ", pad) + s + rb
			case "center":
				l := pad / 2
				s = lb + strings.Repeat(" ", l) + s + strings.Repeat(" ", pad-l) + rb
			}
		}
	}
	return s
}

func toRoman(n int, upper bool) string {
	vals := []int{1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1}
	syms := []string{"m", "cm", "d", "cd", "c", "xc", "l", "xl", "x", "ix", "v", "iv", "i"}
	var sb strings.Builder
	for i, v := range vals {
		for n >= v {
			sb.WriteString(syms[i])
			n -= v
		}
	}
	if upper {
		return strings.ToUpper(sb.String())
	}
	return sb.String()
}

func renderTemplate(tpl string, ctx tmap, ext string) (string, error) {
	nodes, err := parseTemplate(tpl)
	if err != nil {
		return "", err
	}
	c := &tctx{vars: []tmap{ctx}, tplExt: ext}
	c.partials = func(name string) (string, bool) {
		n := name
		if !strings.Contains(n, ".") && ext != "" {
			n = n + "." + ext
		}
		return readDataFile("templates/" + n)
	}
	o := &tout{}
	c.render(nodes, o, 0)
	return o.sb.String(), nil
}
