func metaToInlines(v MetaValue) []Inline {
	switch x := v.(type) {
	case *MetaInlines:
		return x.Inlines
	case *MetaString:
		return textToInlines(x.Text)
	case *MetaBlocks:
		var out []Inline
		for i, b := range x.Blocks {
			if i > 0 {
				out = append(out, &Space{})
			}
			switch bb := b.(type) {
			case *Plain:
				out = append(out, bb.Inlines...)
			case *Para:
				out = append(out, bb.Inlines...)
			case *LineBlock:
				for j, l := range bb.Lines {
					if j > 0 {
						out = append(out, &LineBreak{})
					}
					out = append(out, l...)
				}
			}
		}
		return out
	case *MetaBool:
		if x.Bool {
			return []Inline{&Str{"true"}}
		}
		return []Inline{&Str{"false"}}
	case *MetaList:
		var out []Inline
		for i, it := range x.Items {
			if i > 0 {
				out = append(out, &Str{","}, &Space{})
			}
			out = append(out, metaToInlines(it)...)
		}
		return out
	}
