package main

import "strings"

func htmlStandalone(doc *Pandoc, opts *WriterOptions, w *htmlWriter, body string, html5 bool) string {
	format := "html"
	if !html5 {
		format = "html4"
	}
	if opts.Format != "" {
		format = opts.Format
	}
	tpl, ok := getTemplate(opts, format)
	if !ok {
		return body
	}
	ctx := w.buildContext(doc, html5)
	ctx["body"] = Lit(strings.TrimRight(body, "\n"))
	d, err := renderTemplateDoc(tpl, ctx, "html")
	if err != nil {
		return body
	}
	out := Render(d, 0)
	if !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out
}

func (w *htmlWriter) renderInl(ils []Inline) *Doc {
	cols := w.opts.Columns
	if w.opts.Wrap != WrapAuto {
		cols = 0
	}
	return Lit(Render(w.inlines(ils), cols))
}

func (w *htmlWriter) renderBlocks(bs []Block) *Doc {
	cols := w.opts.Columns
	if w.opts.Wrap != WrapAuto {
		cols = 0
	}
	return Lit(Render(w.blocks(bs), cols))
}

func (w *htmlWriter) buildContext(doc *Pandoc, html5 bool) tmap {
	meta := doc.Meta
	ctx := metaToContext(meta, w.renderBlocks, w.renderInl)
	addVariables(ctx, w.opts)
	var authsMeta []tval
	for _, a := range docAuthors(meta) {
		authsMeta = append(authsMeta, escapeStringForXML(stringify(a)))
	}
	if len(authsMeta) > 0 {
		defField(ctx, "author-meta", authsMeta)
	}
	if dm := lookupMetaString(meta, "date"); dm != "" {
		if nd, ok := normalizeDate(dm); ok {
			defField(ctx, "date-meta", nd)
		}
	}
	if desc := lookupMetaString(meta, "description"); desc != "" {
		defField(ctx, "description-meta", escapeStringForXML(desc))
	}
	title := stringify(lookupMetaInlines(meta, "title"))
	defField(ctx, "pagetitle", escapeStringForXML(title))
	defField(ctx, "idprefix", w.opts.IDPrefix)
	defField(ctx, "slidy-url", "https://www.w3.org/Talks/Tools/Slidy2")
	defField(ctx, "slideous-url", "slideous")
	defField(ctx, "revealjs-url", "https://unpkg.com/reveal.js@^5")
	defField(ctx, "s5-url", "s5/default")
	if html5 {
		defField(ctx, "html5", true)
	}
	if _, hasCSS := ctx["css"]; !hasCSS {
		defField(ctx, "document-css", true)
	}
	if w.opts.HTMLMathMethod == "" || w.opts.HTMLMathMethod == "plain" {
		defField(ctx, "displaymath-css", true)
	}
	if w.highlighting {
		if css, ok := readDataFile("highlight-pygments.css"); ok {
			defField(ctx, "highlighting-css", Lit(strings.TrimRight(css, "\n")))
		}
	}
	if w.math {
		switch w.opts.HTMLMathMethod {
