package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type blockWriterFn func([]Block) *Doc
type inlineWriterFn func([]Inline) *Doc

func metaValueToVal(m MetaValue, bw blockWriterFn, iw inlineWriterFn) tval {
	switch v := m.(type) {
	case *MetaMap:
		mm := tmap{}
		for k, x := range v.Map {
			mm[k] = metaValueToVal(x, bw, iw)
		}
		return mm
	case *MetaList:
		var xs []tval
		for _, x := range v.Items {
			xs = append(xs, metaValueToVal(x, bw, iw))
		}
		return xs
	case *MetaBool:
		return v.Bool
	case *MetaString:
		return iw(textToInlines(v.Text))
	case *MetaInlines:
		return iw(v.Inlines)
	case *MetaBlocks:
		return bw(v.Blocks)
	}
	return nil
}

func metaToContext(meta Meta, bw blockWriterFn, iw inlineWriterFn) tmap {
	ctx := tmap{}
	for k, v := range meta {
		ctx[k] = metaValueToVal(v, bw, iw)
	}
	return ctx
}

// add variables from -V (they override metadata); repeated -V make lists
func addVariables(ctx tmap, opts *WriterOptions) {
	keys := make([]string, 0, len(opts.Variables))
	for k := range opts.Variables {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		vs := opts.Variables[k]
		if len(vs) == 1 {
			ctx[k] = vs[0]
		} else {
			var xs []tval
			for _, v := range vs {
				xs = append(xs, v)
			}
			ctx[k] = xs
		}
	}
}

func defField(ctx tmap, k string, v tval) {
	if _, ok := ctx[k]; !ok {
		ctx[k] = v
	}
}

func lookupMetaInlines(meta Meta, k string) []Inline {
	v, ok := meta[k]
	if !ok {
		return nil
	}
	return metaToInlines(v)
}

func metaToInlines(v MetaValue) []Inline {
	switch x := v.(type) {
	case *MetaInlines:
		return x.Inlines
	case *MetaString:
		return textToInlines(x.Text)
	case *MetaBlocks:
		var out []Inline
		for i, b := range x.Blocks {
			if i > 0 {
				out = append(out, &Space{})
			}
			switch bb := b.(type) {
			case *Plain:
				out = append(out, bb.Inlines...)
			case *Para:
				out = append(out, bb.Inlines...)
			case *LineBlock:
				for j, l := range bb.Lines {
					if j > 0 {
						out = append(out, &LineBreak{})
					}
					out = append(out, l...)
				}
			}
		}
		return out
	case *MetaBool:
		if x.Bool {
			return []Inline{&Str{"true"}}
		}
		return []Inline{&Str{"false"}}
	case *MetaList:
		var out []Inline
		for i, it := range x.Items {
			if i > 0 {
				out = append(out, &Str{","}, &Space{})
			}
			out = append(out, metaToInlines(it)...)
		}
		return out
	}
	return nil
}

