var monthNames = []string{"january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"}

func parseMonthName(s string, abbrev bool) (int, bool) {
	l := strings.ToLower(s)
	for i, m := range monthNames {
		if abbrev && l == m[:3] {
			return i + 1, true
		}
		if !abbrev && l == m {
			return i + 1, true
		}
	}
	return 0, false
}

func daysIn(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	}
	if (y%4 == 0 && y%100 != 0) || y%400 == 0 {
		return 29
	}
	return 28
}

// normalizeDate parses various date formats into YYYY-MM-DD
func normalizeDate(s string) (string, bool) {
	s = strings.TrimSpace(s)
	try := func(y, m, d int) (string, bool) {
		if y < 1601 || y > 9999 || m < 1 || m > 12 || d < 1 || d > daysIn(y, m) {
			return "", false
		}
		return fmt.Sprintf("%04d-%02d-%02d", y, m, d), true
	}
	num := func(x string, minLen, maxLen int) (int, bool) {
		if len(x) < minLen || len(x) > maxLen {
			return 0, false
		}
		for _, c := range x {
			if c < '0' || c > '9' {
				return 0, false
			}
		}
		n, _ := strconv.Atoi(x)
		return n, true
	}
	yy := func(n int) int {
		if n < 69 {
			return 2000 + n
		}
		return 1900 + n
	}
	// %m/%d/%y, %m/%d/%Y
	if parts := strings.Split(s, "/"); len(parts) == 3 {
		m, ok1 := num(parts[0], 1, 2)
		d, ok2 := num(parts[1], 1, 2)
		if ok1 && ok2 {
			if y, ok := num(parts[2], 2, 2); ok {
				if r, ok := try(yy(y), m, d); ok {
					return r, true
				}
			}
			if y, ok := num(parts[2], 1, 4); ok {
				if r, ok := try(y, m, d); ok {
					return r, true
				}
			}
		}
	}
	// %F
	if parts := strings.Split(s, "-"); len(parts) == 3 {
		y, ok1 := num(parts[0], 1, 4)
		m, ok2 := num(parts[1], 1, 2)
		d, ok3 := num(parts[2], 1, 2)
		if ok1 && ok2 && ok3 {
			if r, ok := try(y, m, d); ok {
				return r, true
			}
		}
	}
	f := strings.Fields(s)
	// %d %b %Y / %e %B %Y
	if len(f) == 3 {
		if d, ok := num(f[0], 1, 2); ok {
			if y, ok := num(f[2], 1, 4); ok {
				if m, ok := parseMonthName(f[1], true); ok {
					if r, ok := try(y, m, d); ok {
						return r, true
					}
				}
				if m, ok := parseMonthName(f[1], false); ok {
					if r, ok := try(y, m, d); ok {
						return r, true
					}
				}
			}
		}
		// %b. %e, %Y and %B %e, %Y
		if strings.HasSuffix(f[1], ",") {
			if d, ok := num(strings.TrimSuffix(f[1], ","), 1, 2); ok {
				if y, ok := num(f[2], 1, 4); ok {
					if strings.HasSuffix(f[0], ".") {
						if m, ok := parseMonthName(strings.TrimSuffix(f[0], "."), true); ok {
							if r, ok := try(y, m, d); ok {
								return r, true
							}
						}
					}
					if m, ok := parseMonthName(f[0], false); ok {
						if r, ok := try(y, m, d); ok {
							return r, true
						}
					}
				}
			}
		}
	}
	// %Y%m%d, %Y%m, %Y
	if y, ok := num(s, 8, 8); ok {
		_ = y
		yv, _ := strconv.Atoi(s[:4])
		mv, _ := strconv.Atoi(s[4:6])
		dv, _ := strconv.Atoi(s[6:8])
		if r, ok := try(yv, mv, dv); ok {
			return r, true
		}
	}
	if _, ok := num(s, 6, 6); ok {
		yv, _ := strconv.Atoi(s[:4])
		mv, _ := strconv.Atoi(s[4:6])
		if r, ok := try(yv, mv, 1); ok {
			return r, true
		}
	}
	if y, ok := num(s, 1, 4); ok {
		if r, ok := try(y, 1, 1); ok {
			return r, true
		}
	}
	return "", false
}

func escapeStringForXML(s string) string {
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		case '"':
			sb.WriteString("&quot;")
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func getTemplate(opts *WriterOptions, format string) (string, bool) {
	if opts.HasTemplate {
		return opts.Template, true
	}
	return readDataFile("templates/default." + format)
}
