func run(args []string) int {
	popts, files, code, msg := parseArgs(args)
	if code != 0 {
		return errExit(code, msg)
	}
	wo := &WriterOptions{Columns: 72, TOCDepth: 3, Variables: map[string][]string{}, Highlight: true, TabStop: 4,
		EmailObfuscation: "none", ReferenceLocation: "document", TopLevelDivision: "default"}
	c := &cliOpts{wopts: wo, tabStop: 4}
	c.files = files
	var metaVals [][2]string
	for _, o := range popts {
		switch o.name {
		case "from", "read":
			c.from = o.value
		case "to", "write":
			c.to = o.value
		case "output":
			c.output = o.value
		case "standalone":
			b, ok := boolVal(o)
			if !ok {
				return errExit(6, "Argument of --standalone/-s must be either true or false")
			}
			wo.Standalone = b
		case "template":
			c.templateFile = o.value
			wo.Standalone = true
		case "variable":
			k, v := splitKV(o.value)
			wo.Variables[k] = append(wo.Variables[k], v)
		case "metadata":
			k, v := splitKV(o.value)
			metaVals = append(metaVals, [2]string{k, v})
		case "metadata-file":
			c.metadataFiles = append(c.metadataFiles, o.value)
		case "wrap":
			switch o.value {
			case "auto":
				wo.Wrap = WrapAuto
			case "none":
				wo.Wrap = WrapNone
			case "preserve":
				wo.Wrap = WrapPreserve
			default:
				return errExit(6, "--wrap must be auto, none, or preserve")
			}
		case "columns":
			n, err := strconv.Atoi(o.value)
			if err != nil || n <= 0 {
				return errExit(6, "Argument of --columns must be a number greater than 0")
			}
			wo.Columns = n
		case "toc", "table-of-contents":
			b, _ := boolVal(o)
			wo.TOC = b
		case "toc-depth":
			n, err := strconv.Atoi(o.value)
			if err != nil || n < 1 || n > 6 {
				return errExit(6, "Argument of --toc-depth must be a number 1-6")
			}
			wo.TOCDepth = n
		case "number-sections":
			b, _ := boolVal(o)
			wo.NumberSections = b
		case "number-offset":
			for _, p := range strings.Split(o.value, ",") {
				n, err := strconv.Atoi(strings.TrimSpace(p))
				if err != nil {
					return errExit(6, "Argument of --number-offset must be a comma-separated list of integers")
				}
				wo.NumberOffset = append(wo.NumberOffset, n)
			}
		case "section-divs":
			b, _ := boolVal(o)
			wo.SectionDivs = b
		case "html-q-tags":
			b, _ := boolVal(o)
			wo.HTMLQTags = b
		case "ascii":
			b, _ := boolVal(o)
			wo.ASCII = b
		case "reference-links":
			b, _ := boolVal(o)
			wo.ReferenceLinks = b
		case "reference-location":
			wo.ReferenceLocation = o.value
		case "markdown-headings":
			wo.MarkdownHeadings = o.value
		case "list-tables":
			b, _ := boolVal(o)
			wo.ListTables = b
		case "top-level-division":
			switch o.value {
			case "section", "chapter", "part", "default":
				wo.TopLevelDivision = o.value
			default:
				return errExit(6, "Argument of --top-level division must be section,  chapter, part, or default")
			}
		case "id-prefix":
			wo.IDPrefix = o.value
		case "title-prefix":
			wo.TitlePrefix = o.value
			wo.Variables["title-prefix"] = append(wo.Variables["title-prefix"], o.value)
		case "css":
			wo.CSS = append(wo.CSS, o.value)
			wo.Variables["css"] = append(wo.Variables["css"], o.value)
		case "include-in-header", "include-before-body", "include-after-body":
			b, err := os.ReadFile(o.value)
			if err != nil {
				return errExit(1, fmt.Sprintf("%s: %s: withBinaryFile: does not exist (No such file or directory)", progName, o.value))
			}
			key := map[string]string{"include-in-header": "header-includes", "include-before-body": "include-before", "include-after-body": "include-after"}[o.name]
			wo.Variables[key] = append(wo.Variables[key], strings.TrimRight(string(b), "\n"))
		case "email-obfuscation":
			switch o.value {
			case "none", "javascript", "references":
				wo.EmailObfuscation = o.value
			default:
				return errExit(6, "Argument of --email-obfuscation must be references, javascript, or none")
			}
		case "mathjax":
			wo.HTMLMathMethod = "mathjax"
			wo.MathURL = "https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml-full.js"
			if o.has {
				wo.MathURL = o.value
			}
		case "katex":
			wo.HTMLMathMethod = "katex"
			wo.MathURL = "https://cdn.jsdelivr.net/npm/katex@0.16.21/dist/"
			if o.has {
				wo.MathURL = o.value
			}
		case "webtex":
			wo.HTMLMathMethod = "webtex"
			wo.MathURL = "https://latex.codecogs.com/png.latex?"
			if o.has {
				wo.MathURL = o.value
			}
		case "mathml":
			wo.HTMLMathMethod = "mathml"
		case "gladtex":
			wo.HTMLMathMethod = "gladtex"
		case "no-highlight":
			wo.Highlight = false
		case "highlight-style", "syntax-highlighting":
			if o.value == "none" {
				wo.Highlight = false
			} else {
				wo.HighlightStyle = o.value
			}
		case "tab-stop":
			n, err := strconv.Atoi(o.value)
			if err != nil || n <= 0 {
				return errExit(6, "Argument of --tab-stop must be a number greater than 0")
			}
			c.tabStop = n
			wo.TabStop = n
		case "preserve-tabs":
			b, _ := boolVal(o)
			c.preserveTabs = b
		case "strip-comments":
			b, _ := boolVal(o)
			c.stripComments = b
		case "shift-heading-level-by":
			n, err := strconv.Atoi(o.value)
			if err != nil {
				return errExit(6, "Argument of --shift-heading-level-by must be an integer")
			}
			c.shiftHeading = n
		case "base-header-level":
			n, err := strconv.Atoi(o.value)
			if err != nil {
				return errExit(6, "Argument of --base-header-level must be 1-5")
			}
			c.shiftHeading = n - 1
		case "incremental":
			b, _ := boolVal(o)
			wo.Incremental = b
		case "slide-level":
			n, err := strconv.Atoi(o.value)
			if err != nil {
				return errExit(6, "Argument of --slide-level must be a number between 0 and 6")
			}
			wo.SlideLevel = n
			wo.HasSlideLevel = true
		case "listings":
			b, _ := boolVal(o)
			wo.Listings = b
		case "natbib":
			wo.Natbib = true
		case "biblatex":
			wo.Biblatex = true
		case "dpi":
			n, _ := strconv.Atoi(o.value)
			wo.DPI = n
		case "eol":
			c.eol = o.value
		case "indented-code-classes":
			for _, x := range strings.FieldsFunc(o.value, func(r rune) bool { return r == ',' || r == ' ' }) {
				wo.IndentedCodeClasses = append(wo.IndentedCodeClasses, x)
			}
		case "default-image-extension":
			wo.DefaultImageExt = o.value
		case "figure-caption-position":
			wo.FigCaptionPos = o.value
		case "table-caption-position":
			wo.TableCaptionPos = o.value
		case "track-changes":
			c.trackChanges = o.value
		case "data-dir":
			c.dataDir = o.value
		case "file-scope":
			b, _ := boolVal(o)
			c.fileScope = b
		case "verbose":
			c.verbose = true
		case "quiet":
			c.quiet = true
		case "version":
			fmt.Print(versionText())
			return 0
		case "help":
			fmt.Print(helpText())
			return 0
		case "list-input-formats":
			for _, l := range inputFormats {
				fmt.Println(l)
			}
			return 0
		case "list-output-formats":
			for _, l := range outputFormats {
				fmt.Println(l)
			}
			return 0
		case "list-highlight-languages":
			for _, l := range strings.Fields(highlightLangList) {
				fmt.Println(l)
			}
			return 0
		case "list-highlight-styles":
			for _, l := range []string{"pygments", "tango", "espresso", "zenburn", "kate", "monochrome", "breezedark", "haddock"} {
				fmt.Println(l)
			}
			return 0
		case "list-extensions":
			f := "markdown"
			if o.has && o.value != "" {
				f = o.value
			}
			base := f
			if i := strings.IndexAny(f, "+-"); i >= 0 {
				base = f[:i]
			}
			d, ok := formatExtensions[base]
			if !ok {
				return errExit(6, base+" is not a recognized reader or writer format")
			}
			on := map[string]bool{}
			for _, x := range strings.Fields(d[0]) {
				on[x] = true
			}
			all := strings.Fields(d[1])
			sort.Strings(all)
			for _, x := range all {
				if on[x] {
					fmt.Println("+" + x)
				} else {
					fmt.Println("-" + x)
				}
			}
			return 0
		case "print-default-template":
			f := o.value
			if i := strings.IndexAny(f, "+-"); i >= 0 {
				f = f[:i]
			}
			t, ok := readDataFile("templates/default." + f)
			if !ok {
				return errExit(97, "Could not find data file templates/default."+f)
			}
			fmt.Print(t)
			return 0
		case "print-default-data-file":
			t, ok := readDataFile(o.value)
			if !ok {
				return errExit(97, "Could not find data file "+o.value)
			}
			fmt.Print(t)
			return 0
		case "bash-completion", "print-highlight-style":
			return 0
		}
	}
	// determine formats
	if c.from == "" {
		for _, f := range c.files {
			if ff := formatFromFilePath(f); ff != "" {
				c.from = ff
				break
			}
		}
		if c.from == "" {
			c.from = "markdown"
		}
	}
	if c.to == "" {
		if c.output != "" && c.output != "-" {
			if ff := formatFromFilePath(c.output); ff != "" {
				c.to = ff
			}
		}
		if c.to == "" {
			c.to = "html"
		}
	}
	return convert(c, metaVals)
}

func splitKV(s string) (string, string) {
	if i := strings.IndexAny(s, ":="); i >= 0 {
		return s[:i], s[i+1:]
	}
	return s, "true"
}

