package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

var progName = "pandoc"

type cliOpts struct {
	from, to       string
	output         string
	files          []string
	wopts          *WriterOptions
	metadata       [][2]string
	metadataFiles  []string
	templateFile   string
	listings       bool
	dataDir        string
	fileScope      bool
	preserveTabs   bool
	tabStop        int
	stripComments  bool
	shiftHeading   int
	eol            string
	trackChanges   string
	extractMedia   string
	verbose, quiet bool
}

func main() {
	progName = filepath.Base(os.Args[0])
	os.Exit(run(os.Args[1:]))
}

func errExit(code int, msg string) int {
	fmt.Fprintln(os.Stderr, msg)
	return code
}

type optSpec struct {
	long  []string
	short string
	arg   int // 0 none, 1 required, 2 optional (=value)
	argName string
}

var boolOpts = map[string]bool{
	"standalone": true, "file-scope": true, "sandbox": true, "ascii": true, "toc": true, "table-of-contents": true,
	"lof": true, "list-of-figures": true, "lot": true, "list-of-tables": true, "number-sections": true,
	"preserve-tabs": true, "self-contained": true, "embed-resources": true, "link-images": true,
	"no-check-certificate": true, "strip-comments": true, "reference-links": true, "list-tables": true,
	"listings": true, "incremental": true, "section-divs": true, "html-q-tags": true, "epub-title-page": true,
	"trace": true, "dump-args": true, "ignore-args": true, "fail-if-warnings": true,
}

var argOpts = map[string]string{
	"from": "FORMAT", "read": "FORMAT", "to": "FORMAT", "write": "FORMAT", "output": "FILE", "data-dir": "DIRECTORY",
	"metadata": "KEY[:VALUE]", "metadata-file": "FILE", "defaults": "FILE", "template": "FILE", "variable": "KEY[:VALUE]",
	"variable-json": "KEY[:JSON]", "wrap": "auto|none|preserve", "toc-depth": "NUMBER", "number-offset": "NUMBERS",
	"top-level-division": "section|chapter|part", "extract-media": "PATH", "resource-path": "SEARCHPATH",
	"include-in-header": "FILE", "include-before-body": "FILE", "include-after-body": "FILE",
	"highlight-style": "STYLE|FILE", "syntax-definition": "FILE", "syntax-highlighting": "none|default|idiomatic|<stylename>|<themepath>",
	"dpi": "NUMBER", "eol": "crlf|lf|native", "columns": "NUMBER", "tab-stop": "NUMBER", "pdf-engine": "PROGRAM",
	"pdf-engine-opt": "STRING", "reference-doc": "FILE", "request-header": "NAME:VALUE", "abbreviations": "FILE",
	"indented-code-classes": "STRING", "default-image-extension": "extension", "filter": "PROGRAM", "lua-filter": "SCRIPTPATH",
	"shift-heading-level-by": "NUMBER", "base-header-level": "NUMBER", "track-changes": "accept|reject|all",
	"reference-location": "block|section|document", "figure-caption-position": "above|below",
	"table-caption-position": "above|below", "markdown-headings": "setext|atx", "slide-level": "NUMBER",
	"email-obfuscation": "none|javascript|references", "id-prefix": "STRING", "title-prefix": "STRING", "css": "URL",
	"epub-subdirectory": "DIRNAME", "epub-cover-image": "FILE", "epub-metadata": "FILE", "epub-embed-font": "FILE",
	"split-level": "NUMBER", "chunk-template": "PATHTEMPLATE", "epub-chapter-level": "NUMBER", "ipynb-output": "all|none|best",
	"bibliography": "FILE", "csl": "FILE", "citation-abbreviations": "FILE", "log": "FILE",
	"print-default-template": "FORMAT", "print-default-data-file": "FILE", "print-highlight-style": "STYLE|FILE",
}

var optArgOpts = map[string]bool{"webtex": true, "mathjax": true, "katex": true, "list-extensions": true}

var flagOpts = map[string]bool{"no-highlight": true, "natbib": true, "biblatex": true, "mathml": true, "gladtex": true,
	"verbose": true, "quiet": true, "bash-completion": true, "list-input-formats": true, "list-output-formats": true,
	"list-highlight-languages": true, "list-highlight-styles": true, "version": true, "help": true, "citeproc": true}

var shortMap = map[byte]string{'f': "from", 'r': "read", 't': "to", 'w': "write", 'o': "output", 'M': "metadata",
	'd': "defaults", 'V': "variable", 'H': "include-in-header", 'B': "include-before-body", 'A': "include-after-body",
	'F': "filter", 'L': "lua-filter", 'T': "title-prefix", 'c': "css", 'D': "print-default-template"}
var shortBool = map[byte]string{'s': "standalone", 'N': "number-sections", 'p': "preserve-tabs", 'i': "incremental"}
var shortFlag = map[byte]string{'C': "citeproc", 'v': "version", 'h': "help"}

type parsedOpt struct {
	name  string
	value string
	has   bool
}

func parseArgs(args []string) ([]parsedOpt, []string, int, string) {
	var opts []parsedOpt
	var files []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			files = append(files, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			val := ""
			has := false
			if j := strings.IndexByte(name, '='); j >= 0 {
				val = name[j+1:]
				name = name[:j]
				has = true
			}
			// allow unique prefixes? pandoc uses getopt: exact or unique prefix
			name = resolveLongOpt(name)
			if boolOpts[name] {
				opts = append(opts, parsedOpt{name, val, has})
				continue
			}
			if _, ok := argOpts[name]; ok {
				if !has {
					if i+1 >= len(args) {
						return nil, nil, 6, fmt.Sprintf("option `--%s' requires an argument %s\nTry %s --help for more information.", name, argOpts[name], progName)
					}
					i++
					val = args[i]
				}
				opts = append(opts, parsedOpt{name, val, true})
				continue
			}
			if optArgOpts[name] {
				opts = append(opts, parsedOpt{name, val, has})
				continue
			}
			if flagOpts[name] {
				if has {
					return nil, nil, 6, fmt.Sprintf("option `--%s' doesn't allow an argument\nTry %s --help for more information.", name, progName)
				}
				opts = append(opts, parsedOpt{name, "", false})
				continue
			}
			return nil, nil, 6, fmt.Sprintf("Unknown option --%s.\nTry %s --help for more information.", name, progName)
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short options, possibly clustered
			j := 1
			for j < len(a) {
				c := a[j]
				if long, ok := shortMap[c]; ok {
					val := a[j+1:]
					if val == "" {
						if i+1 >= len(args) {
							return nil, nil, 6, fmt.Sprintf("option `-%c' requires an argument %s\nTry %s --help for more information.", c, argOpts[long], progName)
						}
						i++
						val = args[i]
					}
					opts = append(opts, parsedOpt{long, val, true})
					break
				}
				if long, ok := shortBool[c]; ok {
					rest := a[j+1:]
					if rest == "true" || rest == "false" {
						opts = append(opts, parsedOpt{long, rest, true})
						break
					}
					opts = append(opts, parsedOpt{long, "", false})
					j++
					continue
				}
				if long, ok := shortFlag[c]; ok {
					opts = append(opts, parsedOpt{long, "", false})
					j++
					continue
				}
				return nil, nil, 6, fmt.Sprintf("Unknown option -%c.\nTry %s --help for more information.", c, progName)
			}
			continue
		}
		files = append(files, a)
	}
	return opts, files, 0, ""
}

func resolveLongOpt(name string) string {
	if boolOpts[name] || flagOpts[name] || optArgOpts[name] {
		return name
	}
	if _, ok := argOpts[name]; ok {
		return name
	}
	// unique prefix match
	var cands []string
	for k := range boolOpts {
		if strings.HasPrefix(k, name) {
			cands = append(cands, k)
		}
	}
	for k := range argOpts {
		if strings.HasPrefix(k, name) {
			cands = append(cands, k)
		}
	}
	for k := range flagOpts {
		if strings.HasPrefix(k, name) {
			cands = append(cands, k)
		}
	}
	for k := range optArgOpts {
		if strings.HasPrefix(k, name) {
			cands = append(cands, k)
		}
	}
	if len(cands) == 1 {
		return cands[0]
	}
	return name
}

func boolVal(o parsedOpt) (bool, bool) {
	if !o.has {
		return true, true
	}
	switch o.value {
	case "true":
		return true, true
	case "false":
		return false, true
	}
	return false, false
}

func formatFromFilePath(p string) string {
	ext := strings.ToLower(filepath.Ext(p))
	switch ext {
	case ".rmd":
		return "markdown"
	case ".adoc", ".asciidoc":
