			c.to = o.value
		case "output":
			c.output = o.value
		case "standalone":
			b, ok := boolVal(o)
			if !ok {
				return errExit(6, "Argument of --standalone/-s must be either true or false")
			}
			wo.Standalone = b
		case "template":
			c.templateFile = o.value
