			for _, x := range strings.Fields(d[0]) {
				on[x] = true
			}
			all := strings.Fields(d[1])
			sort.Strings(all)
			for _, x := range all {
				if on[x] {
					fmt.Println("+" + x)
				} else {
					fmt.Println("-" + x)
				}
			}
