func userDataDir() string {
	if x := os.Getenv("XDG_DATA_HOME"); x != "" {
		return x + "/pandoc"
	}
	h, _ := os.UserHomeDir()
	return h + "/.local/share/pandoc"
}

func helpText() string {
	s, _ := readDataFile("help.txt")
	return strings.Replace(s, "pandoc [OPTIONS] [FILES]", progName+" [OPTIONS] [FILES]", 1)
}

func readInputs(c *cliOpts) (string, int, string) {
	var parts []string
	if len(c.files) == 0 || (len(c.files) == 1 && c.files[0] == "-") {
		b, _ := io.ReadAll(os.Stdin)
		parts = append(parts, string(b))
	} else {
		for _, f := range c.files {
			if f == "-" {
				b, _ := io.ReadAll(os.Stdin)
				parts = append(parts, string(b))
				continue
			}
			b, err := os.ReadFile(f)
			if err != nil {
				return "", 1, fmt.Sprintf("%s: %s: withBinaryFile: does not exist (No such file or directory)", progName, f)
			}
			parts = append(parts, string(b))
		}
	}
	for i, p := range parts {
		p = strings.TrimPrefix(p, "\ufeff")
		p = strings.ReplaceAll(p, "\r\n", "\n")
		parts[i] = p
	}
	return strings.Join(parts, "\n\n"), 0, ""
}

