func convert(c *cliOpts, metaVals [][2]string) int {
	fromBase, fromExts, err := parseFormatSpec(c.from)
	if _, ok := formatExtensions[fromBase]; !ok || !isReader(fromBase) {
		return errExit(21, "Unknown input format "+fromBase)
	}
	if err != nil {
		return errExit(23, err.Error())
	}
	toBase, toExts, err := parseFormatSpec(c.to)
	if _, ok := formatExtensions[toBase]; !ok || !isWriter(toBase) {
		return errExit(22, "Unknown output format "+toBase)
	}
	if err != nil {
		return errExit(23, err.Error())
	}
	wo := c.wopts
	wo.Exts = toExts
	wo.Format = toBase
	if c.templateFile != "" {
		t, err := os.ReadFile(c.templateFile)
		if err != nil {
			tf := c.templateFile
			if filepath.Ext(tf) == "" {
				tf += "." + templateExt(toBase)
			}
			t2, err2 := os.ReadFile(tf)
			if err2 != nil {
				return errExit(97, "Could not find data file templates/"+tf)
			}
			t = t2
		}
		wo.Template = string(t)
		wo.HasTemplate = true
	}
	if toBase == "pdf" {
		return errExit(47, "pdflatex not found. Please select a different --pdf-engine or install pdflatex")
	}
	input, code, msg := readInputs(c)
	if code != 0 {
		return errExit(code, msg)
	}
	if !c.preserveTabs && fromBase != "json" && fromBase != "native" {
		input = expandTabs(input, c.tabStop)
	}
	ropts := &ReaderOptions{Exts: fromExts, TabStop: c.tabStop, Columns: wo.Columns, IndentedCodeClasses: wo.IndentedCodeClasses,
		DefaultImageExt: wo.DefaultImageExt, StripComments: c.stripComments, TrackChanges: c.trackChanges, Standalone: wo.Standalone}
	doc, err := readDoc(fromBase, input, ropts)
	if err != nil {
		if pe, ok := err.(*exitError); ok {
			return errExit(pe.code, pe.msg)
		}
		return errExit(64, err.Error())
	}
	// metadata files
	for _, mf := range c.metadataFiles {
		b, err := os.ReadFile(mf)
		if err != nil {
			return errExit(98, "Could not find metadata file "+mf)
		}
		st := newMdState(&ReaderOptions{Exts: defaultExtensions("markdown"), TabStop: 4, Columns: 72})
		p := newMdParser("", st, 1)
		m, err := p.yamlToMeta(string(b))
		if err == nil {
			for k, v := range m {
				if _, exists := doc.Meta[k]; !exists {
					doc.Meta[k] = resolveMeta(st, v)
				}
			}
		}
	}
	for _, kv := range metaVals {
		doc.Meta[kv[0]] = metaFromCLI(kv[1])
	}
	if c.shiftHeading != 0 {
		doc.Blocks = shiftHeadings(doc, c.shiftHeading)
	}
	out, isBinary, err := writeDoc(toBase, doc, wo)
	if err != nil {
		if pe, ok := err.(*exitError); ok {
			return errExit(pe.code, pe.msg)
		}
		return errExit(1, err.Error())
	}
	if c.eol == "crlf" {
		out = strings.ReplaceAll(out, "\n", "\r\n")
	}
	_ = isBinary
	if c.output != "" && c.output != "-" {
		if err := os.WriteFile(c.output, []byte(out), 0644); err != nil {
			return errExit(1, err.Error())
		}
		return 0
	}
	os.Stdout.WriteString(out)
	return 0
}

type exitError struct {
	code int
	msg  string
}

func (e *exitError) Error() string { return e.msg }

func metaFromCLI(v string) MetaValue {
	switch v {
	case "true", "True", "TRUE":
		return &MetaBool{true}
	case "false", "False", "FALSE":
		return &MetaBool{false}
	}
	return &MetaString{v}
}

func templateExt(f string) string {
	switch f {
	case "html", "html4", "html5", "revealjs", "s5", "slidy", "slideous", "dzslides", "chunkedhtml":
		return "html"
	case "beamer":
		return "latex"
	}
	return f
}

func shiftHeadings(doc *Pandoc, n int) []Block {
	var out []Block
	for _, b := range doc.Blocks {
		if h, ok := b.(*Header); ok {
			lv := h.Level + n
			if lv <= 0 {
				if n < 0 && h.Level+n == 0 {
					// becomes title
					if _, has := doc.Meta["title"]; !has {
						doc.Meta["title"] = &MetaInlines{h.Inlines}
					}
					continue
				}
				out = append(out, &Para{h.Inlines})
				continue
			}
			out = append(out, &Header{lv, h.Attr, h.Inlines})
			continue
		}
		out = append(out, b)
	}
	return out
}

func isReader(f string) bool {
	for _, x := range inputFormats {
		if x == f {
			return true
		}
	}
	return false
}

func isWriter(f string) bool {
	for _, x := range outputFormats {
		if x == f {
			return true
		}
	}
	return false
}
