// toTableOfContents builds a BulletList TOC from blocks
func toTableOfContents(opts *WriterOptions, bs []Block) *BulletList {
	secs := makeSections(opts.NumberSections, nil, bs)
	var items [][]Block
	for _, s := range secs {
		if it := sectionToListItem(opts, s); len(it) > 0 {
			items = append(items, it)
		}
	}
	return &BulletList{items}
}

func deLinkNote(xs []Inline) []Inline {
	var out []Inline
	for _, x := range xs {
		switch v := x.(type) {
		case *Link:
			out = append(out, deLinkNote(v.Inlines)...)
		case *Note:
		case *Emph:
			out = append(out, &Emph{deLinkNote(v.Inlines)})
		case *Strong:
			out = append(out, &Strong{deLinkNote(v.Inlines)})
		case *Span:
			out = append(out, &Span{v.Attr, deLinkNote(v.Inlines)})
		default:
			out = append(out, x)
		}
	}
	return out
}

func sectionToListItem(opts *WriterOptions, b Block) []Block {
	d, ok := b.(*Div)
	if !ok || len(d.Blocks) == 0 {
		return nil
	}
	h, ok := d.Blocks[0].(*Header)
	if !ok {
		if inner, ok := d.Blocks[0].(*Div); ok {
			r := sectionToListItem(opts, inner)
			for _, x := range d.Blocks[1:] {
				r = append(r, sectionToListItem(opts, x)...)
			}
			return r
		}
		return nil
	}
	if h.Level > opts.TOCDepth || h.Attr.HasClass("unlisted") {
		return nil
	}
	num, _ := h.Attr.Get("number")
	text := deLinkNote(h.Inlines)
	if num != "" {
		text = append([]Inline{&Span{Attr{Classes: []string{"toc-section-number"}}, []Inline{&Str{num}}}, &Space{}}, text...)
	}
	var link []Inline
	if d.Attr.ID == "" {
		link = text
	} else {
		link = []Inline{&Link{Attr{ID: "toc-" + d.Attr.ID}, text, Target{"#" + d.Attr.ID, ""}}}
	}
	var sub [][]Block
	for _, x := range d.Blocks[1:] {
		if it := sectionToListItem(opts, x); len(it) > 0 {
			sub = append(sub, it)
		}
	}
	res := []Block{&Plain{link}}
	if len(sub) > 0 {
		res = append(res, &BulletList{sub})
	}
	return res
}
