package main

import (
	"strconv"
	"strings"
	"unicode"
)

const (
	mdVariantMarkdown = iota
	mdVariantPlain
	mdVariantCommonmark
	mdVariantMarkua
)

type mdRef struct {
	label  string
	target Target
	attr   Attr
}

type mdWriter struct {
	opts       *WriterOptions
	variant    int
	format     string
	notes      [][]Block
	refs       []mdRef
	ids        map[string]bool
	inList     bool
	shortcut   bool
	blockLevel int
	noteNum    int
	asciiOK    bool
}

func (w *mdWriter) ext(n string) bool { return w.opts.Exts.On(n) }

func newMdWriter(opts *WriterOptions, variant int) *mdWriter {
	return &mdWriter{opts: opts, variant: variant, ids: map[string]bool{}, shortcut: true}
}

func writeMarkdown(doc *Pandoc, opts *WriterOptions, variant int) string {
	w := newMdWriter(opts, variant)
	body := w.blockList(doc.Blocks)
	notes := w.notesAndRefs()
	main := body
	if !notes.IsEmpty() {
		main = Cat(body, dBlank, notes)
	}
	cols := opts.Columns
	if opts.Wrap != WrapAuto {
		cols = 0
	}
	if !opts.Standalone {
		out := Render(main, cols)
		return strings.TrimRight(out, "\n") + "\n"
	}
	return w.standalone(doc, main, cols)
}

func (w *mdWriter) standalone(doc *Pandoc, main *Doc, cols int) string {
	format := "markdown"
	if w.variant == mdVariantPlain {
		format = "plain"
	}
	if w.opts.Format != "" {
		format = w.opts.Format
	}
	tpl, ok := getTemplate(w.opts, format)
	body := Render(main, cols)
	if !ok {
		return body
	}
	ctx := metaToContext(doc.Meta, func(bs []Block) *Doc {
		ww := newMdWriter(w.opts, w.variant)
		return Lit(strings.TrimRight(Render(ww.blockList(bs), cols), "\n"))
	}, func(ils []Inline) *Doc {
		ww := newMdWriter(w.opts, w.variant)
		return Lit(Render(ww.inlines(ils), cols))
	})
	addVariables(ctx, w.opts)
	if w.variant == mdVariantMarkdown && len(doc.Meta) > 0 {
		if y := w.yamlMeta(doc.Meta); y != "" {
			if w.ext("yaml_metadata_block") {
				defField(ctx, "titleblock", Lit(strings.TrimRight(y, "\n")))
			}
		}
	}
	ctx["body"] = Lit(strings.TrimRight(body, "\n"))
	d, err := renderTemplateDoc(tpl, ctx, format)
	if err != nil {
		return body
	}
	out := Render(d, 0)
	return strings.TrimRight(out, "\n") + "\n"
}

// ---------- blocks ----------

func isListBlock(b Block) bool {
	switch b.(type) {
	case *BulletList, *OrderedList, *DefinitionList:
		return true
	}
	return false
}

func (w *mdWriter) commentSep() Block {
	if w.variant == mdVariantPlain {
		return nil
	}
	if w.ext("raw_html") {
		return &RawBlock{"html", "<!-- -->\n"}
	}
	return &RawBlock{"markdown", "&nbsp;\n"}
}

func (w *mdWriter) fixBlocks(bs []Block) []Block {
	var out []Block
	for i := 0; i < len(bs); i++ {
		b := bs[i]
		var next Block
		if i+1 < len(bs) {
			next = bs[i+1]
		}
		if cb, ok := next.(*CodeBlock); ok && isListBlock(b) && (!w.ext("fenced_code_blocks") || cb.Attr.IsEmpty()) {
			out = append(out, b)
			if s := w.commentSep(); s != nil {
				out = append(out, s)
			}
			continue
		}
		same := false
		switch b.(type) {
		case *BulletList:
			_, same = next.(*BulletList)
		case *OrderedList:
			_, same = next.(*OrderedList)
		case *DefinitionList:
			_, same = next.(*DefinitionList)
		}
		if same {
			out = append(out, b)
			if s := w.commentSep(); s != nil {
				out = append(out, s)
			}
			continue
		}
		if pl, ok := b.(*Plain); ok {
			if _, isRaw := next.(*RawBlock); isRaw {
				out = append(out, pl)
				continue
			}
			if w.inList {
				out = append(out, pl)
				continue
			}
			out = append(out, &Para{pl.Inlines})
			continue
		}
		if rb, ok := b.(*RawBlock); ok && next != nil && rb.Text != "" && !strings.HasSuffix(rb.Text, "\n") {
			switch next.(type) {
			case *Plain, *RawBlock:
				out = append(out, rb)
			default:
				out = append(out, &RawBlock{rb.Format, rb.Text + "\n"})
			}
			continue
		}
		out = append(out, b)
	}
	return out
}

func (w *mdWriter) blockList(bs []Block) *Doc {
	var ds []*Doc
	for _, b := range w.fixBlocks(bs) {
		ds = append(ds, w.block(b))
	}
	return Cat(ds...)
}

func beginsWithOrderedListMarker(s string) bool {
	p := newMdParser(s+" ", &mdState{exts: defaultExtensions("markdown"), opts: &ReaderOptions{TabStop: 4}}, 1)
	_, ok := p.anyOrderedListMarker()
	if !ok {
		return false
	}
	return p.pos == len([]rune(s))
}

func (w *mdWriter) escapeMarker(s string) string {
	var sb strings.Builder
	for _, c := range s {
		if c == '.' || c == '(' || c == ')' {
			sb.WriteRune('\\')
		}
		sb.WriteRune(c)
	}
	return sb.String()
}

func (w *mdWriter) plainInlines(ils []Inline) *Doc {
	if w.variant != mdVariantPlain && len(ils) > 0 {
		if s, ok := ils[0].(*Str); ok {
			startsWithSpace := len(ils) == 1
			if len(ils) > 1 {
				switch ils[1].(type) {
				case *Space, *SoftBreak:
					startsWithSpace = true
				}
			}
			if startsWithSpace && beginsWithOrderedListMarker(s.Text) {
				nils := append([]Inline{&RawInline{"markdown", w.escapeMarker(s.Text)}}, ils[1:]...)
				return w.inlines(nils)
			}
			if s.Text == "+" || s.Text == "-" {
				nils := append([]Inline{&RawInline{"markdown", "\\"}}, ils...)
				return w.inlines(nils)
			}
		}
	}
	return w.inlines(ils)
}

func (w *mdWriter) block(b Block) *Doc {
	switch v := b.(type) {
	case *Plain:
		return Cat(w.plainInlines(v.Inlines), dCR)
	case *Para:
		return Cat(w.plainInlines(v.Inlines), dBlank)
	case *Div:
		return w.div(v)
	case *LineBlock:
		if w.ext("line_blocks") {
			var ds []*Doc
			for _, l := range v.Lines {
				ds = append(ds, Hang(2, Lit("| "), w.inlines(l)))
			}
			return Cat(Vcat(ds), dBlank)
		}
		var ils []Inline
		for i, l := range v.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return w.block(&Para{ils})
	case *RawBlock:
		return w.rawBlock(v)
	case *HorizontalRule:
		return Cat(dBlank, Lit(strings.Repeat("-", w.opts.Columns)), dBlank)
	case *Header:
		return w.header(v)
	case *CodeBlock:
		return w.codeBlock(v)
	case *BlockQuote:
		leader := "> "
		if w.variant == mdVariantPlain {
			leader = "  "
		}
		c := w.blockList(v.Blocks)
		return Cat(Prefixed(leader, c), dBlank)
	case *BulletList:
		old := w.inList
		w.inList = true
		var items []*Doc
		for _, it := range v.Items {
			items = append(items, w.bulletItem(it))
		}
		w.inList = old
		if isTightList(v.Items) {
			return Cat(Vcat(items), dBlank)
		}
		return Cat(Vsep(items), dBlank)
	case *OrderedList:
		return w.orderedList(v)
	case *DefinitionList:
		return w.defList(v)
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

func isTightList(items [][]Block) bool {
	for _, it := range items {
		if len(it) == 0 {
			continue
		}
		if _, ok := it[0].(*Plain); !ok {
			return false
		}
	}
	return true
}

func itemEndsWithTightList(bs []Block) bool {
	if len(bs) == 0 {
		return false
	}
	switch v := bs[len(bs)-1].(type) {
	case *BulletList:
		return isTightList(v.Items)
	case *OrderedList:
		return isTightList(v.Items)
	}
	return false
}

func (w *mdWriter) taskListItemToAscii(bs []Block) []Block {
	if !w.ext("task_lists") || len(bs) == 0 {
		return bs
	}
	conv := func(ils []Inline) []Inline {
		if len(ils) == 0 {
			return ils
		}
		s, ok := ils[0].(*Str)
		if !ok {
			return ils
		}
		if s.Text == "\u2610" {
			return append([]Inline{&RawInline{"markdown", "[ ]"}}, ils[1:]...)
		}
		if s.Text == "\u2612" {
			return append([]Inline{&RawInline{"markdown", "[x]"}}, ils[1:]...)
		}
		return ils
	}
	out := append([]Block{}, bs...)
	switch v := bs[0].(type) {
	case *Plain:
		out[0] = &Plain{conv(v.Inlines)}
	case *Para:
		out[0] = &Para{conv(v.Inlines)}
	}
	return out
}

func (w *mdWriter) bulletItem(bs []Block) *Doc {
	c := w.blockList(w.taskListItemToAscii(bs))
	if itemEndsWithTightList(bs) {
		c = Cat(Chomp(c), dCR)
	}
	start := "- "
	if w.variant == mdVariantPlain {
		start = "- "
	}
	return Hang(2, Lit(start), c)
}

func orderedListMarkers(la ListAttributes, n int) []string {
	var out []string
	for i := 0; i < n; i++ {
		num := la.Start + i
		var s string
		switch la.Style {
		case LowerAlpha:
			s = toAlpha(num, false)
		case UpperAlpha:
			s = toAlpha(num, true)
		case LowerRoman:
			s = toRoman(num, false)
		case UpperRoman:
			s = toRoman(num, true)
		default:
			s = strconv.Itoa(num)
		}
		switch la.Delim {
		case OneParen:
			s += ")"
		case TwoParens:
			s = "(" + s + ")"
		default:
			s += "."
		}
		out = append(out, s)
	}
	return out
}

func toAlpha(n int, upper bool) string {
	if n < 1 {
		return strconv.Itoa(n)
	}
	var s string
	for n > 0 {
		n--
		s = string(rune('a'+n%26)) + s
		n /= 26
	}
	if upper {
		return strings.ToUpper(s)
	}
	return s
}

func (w *mdWriter) orderedList(v *OrderedList) *Doc {
	la := v.Attrs
	if !w.ext("startnum") {
		la.Start = 1
	}
	if !w.ext("fancy_lists") {
		la.Style = DefaultStyle
		la.Delim = DefaultDelim
	}
	if la.Style == Example {
		la.Style = Decimal
		if la.Delim == DefaultDelim {
			la.Delim = TwoParens
		}
	}
	markers := orderedListMarkers(la, len(v.Items))
	old := w.inList
	w.inList = true
	var items []*Doc
	for i, it := range v.Items {
		m := markers[i]
		if len([]rune(m)) < 3 {
			m += strings.Repeat(" ", 3-len([]rune(m)))
		}
		items = append(items, w.orderedItem(m, it))
	}
	w.inList = old
	if isTightList(v.Items) {
		return Cat(Vcat(items), dBlank)
	}
	return Cat(Vsep(items), dBlank)
}

func (w *mdWriter) orderedItem(marker string, bs []Block) *Doc {
	c := w.blockList(w.taskListItemToAscii(bs))
	tab := w.opts.TabStop
	ml := len([]rune(marker))
	sps := " "
	if tab-ml > 0 {
		sps = strings.Repeat(" ", tab-ml)
	}
	ind := tab
	if !w.ext("four_space_rule") {
		if ml+1 > ind {
			ind = ml + 1
		}
	}
	if itemEndsWithTightList(bs) {
		c = Cat(Chomp(c), dCR)
	}
	return Hang(ind, Lit(marker+sps), c)
}

func (w *mdWriter) defList(v *DefinitionList) *Doc {
	old := w.inList
	w.inList = true
	var ds []*Doc
	for _, it := range v.Items {
		ds = append(ds, w.defItem(it))
	}
	w.inList = old
	return Cat(Cat(ds...), dBlank)
}

func (w *mdWriter) defItem(it DefItem) *Doc {
	label := w.block(&Plain{it.Term})
	var defs []*Doc
	for _, d := range it.Defs {
		var bs []*Doc
		for _, b := range w.fixBlocks(d) {
			bs = append(bs, w.block(b))
		}
		defs = append(defs, Cat(bs...))
	}
	if w.ext("definition_lists") {
		leader := ": "
		if w.variant == mdVariantPlain {
			leader = "  "
		}
		var items []*Doc
		for _, d := range defs {
			items = append(items, Hang(2, Lit(leader), d))
		}
		tight := isTightList(it.Defs)
		var contents *Doc
		if tight {
			contents = Vcat(items)
		} else {
			contents = Vsep(items)
		}
		if tight {
			return Cat(NoWrap(label), dCR, contents, dBlank)
		}
		return Cat(NoWrap(label), dBlank, contents, dBlank)
	}
	var items []*Doc
	for _, d := range defs {
		items = append(items, d)
	}
	return Cat(NoWrap(label), dCR, Vsep(items), dBlank)
}

func (w *mdWriter) rawBlock(v *RawBlock) *Doc {
	f := v.Format
	if w.variant == mdVariantPlain {
		if f == "plain" {
			return Cat(Lit(v.Text), Lit("\n"))
		}
		return dEmpty
	}
	if w.variant == mdVariantCommonmark {
		switch f {
		case "gfm", "commonmark", "commonmark_x", "markdown":
			return Cat(Lit(v.Text), Lit("\n"))
		}
	}
	if w.variant == mdVariantMarkdown {
		switch f {
		case "markdown", "markdown_github", "markdown_phpextra", "markdown_mmd", "markdown_strict":
			return Cat(Lit(v.Text), dNL)
		}
	}
	if (f == "html" || f == "html5" || f == "html4") && w.ext("raw_html") {
		return Cat(Lit(v.Text), dNL)
	}
	if (f == "latex" || f == "tex") && w.ext("raw_tex") {
		return Cat(Lit(v.Text), dNL)
	}
	if w.ext("raw_attribute") {
		return Cat(Lit("```{="+f+"}"), dCR, Lit(v.Text), dCR, Lit("```"), dNL)
	}
	return dEmpty
}

// attributes

func (w *mdWriter) attrsToMarkdown(a Attr) *Doc {
	var parts []string
	if a.ID != "" {
		parts = append(parts, "#"+a.ID)
	}
	for _, c := range a.Classes {
		parts = append(parts, "."+c)
	}
	for _, kv := range a.KVs {
		parts = append(parts, kv[0]+"=\""+escapeAttrVal(kv[1])+"\"")
	}
	return Lit("{" + strings.Join(parts, " ") + "}")
}

func escapeAttrVal(s string) string {
	var sb strings.Builder
	for _, c := range s {
		if c == '"' || c == '\\' {
			sb.WriteRune('\\')
		}
		sb.WriteRune(c)
	}
	return sb.String()
}

func (w *mdWriter) classOrAttrs(a Attr) *Doc {
	if a.ID == "" && len(a.Classes) == 1 && len(a.KVs) == 0 {
		return Lit(a.Classes[0])
	}
	return w.attrsToMarkdown(a)
}

func divNesting(bs []Block) int {
	m := 0
	for _, b := range bs {
		if d, ok := b.(*Div); ok {
			n := 1 + divNesting(d.Blocks)
			if n > m {
				m = n
			}
		}
	}
	return m
}

func (w *mdWriter) div(v *Div) *Doc {
	contents := w.blockList(v.Blocks)
	if w.ext("fenced_divs") && w.variant != mdVariantPlain {
		fence := strings.Repeat(":", 3+divNesting(v.Blocks))
		var attrDoc *Doc
		if w.variant == mdVariantCommonmark {
			attrDoc = w.attrsToMarkdown(v.Attr)
		} else {
			attrDoc = w.classOrAttrs(v.Attr)
		}
		return Cat(NoWrap(Cat(Lit(fence), dSpace, attrDoc)), dCR, Chomp(contents), dCR, Lit(fence), dBlank)
	}
	if w.ext("native_divs") || (w.ext("raw_html") && (w.variant == mdVariantCommonmark || w.ext("markdown_in_html_blocks"))) {
		return Cat(Lit(tagWithAttrsStr("div", v.Attr)), dBlank, contents, dBlank, Lit("</div>"), dBlank)
	}
	return Cat(contents, dBlank)
}

func tagWithAttrsStr(tag string, a Attr) string {
	var sb strings.Builder
	sb.WriteString("<" + tag)
	if a.ID != "" {
		sb.WriteString(" id=\"" + escHTML(a.ID, true) + "\"")
	}
	if len(a.Classes) > 0 {
		sb.WriteString(" class=\"" + escHTML(strings.Join(a.Classes, " "), true) + "\"")
	}
	for _, kv := range a.KVs {
		sb.WriteString(" " + kv[0] + "=\"" + escHTML(kv[1], true) + "\"")
	}
	sb.WriteString(">")
	return sb.String()
}

func lineBreakToSpace(xs []Inline) []Inline {
	var out []Inline
	for _, x := range xs {
		switch v := x.(type) {
		case *LineBreak:
			out = append(out, &Space{})
		case *SoftBreak:
			out = append(out, &Space{})
		case *Emph:
			out = append(out, &Emph{lineBreakToSpace(v.Inlines)})
		case *Strong:
			out = append(out, &Strong{lineBreakToSpace(v.Inlines)})
		default:
			out = append(out, x)
		}
	}
	return out
}

func (w *mdWriter) header(v *Header) *Doc {
	autoID := uniqueIdent(w.opts.Exts, v.Inlines, w.ids)
	w.ids[autoID] = true
	attr := v.Attr
	if attr.ID == autoID {
		attr.ID = ""
	}
	if !w.ext("auto_identifiers") && false {
	}
	var attrDoc *Doc = dEmpty
	if !attr.IsEmpty() && (w.ext("header_attributes") || w.ext("attributes")) && w.variant != mdVariantPlain {
		attrDoc = Cat(dSpace, w.attrsToMarkdown(attr))
	} else if attr.ID != "" && w.ext("mmd_header_identifiers") {
		attrDoc = Cat(dSpace, Lit("["+attr.ID+"]"))
	}
	contents := w.inlines(lineBreakToSpace(v.Inlines))
	if w.variant == mdVariantPlain {
		return Cat(dBlank, NoWrap(contents), dBlank)
	}
	setext := w.opts.MarkdownHeadings == "setext"
	if setext && v.Level <= 2 {
		ch := "="
		if v.Level == 2 {
			ch = "-"
		}
		c := Cat(contents, attrDoc)
		width := Render(NoWrap(c), 0)
		return Cat(dBlank, NoWrap(c), dCR, Lit(strings.Repeat(ch, max(3, strWidth(width)))), dBlank)
	}
	hashes := strings.Repeat("#", v.Level)
	return Cat(dBlank, NoWrap(Cat(Lit(hashes), dSpace, contents, attrDoc)), dBlank)
}

func (w *mdWriter) codeBlock(v *CodeBlock) *Doc {
	if !v.Attr.IsEmpty() || w.variant == mdVariantCommonmark {
		if w.variant == mdVariantMarkdown && w.ext("backtick_code_blocks") || w.variant == mdVariantCommonmark {
			fence := fenceFor(v.Text, '`')
			return Cat(Lit(fence), w.codeAttrs(v.Attr), dCR, Lit(v.Text), dCR, Lit(fence), dBlank)
		}
		if w.ext("fenced_code_blocks") {
			fence := fenceFor(v.Text, '~')
			return Cat(Lit(fence), w.codeAttrs(v.Attr), dCR, Lit(v.Text), dCR, Lit(fence), dBlank)
		}
	}
	return Cat(Nest(w.opts.TabStop, Lit(v.Text)), dBlank)
}

func fenceFor(code string, c rune) string {
	m := 0
	for _, ln := range strings.Split(code, "\n") {
		t := strings.TrimSpace(ln)
		if strings.HasPrefix(t, strings.Repeat(string(c), 3)) && strings.Trim(t, string(c)) == "" {
			if n := len([]rune(t)); n > m {
				m = n
			}
		}
	}
	if m == 0 {
		return strings.Repeat(string(c), 3)
	}
	return strings.Repeat(string(c), m+1)
}

func (w *mdWriter) codeAttrs(a Attr) *Doc {
	if a.IsEmpty() {
		return dEmpty
	}
	if w.ext("fenced_code_attributes") || w.ext("attributes") {
		return NoWrap(Cat(Lit(" "), w.classOrAttrs(a)))
	}
	if len(a.Classes) > 0 {
		return Lit(" " + a.Classes[0])
	}
	return dEmpty
}

func (w *mdWriter) figure(v *Figure) *Doc {
	// simple figure: single image with caption equal to alt
	if len(v.Blocks) == 1 {
		if pl, ok := v.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok && w.ext("implicit_figures") {
				var capIls []Inline
				if len(v.Caption.Long) == 1 {
					switch c := v.Caption.Long[0].(type) {
					case *Plain:
						capIls = c.Inlines
					case *Para:
						capIls = c.Inlines
					}
				}
				if len(v.Caption.Long) <= 1 {
					attr := img.Attr
					if v.Attr.ID != "" {
						attr.ID = v.Attr.ID
					}
					return w.block(&Para{[]Inline{&Image{attr, capIls, img.Target}}})
				}
			}
		}
	}
	// otherwise render as div
	var bs []Block
	bs = append(bs, v.Blocks...)
	bs = append(bs, v.Caption.Long...)
	return w.div(&Div{Attr{v.Attr.ID, append([]string{"figure"}, v.Attr.Classes...), v.Attr.KVs}, bs})
}

// ---------- notes & refs ----------

func (w *mdWriter) notesAndRefs() *Doc {
	var parts []*Doc
	if len(w.notes) > 0 {
		var ns []*Doc
		for i, n := range w.notes {
			ns = append(ns, w.noteDoc(i+1, n))
		}
		parts = append(parts, Vsep(ns))
	}
	if len(w.refs) > 0 {
		var rs []*Doc
		for _, r := range w.refs {
			rs = append(rs, w.refDoc(r))
		}
		parts = append(parts, Vcat(rs))
	}
	w.notes = nil
	w.refs = nil
	return Vsep(parts)
}

func (w *mdWriter) noteDoc(n int, bs []Block) *Doc {
	contents := w.blockList(bs)
	marker := "[^" + strconv.Itoa(n) + "]:"
	if w.variant == mdVariantPlain {
		marker = "[" + strconv.Itoa(n) + "]"
	}
	return Hang(w.opts.TabStop, Cat(Lit(marker), Lit(" ")), Chomp(contents))
}

func (w *mdWriter) refDoc(r mdRef) *Doc {
	label := Lit("[" + r.label + "]: " + r.target.URL)
	var d *Doc
	if r.target.Title != "" {
		d = Cat(label, Lit(" \""+escapeTitle(r.target.Title)+"\""))
	} else {
		d = label
	}
	if !r.attr.IsEmpty() && w.ext("link_attributes") {
		d = Cat(d, Lit(" "), w.attrsToMarkdown(r.attr))
	}
	return Nest(2, d)
}

func escapeTitle(s string) string {
	return strings.ReplaceAll(s, "\"", "\\\"")
}

// ---------- inlines ----------

func (w *mdWriter) inlines(xs []Inline) *Doc {
	xs = w.avoidBadWraps(xs)
	var ds []*Doc
	for i, x := range xs {
		var rest []Inline
		if i+1 < len(xs) {
			rest = xs[i+1:]
		}
		if _, ok := x.(*Link); ok {
			old := w.shortcut
			w.shortcut = shortcutable(rest)
			ds = append(ds, w.inline(x))
			w.shortcut = old
			continue
		}
		ds = append(ds, w.inline(x))
	}
	return Cat(ds...)
}

func strHead(x Inline) rune {
	switch v := x.(type) {
	case *Str:
		if v.Text != "" {
			return []rune(v.Text)[0]
		}
	case *RawInline:
		if v.Text != "" {
			return []rune(v.Text)[0]
		}
	}
	return 0
}

func shortcutable(rest []Inline) bool {
	if len(rest) == 0 {
		return true
	}
	switch rest[0].(type) {
	case *Link, *Cite:
		return false
	case *Space, *SoftBreak, *LineBreak:
		if len(rest) > 1 {
			switch v := rest[1].(type) {
			case *Link, *Cite:
				return false
			case *Str:
				if strHead(v) == '[' {
					return false
				}
			case *RawInline:
				if strHead(v) == '[' {
					return false
				}
			}
		}
		return true
	case *Str, *RawInline:
		h := strHead(rest[0])
		if h == '[' || h == '(' || h == ':' {
			return false
		}
		if r, ok := rest[0].(*RawInline); ok && strings.HasPrefix(r.Text, " [") {
			return false
		}
	}
	return true
}

func (w *mdWriter) avoidBadWraps(xs []Inline) []Inline {
	if w.variant == mdVariantPlain {
		return xs
	}
	var out []Inline
	for i := 0; i < len(xs); i++ {
		x := xs[i]
		if _, ok := x.(*Space); ok && i+1 < len(xs) {
			if s, ok := xs[i+1].(*Str); ok && s.Text != "" {
				t := s.Text
				bad := false
				first := []rune(t)[0]
				if first == '>' || first == '+' || first == '-' || first == '*' {
					// a line starting with these could become a block quote or list
					if len([]rune(t)) == 1 || first == '>' {
						bad = true
					}
				}
				if first == '#' {
					bad = true
				}
				if beginsWithOrderedListMarker(t) {
					bad = true
				}
				if bad {
					out = append(out, &Str{" "})
					continue
				}
			}
		}
		out = append(out, x)
	}
	return out
}

func (w *mdWriter) escapeText(s string) string {
	var sb strings.Builder
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		var next rune
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch {
		case c == '<':
			if w.ext("all_symbols_escapable") {
				sb.WriteString("\\<")
			} else {
				sb.WriteString("&lt;")
			}
		case c == '>':
			if w.ext("all_symbols_escapable") {
				sb.WriteString("\\>")
			} else {
				sb.WriteString("&gt;")
			}
		case c == '@' && w.ext("citations"):
			if isAlphaNumH(next) || next == '_' || next == '{' {
				sb.WriteString("\\@")
			} else {
				sb.WriteRune(c)
			}
		case c == '\\' || c == '`' || c == '*' || c == '[' || c == ']':
			sb.WriteRune('\\')
			sb.WriteRune(c)
		case c == '_':
			if w.ext("intraword_underscores") && i > 0 && isAlphaNumH(rs[i-1]) && isAlphaNumH(next) {
				sb.WriteRune(c)
			} else {
				sb.WriteString("\\_")
			}
		case c == '#' && i == 0 && w.ext("space_in_atx_header") == false:
			sb.WriteString("\\#")
		case c == '|' && w.ext("pipe_tables"):
			sb.WriteString("\\|")
		case c == '^' && w.ext("superscript"):
			sb.WriteString("\\^")
		case c == '~' && (w.ext("subscript") || w.ext("strikeout")):
			sb.WriteString("\\~")
		case c == '$' && w.ext("tex_math_dollars"):
			sb.WriteString("\\$")
		case c == '\'' && w.ext("smart"):
			sb.WriteString("\\'")
		case c == '"' && w.ext("smart"):
			sb.WriteString("\\\"")
		case c == '-' && w.ext("smart") && next == '-':
			sb.WriteString("\\-")
		case c == '.' && w.ext("smart") && next == '.' && i+2 < len(rs) && rs[i+2] == '.':
			sb.WriteString("\\...")
			i += 2
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *mdWriter) inline(x Inline) *Doc {
	switch v := x.(type) {
	case *Str:
		t := v.Text
		if w.ext("smart") && w.variant != mdVariantPlain {
			t = unsmartify(t)
		} else if w.variant == mdVariantPlain {
			t = unsmartifyPlain(t, w.ext("smart"))
		}
		if w.variant == mdVariantPlain {
			return Lit(t)
		}
		if strings.HasPrefix(t, "#") && false {
		}
		e := w.escapeText(t)
		if t == "#" || (strings.HasPrefix(t, "#") && len(t) > 0 && w.lineStartHash(t)) {
			e = "\\" + e
		}
		return Lit(e)
	case *Space:
		return dSpace
	case *SoftBreak:
		switch w.opts.Wrap {
		case WrapPreserve:
			return dCR
		}
		return dSpace
	case *LineBreak:
		if w.variant == mdVariantPlain {
			return dCR
		}
		if w.ext("escaped_line_breaks") {
			return Cat(Lit("\\"), dCR)
		}
		return Cat(Lit("  "), dCR)
	case *Emph:
		if w.variant == mdVariantPlain {
			return Cat(Lit("_"), w.inlines(v.Inlines), Lit("_"))
		}
		return Cat(Lit("*"), w.inlines(v.Inlines), Lit("*"))
	case *Underline:
		if w.variant == mdVariantPlain {
			return w.inlines(v.Inlines)
		}
		if w.ext("bracketed_spans") {
			return Cat(Lit("["), w.inlines(v.Inlines), Lit("]{.underline}"))
		}
		if w.ext("native_spans") {
			return Cat(Lit(`<span class="underline">`), w.inlines(v.Inlines), Lit("</span>"))
		}
		if w.ext("raw_html") {
			return Cat(Lit("<u>"), w.inlines(v.Inlines), Lit("</u>"))
		}
		return w.inlines(v.Inlines)
	case *Strong:
		if w.variant == mdVariantPlain {
			return w.inlines(v.Inlines)
		}
		return Cat(Lit("**"), w.inlines(v.Inlines), Lit("**"))
	case *Strikeout:
		if w.ext("strikeout") {
			return Cat(Lit("~~"), w.inlines(v.Inlines), Lit("~~"))
		}
		if w.ext("raw_html") {
			return Cat(Lit("<s>"), w.inlines(v.Inlines), Lit("</s>"))
		}
		return w.inlines(v.Inlines)
	case *Superscript:
		if w.ext("superscript") {
			return Cat(Lit("^"), w.inlines(escapeSpaces(v.Inlines)), Lit("^"))
		}
		if w.ext("raw_html") {
			return Cat(Lit("<sup>"), w.inlines(v.Inlines), Lit("</sup>"))
		}
		return w.inlines(v.Inlines)
	case *Subscript:
		if w.ext("subscript") {
			return Cat(Lit("~"), w.inlines(escapeSpaces(v.Inlines)), Lit("~"))
		}
		if w.ext("raw_html") {
			return Cat(Lit("<sub>"), w.inlines(v.Inlines), Lit("</sub>"))
		}
		return w.inlines(v.Inlines)
	case *SmallCaps:
		if w.variant == mdVariantPlain {
			return w.inlines(capitalizeInlines(v.Inlines))
		}
		if w.ext("bracketed_spans") {
			return Cat(Lit("["), w.inlines(v.Inlines), Lit("]{.smallcaps}"))
		}
		if w.ext("native_spans") {
			return Cat(Lit(`<span class="smallcaps">`), w.inlines(v.Inlines), Lit("</span>"))
		}
		return w.inlines(capitalizeInlines(v.Inlines))
	case *Quoted:
		if v.Type == SingleQuote {
			if w.ext("smart") {
				return Cat(Lit("'"), w.inlines(v.Inlines), Lit("'"))
			}
			return Cat(Lit("\u2018"), w.inlines(v.Inlines), Lit("\u2019"))
		}
		if w.ext("smart") {
			return Cat(Lit("\""), w.inlines(v.Inlines), Lit("\""))
		}
		return Cat(Lit("\u201c"), w.inlines(v.Inlines), Lit("\u201d"))
	case *Code:
		return w.code(v)
	case *Math:
		return w.math(v)
	case *RawInline:
		return w.rawInline(v)
	case *Link:
		return w.link(v)
	case *Image:
		return w.image(v)
	case *Note:
		w.notes = append(w.notes, v.Blocks)
		n := len(w.notes)
		if w.variant == mdVariantPlain {
			return Lit("[" + strconv.Itoa(n) + "]")
		}
		return Lit("[^" + strconv.Itoa(n) + "]")
	case *Span:
		return w.span(v)
	case *Cite:
		return w.cite(v)
	}
	return dEmpty
}

func (w *mdWriter) lineStartHash(t string) bool { return false }

func escapeSpaces(xs []Inline) []Inline {
	var out []Inline
	for _, x := range xs {
		switch v := x.(type) {
		case *Space:
			out = append(out, &Str{"\\ "})
		case *Str:
			out = append(out, &Str{v.Text})
		default:
			out = append(out, x)
		}
	}
	return out
}

func capitalizeInlines(xs []Inline) []Inline {
	var out []Inline
	for _, x := range xs {
		if s, ok := x.(*Str); ok {
			out = append(out, &Str{strings.ToUpper(s.Text)})
		} else {
			out = append(out, x)
		}
	}
	return out
}

func unsmartify(s string) string {
	if !strings.ContainsAny(s, "\u2019\u2018\u201c\u201d\u2013\u2014\u2026") {
		return s
	}
	r := strings.NewReplacer("\u2019", "'", "\u2026", "...", "\u2013", "--", "\u2014", "---")
	return r.Replace(s)
}

func unsmartifyPlain(s string, smart bool) string {
	return s
}

func (w *mdWriter) code(v *Code) *Doc {
	// choose backticks
	maxRun := 0
	run := 0
	for _, c := range v.Text {
		if c == '`' {
			run++
			if run > maxRun {
				maxRun = run
			}
		} else {
			run = 0
		}
	}
	ticks := strings.Repeat("`", maxRun+1)
	sp := ""
	if maxRun > 0 || strings.HasPrefix(v.Text, "`") || strings.HasSuffix(v.Text, "`") {
		sp = " "
	}
	if w.variant == mdVariantPlain {
		return Lit(v.Text)
	}
	attrs := dEmpty
	if !v.Attr.IsEmpty() && (w.ext("inline_code_attributes") || w.ext("attributes")) {
		attrs = w.attrsToMarkdown(v.Attr)
	}
	return Cat(Lit(ticks+sp+v.Text+sp+ticks), attrs)
}

func (w *mdWriter) math(v *Math) *Doc {
	if w.ext("tex_math_dollars") {
		if v.Type == InlineMath {
			return Lit("$" + v.Text + "$")
		}
		return Lit("$$" + v.Text + "$$")
	}
	if w.ext("tex_math_single_backslash") {
		if v.Type == InlineMath {
			return Lit("\\(" + v.Text + "\\)")
		}
		return Lit("\\[" + v.Text + "\\]")
	}
	if w.ext("tex_math_double_backslash") {
		if v.Type == InlineMath {
			return Lit("\\\\(" + v.Text + "\\\\)")
		}
		return Lit("\\\\[" + v.Text + "\\\\]")
	}
	ils := texToInlines(v.Text, v.Type == DisplayMath)
	if ils == nil {
		return Lit(v.Text)
	}
	return w.inlines(ils)
}

func (w *mdWriter) rawInline(v *RawInline) *Doc {
	f := v.Format
	if w.variant == mdVariantPlain {
		if f == "plain" {
			return Lit(v.Text)
		}
		return dEmpty
	}
	if w.variant == mdVariantCommonmark {
		switch f {
		case "gfm", "commonmark", "commonmark_x", "markdown":
			return Lit(v.Text)
		}
	}
	if w.variant == mdVariantMarkdown {
		switch f {
		case "markdown", "markdown_github", "markdown_phpextra", "markdown_mmd", "markdown_strict":
			return Lit(v.Text)
		}
	}
	if w.ext("raw_attribute") {
		maxRun := 0
		run := 0
		for _, c := range v.Text {
			if c == '`' {
				run++
				if run > maxRun {
					maxRun = run
				}
			} else {
				run = 0
			}
		}
		n := 1
		if maxRun > 0 {
			n = maxRun + 1
		}
		t := strings.Repeat("`", n)
		return Lit(t + v.Text + t + "{=" + f + "}")
	}
	if (f == "html" || f == "html5" || f == "html4") && w.ext("raw_html") {
		return Lit(v.Text)
	}
	if (f == "latex" || f == "tex") && w.ext("raw_tex") {
		return Lit(v.Text)
	}
	return dEmpty
}

func isURIClass(a Attr, cls string) bool {
	return a.ID == "" && len(a.KVs) == 0 && len(a.Classes) == 1 && a.Classes[0] == cls
}

func (w *mdWriter) link(v *Link) *Doc {
	if w.variant == mdVariantPlain {
		return w.inlines(v.Inlines)
	}
	txt := stringify(v.Inlines)
	src := v.Target.URL
	srcSuffix := strings.TrimPrefix(src, "mailto:")
	isAuto := (txt == src || txt == srcSuffix) && v.Target.Title == "" && isAutolinkable(src) && len(v.Inlines) == 1
	if _, ok := v.Inlines[0].(*Str); !ok && len(v.Inlines) > 0 {
		isAuto = false
	}
	if isAuto && (v.Attr.IsEmpty() || isURIClass(v.Attr, "uri") || isURIClass(v.Attr, "email")) {
		return Lit("<" + srcSuffix + ">")
	}
	linktext := w.inlines(v.Inlines)
	attrs := dEmpty
	if !v.Attr.IsEmpty() && w.ext("link_attributes") {
		attrs = w.attrsToMarkdown(v.Attr)
	}
	if w.opts.ReferenceLinks {
		label := w.getReference(v.Inlines, v.Target, v.Attr)
		first := Cat(Lit("["), linktext, Lit("]"))
		if strings.EqualFold(normKeyText(Render(linktext, 0)), normKeyText(label)) {
			if w.shortcut && w.ext("shortcut_reference_links") {
				return first
			}
			return Cat(first, Lit("[]"))
		}
		return Cat(first, Lit("["+label+"]"))
	}
	tit := ""
	if v.Target.Title != "" {
		tit = " \"" + escapeTitle(v.Target.Title) + "\""
	}
	return Cat(Lit("["), linktext, Lit("]("+escapeLinkURL(src)+tit+")"), attrs)
}

func normKeyText(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), " "))
}

func escapeLinkURL(s string) string {
	if strings.ContainsAny(s, " ()") && !balancedParens(s) || strings.Contains(s, " ") {
		return "<" + s + ">"
	}
	return s
}

func balancedParens(s string) bool {
	d := 0
	for _, c := range s {
		if c == '(' {
			d++
		} else if c == ')' {
			d--
			if d < 0 {
				return false
			}
		}
	}
	return d == 0
}

func isAutolinkable(src string) bool {
	i := strings.Index(src, ":")
	if i <= 0 {
		return false
	}
	return uriSchemes[strings.ToLower(src[:i])]
}

func (w *mdWriter) getReference(label []Inline, t Target, a Attr) string {
	for _, r := range w.refs {
		if r.target == t && attrEqual2(r.attr, a) {
			return r.label
		}
	}
	lbl := Render(w.inlines(label), 0)
	// make unique
	base := lbl
	used := func(l string) bool {
		for _, r := range w.refs {
			if normKeyText(r.label) == normKeyText(l) {
				return true
			}
		}
		return false
	}
	if used(base) {
		i := 1
		for used(strconv.Itoa(i)) {
			i++
		}
		lbl = strconv.Itoa(i)
	}
	w.refs = append(w.refs, mdRef{lbl, t, a})
	return lbl
}

func attrEqual2(a, b Attr) bool {
	return a.ID == b.ID && stringsEqual(a.Classes, b.Classes) && kvsEqual(a.KVs, b.KVs)
}

func (w *mdWriter) image(v *Image) *Doc {
	if w.variant == mdVariantPlain {
		return Cat(Lit("["), w.inlines(v.Inlines), Lit("]"))
	}
	alt := w.inlines(v.Inlines)
	attrs := dEmpty
	if !v.Attr.IsEmpty() && w.ext("link_attributes") {
		attrs = w.attrsToMarkdown(v.Attr)
	}
	if w.opts.ReferenceLinks {
		label := w.getReference(v.Inlines, v.Target, v.Attr)
		first := Cat(Lit("!["), alt, Lit("]"))
		if normKeyText(Render(alt, 0)) == normKeyText(label) {
			if w.shortcut && w.ext("shortcut_reference_links") {
				return first
			}
			return Cat(first, Lit("[]"))
		}
		return Cat(first, Lit("["+label+"]"))
	}
	tit := ""
	if v.Target.Title != "" {
		tit = " \"" + escapeTitle(v.Target.Title) + "\""
	}
	return Cat(Lit("!["), alt, Lit("]("+escapeLinkURL(v.Target.URL)+tit+")"), attrs)
}

func (w *mdWriter) span(v *Span) *Doc {
	c := w.inlines(v.Inlines)
	if w.variant == mdVariantPlain {
		return c
	}
	if w.ext("bracketed_spans") {
		if v.Attr.IsEmpty() {
			return Cat(Lit("["), c, Lit("]{}"))
		}
		return Cat(Lit("["), c, Lit("]"), w.attrsToMarkdown(v.Attr))
	}
	if w.ext("native_spans") || w.ext("raw_html") {
		if v.Attr.IsEmpty() {
			return c
		}
		return Cat(Lit(tagWithAttrsStr("span", v.Attr)), c, Lit("</span>"))
	}
	return c
}

func (w *mdWriter) cite(v *Cite) *Doc {
	if !w.ext("citations") || w.variant == mdVariantPlain {
		return w.inlines(v.Inlines)
	}
	if len(v.Citations) == 0 {
		return w.inlines(v.Inlines)
	}
	cs := v.Citations
	if cs[0].Mode == AuthorInText {
		main := Lit("@" + cs[0].ID)
		var rest []*Doc
		if len(cs[0].Suffix) > 0 {
			rest = append(rest, w.inlines(cs[0].Suffix))
		}
		_ = rest
		suffs := w.inlines(cs[0].Suffix)
		restCites := cs[1:]
		var d *Doc
		if len(cs[0].Suffix) > 0 {
			d = Cat(main, dSpace, Lit("["), suffs, Lit("]"))
		} else {
			d = main
		}
		if len(restCites) > 0 {
			d = Cat(d, dSpace, Lit("["), w.citeList(restCites), Lit("]"))
		}
		return d
	}
	return Cat(Lit("["), w.citeList(cs), Lit("]"))
}

func (w *mdWriter) citeList(cs []Citation) *Doc {
	var ds []*Doc
	for i, c := range cs {
		if i > 0 {
			ds = append(ds, Lit(";"), dSpace)
		}
		var parts []*Doc
		if len(c.Prefix) > 0 {
			parts = append(parts, w.inlines(c.Prefix), dSpace)
		}
		key := "@" + c.ID
		if c.Mode == SuppressAuthor {
			key = "-" + key
		}
		parts = append(parts, Lit(key))
		if len(c.Suffix) > 0 {
			parts = append(parts, w.inlines(c.Suffix))
		}
		ds = append(ds, Cat(parts...))
	}
	return Cat(ds...)
}

func isPunctOrSpace(r rune) bool { return unicode.IsPunct(r) || unicode.IsSpace(r) }
