package main

import (
	"math"
	"sort"
	"strings"
)

// ---------- YAML metadata ----------

func (w *mdWriter) metaToYamlDoc(m Meta) *Doc {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var lines []*Doc
	for _, k := range keys {
		if d := w.yamlKV(k, m[k]); !d.IsEmpty() {
			lines = append(lines, d)
		}
	}
	return Vcat(lines)
}

func yamlKey(k string) string {
	if strings.ContainsAny(k, ":#") || strings.HasPrefix(k, "-") {
		return "'" + strings.ReplaceAll(k, "'", "''") + "'"
	}
	return k
}

func (w *mdWriter) yamlKV(k string, v MetaValue) *Doc {
	key := yamlKey(k)
	switch x := v.(type) {
	case *MetaList:
		if len(x.Items) == 0 {
			return dEmpty
		}
		return Above(Lit(key+":"), w.yamlVal(v))
	case *MetaMap:
		if len(x.Map) == 0 {
			return Lit(key + ": {}")
		}
		return Above(Lit(key+":"), Nest(2, w.yamlVal(v)))
	}
	val := w.yamlVal(v)
	if val.IsEmpty() {
		return dEmpty
	}
	return Cat(Lit(key+":"), dSpace, Hang(2, dEmpty, val))
}

func (w *mdWriter) yamlVal(v MetaValue) *Doc {
	cols := w.opts.Columns
	if w.opts.Wrap != WrapAuto {
		cols = 0
	}
	switch x := v.(type) {
	case *MetaList:
		var ds []*Doc
		for _, it := range x.Items {
			ds = append(ds, Hang(2, Lit("- "), w.yamlVal(it)))
		}
		return Vcat(ds)
	case *MetaMap:
		return w.metaToYamlDoc(Meta(x.Map))
	case *MetaBool:
		if x.Bool {
			return Lit("true")
		}
		return Lit("false")
	case *MetaString:
		return w.yamlScalar(Render(w.inlines(textToInlines(x.Text)), cols))
	case *MetaInlines:
		ww := newMdWriter(w.opts, w.variant)
		return w.yamlScalar(Render(ww.inlines(x.Inlines), cols))
	case *MetaBlocks:
		ww := newMdWriter(w.opts, w.variant)
		s := strings.TrimRight(Render(ww.blockList(x.Blocks), cols), "\n")
		if s == "" {
			return dEmpty
		}
		return Cat(Lit("|"), dCR, Nest(2, Lit(s)))
	}
	return dEmpty
}

func isYamlPunct(c rune) bool {
	return strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", c)
}

func (w *mdWriter) yamlScalar(s string) *Doc {
	if s == "" {
		return dEmpty
	}
	if strings.Contains(s, "\n") {
		return Cat(Lit("|"), dCR, Nest(2, Lit(s)))
	}
	needs := strings.ContainsAny(s, "#:")
	if !needs {
		if isYamlPunct([]rune(s)[0]) {
			needs = true
		}
	}
	if needs {
		e := strings.ReplaceAll(s, "\\", "\\\\")
		e = strings.ReplaceAll(e, "\"", "\\\"")
		return Lit("\"" + e + "\"")
	}
	return Lit(s)
}

func (w *mdWriter) yamlMeta(m Meta) string {
	d := Cat(Lit("---"), dCR, w.metaToYamlDoc(m), dCR, Lit("---"))
	return Render(d, 0)
}

func (w *mdWriter) titleBlock(doc *Pandoc, cols int) (string, bool) {
	m := doc.Meta
	render := func(ils []Inline) string {
		ww := newMdWriter(w.opts, w.variant)
		return Render(ww.inlines(ils), cols)
	}
	title := render(lookupMetaInlines(m, "title"))
	var auths []string
	for _, a := range docAuthors(m) {
		auths = append(auths, render(a))
	}
	date := render(lookupMetaInlines(m, "date"))
	if w.variant == mdVariantPlain {
		s := title + "\n"
		if len(auths) > 0 {
			s += strings.Join(auths, "; ") + "\n"
		}
		if date != "" {
			s += date + "\n"
		}
		return s, true
	}
	if w.ext("yaml_metadata_block") {
		if len(m) == 0 {
			return "", false
		}
		return w.yamlMeta(m), true
	}
	_, ht := m["title"]
	_, ha := m["author"]
	_, hd := m["date"]
	if !ht && !ha && !hd {
		return "", false
	}
	if w.ext("pandoc_title_block") {
		var sb strings.Builder
		sb.WriteString("% " + strings.ReplaceAll(title, "\n", "\n  ") + "\n")
		sb.WriteString("% " + strings.Join(auths, "\n  ") + "\n")
		sb.WriteString("% " + date)
		return strings.TrimRight(sb.String(), " "), true
	}
	return "", false
}

// ---------- tables ----------

type legacyTable struct {
	caption []Inline
	capBlocks []Block
	aligns  []Alignment
	widths  []float64
	headers [][]Block
	rows    [][][]Block
}

func expandCells(r Row, ncols int) [][]Block {
	var out [][]Block
	for _, c := range r.Cells {
		out = append(out, c.Blocks)
		for i := 1; i < c.ColSpan; i++ {
			out = append(out, nil)
		}
	}
	return out
}

func toLegacyTable(t *Table) legacyTable {
	var lt legacyTable
	if len(t.Caption.Long) > 0 {
		lt.capBlocks = t.Caption.Long
		lt.caption = blocksToInlines(t.Caption.Long)
	}
	for _, cs := range t.ColSpecs {
		lt.aligns = append(lt.aligns, cs.Align)
		if cs.HasWidth {
			lt.widths = append(lt.widths, cs.Width)
		} else {
			lt.widths = append(lt.widths, 0)
		}
	}
	n := len(t.ColSpecs)
	var bodyRows []Row
	if len(t.Head.Rows) > 0 {
		lt.headers = expandCells(t.Head.Rows[len(t.Head.Rows)-1], n)
		bodyRows = append(bodyRows, t.Head.Rows[:len(t.Head.Rows)-1]...)
		bodyRows = nil
	}
	for _, b := range t.Bodies {
		bodyRows = append(bodyRows, b.Head...)
		bodyRows = append(bodyRows, b.Body...)
	}
	bodyRows = append(bodyRows, t.Foot.Rows...)
	for _, r := range bodyRows {
		lt.rows = append(lt.rows, expandCells(r, n))
	}
	return lt
}

func blocksToInlines(bs []Block) []Inline {
	var out []Inline
	for i, b := range bs {
		if i > 0 {
			out = append(out, &Space{})
		}
		switch v := b.(type) {
		case *Plain:
			out = append(out, v.Inlines...)
		case *Para:
			out = append(out, v.Inlines...)
		case *LineBlock:
			for j, l := range v.Lines {
				if j > 0 {
					out = append(out, &LineBreak{})
				}
				out = append(out, l...)
			}
		case *CodeBlock:
			out = append(out, &Str{v.Text})
		default:
			out = append(out, &Str{stringifyBlock(b)})
		}
	}
	return out
}

func hasLineBreak(ils []Inline) bool {
	found := false
	walkInlines(ils, func(x Inline) {
		if _, ok := x.(*LineBreak); ok {
			found = true
		}
	})
	return found
}

func onlySimpleTableCells(rows [][][]Block) bool {
	for _, r := range rows {
		for _, c := range r {
			switch len(c) {
			case 0:
				continue
			case 1:
				switch v := c[0].(type) {
				case *Plain:
					if hasLineBreak(v.Inlines) {
						return false
					}
				case *Para:
					if hasLineBreak(v.Inlines) {
						return false
					}
				default:
					return false
				}
			default:
				return false
			}
		}
	}
	return true
}

func allEmptyCells(cells [][]Block) bool {
	for _, c := range cells {
		if len(c) > 0 {
			return false
		}
	}
	return true
}

func (w *mdWriter) cellDocs(cells [][]Block, n int) []*Doc {
	var out []*Doc
	old := w.inList
	for _, c := range cells {
		out = append(out, w.blockList(c))
	}
	w.inList = old
	for len(out) < n {
		out = append(out, dEmpty)
	}
	return out
}

func (w *mdWriter) table(t *Table) *Doc {
	lt := toLegacyTable(t)
	numcols := len(lt.aligns)
	for _, r := range append([][][]Block{lt.headers}, lt.rows...) {
		if len(r) > numcols {
			numcols = len(r)
		}
	}
	for len(lt.aligns) < numcols {
		lt.aligns = append(lt.aligns, AlignDefault)
	}
	for len(lt.widths) < numcols {
		lt.widths = append(lt.widths, 0)
	}
	var capDoc *Doc
	if len(lt.caption) == 0 {
		capDoc = dBlank
	} else {
		c := w.inlines(lt.caption)
		if !t.Attr.IsEmpty() && w.ext("table_attributes") {
			c = Cat(c, dSpace, w.attrsToMarkdown(t.Attr))
		}
		if w.ext("table_captions") {
			capDoc = Cat(dBlank, Lit(": "), c, dBlank)
		} else {
			capDoc = Cat(dBlank, c, dBlank)
		}
	}
	allRows := append([][][]Block{lt.headers}, lt.rows...)
	simpleCells := onlySimpleTableCells(allRows)
	zeroWidths := true
	for _, x := range lt.widths {
		if x != 0 {
			zeroWidths = false
		}
	}
	isSimple := simpleCells && zeroWidths
	hasBlocks := false
	for _, r := range allRows {
		for _, c := range r {
			for _, b := range c {
				if _, ok := b.(*Plain); !ok {
					hasBlocks = true
				}
			}
		}
	}
	headless := allEmptyCells(lt.headers)
	old := w.inList
	w.inList = true
	defer func() { w.inList = old }()
	var tbl *Doc
	nest := false
	switch {
	case isSimple && w.ext("simple_tables"):
		tbl = w.pandocTable(false, headless, lt.aligns, lt.widths, w.cellDocs(lt.headers, numcols), w.rowDocs(lt.rows, numcols))
		nest = true
	case isSimple && w.ext("pipe_tables"):
		tbl = w.pipeTable(headless, lt.aligns, lt.widths, w.cellDocs(lt.headers, numcols), w.rowDocs(lt.rows, numcols))
	case !hasBlocks && w.ext("multiline_tables"):
		tbl = w.pandocTable(true, headless, lt.aligns, lt.widths, w.cellDocs(lt.headers, numcols), w.rowDocs(lt.rows, numcols))
		nest = true
	case w.ext("grid_tables") && w.opts.Columns >= 8*numcols:
		tbl = gridTable(w.opts, func(o *WriterOptions, bs []Block) *Doc {
			ww := newMdWriter(o, w.variant)
			ww.inList = true
			return ww.blockList(bs)
		}, headless, lt.aligns, lt.widths, lt.headers, lt.rows)
	case simpleCells && w.ext("pipe_tables"):
		tbl = w.pipeTable(headless, lt.aligns, lt.widths, w.cellDocs(lt.headers, numcols), w.rowDocs(lt.rows, numcols))
	case w.ext("raw_html"):
		o := *w.opts
		o.Standalone = false
		tbl = Lit(strings.TrimRight(writeHTML(&Pandoc{Meta{}, []Block{t}}, &o, true), "\n"))
	default:
		tbl = Lit("[TABLE]")
	}
	body := Above(tbl, capDoc)
	if nest {
		body = Nest(2, body)
	}
	return Cat(body, dBlank)
}

func (w *mdWriter) rowDocs(rows [][][]Block, n int) [][]*Doc {
	var out [][]*Doc
	for _, r := range rows {
		out = append(out, w.cellDocs(r, n))
	}
	return out
}

func alignBlock(a Alignment, width int, d *Doc) *Doc {
	switch a {
	case AlignCenter:
		return CBlock(width, d)
	case AlignRight:
		return RBlock(width, d)
	}
	return LBlock(width, d)
}

func (w *mdWriter) pandocTable(multiline, headless bool, aligns []Alignment, widths []float64, heads []*Doc, rows [][]*Doc) *Doc {
	isSimple := true
	for _, x := range widths {
		if x != 0 {
			isSimple = false
		}
	}
	ncols := len(aligns)
	columns := make([][]*Doc, ncols)
	for i := 0; i < ncols; i++ {
		if i < len(heads) {
			columns[i] = append(columns[i], heads[i])
		}
		for _, r := range rows {
			if i < len(r) {
				columns[i] = append(columns[i], r[i])
			}
		}
	}
	numChars := func(col []*Doc) int {
		m := 0
		for _, d := range col {
			if o := d.Offset(); o > m {
				m = o
			}
		}
		return m + 2
	}
	minNumChars := func(col []*Doc) int {
		m := 0
		for _, d := range col {
			if o := d.MinOffset(); o > m {
				m = o
			}
		}
		return m + 2
	}
	widthsInChars := make([]int, ncols)
	for i := range columns {
		if isSimple {
			widthsInChars[i] = numChars(columns[i])
		} else {
			rel := int(math.Floor(float64(w.opts.Columns-1) * widths[i]))
			var alt int
			if w.opts.Wrap == WrapAuto {
				alt = minNumChars(columns[i])
			} else {
				alt = numChars(columns[i])
			}
			if alt > rel {
				rel = alt
			}
			widthsInChars[i] = rel
		}
	}
	makeRow := func(cells []*Doc) *Doc {
		var ds []*Doc
		for i := 0; i < ncols; i++ {
			if i > 0 {
				ds = append(ds, LBlock(1, Lit(" ")))
			}
			var c *Doc = dEmpty
			if i < len(cells) {
				c = cells[i]
			}
			ds = append(ds, alignBlock(aligns[i], widthsInChars[i], c))
		}
		return Cat(ds...)
	}
	var rowDocs []*Doc
	for _, r := range rows {
		rowDocs = append(rowDocs, makeRow(r))
	}
	head := makeRow(heads)
	var ul []string
	total := 0
	for _, wd := range widthsInChars {
		ul = append(ul, strings.Repeat("-", wd))
		total += wd
	}
	underline := Lit(strings.Join(ul, " "))
	var border *Doc
	if multiline {
		border = Lit(strings.Repeat("-", total+len(widthsInChars)-1))
	} else if headless {
		border = underline
	} else {
		border = dEmpty
	}
	var head2 *Doc
	if headless {
		head2 = dEmpty
	} else {
		head2 = Cat(border, dCR, head)
	}
	var body *Doc
	if multiline {
		body = Vsep(rowDocs)
		if len(rowDocs) < 2 {
			body = Cat(body, dBlank)
		}
	} else {
		body = Vcat(rowDocs)
	}
	var bottom *Doc
	if headless {
		bottom = underline
	} else {
		bottom = border
	}
	return Above(Above(Above(head2, underline), body), bottom)
}

func (w *mdWriter) pipeTable(headless bool, aligns []Alignment, widths []float64, heads []*Doc, rows [][]*Doc) *Doc {
	ncols := len(aligns)
	contentWidths := make([]int, ncols)
	for i := 0; i < ncols; i++ {
		m := 3
		if i < len(heads) {
			if o := heads[i].Offset(); o > m {
				m = o
			}
		}
		for _, r := range rows {
			if i < len(r) {
				if o := r[i].Offset(); o > m {
					m = o
				}
			}
		}
		contentWidths[i] = m
	}
	colwidth := w.opts.Columns
	maxwidth := 0
	sumW := 0.0
	for i, c := range contentWidths {
		maxwidth += c
		sumW += widths[i]
	}
	pipeWidths := contentWidths
	if maxwidth+3*ncols+1 > colwidth && sumW > 0 {
		pipeWidths = make([]int, ncols)
		for i := range widths {
			pipeWidths[i] = int(math.Floor(widths[i] * float64(colwidth)))
		}
	}
	_ = pipeWidths
	blockFor := func(a Alignment, x int, y *Doc) *Doc {
		switch a {
		case AlignCenter:
			return Cat(CBlock(x+2, Cat(Lit(" "), y, Lit(" "))), LBlock(0, dEmpty))
		case AlignRight:
			return Cat(RBlock(x+2, Cat(y, Lit(" "))), LBlock(0, dEmpty))
		}
		return Cat(LBlock(x+2, Cat(Lit(" "), y)), LBlock(0, dEmpty))
	}
	torow := func(cs []*Doc) *Doc {
		var ds []*Doc
		ds = append(ds, Lit("|"))
		for i := 0; i < ncols; i++ {
			if i > 0 {
				ds = append(ds, Lit("|"))
			}
			var c *Doc = dEmpty
			if i < len(cs) {
				c = Chomp(cs[i])
			}
			ds = append(ds, blockFor(aligns[i], contentWidths[i], c))
		}
		ds = append(ds, Lit("|"))
		return NoWrap(Cat(ds...))
	}
	toborder := func(a Alignment, wd int) string {
		switch a {
		case AlignLeft:
			return ":" + strings.Repeat("-", wd+1)
		case AlignCenter:
			return ":" + strings.Repeat("-", wd) + ":"
		case AlignRight:
			return strings.Repeat("-", wd+1) + ":"
		}
		return strings.Repeat("-", wd+2)
	}
	var header *Doc
	if headless {
		header = torow(make([]*Doc, ncols))
	} else {
		header = torow(heads)
	}
	var bs []string
	for i := 0; i < ncols; i++ {
		bs = append(bs, toborder(aligns[i], contentWidths[i]))
	}
	border := Lit("|" + strings.Join(bs, "|") + "|")
	var rds []*Doc
	for _, r := range rows {
		rds = append(rds, torow(r))
	}
	return Above(Above(header, border), Vcat(rds))
}

// gridTable shared by markdown and rst
func gridTable(opts *WriterOptions, blocksToDoc func(*WriterOptions, []Block) *Doc, headless bool, aligns []Alignment, widths []float64, headers [][]Block, rows [][][]Block) *Doc {
	numcols := len(aligns)
	if len(widths) > numcols {
		numcols = len(widths)
	}
	for _, r := range append([][][]Block{headers}, rows...) {
		if len(r) > numcols {
			numcols = len(r)
		}
	}
	for len(aligns) < numcols {
		aligns = append(aligns, AlignDefault)
	}
	for len(widths) < numcols {
		widths = append(widths, 0)
	}
	pad := func(r [][]Block) [][]Block {
		for len(r) < numcols {
			r = append(r, nil)
		}
		return r
	}
	headers = pad(headers)
	for i := range rows {
		rows[i] = pad(rows[i])
	}
	official := func(ws []float64) []int {
		out := make([]int, len(ws))
		for i, x := range ws {
			v := int(math.Floor(float64(opts.Columns)*x)) - 3
			if v < 1 {
				v = 1
			}
			out[i] = v
		}
		return out
	}
	renderWith := func(wic []int) ([]*Doc, [][]*Doc) {
		var hs []*Doc
		for i, h := range headers {
			o := *opts
			if wic[i]-2 < o.Columns {
				o.Columns = wic[i] - 2
			}
			hs = append(hs, blocksToDoc(&o, h))
		}
		var rs [][]*Doc
		for _, r := range rows {
			var cs []*Doc
			for i, c := range r {
				o := *opts
				if wic[i]-2 < o.Columns {
					o.Columns = wic[i] - 2
				}
				cs = append(cs, blocksToDoc(&o, c))
			}
			rs = append(rs, cs)
		}
		return hs, rs
	}
	full := func(ws []float64) ([]int, []*Doc, [][]*Doc) {
		var hs []*Doc
		for _, h := range headers {
			hs = append(hs, blocksToDoc(opts, h))
		}
		var rs [][]*Doc
		for _, r := range rows {
			var cs []*Doc
			for _, c := range r {
				cs = append(cs, blocksToDoc(opts, c))
			}
			rs = append(rs, cs)
		}
		off := official(ws)
		wic := make([]int, numcols)
		for i := 0; i < numcols; i++ {
			m := hs[i].Offset()
			for _, r := range rs {
				if o := r[i].Offset(); o > m {
					m = o
				}
			}
			if off[i] > m {
				m = off[i]
			}
			wic[i] = m
		}
		return wic, hs, rs
	}
	var wic []int
	var hs []*Doc
	var rs [][]*Doc
	zero := true
	for _, x := range widths {
		if x != 0 {
			zero = false
		}
	}
	if opts.Wrap == WrapNone {
		wic, hs, rs = full(widths)
	} else if zero {
		wic, hs, rs = full(widths)
		tot := 0
		for _, x := range wic {
			tot += x
		}
		if tot > opts.Columns {
			evenCols := (opts.Columns-1)/numcols - 3
			if evenCols < 5 {
				evenCols = 5
			}
			for i := range wic {
				if wic[i] > evenCols {
					wic[i] = evenCols
				}
			}
			hs, rs = renderWith(wic)
		}
	} else {
		wic = official(widths)
		hs, rs = renderWith(wic)
	}
	hpipe := func(blocks []*Doc) *Doc {
		var ds []*Doc
		ds = append(ds, VFill("| "))
		for i, b := range blocks {
			if i > 0 {
				ds = append(ds, VFill(" | "))
			}
			ds = append(ds, b)
		}
		ds = append(ds, VFill(" |"))
		return Cat(ds...)
	}
	makeRow := func(cells []*Doc) *Doc {
		var bs []*Doc
		for i, c := range cells {
			bs = append(bs, LBlock(wic[i], Chomp(c)))
		}
		return hpipe(bs)
	}
	borderpart := func(ch byte, a Alignment, wd int) string {
		if wd < 1 {
			wd = 1
		}
		l := string(ch)
		r := string(ch)
		if a == AlignLeft || a == AlignCenter {
			l = ":"
		}
		if a == AlignRight || a == AlignCenter {
			r = ":"
		}
		return l + strings.Repeat(string(ch), wd) + r
	}
	border := func(ch byte, as []Alignment) *Doc {
		var parts []string
		for i := 0; i < numcols; i++ {
			a := AlignDefault
			if as != nil {
				a = as[i]
			}
			parts = append(parts, borderpart(ch, a, wic[i]))
		}
		return Lit("+" + strings.Join(parts, "+") + "+")
	}
	var bodyParts []*Doc
	for i, r := range rs {
		if i > 0 {
			bodyParts = append(bodyParts, border('-', nil))
		}
		bodyParts = append(bodyParts, makeRow(r))
	}
	body := Vcat(bodyParts)
	if headless {
		return Vcat([]*Doc{border('-', aligns), body, border('-', nil)})
	}
	return Vcat([]*Doc{border('-', nil), makeRow(hs), border('=', aligns), body, border('-', nil)})
}
