	usesUrl     bool
	usesSubfig  bool
	usesSvg     bool
	csquotes    bool
	usesCode    bool
	verbInNote  bool
	hasLang     bool
	langs       map[string]bool
	zwnj        bool
	incremental bool
	hasChapters bool
	tightList   bool
	internalLinks map[string]bool
}

func (w *latexWriter) ext(n string) bool { return w.opts.Exts.On(n) }

func (w *latexWriter) stringToLaTeX(ctx int, s string) string {
	ligatures := w.ext("smart") && ctx == ctxText
	isURL := ctx == ctxURL
	rs := []rune(s)
	var sb strings.Builder
	for i := 0; i < len(rs); i++ {
		x := rs[i]
		var next rune = -1
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		emitcseq := func(cs string) {
			switch {
			case next >= 0 && unicode.IsLetter(next) && ctx == ctxText:
				sb.WriteString(cs + " ")
			case next >= 0 && isSpaceH(next):
				sb.WriteString(cs + "{}")
			case next >= 0 && ctx == ctxText:
				sb.WriteString(cs)
			default:
				sb.WriteString(cs + "{}")
			}
		}
		emitquote := func(cs string) {
			sb.WriteString(cs)
			if next == '`' || next == '\'' {
				sb.WriteString("\\,")
			}
		}
		switch {
		case x == '?' && ligatures && next == '`':
			sb.WriteString("?{}")
		case x == '!' && ligatures && next == '`':
			sb.WriteString("!{}")
		case x == '{':
			sb.WriteString("\\{")
		case x == '}':
			sb.WriteString("\\}")
		case x == '`' && ctx == ctxCode:
			emitcseq("\\textasciigrave")
		case x == '$' && !isURL:
			sb.WriteString("\\$")
		case x == '%':
			sb.WriteString("\\%")
		case x == '&' && !isURL:
			sb.WriteString("\\&")
		case x == '_' && !isURL:
			sb.WriteString("\\_")
		case x == '#':
			sb.WriteString("\\#")
		case x == '-' && !isURL:
			if next == '-' {
				sb.WriteString("-\\/")
			} else {
				sb.WriteRune('-')
			}
		case x == '~' && !isURL:
			emitcseq("\\textasciitilde")
		case x == '^':
			sb.WriteString("\\^{}")
		case x == '\\':
			if isURL {
				sb.WriteRune('/')
			} else {
				emitcseq("\\textbackslash")
			}
		case x == '|' && !isURL:
			emitcseq("\\textbar")
		case x == '<':
			emitcseq("\\textless")
		case x == '>':
			emitcseq("\\textgreater")
		case x == '[':
			sb.WriteString("{[}")
		case x == ']':
			sb.WriteString("{]}")
		case x == '\'' && ctx == ctxCode:
			emitcseq("\\textquotesingle")
		case x == '\u00a0':
			sb.WriteString("~")
		case x == '\u200b':
			sb.WriteString("\\hspace{0pt}")
		case x == '\u202f':
			sb.WriteString("\\,")
		case x == '\u2026' && ligatures:
			emitcseq("\\ldots")
		case x == '\u2018' && ligatures:
			emitquote("`")
		case x == '\u2019' && ligatures:
			emitquote("'")
		case x == '\u201c' && ligatures:
			emitquote("``")
		case x == '\u201d' && ligatures:
			emitquote("''")
		case x == '\u2014' && ligatures:
			sb.WriteString("---")
		case x == '\u2013' && ligatures:
			sb.WriteString("--")
		case x == '\u200c':
			w.zwnj = true
			sb.WriteRune(x)
		default:
			sb.WriteRune(x)
		}
	}
	return sb.String()
}

func toLabel(s string) string {
	var sb strings.Builder
	for _, c := range s {
		if c < 128 && (isAlphaNumH(c) || strings.ContainsRune("_-+=:;.", c)) {
			sb.WriteRune(c)
		} else if c >= 128 && unicode.IsLetter(c) {
			sb.WriteRune(c)
		} else {
			sb.WriteString(fmt.Sprintf("ux%x", c))
		}
	}
	return sb.String()
}

func braces(d *Doc) *Doc { return Cat(Lit("{"), d, Lit("}")) }

func (w *latexWriter) blocks(bs []Block) *Doc {
	var ds []*Doc
	for i, b := range bs {
		_ = i
		ds = append(ds, w.block(b))
	}
	return Vcat(filterEmpty(ds))
}

func filterEmpty(ds []*Doc) []*Doc {
	var out []*Doc
	for _, d := range ds {
		if !d.IsEmpty() {
			out = append(out, d)
		}
	}
	return out
}

func (w *latexWriter) inlines(xs []Inline) *Doc {
	var ds []*Doc
	for i, x := range xs {
		// special: Str followed by Code etc handled in Str
		_ = i
		ds = append(ds, w.inline(x))
	}
	return Cat(ds...)
}

func (w *latexWriter) hypertarget(id string) *Doc {
	if id == "" {
		return dEmpty
	}
	return Lit("\\protect\\phantomsection\\label{" + toLabel(id) + "}")
}

func (w *latexWriter) block(b Block) *Doc {
	switch v := b.(type) {
	case *Plain:
		return w.inlines(v.Inlines)
	case *Para:
		return Cat(w.inlines(v.Inlines), dBlank)
	case *Div:
		return w.div(v)
	case *LineBlock:
		var ils []Inline
		for i, l := range v.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return w.block(&Para{ils})
	case *BlockQuote:
		c := w.blocks(v.Blocks)
		return Cat(Lit("\\begin{quote}"), dCR, c, dCR, Lit("\\end{quote}"), dBlank)
	case *CodeBlock:
		return w.codeBlock(v)
	case *RawBlock:
		if v.Format == "latex" || v.Format == "tex" {
			return Cat(Lit(v.Text), dBlank)
		}
		return dEmpty
	case *BulletList:
		return w.bulletList(v)
	case *OrderedList:
		return w.orderedList(v)
	case *DefinitionList:
		return w.defList(v)
	case *HorizontalRule:
		return Cat(Lit("\\begin{center}\\rule{0.5\\linewidth}{0.5pt}\\end{center}"), dBlank)
	case *Header:
		return w.header(v)
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

var langMap = map[string]string{"de": "ngerman", "de-DE": "ngerman", "de-AT": "naustrian", "de-CH": "nswissgerman",
	"en": "english", "en-US": "american", "en-GB": "british", "en-AU": "australian", "en-CA": "canadian", "en-NZ": "newzealand",
