	"nb": "norsk", "nn": "nynorsk", "no": "norsk", "el": "greek", "he": "hebrew", "ar": "arabic", "ja": "japanese",
	"zh": "chinese", "ko": "korean", "tr": "turkish", "hu": "magyar", "uk": "ukrainian", "la": "latin", "ca": "catalan",
	"eu": "basque", "gl": "galician", "ro": "romanian", "hr": "croatian", "sk": "slovak", "sl": "slovenian", "sr": "serbian",
	"bg": "bulgarian", "et": "estonian", "lv": "latvian", "lt": "lithuanian", "is": "icelandic", "ga": "irish", "cy": "welsh",
	"hi": "hindi", "th": "thai", "vi": "vietnamese", "id": "indonesian", "ms": "malay", "fa": "persian", "ur": "urdu"}

func babelLang(l string) string {
	if v, ok := langMap[l]; ok {
		return v
	}
	if i := strings.IndexByte(l, '-'); i > 0 {
		if v, ok := langMap[l[:i]]; ok {
			return v
		}
	}
	return ""
}

func (w *latexWriter) div(v *Div) *Doc {
	contents := w.blocks(v.Blocks)
	anchor := w.hypertarget(v.Attr.ID)
	if lang, ok := v.Attr.Get("lang"); ok {
		if bl := babelLang(lang); bl != "" {
			w.hasLang = true
			contents = Cat(Lit("\\begin{otherlanguage}{"+bl+"}"), dBlank, contents, dBlank, Lit("\\end{otherlanguage}"))
		}
	}
	if dir, ok := v.Attr.Get("dir"); ok {
		if dir == "rtl" {
			contents = Cat(Lit("\\begin{RTL}"), dCR, contents, dCR, Lit("\\end{RTL}"))
		} else if dir == "ltr" {
			contents = Cat(Lit("\\begin{LTR}"), dCR, contents, dCR, Lit("\\end{LTR}"))
		}
	}
	if anchor.IsEmpty() {
		return Cat(contents, dBlank)
	}
	return Cat(Above(anchor, contents), dBlank)
}

func (w *latexWriter) codeBlock(v *CodeBlock) *Doc {
	lang := ""
	for _, c := range v.Attr.Classes {
		if l := canonicalLang(c); l != "" {
			lang = l
			break
		}
	}
	anchor := dEmpty
	if v.Attr.ID != "" {
		anchor = Lit("\\protect\\phantomsection\\label{" + toLabel(v.Attr.ID) + "}%")
	}
	if w.opts.Listings {
		return w.listingsBlock(v, lang, anchor)
	}
	if lang == "" || !w.opts.Highlight {
		return Cat(Above(anchor, Cat(Lit("\\begin{verbatim}"), dCR, Flush(Lit(v.Text)), dCR, Lit("\\end{verbatim}"))), dBlank)
	}
	w.usesHighlighting = true
	numberLines := v.Attr.HasClass("numberLines") || v.Attr.HasClass("number-lines")
	opt := ""
	if numberLines {
		opt = "numbers=left,,"
		if st, ok := v.Attr.Get("startFrom"); ok {
			opt += "firstnumber=" + st + ","
		}
	}
	lines := highlightLines(lang, v.Text)
	var sb strings.Builder
	for i, toks := range lines {
		if i > 0 {
			sb.WriteString("\n")
		}
		for _, t := range toks {
			sb.WriteString(latexTok(t))
		}
	}
	return Cat(Above(anchor, Cat(Lit("\\begin{Shaded}"), dCR, Lit("\\begin{Highlighting}["+opt+"]"), dCR, Flush(Lit(sb.String())), dCR, Lit("\\end{Highlighting}"), dCR, Lit("\\end{Shaded}"))), dBlank)
}

var tokNames = map[string]string{"kw": "KeywordTok", "dt": "DataTypeTok", "dv": "DecValTok", "bn": "BaseNTok", "fl": "FloatTok",
	"ch": "CharTok", "st": "StringTok", "co": "CommentTok", "ot": "OtherTok", "al": "AlertTok", "fu": "FunctionTok",
	"er": "ErrorTok", "wa": "WarningTok", "cn": "ConstantTok", "sc": "SpecialCharTok", "vs": "VerbatimStringTok",
	"ss": "SpecialStringTok", "im": "ImportTok", "do": "DocumentationTok", "an": "AnnotationTok", "cv": "CommentVarTok",
	"va": "VariableTok", "cf": "ControlFlowTok", "op": "OperatorTok", "bu": "BuiltInTok", "ex": "ExtensionTok",
	"pp": "PreprocessorTok", "at": "AttributeTok", "in": "InformationTok", "": "NormalTok"}

func latexTokEscape(s string) string {
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case '\\':
			sb.WriteString("\\textbackslash{}")
		case '{':
			sb.WriteString("\\{")
		case '}':
			sb.WriteString("\\}")
		case '|':
			sb.WriteString("\\VerbBar{}")
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func latexTok(t hlTok) string {
	name := tokNames[t.cls]
	// whitespace-only normal tokens are emitted raw
	if t.cls == "" && strings.TrimSpace(t.text) == "" {
		return t.text
	}
	return "\\" + name + "{" + latexTokEscape(t.text) + "}"
}

func (w *latexWriter) listingsBlock(v *CodeBlock, lang string, anchor *Doc) *Doc {
	var params []string
	if lang != "" {
		params = append(params, "language="+lang)
	}
	if v.Attr.ID != "" {
		params = append(params, "label="+toLabel(v.Attr.ID))
	}
	p := ""
	if len(params) > 0 {
		p = "[" + strings.Join(params, ", ") + "]"
	}
	return Cat(Lit("\\begin{lstlisting}"+p), dCR, Flush(Lit(v.Text)), dCR, Lit("\\end{lstlisting}"), dBlank)
}

func (w *latexWriter) isTight(items [][]Block) bool {
	for _, it := range items {
		if len(it) > 0 {
			if _, ok := it[0].(*Plain); !ok {
				return false
			}
		} else {
			return false
		}
	}
	return true
}

func (w *latexWriter) listItem(bs []Block) *Doc {
	// task list
	if isTaskItem(bs) {
		ils := firstInlines(bs)
		s := ils[0].(*Str)
		checked := strings.HasPrefix(s.Text, "\u2612")
		rest := []Inline{}
		t := strings.TrimPrefix(strings.TrimPrefix(s.Text, "\u2610"), "\u2612")
		if t != "" {
			rest = append(rest, &Str{t})
		}
		rest = append(rest, ils[1:]...)
		if len(rest) > 0 {
			if _, ok := rest[0].(*Space); ok {
				rest = rest[1:]
			}
		}
		nb := append([]Block{}, bs...)
		switch b := bs[0].(type) {
		case *Plain:
			nb[0] = &Plain{rest}
		case *Para:
			nb[0] = &Para{rest}
		}
		box := "$\\square$"
		if checked {
			box = "$\\boxtimes$"
		}
		c := w.blocks(nb)
		return Hang(2, Lit("\\item["+box+"]"), Cat(dCR, c))
	}
	c := w.blocks(bs)
	return Hang(2, Lit("\\item"), Cat(dCR, c))
}

func firstInlines(bs []Block) []Inline {
	if len(bs) == 0 {
		return nil
	}
	switch b := bs[0].(type) {
	case *Plain:
		return b.Inlines
	case *Para:
		return b.Inlines
	}
	return nil
}

func (w *latexWriter) bulletList(v *BulletList) *Doc {
	old := w.incremental
	_ = old
	w.listLevel++
	var items []*Doc
	for _, it := range v.Items {
		items = append(items, w.listItem(it))
	}
	w.listLevel--
	var parts []*Doc
	parts = append(parts, Lit("\\begin{itemize}"))
	if w.isTight(v.Items) {
		parts = append(parts, Lit("\\tightlist"))
	}
	parts = append(parts, items...)
	parts = append(parts, Lit("\\end{itemize}"))
	return Cat(Vcat(parts), dBlank)
}

func (w *latexWriter) orderedList(v *OrderedList) *Doc {
	w.olLevel++
	w.listLevel++
	lvl := w.olLevel
	var items []*Doc
	for _, it := range v.Items {
		items = append(items, w.listItem(it))
	}
	w.listLevel--
	w.olLevel--
	enumNames := []string{"", "i", "ii", "iii", "iv", "v", "vi"}
	ename := "enum" + enumNames[min(lvl, 6)]
	var parts []*Doc
	parts = append(parts, Lit("\\begin{enumerate}"))
	la := v.Attrs
	if la.Style != DefaultStyle || la.Delim != DefaultDelim {
		cmd := ""
		switch la.Style {
		case Decimal, Example, DefaultStyle:
			cmd = "\\arabic"
		case LowerRoman:
			cmd = "\\roman"
		case UpperRoman:
			cmd = "\\Roman"
		case LowerAlpha:
			cmd = "\\alph"
		case UpperAlpha:
			cmd = "\\Alph"
		}
		num := cmd + "{" + ename + "}"
		switch la.Delim {
		case OneParen:
			num += ")"
		case TwoParens:
			num = "(" + num + ")"
		default:
			num += "."
		}
		if lvl <= 4 {
			parts = append(parts, Lit("\\def\\label"+ename+"{"+num+"}"))
		}
	}
	if la.Start != 1 && lvl <= 4 {
		parts = append(parts, Lit("\\setcounter{"+ename+"}{"+strconv.Itoa(la.Start-1)+"}"))
	}
	if w.isTight(v.Items) {
		parts = append(parts, Lit("\\tightlist"))
	}
	parts = append(parts, items...)
	parts = append(parts, Lit("\\end{enumerate}"))
	return Cat(Vcat(parts), dBlank)
}

func (w *latexWriter) defList(v *DefinitionList) *Doc {
	var parts []*Doc
	parts = append(parts, Lit("\\begin{description}"))
	tight := true
	for _, it := range v.Items {
		for _, d := range it.Defs {
			if len(d) == 0 {
				continue
			}
			if _, ok := d[0].(*Plain); !ok {
				tight = false
			}
		}
	}
	if tight {
		parts = append(parts, Lit("\\tightlist"))
	}
	for _, it := range v.Items {
		term := w.inlines(it.Term)
		// avoid ] in term
		var defs []*Doc
		for _, d := range it.Defs {
			defs = append(defs, w.blocks(d))
		}
		item := Cat(Lit("\\item["), term, Lit("]"))
		parts = append(parts, Above(item, Vcat(defs)))
	}
	parts = append(parts, Lit("\\end{description}"))
	return Cat(Vcat(parts), dBlank)
}

func (w *latexWriter) sectionCmd(level int) (string, bool) {
	tld := w.opts.TopLevelDivision
	var names []string
	switch tld {
	case "part":
		names = []string{"part", "chapter", "section", "subsection", "subsubsection", "paragraph", "subparagraph"}
	case "chapter":
		names = []string{"chapter", "section", "subsection", "subsubsection", "paragraph", "subparagraph"}
	default:
		names = []string{"section", "subsection", "subsubsection", "paragraph", "subparagraph"}
	}
	if w.beamer && tld == "default" {
		names = []string{"section", "subsection", "subsubsection", "paragraph", "subparagraph"}
	}
	if level < 1 || level > len(names) {
		return "", false
	}
	return names[level-1], true
}

func hasFormatting(xs []Inline) bool {
	found := false
	walkInlines(xs, func(x Inline) {
		switch x.(type) {
		case *Str, *Space, *SoftBreak:
		default:
			found = true
		}
	})
	return found
}

func (w *latexWriter) header(v *Header) *Doc {
	if v.Attr.HasClass("unlisted") && false {
	}
	w.inHeading = true
	txt := w.inlines(v.Inlines)
	w.inHeading = false
	lab := dEmpty
	if v.Attr.ID != "" {
		lab = Lit("\\label{" + toLabel(v.Attr.ID) + "}")
	}
	var txt2 *Doc
	if hasFormatting(v.Inlines) {
		plain := w.stringToLaTeX(ctxText, stringify(v.Inlines))
		txt2 = Cat(Lit("\\texorpdfstring{"), txt, Lit("}{"+plain+"}"))
	} else {
		txt2 = txt
	}
	cmd, ok := w.sectionCmd(v.Level)
	if !ok {
		return Cat(txt, lab, dBlank)
	}
	unnumbered := v.Attr.HasClass("unnumbered")
	star := ""
	if unnumbered {
		star = "*"
	}
	hdr := Cat(Lit("\\"+cmd+star+"{"), txt2, Lit("}"), lab)
	if unnumbered && !v.Attr.HasClass("unlisted") {
		plain := w.stringToLaTeX(ctxText, stringify(v.Inlines))
		_ = plain
		hdr = Above(hdr, Cat(Lit("\\addcontentsline{toc}{"+cmd+"}{"), txt, Lit("}")))
	}
	return Cat(hdr, dBlank)
}

func (w *latexWriter) figure(v *Figure) *Doc {
	w.usesGraphics = true
	var capDoc *Doc = dEmpty
	if len(v.Caption.Long) > 0 {
		w.inCaption = true
		c := w.inlines(blocksToInlines(v.Caption.Long))
		w.inCaption = false
		lab := dEmpty
		if v.Attr.ID != "" {
			lab = Lit("\\label{" + toLabel(v.Attr.ID) + "}")
		}
		capDoc = Cat(Lit("\\caption{"), c, Lit("}"), lab)
	}
	body := w.blocks(v.Blocks)
	return Cat(Vcat(filterEmpty([]*Doc{Lit("\\begin{figure}"), Lit("\\centering"), body, capDoc, Lit("\\end{figure}")})), dBlank)
}

// ---------- inlines ----------

func (w *latexWriter) inline(x Inline) *Doc {
	switch v := x.(type) {
	case *Str:
		return Lit(w.stringToLaTeX(ctxText, v.Text))
	case *Space:
		return dSpace
	case *SoftBreak:
		if w.opts.Wrap == WrapPreserve {
			return dCR
		}
		return dSpace
	case *LineBreak:
		if w.inHeading {
			return Lit(" ")
		}
		return Cat(Lit("\\\\"), dCR)
	case *Emph:
		return Cat(Lit("\\emph{"), w.inlines(v.Inlines), Lit("}"))
	case *Underline:
		w.usesUl = true
		return Cat(Lit("\\ul{"), w.inlines(v.Inlines), Lit("}"))
	case *Strong:
		return Cat(Lit("\\textbf{"), w.inlines(v.Inlines), Lit("}"))
	case *Strikeout:
		w.usesStrike = true
		return Cat(Lit("\\st{"), w.inlines(v.Inlines), Lit("}"))
	case *Superscript:
		return Cat(Lit("\\textsuperscript{"), w.inlines(v.Inlines), Lit("}"))
	case *Subscript:
		return Cat(Lit("\\textsubscript{"), w.inlines(v.Inlines), Lit("}"))
	case *SmallCaps:
		return Cat(Lit("\\textsc{"), w.inlines(v.Inlines), Lit("}"))
	case *Quoted:
		c := w.inlines(v.Inlines)
		s1, s2 := "", ""
		if len(v.Inlines) > 0 {
			if _, ok := v.Inlines[0].(*Quoted); ok {
				s1 = "\\,"
			}
			if _, ok := v.Inlines[len(v.Inlines)-1].(*Quoted); ok {
				s2 = "\\,"
			}
		}
		inner := Cat(Lit(s1), c, Lit(s2))
		if v.Type == DoubleQuote {
			if w.ext("smart") {
				return Cat(Lit("``"), inner, Lit("''"))
			}
			return Cat(Lit("\u201c"), inner, Lit("\u201d"))
		}
		if w.ext("smart") {
			return Cat(Lit("`"), inner, Lit("'"))
		}
		return Cat(Lit("\u2018"), inner, Lit("\u2019"))
	case *Code:
		return w.code(v)
	case *Math:
		if v.Type == InlineMath {
			return Lit("\\(" + v.Text + "\\)")
		}
		return Lit("\\[" + v.Text + "\\]")
	case *RawInline:
		if v.Format == "latex" || v.Format == "tex" {
			return Lit(v.Text)
		}
		return dEmpty
	case *Link:
		return w.link(v)
	case *Image:
		return w.image(v)
	case *Note:
		return w.note(v)
	case *Span:
		return w.span(v)
	case *Cite:
		return w.inlines(v.Inlines)
	}
	return dEmpty
}

func (w *latexWriter) code(v *Code) *Doc {
	lang := ""
	for _, c := range v.Attr.Classes {
		if l := canonicalLang(c); l != "" {
			lang = l
			break
		}
	}
	if lang != "" && w.opts.Highlight && !w.opts.Listings {
		w.usesHighlighting = true
		lines := highlightLines(lang, v.Text)
		var sb strings.Builder
		for _, toks := range lines {
			for _, t := range toks {
				sb.WriteString(latexTok(t))
			}
		}
		return Lit("\\VERB|" + sb.String() + "|")
	}
	if w.opts.Listings {
		chr := "|"
		for _, c := range "!\"&'()*,-./:;?@_|`" {
			if !strings.ContainsRune(v.Text, c) {
				chr = string(c)
				break
			}
		}
		return Lit("\\passthrough{\\lstinline" + chr + v.Text + chr + "}")
	}
	return Lit("\\texttt{" + w.stringToLaTeX(ctxCode, v.Text) + "}")
}

func isURIScheme(u string) bool {
	i := strings.Index(u, ":")
	if i <= 0 {
		return false
	}
	return uriSchemes[strings.ToLower(u[:i])]
}

func (w *latexWriter) link(v *Link) *Doc {
	u := v.Target.URL
	if strings.HasPrefix(u, "#") {
		lab := toLabel(u[1:])
		return Cat(Lit("\\hyperref["+lab+"]{"), w.inlines(v.Inlines), Lit("}"))
	}
	txt := stringify(v.Inlines)
	escURL := w.escapeURL(u)
	if (txt == u || "mailto:"+txt == u) && len(v.Inlines) == 1 {
		if _, ok := v.Inlines[0].(*Str); ok {
			if txt == u {
				w.usesUrl = true
				return Lit("\\url{" + escURL + "}")
			}
			return Cat(Lit("\\href{"+escURL+"}{"), Lit("\\nolinkurl{"+w.stringToLaTeX(ctxCode, txt)+"}"), Lit("}"))
		}
	}
	if (txt == u || "mailto:"+txt == u) && len(v.Inlines) == 1 {
		if _, ok := v.Inlines[0].(*Code); ok {
			return Lit("\\url{" + escURL + "}")
		}
	}
	return Cat(Lit("\\href{"+escURL+"}{"), w.inlines(v.Inlines), Lit("}"))
}

func (w *latexWriter) escapeURL(u string) string {
	var sb strings.Builder
	for _, c := range u {
		switch c {
		case '%':
			sb.WriteString("\\%")
		case '#':
			sb.WriteString("\\#")
		case '{':
			sb.WriteString("\\{")
		case '}':
			sb.WriteString("\\}")
		case '\\':
			sb.WriteString("/")
		case '~':
			sb.WriteString("\\textasciitilde{}")
		case '^':
			sb.WriteString("\\^{}")
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *latexWriter) imageDims(a Attr) (string, bool) {
	var parts []string
	hasW, hasH := false, false
	dimToLaTeX := func(d dimension, dir string) string {
		switch d.unit {
		case "%":
			base := "\\linewidth"
			if dir == "height" {
				base = "\\textheight"
			}
			return showFl(d.val/100) + base
		case "px":
			dpi := w.opts.DPI
			if dpi == 0 {
				dpi = 96
			}
			return showFl(d.val/float64(dpi)) + "in"
		}
		return d.String()
	}
	if v, ok := a.Get("width"); ok {
		if d, ok := lengthToDim(v); ok {
			parts = append(parts, "width="+dimToLaTeX(d, "width"))
			hasW = true
		}
	}
	if v, ok := a.Get("height"); ok {
		if d, ok := lengthToDim(v); ok {
			parts = append(parts, "height="+dimToLaTeX(d, "height"))
			hasH = true
		}
	}
	if hasW && !hasH {
		parts = append(parts, "height=\\textheight")
	}
	if hasH && !hasW {
		parts = append([]string{"width=\\linewidth"}, parts...)
	}
	return strings.Join(parts, ","), hasW || hasH
}

func (w *latexWriter) image(v *Image) *Doc {
	w.usesGraphics = true
	dims, has := w.imageDims(v.Attr)
	opts := []string{}
	if dims != "" {
		opts = append(opts, dims)
	}
	opts = append(opts, "keepaspectratio")
	alt := stringify(v.Inlines)
	if alt != "" {
		opts = append(opts, "alt={"+w.stringToLaTeX(ctxText, alt)+"}")
	}
	src := v.Target.URL
	if strings.ContainsAny(src, " ") || strings.Count(src, ".") > 1 {
		src = "{" + src + "}"
	}
	inc := "\\includegraphics[" + strings.Join(opts, ",") + "]{" + src + "}"
	var d *Doc
	if has {
		d = Lit(inc)
	} else {
		d = Lit("\\pandocbounded{" + inc + "}")
	}
	if v.Attr.ID != "" {
		d = Cat(w.hypertarget(v.Attr.ID), d)
	}
	return d
}

func (w *latexWriter) note(v *Note) *Doc {
	old := w.inNote
	w.inNote = true
	c := w.blocks(v.Blocks)
	w.inNote = old
	return Cat(Lit("\\footnote{"), Nest(2, Chomp(c)), Lit("}"))
}

func (w *latexWriter) span(v *Span) *Doc {
	c := w.inlines(v.Inlines)
	var cmds []string
	if lang, ok := v.Attr.Get("lang"); ok {
		if bl := babelLang(lang); bl != "" {
			w.hasLang = true
			cmds = append(cmds, "\\foreignlanguage{"+bl+"}")
		}
	}
	for _, cl := range v.Attr.Classes {
		switch cl {
		case "csl-no-emph":
			cmds = append(cmds, "\\textup")
		case "csl-no-strong":
			cmds = append(cmds, "\\textnormal")
		case "csl-no-smallcaps":
			cmds = append(cmds, "\\textnormal")
		case "underline":
			cmds = append(cmds, "\\ul")
		}
	}
	var d *Doc = braces(c)
	for i := len(cmds) - 1; i >= 0; i-- {
		d = Cat(Lit(cmds[i]), d)
	}
	if v.Attr.ID != "" {
		d = Cat(w.hypertarget(v.Attr.ID), d)
	}
	return d
}

// ---------- tables ----------

func (w *latexWriter) table(t *Table) *Doc {
	w.usesTable = true
	ncols := len(t.ColSpecs)
	var capDoc *Doc = dEmpty
	if len(t.Caption.Long) > 0 {
		w.inCaption = true
		c := w.inlines(blocksToInlines(t.Caption.Long))
		w.inCaption = false
		lab := dEmpty
		if t.Attr.ID != "" {
			lab = Lit("\\label{" + toLabel(t.Attr.ID) + "}")
		}
		capDoc = Cat(Lit("\\caption{"), c, Lit("}"), lab, Lit("\\tabularnewline"))
	}
	hasHead := len(t.Head.Rows) > 0 && !allRowsEmpty(t.Head.Rows)
	headDoc := func() *Doc {
		var rows []*Doc
		for _, r := range t.Head.Rows {
			rows = append(rows, w.tableRow(r, t.ColSpecs, true))
		}
		return Vcat([]*Doc{Lit("\\toprule\\noalign{}"), Vcat(rows), Lit("\\midrule\\noalign{}")})
	}
	var firsthead *Doc = dEmpty
	if !capDoc.IsEmpty() && hasHead {
		firsthead = Above(headDoc(), Lit("\\endfirsthead"))
	}
	var head *Doc
	if hasHead {
		head = headDoc()
	} else {
		head = Lit("\\toprule\\noalign{}")
	}
	var rows []*Doc
	for _, b := range t.Bodies {
		for _, r := range b.Head {
			rows = append(rows, w.tableRow(r, t.ColSpecs, false))
		}
		for _, r := range b.Body {
			rows = append(rows, w.tableRow(r, t.ColSpecs, false))
		}
	}
	var foot *Doc = dEmpty
	if len(t.Foot.Rows) > 0 {
		var fr []*Doc
		for _, r := range t.Foot.Rows {
			fr = append(fr, w.tableRow(r, t.ColSpecs, false))
		}
		foot = Above(Lit("\\midrule\\noalign{}"), Vcat(fr))
	}
	parts := []*Doc{}
	if capDoc.IsEmpty() {
		parts = append(parts, Lit("{\\def\\LTcaptype{none} % do not increment counter"))
	}
	parts = append(parts, Cat(Lit("\\begin{longtable}[]{@{}"), w.colDescriptors(t, ncols), Lit("@{}}")))
	parts = append(parts, capDoc, firsthead, head, Lit("\\endhead"), foot, Lit("\\bottomrule\\noalign{}"), Lit("\\endlastfoot"), Vcat(rows), Lit("\\end{longtable}"))
	if capDoc.IsEmpty() {
		parts = append(parts, Lit("}"))
	}
	return Cat(Vcat(filterEmpty(parts)), dBlank)
}

func allRowsEmpty(rows []Row) bool {
	for _, r := range rows {
		for _, c := range r.Cells {
			if len(c.Blocks) > 0 {
				return false
			}
		}
	}
	return true
}

func isSimpleLaTeXCell(bs []Block) bool {
	switch len(bs) {
	case 0:
		return true
	case 1:
		switch bs[0].(type) {
		case *Plain, *Para:
			return true
		}
	}
	return false
}

func (w *latexWriter) colDescriptors(t *Table, ncols int) *Doc {
	defaultOnly := true
	for _, cs := range t.ColSpecs {
		if cs.HasWidth {
			defaultOnly = false
		}
	}
	simple := true
	check := func(rows []Row) {
		for _, r := range rows {
			for _, c := range r.Cells {
				if !isSimpleLaTeXCell(c.Blocks) {
					simple = false
				}
			}
		}
	}
	check(t.Head.Rows)
	for _, b := range t.Bodies {
		check(b.Head)
		check(b.Body)
	}
	check(t.Foot.Rows)
	if defaultOnly && simple {
		var sb strings.Builder
		for _, cs := range t.ColSpecs {
			switch cs.Align {
			case AlignRight:
				sb.WriteString("r")
			case AlignCenter:
				sb.WriteString("c")
			default:
				sb.WriteString("l")
			}
		}
		return Lit(sb.String())
	}
	var lines []*Doc
	for _, cs := range t.ColSpecs {
		width := 1.0 / float64(ncols)
		if !defaultOnly {
			width = 0
			if cs.HasWidth {
				width = cs.Width
			}
		}
		lines = append(lines, Lit(fmt.Sprintf(">{%s\\arraybackslash}p{(\\linewidth - %d\\tabcolsep) * \\real{%0.4f}}", alignCommand(cs.Align), (ncols-1)*2, width)))
	}
	return Cat(dCR, Nest(2, Vcat(lines)))
}

func alignCommand(a Alignment) string {
	switch a {
	case AlignRight:
		return "\\raggedleft"
	case AlignCenter:
		return "\\centering"
	}
	return "\\raggedright"
}

func (w *latexWriter) tableRow(r Row, specs []ColSpec, header bool) *Doc {
	var cells []*Doc
	col := 0
	for _, c := range r.Cells {
		cells = append(cells, w.tableCell(c, specs, col, header))
		col += max(1, c.ColSpan)
	}
	var ds []*Doc
	for i, c := range cells {
		if i > 0 {
			ds = append(ds, dSpace, Lit("&"), dSpace)
		}
		ds = append(ds, c)
	}
	return Cat(Cat(ds...), Lit(" \\\\"))
}

func (w *latexWriter) tableCell(c Cell, specs []ColSpec, col int, header bool) *Doc {
	hasWidth := col < len(specs) && specs[col].HasWidth
	specAlign := AlignDefault
	if col < len(specs) {
		specAlign = specs[col].Align
	}
	al := c.Align
	if al == AlignDefault {
		al = specAlign
	}
	valign := "t"
	if header {
		valign = "b"
	}
	allPlain := true
	for _, b := range c.Blocks {
		switch b.(type) {
		case *Plain:
		default:
			allPlain = false
		}
	}
	var content *Doc
	if allPlain && !(header && hasWidth) && len(c.Blocks) <= 1 {
		var ils []Inline
		for _, b := range c.Blocks {
			ils = append(ils, b.(*Plain).Inlines...)
		}
		content = w.inlines(ils)
	} else {
		old := w.inMinipage
		w.inMinipage = true
		cc := w.blocks(c.Blocks)
		w.inMinipage = old
		content = Cat(Lit("\\begin{minipage}["+valign+"]{\\linewidth}"+alignCommand(al)), dCR, Chomp(cc), dCR, Lit("\\end{minipage}"))
	}
	if c.ColSpan > 1 {
		a := "l"
		switch al {
		case AlignRight:
			a = "r"
		case AlignCenter:
			a = "c"
		}
		content = Cat(Lit("\\multicolumn{"+strconv.Itoa(c.ColSpan)+"}{"+a+"}{"), content, Lit("}"))
	}
	if c.RowSpan > 1 {
		content = Cat(Lit("\\multirow{"+strconv.Itoa(c.RowSpan)+"}{*}{"), content, Lit("}"))
	}
	return content
}

// ---------- entry ----------

func writeLaTeX(doc *Pandoc, opts *WriterOptions, beamer bool) string {
	w := &latexWriter{opts: opts, beamer: beamer, langs: map[string]bool{}}
	if opts.TopLevelDivision == "default" && opts.Standalone {
		// documentclass book/report => chapter
		if dc := lookupMetaString(doc.Meta, "documentclass"); dc == "book" || dc == "report" || dc == "memoir" || dc == "scrbook" || dc == "scrreprt" {
			o := *opts
			o.TopLevelDivision = "chapter"
			w.opts = &o
		}
		if v, ok := opts.Variables["documentclass"]; ok && len(v) > 0 {
			dc := v[0]
			if dc == "book" || dc == "report" || dc == "memoir" || dc == "scrbook" || dc == "scrreprt" {
				o := *w.opts
				o.TopLevelDivision = "chapter"
				w.opts = &o
			}
		}
	}
	body := w.blocks(doc.Blocks)
	cols := opts.Columns
	if opts.Wrap != WrapAuto {
		cols = 0
	}
	out := Render(body, cols)
	if !opts.Standalone {
		return strings.TrimRight(out, "\n") + "\n"
	}
	return w.standalone(doc, out, cols)
}
