package main

import (
	"strconv"
	"strings"
)

type rstWriter struct {
	opts      *WriterOptions
	notes     []*Doc
	refs      []mdRef
	subs      []rstSub
	hasMath   bool
	hasCode   bool
	inList    bool
	topLevel  bool
	ids       map[string]bool
}

type rstSub struct {
	label string
	img   *Image
}

func (w *rstWriter) ext(n string) bool { return w.opts.Exts.On(n) }

func writeRST(doc *Pandoc, opts *WriterOptions) string {
	w := &rstWriter{opts: opts, ids: map[string]bool{}}
	bs := doc.Blocks
	body := w.blockList(bs, true)
	notes := w.notesDoc()
	refs := w.refsDoc()
	main := Vsep(filterEmpty([]*Doc{body, notes, refs, w.subsDoc()}))
	cols := opts.Columns
	if opts.Wrap != WrapAuto {
		cols = 0
	}
	out := Render(main, cols)
	if !opts.Standalone {
		return strings.TrimRight(out, "\n") + "\n"
	}
	tpl, ok := getTemplate(opts, "rst")
	if !ok {
		return out
	}
	ctx := metaToContext(doc.Meta, func(bs []Block) *Doc {
		ww := &rstWriter{opts: opts, ids: map[string]bool{}}
		return Lit(strings.TrimRight(Render(ww.blockList(bs, false), cols), "\n"))
	}, func(ils []Inline) *Doc {
		ww := &rstWriter{opts: opts, ids: map[string]bool{}}
		return Lit(Render(ww.inlines(ils), cols))
	})
	addVariables(ctx, opts)
	ctx["body"] = Lit(strings.TrimRight(out, "\n"))
	if title := lookupMetaInlines(doc.Meta, "title"); len(title) > 0 {
		ww := &rstWriter{opts: opts, ids: map[string]bool{}}
		t := Render(ww.inlines(title), 0)
		bar := strings.Repeat("=", strWidth(t))
		tb := bar + "\n" + t + "\n" + bar
		if st := lookupMetaInlines(doc.Meta, "subtitle"); len(st) > 0 {
			s := Render(ww.inlines(st), 0)
			sbar := strings.Repeat("-", strWidth(s))
			tb += "\n\n" + sbar + "\n" + s + "\n" + sbar
		}
		defField(ctx, "title", Lit(tb))
	}
	if w.hasMath {
		defField(ctx, "math", true)
	}
	d, err := renderTemplateDoc(tpl, ctx, "rst")
	if err != nil {
		return out
	}
	return strings.TrimRight(Render(d, 0), "\n") + "\n"
}

func (w *rstWriter) blockList(bs []Block, top bool) *Doc {
	var ds []*Doc
	for i, b := range bs {
		d := w.block(b, top)
		if d.IsEmpty() {
			continue
		}
		// consecutive block quotes need separator
		if i > 0 {
			if _, ok := b.(*BlockQuote); ok {
				if _, ok2 := bs[i-1].(*BlockQuote); ok2 {
					ds = append(ds, Lit(".."))
				}
			}
			if isListBlock(b) && isListBlock(bs[i-1]) {
				ds = append(ds, Lit(".."))
			}
			if _, ok := b.(*BlockQuote); ok {
				if isListBlock(bs[i-1]) {
					ds = append(ds, Lit(".."))
				}
			}
		}
		ds = append(ds, d)
	}
	return Vsep(ds)
}

func (w *rstWriter) block(b Block, top bool) *Doc {
	switch v := b.(type) {
	case *Plain:
		return w.inlinesWithSubs(v.Inlines)
	case *Para:
		return w.para(v.Inlines)
	case *LineBlock:
		var ds []*Doc
		for _, l := range v.Lines {
			ds = append(ds, Hang(2, Lit("| "), w.inlines(l)))
		}
		return Vcat(ds)
	case *RawBlock:
		if v.Format == "rst" {
			return Lit(v.Text)
		}
		return Cat(Lit(".. raw:: "+v.Format), dBlank, Nest(3, Lit(v.Text)))
	case *HorizontalRule:
		return Lit("--------------")
	case *Header:
		return w.header(v, top)
	case *CodeBlock:
		return w.codeBlock(v)
	case *BlockQuote:
		return Nest(3, w.blockList(v.Blocks, false))
	case *BulletList:
		var items []*Doc
		for _, it := range v.Items {
			items = append(items, Hang(2, Lit("- "), w.blockList(it, false)))
		}
		if isTightList(v.Items) {
			return Vcat(items)
		}
		return Vsep(items)
	case *OrderedList:
		return w.orderedList(v)
	case *DefinitionList:
		var items []*Doc
		for _, it := range v.Items {
			term := NoWrap(w.inlines(it.Term))
			var defs []*Doc
			for _, d := range it.Defs {
				defs = append(defs, w.blockList(d, false))
			}
			items = append(items, Above(term, Nest(3, Vsep(defs))))
		}
		return Vsep(items)
	case *Div:
		return w.div(v)
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

func (w *rstWriter) para(ils []Inline) *Doc {
	// display math splits paragraphs
	var parts []*Doc
	var cur []Inline
	flush := func() {
		if len(cur) > 0 {
			c := cur
			// leading space after split: escaped
			if len(parts) > 0 && len(c) > 0 && isSpaceLike(c[0]) {
				c = append([]Inline{&RawInline{"rst", "\\ "}}, c[1:]...)
			}
			parts = append(parts, w.inlinesWithSubs(c))
			cur = nil
		}
	}
	for _, x := range ils {
		if m, ok := x.(*Math); ok && m.Type == DisplayMath {
			// trim trailing space
			for len(cur) > 0 && isSpaceLike(cur[len(cur)-1]) {
				cur = cur[:len(cur)-1]
			}
			flush()
			w.hasMath = true
			parts = append(parts, w.displayMath(m.Text))
			continue
		}
		cur = append(cur, x)
	}
	flush()
	return Vsep(parts)
}

func (w *rstWriter) displayMath(t string) *Doc {
	if strings.Contains(strings.TrimSpace(t), "\n") {
		return Cat(Lit(".. math::"), dBlank, Nest(3, Lit(strings.TrimSpace(t))))
	}
	return Lit(".. math:: " + strings.TrimSpace(t))
}

func (w *rstWriter) header(v *Header, top bool) *Doc {
	txt := w.inlines(v.Inlines)
	s := Render(NoWrap(txt), 0)
	chars := "=-~^'"
	ch := " "
	if v.Level >= 1 && v.Level <= len(chars) {
		ch = string(chars[v.Level-1])
	}
	autoID := textToIdentifier(w.opts.Exts, stringify(v.Inlines))
	if autoID == "" {
		autoID = "section"
	}
	var label *Doc = dEmpty
	if v.Attr.ID != "" && v.Attr.ID != autoID {
		label = Cat(Lit(".. _"+v.Attr.ID+":"), dBlank)
	}
	var classDir *Doc = dEmpty
	if len(v.Attr.Classes) > 0 {
		var cls []string
		for _, c := range v.Attr.Classes {
			if c != "unnumbered" {
				cls = append(cls, c)
			}
		}
		if len(cls) > 0 {
			classDir = Cat(Lit(".. class:: "+strings.Join(cls, " ")), dBlank)
		}
	}
	under := strings.Repeat(ch, strWidth(s))
	return Cat(label, classDir, NoWrap(txt), dCR, Lit(under))
}

func (w *rstWriter) codeBlock(v *CodeBlock) *Doc {
	if v.Attr.HasClass("haskell") && v.Attr.HasClass("literate") {
		return Prefixed("> ", Lit(v.Text))
	}
	if len(v.Attr.Classes) == 0 {
		return Cat(Lit("::"), dBlank, Nest(3, Lit(v.Text)))
	}
	lang := v.Attr.Classes[0]
	var opts []*Doc
	if v.Attr.HasClass("numberLines") || v.Attr.HasClass("number-lines") {
		if st, ok := v.Attr.Get("startFrom"); ok {
			opts = append(opts, Lit(":number-lines: "+st))
		} else {
			opts = append(opts, Lit(":number-lines:"))
		}
	}
	if v.Attr.ID != "" {
		opts = append(opts, Lit(":name: "+v.Attr.ID))
	}
	head := Lit(".. code:: " + lang)
	if len(opts) > 0 {
		head = Above(head, Nest(3, Vcat(opts)))
	}
	return Cat(head, dBlank, Nest(3, Lit(v.Text)))
}

func (w *rstWriter) orderedList(v *OrderedList) *Doc {
	la := v.Attrs
	var markers []string
	if la.Style == DefaultStyle && la.Delim == DefaultDelim {
		for range v.Items {
			markers = append(markers, "#.")
		}
	} else {
		if la.Style == Example {
			la.Style = Decimal
		}
		markers = orderedListMarkers(la, len(v.Items))
	}
	maxw := 0
	for _, m := range markers {
		if l := len([]rune(m)); l > maxw {
			maxw = l
		}
	}
	var items []*Doc
	for i, it := range v.Items {
		m := markers[i]
		m = m + strings.Repeat(" ", maxw-len([]rune(m))+1)
		items = append(items, Hang(len([]rune(m)), Lit(m), w.blockList(it, false)))
	}
	if isTightList(v.Items) {
		return Vcat(items)
	}
	return Vsep(items)
}

var admonitions = makeSet("attention", "caution", "danger", "error", "hint", "important", "note", "tip", "warning", "admonition")

func (w *rstWriter) div(v *Div) *Doc {
	contents := w.blockList(v.Blocks, false)
	var adm string
	var rest []string
	for _, c := range v.Attr.Classes {
		if admonitions[c] && adm == "" {
			adm = c
		} else {
			rest = append(rest, c)
		}
	}
	if adm != "" {
		head := Lit(".. " + adm + "::")
		var opts []*Doc
		if v.Attr.ID != "" {
			opts = append(opts, Lit(":name: "+v.Attr.ID))
		}
		if len(rest) > 0 {
			opts = append(opts, Lit(":class: "+strings.Join(rest, " ")))
		}
		if len(opts) > 0 {
			head = Above(head, Nest(3, Vcat(opts)))
		}
		return Cat(head, dBlank, Nest(3, contents))
	}
	if v.Attr.ID == "" && len(v.Attr.Classes) == 0 {
		return contents
	}
	head := Lit(".. container::")
	if len(v.Attr.Classes) > 0 {
		head = Lit(".. container:: " + strings.Join(v.Attr.Classes, " "))
	}
	if v.Attr.ID != "" {
		head = Above(head, Nest(3, Lit(":name: "+v.Attr.ID)))
	}
	return Cat(head, dBlank, Nest(3, contents))
}

func (w *rstWriter) figure(v *Figure) *Doc {
	if len(v.Blocks) == 1 {
		if pl, ok := v.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok {
				var opts []*Doc
				alt := stringify(img.Inlines)
				if alt != "" {
					opts = append(opts, Lit(":alt: "+alt))
				}
				opts = append(opts, w.imageDims(img.Attr)...)
				if v.Attr.ID != "" {
					opts = append(opts, Lit(":name: "+v.Attr.ID))
				}
				head := Lit(".. figure:: " + img.Target.URL)
				if len(opts) > 0 {
					head = Above(head, Nest(3, Vcat(opts)))
				}
				capDoc := w.blockList(v.Caption.Long, false)
				if capDoc.IsEmpty() {
					return head
				}
				return Cat(head, dBlank, Nest(3, capDoc))
			}
		}
	}
	return w.blockList(v.Blocks, false)
}

func (w *rstWriter) imageDims(a Attr) []*Doc {
	var out []*Doc
	for _, dir := range []string{"width", "height"} {
		if v, ok := a.Get(dir); ok {
			if d, ok := lengthToDim(v); ok {
				s := d.String()
				if d.unit == "px" {
					s = strconv.Itoa(int(d.val)) + "px"
				}
				out = append(out, Lit(":"+dir+": "+s))
			}
		}
	}
	return out
}

// ---------- tables ----------

func (w *rstWriter) table(t *Table) *Doc {
	lt := toLegacyTable(t)
	capDoc := w.inlines(lt.caption)
	simple := onlySimpleTableCells(append([][][]Block{lt.headers}, lt.rows...))
	zero := true
	for _, x := range lt.widths {
		if x != 0 {
			zero = false
		}
	}
	var tbl *Doc
	ncols := len(lt.aligns)
	if simple && zero && ncols > 0 {
		tbl = w.simpleTable(lt)
	} else {
		tbl = gridTable(w.opts, func(o *WriterOptions, bs []Block) *Doc {
			ww := &rstWriter{opts: o, ids: map[string]bool{}}
			d := ww.blockList(bs, false)
			w.notes = append(w.notes, ww.notes...)
			return d
		}, allEmptyCells(lt.headers), lt.aligns, lt.widths, lt.headers, lt.rows)
	}
	if len(lt.caption) == 0 {
		return tbl
	}
	return Cat(Lit(".. table:: "), NoWrap(capDoc), dBlank, Nest(3, tbl))
}

func (w *rstWriter) simpleTable(lt legacyTable) *Doc {
	ncols := len(lt.aligns)
	headless := allEmptyCells(lt.headers)
	render := func(cells [][]Block) []*Doc {
		var out []*Doc
		for i := 0; i < ncols; i++ {
			if i < len(cells) {
				out = append(out, NoWrap(w.blockList(cells[i], false)))
			} else {
				out = append(out, dEmpty)
			}
		}
		return out
	}
	heads := render(lt.headers)
	var rows [][]*Doc
	for _, r := range lt.rows {
		rows = append(rows, render(r))
	}
	widths := make([]int, ncols)
	for i := 0; i < ncols; i++ {
		m := 1
		if !headless {
			if o := heads[i].Offset(); o > m {
				m = o
			}
		}
		for _, r := range rows {
			if o := r[i].Offset(); o > m {
				m = o
			}
		}
		widths[i] = m
	}
	toRow := func(cs []*Doc) *Doc {
		var ds []*Doc
		for i, c := range cs {
			if i > 0 {
				ds = append(ds, LBlock(1, Lit(" ")))
			}
			ds = append(ds, LBlock(widths[i], c))
		}
		return Cat(ds...)
	}
	var bs []string
	for _, wd := range widths {
		bs = append(bs, strings.Repeat("=", wd))
	}
	border := Lit(strings.Join(bs, " "))
	var parts []*Doc
	parts = append(parts, border)
	if !headless {
		parts = append(parts, toRow(heads), border)
	}
	for _, r := range rows {
		parts = append(parts, toRow(r))
	}
	parts = append(parts, border)
	return Vcat(parts)
}

// ---------- notes/refs ----------

func (w *rstWriter) notesDoc() *Doc {
	var ds []*Doc
	for i, n := range w.notes {
		ds = append(ds, Above(Lit(".. ["+strconv.Itoa(i+1)+"]"), Nest(3, n)))
	}
	return Vsep(ds)
}

func (w *rstWriter) refsDoc() *Doc {
	var ds []*Doc
	for _, r := range w.refs {
		ds = append(ds, Lit(".. _"+r.label+": "+r.target.URL))
	}
	return Vcat(ds)
}

func (w *rstWriter) subsDoc() *Doc { return dEmpty }

// ---------- inlines ----------

func (w *rstWriter) inlinesWithSubs(ils []Inline) *Doc {
	old := w.subs
	w.subs = nil
	d := w.inlines(ils)
	subs := w.subs
	w.subs = old
	if len(subs) == 0 {
		return d
	}
	var defs []*Doc
	for _, s := range subs {
		head := Lit(".. |" + s.label + "| image:: " + s.img.Target.URL)
		var opts []*Doc
		opts = append(opts, w.imageDims(s.img.Attr)...)
		if len(opts) > 0 {
			head = Above(head, Nest(3, Vcat(opts)))
		}
		defs = append(defs, head)
	}
	return Cat(d, dBlank, Vcat(defs))
}

func rstEscape(s string) string {
	var sb strings.Builder
	rs := []rune(s)
	for i, c := range rs {
		switch c {
		case '\\', '`', '*', '_', '|':
			if c == '_' {
				// escape only at word end / start? pandoc escapes all underscores at word boundaries
				prevAlnum := i > 0 && isAlphaNumH(rs[i-1])
				nextAlnum := i+1 < len(rs) && isAlphaNumH(rs[i+1])
				if prevAlnum && nextAlnum {
					sb.WriteRune(c)
					continue
				}
			}
			sb.WriteRune('\\')
			sb.WriteRune(c)
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *rstWriter) inlines(xs []Inline) *Doc {
	var ds []*Doc
	for i, x := range xs {
		var prev, next Inline
		if i > 0 {
			prev = xs[i-1]
		}
		if i+1 < len(xs) {
			next = xs[i+1]
		}
		d := w.inline(x)
		// complex inlines need escaped spaces when adjacent to text
		if isRSTComplex(x) {
			if prev != nil && !isSpaceLike(prev) && !isRSTOpenPunct(prev) {
				d = Cat(Lit("\\ "), d)
			}
			if next != nil && !isSpaceLike(next) && !isRSTClosePunct(next) {
				d = Cat(d, Lit("\\ "))
			}
		}
		ds = append(ds, d)
	}
	return Cat(ds...)
}

func isRSTComplex(x Inline) bool {
	switch x.(type) {
	case *Emph, *Strong, *Code, *Subscript, *Superscript, *Math, *Link, *Image, *Strikeout:
		return true
	}
	return false
}

func isRSTOpenPunct(x Inline) bool {
	if s, ok := x.(*Str); ok && s.Text != "" {
		rs := []rune(s.Text)
		c := rs[len(rs)-1]
		return strings.ContainsRune("-:/'\"<([{", c)
	}
	return false
}

func isRSTClosePunct(x Inline) bool {
	if s, ok := x.(*Str); ok && s.Text != "" {
		c := []rune(s.Text)[0]
