		return dSpace
	case *LineBreak:
		return dCR
	case *Emph:
		return Cat(Lit("*"), w.inlines(flattenEmph(v.Inlines)), Lit("*"))
	case *Strong:
		return Cat(Lit("**"), w.inlines(flattenEmph(v.Inlines)), Lit("**"))
	case *Underline:
		return w.inlines(v.Inlines)
	case *Strikeout:
		return Cat(Lit("[STRIKEOUT:"), w.inlines(v.Inlines), Lit("]"))
	case *Superscript:
		return Cat(Lit(":sup:`"), w.inlines(v.Inlines), Lit("`"))
	case *Subscript:
		return Cat(Lit(":sub:`"), w.inlines(v.Inlines), Lit("`"))
