cd /workspace && cat data/templates/default.org; cat > org_writer.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

type orgWriter struct {
	opts  *WriterOptions
	notes []*Doc
	hasMath bool
}

func writeOrg(doc *Pandoc, opts *WriterOptions) string {
	w := &orgWriter{opts: opts}
	body := w.blockList(doc.Blocks)
	notes := w.notesDoc()
	main := body
	if !notes.IsEmpty() {
		main = Above(Cat(body, dBlank), notes)
	}
	cols := opts.Columns
	if opts.Wrap != WrapAuto {
		cols = 0
	}
	out := Render(main, cols)
	if !opts.Standalone {
		return strings.TrimRight(out, "\n") + "\n"
	}
	tpl, ok := getTemplate(opts, "org")
	if !ok {
		return out
	}
	ctx := metaToContext(doc.Meta, func(bs []Block) *Doc {
		ww := &orgWriter{opts: opts}
		return Lit(strings.TrimRight(Render(ww.blockList(bs), cols), "\n"))
	}, func(ils []Inline) *Doc {
		ww := &orgWriter{opts: opts}
		return Lit(Render(ww.inlines(ils), cols))
	})
	addVariables(ctx, opts)
	ctx["body"] = Lit(strings.TrimRight(out, "\n"))
	if w.hasMath {
		defField(ctx, "math", true)
	}
	d, err := renderTemplateDoc(tpl, ctx, "org")
	if err != nil {
		return out
	}
	return strings.TrimRight(Render(d, 0), "\n") + "\n"
}

func (w *orgWriter) blockList(bs []Block) *Doc {
	var ds []*Doc
	for _, b := range bs {
		d := w.block(b)
		if !d.IsEmpty() {
			ds = append(ds, d)
		}
	}
	return Vcat(ds)
}

func (w *orgWriter) block(b Block) *Doc {
	switch v := b.(type) {
	case *Plain:
		return w.inlines(v.Inlines)
	case *Para:
		return Cat(w.inlines(v.Inlines), dBlank)
	case *Div:
		return w.div(v)
	case *LineBlock:
		var ds []*Doc
		for _, l := range v.Lines {
			ds = append(ds, w.inlines(l))
		}
		return Cat(Lit("#+begin_verse"), dCR, Nest(2, Vcat(ds)), dCR, Lit("#+end_verse"), dBlank)
	case *RawBlock:
		if v.Format == "org" {
			return Cat(Lit(v.Text), dBlank)
		}
		if v.Format == "html" || v.Format == "latex" || v.Format == "tex" {
			f := v.Format
			if f == "tex" {
				f = "latex"
			}
			return Cat(Lit("#+begin_export "+f), dCR, Lit(v.Text), dCR, Lit("#+end_export"), dBlank)
		}
		return dEmpty
	case *HorizontalRule:
		return Cat(Lit("--------------"), dBlank)
	case *Header:
		return w.header(v)
	case *CodeBlock:
		return w.codeBlock(v)
	case *BlockQuote:
		return Cat(Lit("#+begin_quote"), dCR, w.blockList(v.Blocks), dCR, Lit("#+end_quote"), dBlank)
	case *BulletList:
		var items []*Doc
		for _, it := range v.Items {
			items = append(items, w.listItem("-", it))
		}
		return w.listDoc(items, v.Items)
	case *OrderedList:
		delim := "."
		if v.Attrs.Delim == OneParen || v.Attrs.Delim == TwoParens {
			delim = ")"
		}
		var items []*Doc
		n := len(v.Items)
		width := len(strconv.Itoa(v.Attrs.Start + n - 1))
		for i, it := range v.Items {
			num := strconv.Itoa(v.Attrs.Start + i)
			m := num + delim
			m += strings.Repeat(" ", width-len(num))
			if i == 0 && v.Attrs.Start != 1 {
				items = append(items, w.listItemCounter(m, "[@"+strconv.Itoa(v.Attrs.Start)+"]", it))
				continue
			}
			items = append(items, w.listItem(m, it))
		}
		return w.listDoc(items, v.Items)
	case *DefinitionList:
		var items []*Doc
		for _, it := range v.Items {
			term := w.inlines(it.Term)
			var defs []*Doc
			for _, d := range it.Defs {
				defs = append(defs, w.blockList(d))
			}
			items = append(items, Hang(2, Cat(Lit("- "), term, Lit(" :: ")), Vcat(defs)))
		}
		var tight [][]Block
		for _, it := range v.Items {
			var bs []Block
			for _, d := range it.Defs {
				bs = append(bs, d...)
			}
			tight = append(tight, bs)
		}
		if isTightList(tight) {
			return Cat(Vcat(items), dBlank)
		}
		return Cat(Vsep(items), dBlank)
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

func (w *orgWriter) listDoc(items []*Doc, its [][]Block) *Doc {
	if isTightList(its) {
		return Cat(Vcat(items), dBlank)
	}
	return Cat(Vsep(items), dBlank)
}

func (w *orgWriter) taskify(bs []Block) []Block {
	if !isTaskItem(bs) {
		return bs
	}
	ils := firstInlines(bs)
	s := ils[0].(*Str)
	box := "[ ]"
	if strings.HasPrefix(s.Text, "\u2612") {
		box = "[X]"
	}
	rest := strings.TrimPrefix(strings.TrimPrefix(s.Text, "\u2610"), "\u2612")
	nils := []Inline{&RawInline{"org", box}}
	if rest != "" {
		nils = append(nils, &Str{rest})
	}
	nils = append(nils, ils[1:]...)
	out := append([]Block{}, bs...)
	switch bs[0].(type) {
	case *Plain:
		out[0] = &Plain{nils}
	case *Para:
		out[0] = &Para{nils}
	}
	return out
}

func (w *orgWriter) listItem(marker string, bs []Block) *Doc {
	c := w.blockList(w.taskify(bs))
	return Hang(len([]rune(marker))+1, Lit(marker+" "), c)
}

func (w *orgWriter) listItemCounter(marker, counter string, bs []Block) *Doc {
	c := w.blockList(w.taskify(bs))
	return Hang(len([]rune(marker))+1, Lit(marker+" "+counter+" "), c)
}

func (w *orgWriter) div(v *Div) *Doc {
	contents := w.blockList(v.Blocks)
	var anchor *Doc = dEmpty
	if v.Attr.ID != "" {
		anchor = Lit("<<" + v.Attr.ID + ">>")
	}
	if len(v.Attr.Classes) > 0 {
		cls := v.Attr.Classes[0]
		return Cat(Above(anchor, Cat(Lit("#+begin_"+cls), dCR, contents, dCR, Lit("#+end_"+cls))), dBlank)
	}
	if anchor.IsEmpty() {
		return contents
	}
	return Above(anchor, contents)
}

func (w *orgWriter) header(v *Header) *Doc {
	stars := strings.Repeat("*", v.Level)
	contents := w.inlines(v.Inlines)
	var props []*Doc
	if v.Attr.ID != "" {
		props = append(props, Lit(":CUSTOM_ID: "+v.Attr.ID))
	}
	for _, c := range v.Attr.Classes {
		if c == "unnumbered" {
			props = append(props, Lit(":UNNUMBERED: t"))
		} else {
			props = append(props, Lit(":CLASS: "+c))
		}
	}
	for _, kv := range v.Attr.KVs {
		props = append(props, Lit(":"+kv[0]+": "+kv[1]))
	}
	h := Cat(Lit(stars+" "), contents)
	if len(props) > 0 {
		h = Above(h, Vcat(append(append([]*Doc{Lit(":PROPERTIES:")}, props...), Lit(":END:"))))
	}
	return Cat(h, dCR)
}

func (w *orgWriter) codeBlock(v *CodeBlock) *Doc {
	var name *Doc = dEmpty
	if v.Attr.ID != "" {
		name = Lit("#+name: " + v.Attr.ID)
	}
	if len(v.Attr.Classes) == 0 {
		return Cat(Above(name, Cat(Lit("#+begin_example"), dCR, Flush(Lit(v.Text)), dCR, Lit("#+end_example"))), dBlank)
	}
	lang := v.Attr.Classes[0]
	if lang == "numberLines" && len(v.Attr.Classes) > 1 {
		lang = v.Attr.Classes[1]
	}
	params := ""
	if v.Attr.HasClass("numberLines") {
		params = " -n"
		if st, ok := v.Attr.Get("startFrom"); ok {
			params += " " + st
		}
	}
	return Cat(Above(name, Cat(Lit("#+begin_src "+lang+params), dCR, Flush(Lit(v.Text)), dCR, Lit("#+end_src"))), dBlank)
}

func (w *orgWriter) figure(v *Figure) *Doc {
	capIls := blocksToInlines(v.Caption.Long)
	var capDoc *Doc = dEmpty
	if len(capIls) > 0 {
		capDoc = Cat(Lit("#+caption: "), w.inlines(capIls))
	}
	var name *Doc = dEmpty
	if v.Attr.ID != "" {
		name = Lit("#+name: " + v.Attr.ID)
	}
	return Cat(Vcat(filterEmpty([]*Doc{capDoc, name, w.blockList(v.Blocks)})), dBlank)
}

func (w *orgWriter) table(t *Table) *Doc {
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	render := func(cells [][]Block) []*Doc {
		var out []*Doc
		for i := 0; i < ncols; i++ {
			if i < len(cells) {
				out = append(out, NoWrap(w.blockList(cells[i])))
			} else {
				out = append(out, dEmpty)
			}
		}
		return out
	}
	headless := allEmptyCells(lt.headers)
	heads := render(lt.headers)
	var rows [][]*Doc
	for _, r := range lt.rows {
		rows = append(rows, render(r))
	}
	widths := make([]int, ncols)
	for i := 0; i < ncols; i++ {
		m := 1
		if !headless {
			if o := heads[i].Offset(); o > m {
				m = o
			}
		}
		for _, r := range rows {
			if o := r[i].Offset(); o > m {
				m = o
			}
		}
		widths[i] = m
	}
	mkRow := func(cs []*Doc) *Doc {
		var parts []string
		for i, c := range cs {
			s := strings.TrimRight(Render(c, 0), "\n")
			parts = append(parts, " "+s+strings.Repeat(" ", widths[i]-strWidth(s))+" ")
		}
		return Lit("|" + strings.Join(parts, "|") + "|")
	}
	var lines []*Doc
	if !headless {
		lines = append(lines, mkRow(heads))
		var seps []string
		for _, wd := range widths {
			seps = append(seps, strings.Repeat("-", wd+2))
		}
		lines = append(lines, Lit("|"+strings.Join(seps, "+")+"|"))
	}
	for _, r := range rows {
		lines = append(lines, mkRow(r))
	}
	tbl := Vcat(lines)
	if len(lt.caption) > 0 {
		tbl = Above(tbl, Cat(Lit("#+caption: "), w.inlines(lt.caption)))
	}
	return Cat(tbl, dBlank)
}

func (w *orgWriter) notesDoc() *Doc {
	var ds []*Doc
	for i, n := range w.notes {
		m := "[fn:" + strconv.Itoa(i+1) + "] "
		ds = append(ds, Hang(len(m), Lit(m), n))
	}
	return Vsep(ds)
}

func orgEscape(s string) string {
	return s
}

func (w *orgWriter) inlines(xs []Inline) *Doc {
	var ds []*Doc
	for i, x := range xs {
		d := w.inline(x)
		if i == 0 {
			if s, ok := x.(*Str); ok && s.Text != "" {
				c := []rune(s.Text)[0]
				if c == '*' || c == '#' || c == '|' {
					d = Cat(Lit("\u200b"), d)
				}
			}
		}
		ds = append(ds, d)
	}
	return Cat(ds...)
}

func isOrgURL(u string) bool {
	return isURIScheme(u) || strings.HasPrefix(u, "#") || strings.HasPrefix(u, "/") || strings.HasPrefix(u, "./") || strings.HasPrefix(u, "../") || strings.HasPrefix(u, "file:")
}

func orgLinkTarget(u string) string {
	if isOrgURL(u) {
		return u
	}
	return "file:" + u
}

func (w *orgWriter) inline(x Inline) *Doc {
	switch v := x.(type) {
	case *Str:
		return Lit(v.Text)
	case *Space:
		return dSpace
	case *SoftBreak:
		if w.opts.Wrap == WrapPreserve {
			return dCR
		}
		return dSpace
	case *LineBreak:
		return Cat(Lit("\\\\"), dCR)
	case *Emph:
		return Cat(Lit("/"), w.inlines(v.Inlines), Lit("/"))
	case *Strong:
		return Cat(Lit("*"), w.inlines(v.Inlines), Lit("*"))
	case *Underline:
		return Cat(Lit("_"), w.inlines(v.Inlines), Lit("_"))
	case *Strikeout:
		return Cat(Lit("+"), w.inlines(v.Inlines), Lit("+"))
	case *Superscript:
		return Cat(Lit("^{"), w.inlines(v.Inlines), Lit("}"))
	case *Subscript:
		return Cat(Lit("_{"), w.inlines(v.Inlines), Lit("}"))
	case *SmallCaps:
		return w.inlines(v.Inlines)
	case *Quoted:
		if v.Type == SingleQuote {
			return Cat(Lit("\u2018"), w.inlines(v.Inlines), Lit("\u2019"))
		}
		return Cat(Lit("\u201c"), w.inlines(v.Inlines), Lit("\u201d"))
	case *Cite:
		return w.inlines(v.Inlines)
	case *Code:
		return Lit("=" + v.Text + "=")
	case *Math:
		w.hasMath = true
		if v.Type == InlineMath {
			return Lit("\\(" + v.Text + "\\)")
		}
		return Lit("\\[" + v.Text + "\\]")
	case *RawInline:
		if v.Format == "org" || v.Format == "latex" || v.Format == "tex" {
			return Lit(v.Text)
		}
		return dEmpty
	case *Link:
		txt := stringify(v.Inlines)
		u := v.Target.URL
		if len(v.Inlines) == 1 && txt == u && isURIScheme(u) {
			return Lit("[[" + u + "]]")
		}
		return Cat(Lit("[["+orgLinkTarget(u)+"]["), w.inlines(v.Inlines), Lit("]]"))
	case *Image:
		return Lit("[[" + orgLinkTarget(v.Target.URL) + "]]")
	case *Note:
		ww := &orgWriter{opts: w.opts}
		c := ww.blockList(v.Blocks)
		w.notes = append(w.notes, c)
		return Lit("[fn:" + strconv.Itoa(len(w.notes)) + "]")
	case *Span:
		c := w.inlines(v.Inlines)
		if v.Attr.ID != "" {
			return Cat(Lit("<<"+v.Attr.ID+">>"), c)
		}
		return c
	}
	return dEmpty
}
