package main

import (
	"strings"
)

type mwWriter struct {
	opts      *WriterOptions
	notes     bool
	useTags   bool
	listLevel string
}

func writeMediaWiki(doc *Pandoc, opts *WriterOptions) string {
	w := &mwWriter{opts: opts}
	body := w.blockList(doc.Blocks)
	if w.notes {
		body += "\n<references />\n"
	}
	if !opts.Standalone {
		return strings.TrimRight(body, "\n") + "\n"
	}
	tpl, ok := getTemplate(opts, "mediawiki")
	if !ok {
		return body
	}
	ctx := metaToContext(doc.Meta, func(bs []Block) *Doc {
		ww := &mwWriter{opts: opts}
		return Lit(strings.TrimRight(ww.blockList(bs), "\n"))
	}, func(ils []Inline) *Doc {
		ww := &mwWriter{opts: opts}
		return Lit(ww.inlines(ils))
	})
	addVariables(ctx, opts)
	ctx["body"] = Lit(strings.TrimRight(body, "\n"))
	if opts.TOC {
		defField(ctx, "toc", true)
	}
	d, err := renderTemplateDoc(tpl, ctx, "mediawiki")
	if err != nil {
		return body
	}
	return strings.TrimRight(Render(d, 0), "\n") + "\n"
}

func (w *mwWriter) blockList(bs []Block) string {
	var parts []string
	for _, b := range bs {
		parts = append(parts, w.block(b))
	}
	return strings.Join(parts, "\n")
}

func mwEscape(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
}

func tagWithAttrsMW(tag string, a Attr) string {
	return tagWithAttrsStr(tag, a)
}

func startsWithListMarker(s string) bool {
	return strings.HasPrefix(s, "*") || strings.HasPrefix(s, "#") || strings.HasPrefix(s, ":") || strings.HasPrefix(s, ";")
}

func (w *mwWriter) block(b Block) string {
	switch v := b.(type) {
	case *Div:
		return tagWithAttrsMW("div", v.Attr) + "\n\n" + w.blockList(v.Blocks) + "\n\n</div>"
	case *Plain:
		return w.inlines(v.Inlines)
	case *Para:
		c := w.inlines(v.Inlines)
		if w.useTags {
			return "<p>" + c + "</p>"
		}
		esc := ""
		if startsWithListMarker(c) {
			esc = "<nowiki></nowiki>"
		}
		if w.listLevel == "" {
			return esc + c + "\n"
		}
		return esc + c
	case *LineBlock:
		var ils []Inline
		for i, l := range v.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return w.block(&Para{ils})
	case *RawBlock:
		if v.Format == "mediawiki" || v.Format == "html" {
			return v.Text
		}
		return ""
	case *HorizontalRule:
		return "\n-----\n"
	case *Header:
		auto := strings.ReplaceAll(stringify(v.Inlines), " ", "_")
		c := w.inlines(v.Inlines)
		eqs := strings.Repeat("=", v.Level)
		pre := ""
		if v.Attr.ID != "" && v.Attr.ID != auto {
			pre = "<span id=\"" + v.Attr.ID + "\"></span>\n"
		}
		return pre + eqs + " " + c + " " + eqs + "\n"
	case *CodeBlock:
		lang := ""
		for _, c := range v.Attr.Classes {
			if l := canonicalLang(c); l != "" {
				lang = c
				break
			}
		}
		if lang == "" {
			cls := ""
			if len(v.Attr.Classes) > 0 {
				cls = " class=\"" + strings.Join(v.Attr.Classes, " ") + "\""
			}
			return "<pre" + cls + ">" + mwEscape(v.Text) + "</pre>"
		}
		numberLines := v.Attr.HasClass("number") || v.Attr.HasClass("numberLines") || v.Attr.HasClass("number-lines")
		s := "<syntaxhighlight lang=\"" + lang + "\""
		if numberLines {
			s += " line"
		}
		if st, ok := v.Attr.Get("startFrom"); ok {
			s += " start=\"" + st + "\""
		}
		return s + ">" + v.Text + "</syntaxhighlight>"
	case *BlockQuote:
		return "<blockquote>" + w.blockList(v.Blocks) + "</blockquote>"
	case *Table:
		return w.table(v)
	case *BulletList:
		return w.list(v, "ul", "*", v.Items, "")
	case *OrderedList:
		attrs := ""
		if v.Attrs.Start != 1 {
			attrs += " start=\"" + itoa(v.Attrs.Start) + "\""
		}
		if v.Attrs.Style != DefaultStyle {
			attrs += " style=\"list-style-type: " + camelToHyphen(listStyleName(v.Attrs.Style)) + ";\""
		}
		return w.list(v, "ol", "#", v.Items, attrs)
	case *DefinitionList:
		tags := w.useTags || !isSimpleMWList(v)
		if tags {
			old := w.useTags
			w.useTags = true
			var items []string
			for _, it := range v.Items {
				items = append(items, w.defItem(it))
			}
			w.useTags = old
			return "<dl>\n" + strings.Join(items, "\n") + "</dl>\n"
		}
		old := w.listLevel
		w.listLevel += ";"
		var items []string
		for _, it := range v.Items {
			items = append(items, w.defItem(it))
		}
		w.listLevel = old
		end := ""
		if old == "" {
			end = "\n"
		}
		return strings.Join(items, "\n") + end
	case *Figure:
		return w.figure(v)
	}
	return ""
}

func camelToHyphen(s string) string {
	var sb strings.Builder
	for i, c := range s {
		if c >= 'A' && c <= 'Z' {
			if i > 0 {
				sb.WriteRune('-')
			}
			sb.WriteRune(c + 32)
		} else {
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *mwWriter) list(b Block, tag, marker string, items [][]Block, attrs string) string {
	tags := w.useTags || !isSimpleMWList(b)
	if tags {
		old := w.useTags
		w.useTags = true
		var cs []string
		for _, it := range items {
			cs = append(cs, w.listItem(it))
		}
		w.useTags = old
		return "<" + tag + attrs + ">\n" + strings.Join(cs, "\n") + "</" + tag + ">\n"
	}
	old := w.listLevel
	w.listLevel += marker
	var cs []string
	for _, it := range items {
		cs = append(cs, w.listItem(it))
	}
	w.listLevel = old
	end := ""
	if old == "" {
		end = "\n"
	}
	return strings.Join(cs, "\n") + end
}

func (w *mwWriter) listItem(bs []Block) string {
	c := w.blockList(bs)
	if w.useTags {
		return "<li>" + c + "</li>"
	}
	return w.listLevel + " " + c
}

func (w *mwWriter) defItem(it DefItem) string {
	label := w.inlines(it.Term)
	var cs []string
	for _, d := range it.Defs {
		cs = append(cs, w.blockList(d))
	}
	if w.useTags {
		var dd []string
		for _, c := range cs {
			dd = append(dd, "<dd>"+c+"</dd>")
		}
		return "<dt>" + label + "</dt>\n" + strings.Join(dd, "\n")
	}
	marker := w.listLevel
	var dd []string
	for _, c := range cs {
		dd = append(dd, marker[:len(marker)-1]+": "+c)
	}
	return marker + " " + label + "\n" + strings.Join(dd, "\n")
}

func isSimpleMWList(b Block) bool {
	switch v := b.(type) {
	case *BulletList:
		for _, it := range v.Items {
			if !isSimpleMWItem(it) {
				return false
			}
		}
		return true
	case *OrderedList:
		for _, it := range v.Items {
			if !isSimpleMWItem(it) {
				return false
			}
		}
		return v.Attrs.Start == 1 && (v.Attrs.Style == DefaultStyle || v.Attrs.Style == Decimal)
	case *DefinitionList:
		for _, it := range v.Items {
			for _, d := range it.Defs {
				if !isSimpleMWItem(d) {
					return false
				}
			}
		}
		return true
	}
	return false
}

func isSimpleMWItem(bs []Block) bool {
	switch len(bs) {
	case 0:
		return true
	case 1:
		switch bs[0].(type) {
		case *Plain, *Para:
			return true
		case *BulletList, *OrderedList, *DefinitionList:
			return isSimpleMWList(bs[0])
		}
		return false
	case 2:
		switch bs[0].(type) {
		case *Plain, *Para:
		default:
			return false
		}
		switch bs[1].(type) {
		case *BulletList, *OrderedList, *DefinitionList:
			return isSimpleMWList(bs[1])
		}
		return false
	}
	return false
}

func (w *mwWriter) figure(v *Figure) string {
	if len(v.Blocks) == 1 {
		if pl, ok := v.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok {
				capt := w.inlines(blocksToInlines(v.Caption.Long))
				opt := w.imageDims(img.Attr)
				parts := []string{"File:" + img.Target.URL, "thumb", "none"}
				if opt != "" {
					parts = append(parts, opt)
				}
				alt := stringify(img.Inlines)
				if alt != "" {
					parts = append(parts, "alt="+alt)
				}
				if capt != "" {
					parts = append(parts, capt)
				}
				return "[[" + strings.Join(parts, "|") + "]]\n"
			}
		}
	}
	return w.blockList(v.Blocks)
}

func (w *mwWriter) imageDims(a Attr) string {
	wd, _ := a.Get("width")
	ht, _ := a.Get("height")
	toPx := func(s string) string {
		d, ok := lengthToDim(s)
		if !ok {
			return ""
		}
		switch d.unit {
		case "px":
			return itoa(int(d.val))
		case "%":
			return ""
		}
		return ""
	}
	pw, ph := toPx(wd), toPx(ht)
	switch {
	case pw != "" && ph != "":
		return pw + "x" + ph + "px"
	case pw != "":
		return pw + "px"
	case ph != "":
		return "x" + ph + "px"
	}
	return ""
}

func (w *mwWriter) table(t *Table) string {
	lt := toLegacyTable(t)
	var sb strings.Builder
	sb.WriteString("{| class=\"wikitable\"\n")
	if len(lt.caption) > 0 {
		sb.WriteString("|+ " + w.inlines(lt.caption) + "\n")
	}
	widthsSet := false
	for _, x := range lt.widths {
		if x != 0 {
			widthsSet = true
		}
	}
	cell := func(marker string, i int, c []Block) string {
		al := ""
		if i < len(lt.aligns) {
			switch lt.aligns[i] {
			case AlignLeft:
				al = "text-align: left;"
			case AlignRight:
				al = "text-align: right;"
			case AlignCenter:
				al = "text-align: center;"
			}
		}
		var attrs []string
		if al != "" || (widthsSet && i < len(lt.widths) && lt.widths[i] != 0) {
			style := al
			if widthsSet && i < len(lt.widths) && lt.widths[i] != 0 && marker == "!" {
				style = "width:" + percent(lt.widths[i]) + ";" + al
			}
			if style != "" {
				attrs = append(attrs, "style=\""+style+"\"")
			}
		}
		content := w.blockList(c)
		if len(attrs) > 0 {
			return marker + " " + strings.Join(attrs, " ") + "| " + content
		}
		return marker + " " + content
	}
	if !allEmptyCells(lt.headers) {
		sb.WriteString("|-\n")
		for i, h := range lt.headers {
			sb.WriteString(cell("!", i, h) + "\n")
		}
	}
	for _, r := range lt.rows {
		sb.WriteString("|-\n")
		for i, c := range r {
			sb.WriteString(cell("|", i, c) + "\n")
		}
	}
	sb.WriteString("|}\n")
	return sb.String()
}

func (w *mwWriter) inlines(xs []Inline) string {
	var sb strings.Builder
	for _, x := range xs {
		sb.WriteString(w.inline(x))
	}
	return sb.String()
}

func (w *mwWriter) inline(x Inline) string {
	switch v := x.(type) {
	case *Str:
		return mwEscape(v.Text)
	case *Space:
		return " "
	case *SoftBreak:
		if w.opts.Wrap == WrapPreserve && w.listLevel == "" {
			return "\n"
		}
		return " "
	case *LineBreak:
		return "<br />\n"
	case *Emph:
		return "''" + w.inlines(v.Inlines) + "''"
	case *Underline:
		return "<u>" + w.inlines(v.Inlines) + "</u>"
	case *Strong:
		return "'''" + w.inlines(v.Inlines) + "'''"
	case *Strikeout:
		return "<s>" + w.inlines(v.Inlines) + "</s>"
	case *Superscript:
		return "<sup>" + w.inlines(v.Inlines) + "</sup>"
	case *Subscript:
		return "<sub>" + w.inlines(v.Inlines) + "</sub>"
	case *SmallCaps:
		return w.inlines(v.Inlines)
	case *Quoted:
		if v.Type == SingleQuote {
			return "\u2018" + w.inlines(v.Inlines) + "\u2019"
		}
		return "\u201c" + w.inlines(v.Inlines) + "\u201d"
	case *Cite:
		return w.inlines(v.Inlines)
	case *Code:
		return "<code>" + mwEscape(v.Text) + "</code>"
	case *Math:
		d := "inline"
		if v.Type == DisplayMath {
			d = "block"
		}
		return "<math display=\"" + d + "\">" + v.Text + "</math>"
	case *RawInline:
		if v.Format == "mediawiki" || v.Format == "html" {
			return v.Text
		}
		return ""
	case *Link:
		label := w.inlines(v.Inlines)
		src := v.Target.URL
		if len(v.Inlines) == 1 {
			if s, ok := v.Inlines[0].(*Str); ok && isURIScheme(src) && (escapeURI(s.Text) == src || "mailto:"+s.Text == src) {
				return src
			}
		}
		if isURIScheme(src) {
			return "[" + src + " " + label + "]"
		}
		s := strings.TrimPrefix(src, "/")
		return "[[" + s + "|" + label + "]]"
	case *Image:
		alt := w.inlines(v.Inlines)
		dims := w.imageDims(v.Attr)
		txt := ""
		if v.Target.Title != "" && alt == "" {
			txt = "|" + v.Target.Title
		} else if alt != "" {
			txt = "|" + alt
		}
		parts := []string{"File:" + v.Target.URL}
		if dims != "" {
			parts = append(parts, dims)
		}
		return "[[" + strings.Join(parts, "|") + txt + "]]"
	case *Note:
		w.notes = true
		ww := &mwWriter{opts: w.opts}
		c := ww.blockList(v.Blocks)
		return "<ref>" + strings.TrimRight(c, "\n") + "</ref>"
	case *Span:
		return tagWithAttrsMW("span", v.Attr) + w.inlines(v.Inlines) + "</span>"
	}
	return ""
}
