		al := ""
		if i < len(lt.aligns) {
			switch lt.aligns[i] {
			case AlignLeft:
				al = "text-align: left;"
			case AlignRight:
				al = "text-align: right;"
			case AlignCenter:
				al = "text-align: center;"
			}
		}
		var attrs []string
		if al != "" || (widthsSet && i < len(lt.widths) && lt.widths[i] != 0) {
			style := al
			if widthsSet && i < len(lt.widths) && lt.widths[i] != 0 && marker == "!" {
				style = "width:" + percent(lt.widths[i]) + ";" + al
			}
			if style != "" {
				attrs = append(attrs, "style=\""+style+"\"")
			}
		}
		content := w.blockList(c)
		if len(attrs) > 0 {
			return marker + " " + strings.Join(attrs, " ") + "| " + content
		}
		return marker + " " + content
	}
	if !allEmptyCells(lt.headers) {
		sb.WriteString("|-\n")
		for i, h := range lt.headers {
			sb.WriteString(cell("!", i, h) + "\n")
		}
	}
	for _, r := range lt.rows {
		sb.WriteString("|-\n")
		for i, c := range r {
			sb.WriteString(cell("|", i, c) + "\n")
		}
	}
	sb.WriteString("|}\n")
	return sb.String()
}

func (w *mwWriter) inlines(xs []Inline) string {
	var sb strings.Builder
	for _, x := range xs {
		sb.WriteString(w.inline(x))
	}
	return sb.String()
}

func (w *mwWriter) inline(x Inline) string {
	switch v := x.(type) {
	case *Str:
		return mwEscape(v.Text)
	case *Space:
		return " "
	case *SoftBreak:
		if w.opts.Wrap == WrapPreserve && w.listLevel == "" {
			return "\n"
		}
		return " "
	case *LineBreak:
		return "<br />\n"
	case *Emph:
		return "''" + w.inlines(v.Inlines) + "''"
	case *Underline:
		return "<u>" + w.inlines(v.Inlines) + "</u>"
	case *Strong:
		return "'''" + w.inlines(v.Inlines) + "'''"
	case *Strikeout:
		return "<s>" + w.inlines(v.Inlines) + "</s>"
	case *Superscript:
		return "<sup>" + w.inlines(v.Inlines) + "</sup>"
	case *Subscript:
		return "<sub>" + w.inlines(v.Inlines) + "</sub>"
	case *SmallCaps:
		return w.inlines(v.Inlines)
	case *Quoted:
		if v.Type == SingleQuote {
			return "\u2018" + w.inlines(v.Inlines) + "\u2019"
		}
		return "\u201c" + w.inlines(v.Inlines) + "\u201d"
	case *Cite:
		return w.inlines(v.Inlines)
	case *Code:
		return "<code>" + mwEscape(v.Text) + "</code>"
	case *Math:
		d := "inline"
		if v.Type == DisplayMath {
			d = "block"
		}
		return "<math display=\"" + d + "\">" + v.Text + "</math>"
	case *RawInline:
		if v.Format == "mediawiki" || v.Format == "html" {
			return v.Text
		}
		return ""
	case *Link:
		label := w.inlines(v.Inlines)
		src := v.Target.URL
		if len(v.Inlines) == 1 {
			if s, ok := v.Inlines[0].(*Str); ok && isURIScheme(src) && (escapeURI(s.Text) == src || "mailto:"+s.Text == src) {
				return src
			}
		}
		if isURIScheme(src) {
			return "[" + src + " " + label + "]"
		}
		s := strings.TrimPrefix(src, "/")
		return "[[" + s + "|" + label + "]]"
	case *Image:
		alt := w.inlines(v.Inlines)
		dims := w.imageDims(v.Attr)
		txt := ""
		if v.Target.Title != "" && alt == "" {
			txt = "|" + v.Target.Title
		} else if alt != "" {
			txt = "|" + alt
		}
		parts := []string{"File:" + v.Target.URL}
		if dims != "" {
			parts = append(parts, dims)
		}
		return "[[" + strings.Join(parts, "|") + txt + "]]"
	case *Note:
		w.notes = true
		ww := &mwWriter{opts: w.opts}
		c := ww.blockList(v.Blocks)
		return "<ref>" + strings.TrimRight(c, "\n") + "</ref>"
	case *Span:
		return tagWithAttrsMW("span", v.Attr) + w.inlines(v.Inlines) + "</span>"
	}
	return ""
}
