package main

import (
	"strings"
)

type dbWriter struct {
	opts *WriterOptions
	v5   bool
}

func writeDocBook(doc *Pandoc, opts *WriterOptions, v5 bool) string {
	w := &dbWriter{opts: opts, v5: v5}
	startLvl := 1
	switch opts.TopLevelDivision {
	case "part":
		startLvl = -1
	case "chapter":
		startLvl = 0
	}
	bs := doc.Blocks
	secs := makeSections(opts.NumberSections, nil, bs)
	if startLvl != 1 {
		secs = shiftSectionLevels(secs, startLvl-1)
	}
	body := w.blocks(secs)
	cols := opts.Columns
	if opts.Wrap != WrapAuto {
		cols = 0
	}
	out := Render(body, cols)
	if !opts.Standalone {
		return strings.TrimRight(out, "\n") + "\n"
	}
	format := "docbook4"
	if v5 {
		format = "docbook5"
	}
	tpl, ok := getTemplate(opts, format)
	if !ok {
		return out
	}
	ctx := metaToContext(doc.Meta, func(bs []Block) *Doc {
		return Lit(strings.TrimRight(Render(w.blocks(bs), cols), "\n"))
	}, func(ils []Inline) *Doc {
		return Lit(Render(w.inlines(ils), cols))
	})
	addVariables(ctx, opts)
	ctx["body"] = Lit(strings.TrimRight(out, "\n"))
	if as := docAuthors(doc.Meta); len(as) > 0 {
		var avs []tval
		for _, a := range as {
			s := stringify(a)
			first, last := splitName(s)
			avs = append(avs, tmap{"firstname": escapeStringForXML(first), "surname": escapeStringForXML(last)})
		}
		ctx["author"] = avs
	}
	defField(ctx, "mathml", false)
	d, err := renderTemplateDoc(tpl, ctx, format)
	if err != nil {
		return out
	}
	return strings.TrimRight(Render(d, 0), "\n") + "\n"
}

func splitName(s string) (string, string) {
	if i := strings.Index(s, ","); i >= 0 {
		return strings.TrimSpace(s[i+1:]), strings.TrimSpace(s[:i])
	}
	f := strings.Fields(s)
	if len(f) <= 1 {
		return "", s
	}
	return strings.Join(f[:len(f)-1], " "), f[len(f)-1]
}

func shiftSectionLevels(bs []Block, delta int) []Block {
	var out []Block
	for _, b := range bs {
		if d, h, ok := isSectionDiv(b); ok {
			nh := &Header{h.Level + delta, h.Attr, h.Inlines}
			nbs := append([]Block{nh}, shiftSectionLevels(d.Blocks[1:], delta)...)
			out = append(out, &Div{d.Attr, nbs})
			continue
		}
		out = append(out, b)
	}
	return out
}

func (w *dbWriter) idName() string {
	if w.v5 {
		return "xml:id"
	}
	return "id"
}

func (w *dbWriter) blocks(bs []Block) *Doc {
	var ds []*Doc
	for _, b := range bs {
		ds = append(ds, w.block(b))
	}
	return Vcat(filterEmpty(ds))
}

func plainToPara(b Block) Block {
	if p, ok := b.(*Plain); ok {
		return &Para{p.Inlines}
	}
	return b
}

func hasLineBreaksIl(xs []Inline) bool {
	return hasLineBreak(xs)
}

func (w *dbWriter) block(b Block) *Doc {
	switch v := b.(type) {
	case *Div:
		if d, h, ok := isSectionDiv(v); ok {
			return w.section(d, h)
		}
		ident := v.Attr.ID
		var idAttr [][2]string
		if ident != "" {
			idAttr = [][2]string{{w.idName(), w.opts.IDPrefix + ident}}
		}
		admon := map[string]bool{"caution": true, "danger": true, "important": true, "note": true, "tip": true, "warning": true}
		if len(v.Attr.Classes) > 0 && admon[v.Attr.Classes[0]] {
			bs := v.Blocks
			var titleDoc *Doc = dEmpty
			if len(bs) > 0 {
				if d2, ok := bs[0].(*Div); ok && d2.Attr.HasClass("title") {
					titleDoc = xInTags(false, "title", nil, w.inlines(blocksToInlines(d2.Blocks)))
					bs = bs[1:]
				}
			}
			return xInTags(true, v.Attr.Classes[0], idAttr, Above(titleDoc, w.divBody(nil, bs)))
		}
		return w.divBody(idAttr, v.Blocks)
	case *Header:
		return dEmpty
	case *Plain:
		return w.inlines(v.Inlines)
	case *Para:
		if hasLineBreaksIl(v.Inlines) {
			return Flush(NoWrap(xInTags(false, "literallayout", nil, w.inlines(v.Inlines))))
		}
		return xInTagsIndented("para", nil, w.inlines(v.Inlines))
	case *LineBlock:
		var ils []Inline
		for i, l := range v.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return w.block(&Para{ils})
	case *BlockQuote:
		return xInTagsIndented("blockquote", nil, w.blocks(v.Blocks))
	case *CodeBlock:
		lang := ""
		for _, c := range v.Attr.Classes {
			if canonicalLang(c) != "" {
				lang = c
				break
			}
		}
		la := ""
		if lang != "" {
			la = " language=\"" + escapeStringForXML(lang) + "\""
		}
		return Cat(Lit("<programlisting"+la+">"), dCR, Flush(Cat(Lit(escapeStringForXML(v.Text)), dCR, Lit("</programlisting>"))))
	case *BulletList:
		var attrs [][2]string
		if isTightList(v.Items) {
			attrs = append(attrs, [2]string{"spacing", "compact"})
		}
		return xInTags(true, "itemizedlist", attrs, w.listItems(v.Items))
	case *OrderedList:
		if len(v.Items) == 0 {
			return dEmpty
		}
		var attrs [][2]string
		switch v.Attrs.Style {
		case Decimal, Example:
			attrs = append(attrs, [2]string{"numeration", "arabic"})
		case UpperAlpha:
			attrs = append(attrs, [2]string{"numeration", "upperalpha"})
		case LowerAlpha:
			attrs = append(attrs, [2]string{"numeration", "loweralpha"})
		case UpperRoman:
			attrs = append(attrs, [2]string{"numeration", "upperroman"})
		case LowerRoman:
			attrs = append(attrs, [2]string{"numeration", "lowerroman"})
		}
		if isTightList(v.Items) {
			attrs = append(attrs, [2]string{"spacing", "compact"})
		}
		if v.Attrs.Start != 1 {
			attrs = append(attrs, [2]string{"startingnumber", itoa(v.Attrs.Start)})
		}
		return xInTags(true, "orderedlist", attrs, w.listItems(v.Items))
	case *DefinitionList:
		var items []*Doc
		for _, it := range v.Items {
			term := xInTagsIndented("term", nil, w.inlines(it.Term))
			var defs []Block
			for _, d := range it.Defs {
				for _, b := range d {
					defs = append(defs, plainToPara(b))
				}
			}
			items = append(items, xInTags(true, "varlistentry", nil, Above(term, xInTags(true, "listitem", nil, w.blocks(defs)))))
		}
		var attrs [][2]string
		return xInTags(true, "variablelist", attrs, Vcat(items))
	case *HorizontalRule:
		return dEmpty
	case *RawBlock:
		if v.Format == "docbook" || v.Format == "docbook4" || v.Format == "docbook5" {
			return Lit(v.Text)
		}
		return dEmpty
	case *Table:
		return w.table(v)
	case *Figure:
		return w.figure(v)
	}
	return dEmpty
}

func (w *dbWriter) divBody(idAttr [][2]string, bs []Block) *Doc {
	if len(bs) == 1 {
		if p, ok := bs[0].(*Para); ok {
			if hasLineBreaksIl(p.Inlines) {
				return Flush(NoWrap(xInTags(false, "literallayout", idAttr, w.inlines(p.Inlines))))
			}
			return xInTagsIndented("para", idAttr, w.inlines(p.Inlines))
		}
	}
	var nbs []Block
	for _, b := range bs {
		nbs = append(nbs, plainToPara(b))
	}
	c := w.blocks(nbs)
	if len(idAttr) > 0 {
		return Above(xSelfClosing("anchor", idAttr), c)
	}
	return c
}

func (w *dbWriter) listItems(items [][]Block) *Doc {
	var ds []*Doc
	for _, it := range items {
		var bs []Block
		for _, b := range it {
			bs = append(bs, plainToPara(b))
		}
		ds = append(ds, xInTags(true, "listitem", nil, w.blocks(bs)))
	}
	return Vcat(ds)
}

func (w *dbWriter) section(d *Div, h *Header) *Doc {
	bs := d.Blocks[1:]
	if len(bs) == 0 {
		bs = []Block{&Para{}}
	}
	lvl := h.Level
	var tag string
	switch {
	case lvl == -1:
		tag = "part"
	case lvl == 0:
		tag = "chapter"
	case lvl >= 1 && lvl <= 5:
		if w.v5 {
			tag = "section"
		} else {
			tag = "sect" + itoa(lvl)
		}
	default:
		tag = "simplesect"
	}
	var attrs [][2]string
	if w.v5 && w.topLevel(lvl) {
		attrs = append(attrs, [2]string{"xmlns", "http://docbook.org/ns/docbook"}, [2]string{"xmlns:xlink", "http://www.w3.org/1999/xlink"})
	}
	if d.Attr.ID != "" {
		attrs = append(attrs, [2]string{w.idName(), w.opts.IDPrefix + d.Attr.ID})
	}
	title := xInTags(false, "title", nil, w.inlines(h.Inlines))
	return xInTags(true, tag, attrs, Above(title, w.blocks(bs)))
}

func (w *dbWriter) topLevel(lvl int) bool {
	switch w.opts.TopLevelDivision {
	case "part":
		return lvl == -1
	case "chapter":
		return lvl == 0
	}
	return lvl == 1
}

func (w *dbWriter) figure(v *Figure) *Doc {
	capt := w.inlines(blocksToInlines(v.Caption.Long))
	if len(v.Blocks) == 1 {
		if pl, ok := v.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok {
				mo := w.mediaObject("mediaobject", img)
				var attrs [][2]string
				if v.Attr.ID != "" {
					attrs = append(attrs, [2]string{w.idName(), w.opts.IDPrefix + v.Attr.ID})
				}
				return xInTags(true, "figure", attrs, Above(xInTags(false, "title", nil, capt), mo))
			}
		}
	}
	return w.blocks(v.Blocks)
}

func (w *dbWriter) imageAttrs(img *Image) [][2]string {
	attrs := [][2]string{{"fileref", img.Target.URL}}
	for _, dir := range []string{"width", "height"} {
		if v, ok := img.Attr.Get(dir); ok {
			if d, ok := lengthToDim(v); ok {
				attrs = append(attrs, [2]string{dir, d.String()})
			}
		}
	}
	return attrs
}

func (w *dbWriter) mediaObject(tag string, img *Image) *Doc {
	imgDoc := xInTags(true, "imageobject", nil, xSelfClosing("imagedata", w.imageAttrs(img)))
	alt := stringify(img.Inlines)
	var txt *Doc = dEmpty
	if alt != "" {
		if tag == "mediaobject" {
			txt = Lit("<textobject><phrase>" + escapeStringForXML(alt) + "</phrase></textobject>")
		} else {
			txt = xInTags(true, "textobject", nil, xInTags(false, "phrase", nil, w.inlines(img.Inlines)))
		}
	}
	return xInTags(true, tag, nil, Above(imgDoc, txt))
}

func (w *dbWriter) table(t *Table) *Doc {
	lt := toLegacyTable(t)
	var capDoc *Doc = dEmpty
	if len(lt.caption) > 0 {
		capDoc = xInTags(false, "title", nil, w.inlines(lt.caption))
	}
	ncols := len(lt.aligns)
	var colspecs []*Doc
	hasWidths := false
	for _, x := range lt.widths {
		if x != 0 {
			hasWidths = true
		}
	}
	for i, a := range lt.aligns {
		al := "left"
		switch a {
		case AlignRight:
			al = "right"
		case AlignCenter:
			al = "center"
		}
		attrs := [][2]string{}
		if hasWidths {
			attrs = append(attrs, [2]string{"colwidth", haskellShowDouble(lt.widths[i]*100) + "*"})
		}
		attrs = append(attrs, [2]string{"align", al})
		colspecs = append(colspecs, xSelfClosing("colspec", attrs))
	}
	row := func(cells [][]Block) *Doc {
		var es []*Doc
		for _, c := range cells {
			var bs []Block
			for _, b := range c {
				bs = append(bs, b)
			}
			es = append(es, xInTagsIndented("entry", nil, w.blocks(bs)))
		}
		return xInTags(true, "row", nil, Vcat(es))
	}
	var head *Doc = dEmpty
	if !allEmptyCells(lt.headers) {
		head = xInTags(true, "thead", nil, row(lt.headers))
	}
	var rows []*Doc
	for _, r := range lt.rows {
		rows = append(rows, row(r))
	}
	body := xInTags(true, "tbody", nil, Vcat(rows))
	tg := xInTags(true, "tgroup", [][2]string{{"cols", itoa(ncols)}}, Vcat(filterEmpty(append(colspecs, head, body))))
	tag := "informaltable"
	if len(lt.caption) > 0 {
		tag = "table"
	}
	return xInTags(true, tag, nil, Above(capDoc, tg))
}

func (w *dbWriter) inlines(xs []Inline) *Doc {
	var ds []*Doc
	for _, x := range xs {
		ds = append(ds, w.inline(x))
	}
	return Cat(ds...)
}

func (w *dbWriter) inline(x Inline) *Doc {
	switch v := x.(type) {
	case *Str:
		return Lit(escapeStringForXML(v.Text))
	case *Space:
		return dSpace
	case *SoftBreak:
		if w.opts.Wrap == WrapPreserve {
			return dCR
		}
		return dSpace
	case *LineBreak:
		return Lit("\n")
	case *Emph:
		return xInTags(false, "emphasis", nil, w.inlines(v.Inlines))
	case *Strong:
		return xInTags(false, "emphasis", [][2]string{{"role", "strong"}}, w.inlines(v.Inlines))
	case *Underline:
		return xInTags(false, "emphasis", [][2]string{{"role", "underline"}}, w.inlines(v.Inlines))
	case *Strikeout:
		return xInTags(false, "emphasis", [][2]string{{"role", "strikethrough"}}, w.inlines(v.Inlines))
	case *Superscript:
		return xInTags(false, "superscript", nil, w.inlines(v.Inlines))
	case *Subscript:
		return xInTags(false, "subscript", nil, w.inlines(v.Inlines))
	case *SmallCaps:
		return xInTags(false, "emphasis", [][2]string{{"role", "smallcaps"}}, w.inlines(v.Inlines))
	case *Quoted:
		return xInTags(false, "quote", nil, w.inlines(v.Inlines))
	case *Cite:
		return w.inlines(v.Inlines)
	case *Code:
		return xInTags(false, "literal", nil, Lit(escapeStringForXML(v.Text)))
	case *Math:
		ils := texToInlines(v.Text, v.Type == DisplayMath)
		if ils == nil {
			return Lit(escapeStringForXML(v.Text))
		}
		return w.inlines(ils)
	case *RawInline:
		if v.Format == "docbook" || v.Format == "docbook4" || v.Format == "docbook5" {
			return Lit(v.Text)
		}
		return dEmpty
	case *Link:
		u := v.Target.URL
		if strings.HasPrefix(u, "mailto:") {
			addr := strings.TrimPrefix(u, "mailto:")
			em := xInTags(false, "email", nil, Lit(escapeStringForXML(addr)))
			if stringify(v.Inlines) == addr {
				return em
			}
			return Cat(w.inlines(v.Inlines), Lit(" ("), em, Lit(")"))
		}
		if strings.HasPrefix(u, "#") {
			return xInTags(false, "link", [][2]string{{"linkend", w.opts.IDPrefix + u[1:]}}, w.inlines(v.Inlines))
		}
		var attrs [][2]string
		if w.v5 {
			attrs = [][2]string{{"xlink:href", u}}
		} else {
			attrs = [][2]string{{"url", u}}
		}
		if v.Attr.HasClass("uri") || v.Attr.HasClass("email") {
			attrs = append(attrs, [2]string{"role", v.Attr.Classes[0]})
		}
		tag := "link"
		if !w.v5 {
			tag = "ulink"
		}
		return xInTags(false, tag, attrs, w.inlines(v.Inlines))
	case *Image:
		return w.mediaObject("inlinemediaobject", v)
	case *Note:
		var bs []Block
		for _, b := range v.Blocks {
			bs = append(bs, plainToPara(b))
		}
		return xInTags(true, "footnote", nil, w.blocks(bs))
	case *Span:
		c := w.inlines(v.Inlines)
		if v.Attr.ID != "" {
			return Cat(xSelfClosing("anchor", [][2]string{{w.idName(), w.opts.IDPrefix + v.Attr.ID}}), c)
		}
		return c
	}
	return dEmpty
}
