package main

import "strings"

func xmlAttrs(attrs [][2]string) string {
	var sb strings.Builder
	for _, a := range attrs {
		sb.WriteString(" " + a[0] + "=\"" + escapeStringForXML(a[1]) + "\"")
	}
	return sb.String()
}

func xInTags(indented bool, tag string, attrs [][2]string, content *Doc) *Doc {
	open := Lit("<" + tag + xmlAttrs(attrs) + ">")
	cl := Lit("</" + tag + ">")
	if indented {
		return Above(Above(open, Nest(2, content)), cl)
	}
	return Cat(open, content, cl)
}

// inTags with indentation where empty content still yields two lines
func xInTagsIndented(tag string, attrs [][2]string, content *Doc) *Doc {
	open := Lit("<" + tag + xmlAttrs(attrs) + ">")
	cl := Lit("</" + tag + ">")
	return Cat(open, dCR, Nest(2, content), dCR, cl)
}

func xSelfClosing(tag string, attrs [][2]string) *Doc {
	return Lit("<" + tag + xmlAttrs(attrs) + " />")
}

func xTextDoc(s string) *Doc {
	e := escapeStringForXML(s)
	if !strings.Contains(e, " ") {
		return Lit(e)
	}
	parts := strings.Split(e, " ")
	var ds []*Doc
	for i, p := range parts {
		if i > 0 {
			ds = append(ds, dSpace)
		}
		ds = append(ds, Lit(p))
	}
	return Cat(ds...)
}
