func (p *mathParser) peek() rune {
	if p.pos < len(p.s) {
		return p.s[p.pos]
	}
	return 0
}

func (p *mathParser) skipWS() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\n' || p.s[p.pos] == '\t') {
		p.pos++
	}
}

func (p *mathParser) cmdName() string {
	// after backslash
	st := p.pos
	if p.pos < len(p.s) && unicode.IsLetter(p.s[p.pos]) {
		for p.pos < len(p.s) && unicode.IsLetter(p.s[p.pos]) {
			p.pos++
		}
		return string(p.s[st:p.pos])
	}
	if p.pos < len(p.s) {
		p.pos++
		return string(p.s[st:p.pos])
	}
	return ""
}

// rawGroup reads {...} returning inner text
func (p *mathParser) rawGroup() (string, bool) {
	p.skipWS()
	if p.peek() != '{' {
		return "", false
	}
	depth := 0
	st := p.pos
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '\\' {
			p.pos += 2
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				p.pos++
				return string(p.s[st+1 : p.pos-1]), true
			}
		}
		p.pos++
	}
	return "", false
}

func (p *mathParser) parseList(endCh rune) []*mexp {
	var out []*mexp
	for {
		p.skipWS()
		if p.err {
			return out
		}
		if p.pos >= len(p.s) {
			if endCh != 0 {
				p.err = true
			}
			return out
		}
		c := p.peek()
		if endCh != 0 && c == endCh {
			p.pos++
			return out
		}
		if c == '}' {
			p.err = true
			return out
		}
		if c == '^' || c == '_' {
			p.pos++
			var base *mexp
			if len(out) > 0 {
				base = out[len(out)-1]
				out = out[:len(out)-1]
			} else {
				base = &mexp{kind: "group"}
			}
			script := p.parseAtom()
			if script == nil {
				p.err = true
				return out
			}
			out = append(out, p.attachScript(base, c, script))
			continue
		}
		if c == '\'' {
			p.pos++
			primes := "′"
			for p.peek() == '\'' {
				p.pos++
				primes += "′"
			}
			var base *mexp
			if len(out) > 0 {
				base = out[len(out)-1]
				out = out[:len(out)-1]
			} else {
				base = &mexp{kind: "group"}
			}
			out = append(out, p.attachScript(base, '^', &mexp{kind: "sym", st: symOrd, s: primes}))
			continue
		}
		e := p.parseAtom()
		if p.err {
			return out
		}
		if e == nil {
			continue
		}
		if e.kind == "group" && len(e.items) == 1 && e.items[0].kind != "styled" {
			out = append(out, e.items[0])
			continue
		}
		if e.kind == "flat" {
			out = append(out, e.items...)
			continue
		}
		out = append(out, e)
	}
}

func (p *mathParser) attachScript(base *mexp, c rune, script *mexp) *mexp {
	isLim := base.kind == "limop"
	switch base.kind {
	case "sub":
		if c == '^' {
			if base.isLim {
				return &mexp{kind: "underover", a: base.a, b: base.b, c: script}
			}
			return &mexp{kind: "subsup", a: base.a, b: base.b, c: script}
		}
	case "sup":
		if c == '_' {
			if base.isLim {
				return &mexp{kind: "underover", a: base.a, b: script, c: base.b}
			}
			return &mexp{kind: "subsup", a: base.a, b: script, c: base.b}
		}
	}
	if c == '^' {
		return &mexp{kind: "sup", a: base, b: script, isLim: isLim}
	}
	return &mexp{kind: "sub", a: base, b: script, isLim: isLim}
}

func (p *mathParser) parseAtom() *mexp {
	p.skipWS()
	if p.pos >= len(p.s) {
		p.err = true
		return nil
	}
	c := p.peek()
	switch {
	case c == '{':
		p.pos++
		items := p.parseList('}')
		return &mexp{kind: "group", items: items}
	case unicode.IsLetter(c):
		p.pos++
		return &mexp{kind: "ident", s: string(c)}
	case c >= '0' && c <= '9':
		st := p.pos
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
		if p.pos+1 < len(p.s) && p.s[p.pos] == '.' && p.s[p.pos+1] >= '0' && p.s[p.pos+1] <= '9' {
			p.pos++
			for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
				p.pos++
			}
		}
		return &mexp{kind: "num", s: string(p.s[st:p.pos])}
	case c == '\\':
		p.pos++
		return p.parseCommand()
	case c == '&' || c == '#' || c == '%':
		p.err = true
		return nil
	case c == '~':
		p.pos++
		return &mexp{kind: "space", width: -1}
	}
	if sv, ok := charSymbols[c]; ok {
		p.pos++
		return &mexp{kind: "sym", st: sv[0].(int), s: sv[1].(string)}
	}
	p.pos++
	return &mexp{kind: "sym", st: symOrd, s: string(c)}
}

func (p *mathParser) parseStyledArg(tt int) *mexp {
	p.skipWS()
	var items []*mexp
	if p.peek() == '{' {
		p.pos++
		items = p.parseList('}')
	} else {
		a := p.parseAtom()
		if a == nil {
			return nil
		}
		items = []*mexp{a}
	}
	return &mexp{kind: "styled", st: tt, items: items}
}

func (p *mathParser) parseCommand() *mexp {
	name := p.cmdName()
	switch name {
	case "frac", "dfrac", "tfrac", "cfrac", "binom", "dbinom", "tbinom", "sqrt", "over", "choose", "begin", "end",
		"\\", "overline", "underline", "overbrace", "underbrace", "ddot", "dddot", "stackrel", "overset", "underset",
		"xrightarrow", "xleftarrow", "substack", "cancel", "boxed", "phantom", "label", "tag", "color", "textcolor":
		p.err = true
		return nil
	case "left", "right", "bigl", "bigr", "Bigl", "Bigr", "biggl", "biggr", "Biggl", "Biggr", "big", "Big", "bigg", "Bigg", "middle":
		p.skipWS()
		if p.peek() == '.' {
			p.pos++
			return &mexp{kind: "flat"}
		}
		a := p.parseAtom()
		return a
	case "text", "textrm", "textnormal", "mbox", "hbox", "textup", "textmd":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "text", st: ttNormal, s: s}
	case "textbf":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "text", st: ttBold, s: s}
	case "textit", "emph", "textsl":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "text", st: ttItalic, s: s}
	case "texttt":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "text", st: ttMono, s: s}
	case "textsf":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "text", st: ttSans, s: s}
	case "mathrm", "rm", "operatorname*":
		return p.parseStyledArg(ttNormal)
	case "operatorname":
		s, ok := p.rawGroup()
		if !ok {
			p.err = true
			return nil
		}
		return &mexp{kind: "op", s: strings.TrimSpace(s)}
	case "mathbf", "bf", "boldsymbol", "bm", "pmb":
		return p.parseStyledArg(ttBold)
	case "mathit", "it":
		return p.parseStyledArg(ttItalic)
	case "mathtt", "tt":
		return p.parseStyledArg(ttMono)
	case "mathsf", "sf":
		return p.parseStyledArg(ttSans)
	case "mathbb", "Bbb":
		return p.parseStyledArg(ttDouble)
	case "mathcal", "mathscr", "cal":
		return p.parseStyledArg(ttScript)
	case "mathfrak", "frak":
		return p.parseStyledArg(ttFraktur)
	case ",", "thinspace":
		return &mexp{kind: "space", width: 3.0 / 18}
	case ":", ">", "medspace":
		return &mexp{kind: "space", width: 4.0 / 18}
	case ";", "thickspace":
		return &mexp{kind: "space", width: 5.0 / 18}
	case "!", "negthinspace":
		return &mexp{kind: "space", width: -3.0 / 18}
	case "quad":
		return &mexp{kind: "space", width: 1}
	case "qquad":
		return &mexp{kind: "space", width: 2}
	case " ":
		return &mexp{kind: "space", width: -1}
	case "displaystyle", "textstyle", "scriptstyle", "scriptscriptstyle", "limits", "nolimits", "nonumber", "notag":
		return &mexp{kind: "flat"}
	}
	if acc, ok := mathAccents[name]; ok {
		arg := p.parseAtom()
		if arg == nil {
			p.err = true
			return nil
		}
		return &mexp{kind: "accent", a: arg, s: string(acc)}
	}
	if s, ok := mathIdentCmds[name]; ok {
		return &mexp{kind: "ident", s: s}
	}
	if mathOperators[name] {
		if limitsOps[name] {
			return &mexp{kind: "limop", s: name, a: &mexp{kind: "op", s: name}}
		}
		return &mexp{kind: "op", s: name}
	}
	if sv, ok := mathSymbols[name]; ok {
		e := &mexp{kind: "sym", st: sv[0].(int), s: sv[1].(string)}
		if limitsOps[name] {
			return &mexp{kind: "limop", s: name, a: e}
		}
		return e
	}
	p.err = true
	return nil
}

func unwrapLimop(e *mexp) *mexp {
	if e != nil && e.kind == "limop" {
		return e.a
	}
	return e
}

func spaceChars(w float64) string {
	switch {
	case w == -1:
		return "\u00a0"
	case w <= 0:
		return ""
	case w == 3.0/18:
		return "\u2006"
	case w == 4.0/18:
		return "\u2005"
	case w == 5.0/18:
		return "\u2004"
	case w == 1:
		return "\u200a\u2001"
	case w == 2:
		return "\u200a\u2001\u2001"
	}
	return " "
}

func symOf(e *mexp) (int, bool) {
	if e.kind == "sym" {
		return e.st, true
	}
	return 0, false
}

func isSpacedType(t int) bool {
	return t == symBin || t == symOp || t == symRel || t == symOpen || t == symPun
}

func addSpaceFor(t int, x *mexp) []*mexp {
	switch t {
	case symBin:
		return []*mexp{{kind: "space", width: 4.0 / 18}, x, {kind: "space", width: 4.0 / 18}}
	case symRel:
		return []*mexp{{kind: "space", width: 5.0 / 18}, x, {kind: "space", width: 5.0 / 18}}
	case symPun:
		return []*mexp{x, {kind: "space", width: 3.0 / 18}}
	}
	return []*mexp{x}
}

func addMathSpaces(xs []*mexp) []*mexp {
	var out []*mexp
	i := 0
	for i < len(xs) {
		x := xs[i]
		if t1, ok := symOf(x); ok {
			if i+1 < len(xs) && xs[i+1].kind == "space" {
				out = append(out, x, xs[i+1])
				i += 2
				continue
			}
			if !isSpacedType(t1) {
				out = append(out, x)
				i++
				continue
			}
			if i+1 < len(xs) {
				if t2, ok2 := symOf(xs[i+1]); ok2 && isSpacedType(t2) {
					out = append(out, x)
					out = append(out, addSpaceFor(t2, xs[i+1])...)
					i += 2
					continue
				}
			}
		}
		if i+1 < len(xs) {
			if t2, ok2 := symOf(xs[i+1]); ok2 {
				if !isSpacedType(t2) {
					out = append(out, x, xs[i+1])
					i += 2
					continue
				}
				out = append(out, x)
				out = append(out, addSpaceFor(t2, xs[i+1])...)
				i += 2
				continue
			}
		}
		if x.kind == "op" {
			out = append(out, x, &mexp{kind: "space", width: 3.0 / 18})
			i++
			continue
		}
		out = append(out, x)
		i++
	}
	return out
}

var doubleStruck = map[rune]rune{'C': 'ℂ', 'H': 'ℍ', 'N': 'ℕ', 'P': 'ℙ', 'Q': 'ℚ', 'R': 'ℝ', 'Z': 'ℤ'}
var scriptMap = map[rune]rune{'B': 'ℬ', 'E': 'ℰ', 'F': 'ℱ', 'H': 'ℋ', 'I': 'ℐ', 'L': 'ℒ', 'M': 'ℳ', 'R': 'ℛ', 'e': 'ℯ', 'g': 'ℊ', 'o': 'ℴ'}
var frakturMap = map[rune]rune{'C': 'ℭ', 'H': 'ℌ', 'I': 'ℑ', 'R': 'ℜ', 'Z': 'ℨ'}

func toUnicodeStyle(tt int, s string) string {
	var sb strings.Builder
	for _, c := range s {
		switch tt {
		case ttDouble:
			if r, ok := doubleStruck[c]; ok {
				sb.WriteRune(r)
			} else if c >= 'A' && c <= 'Z' {
				sb.WriteRune(0x1D538 + (c - 'A'))
			} else if c >= 'a' && c <= 'z' {
				sb.WriteRune(0x1D552 + (c - 'a'))
			} else if c >= '0' && c <= '9' {
				sb.WriteRune(0x1D7D8 + (c - '0'))
			} else {
				sb.WriteRune(c)
			}
		case ttScript:
			if r, ok := scriptMap[c]; ok {
				sb.WriteRune(r)
			} else if c >= 'A' && c <= 'Z' {
				sb.WriteRune(0x1D49C + (c - 'A'))
			} else if c >= 'a' && c <= 'z' {
				sb.WriteRune(0x1D4B6 + (c - 'a'))
			} else {
				sb.WriteRune(c)
			}
		case ttFraktur:
			if r, ok := frakturMap[c]; ok {
				sb.WriteRune(r)
			} else if c >= 'A' && c <= 'Z' {
				sb.WriteRune(0x1D504 + (c - 'A'))
			} else if c >= 'a' && c <= 'z' {
				sb.WriteRune(0x1D51E + (c - 'a'))
			} else {
				sb.WriteRune(c)
			}
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func renderMathStr(tt int, s string) []Inline {
	if s == "" {
		return nil
	}
	switch tt {
	case ttBold:
		return []Inline{&Strong{[]Inline{&Str{s}}}}
	case ttItalic:
		return []Inline{&Emph{[]Inline{&Str{s}}}}
	case ttMono:
		return []Inline{&Code{Attr{}, s}}
	case ttDouble, ttScript, ttFraktur:
		return []Inline{&Str{toUnicodeStyle(tt, s)}}
	case ttBoldItalic:
		return []Inline{&Strong{[]Inline{&Emph{[]Inline{&Str{s}}}}}}
	}
	return []Inline{&Str{s}}
}

func mexpsToInlines(tt int, xs []*mexp) ([]Inline, bool) {
	var out []Inline
	for _, x := range addMathSpaces(xs) {
		r, ok := mexpToInlines(tt, x)
		if !ok {
			return nil, false
		}
		out = append(out, r...)
	}
	return out, true
}

func mexpToInlines(tt int, e *mexp) ([]Inline, bool) {
	switch e.kind {
	case "num":
		return []Inline{&Str{e.s}}, true
	case "ident":
		if tt == ttDefault {
			return []Inline{&Emph{[]Inline{&Str{e.s}}}}, true
		}
		return renderMathStr(tt, e.s), true
	case "op":
		return renderMathStr(ttNormal, e.s), true
	case "sym":
		return []Inline{&Str{e.s}}, true
	case "limop":
		return mexpToInlines(tt, e.a)
	case "group":
		return mexpsToInlines(tt, e.items)
	case "flat":
		return nil, true
	case "styled":
		return mexpsToInlines(e.st, e.items)
	case "space":
		s := spaceChars(e.width)
		if s == "" {
			return nil, true
		}
		return []Inline{&Str{s}}, true
	case "text":
		return renderMathStr(e.st, e.s), true
	case "sub", "sup":
		base := unwrapLimop(e.a)
		x, ok := mexpToInlines(tt, base)
		if !ok {
			return nil, false
		}
		y, ok := mexpToInlines(tt, e.b)
		if !ok {
			return nil, false
		}
		if e.kind == "sub" {
			return append(x, &Subscript{y}), true
		}
		return append(x, &Superscript{y}), true
	case "subsup":
		x, ok := mexpToInlines(tt, unwrapLimop(e.a))
		if !ok {
			return nil, false
		}
		y, ok := mexpToInlines(tt, e.b)
		if !ok {
			return nil, false
		}
		z, ok := mexpToInlines(tt, e.c)
		if !ok {
			return nil, false
		}
		return append(x, &Subscript{y}, &Superscript{z}), true
	case "underover":
		return nil, false
	case "accent":
		a := e.a
		if a.kind == "group" && len(a.items) == 1 {
			a = a.items[0]
		}
		if a.kind == "ident" && len([]rune(a.s)) == 1 {
			return []Inline{&Emph{[]Inline{&Str{a.s + e.s}}}}, true
		}
		return nil, false
	}
	return nil, false
}

// texToInlines converts TeX math to inlines (texmath-like); nil if unsupported
func texToInlines(tex string, display bool) []Inline {
	p := &mathParser{s: []rune(tex)}
	items := p.parseList(0)
	if p.err {
		return nil
	}
	ils, ok := mexpsToInlines(ttDefault, items)
	if !ok {
		return nil
	}
	return ils
}

func mathWarn(tex string) {
	fmt.Fprintf(os.Stderr, "[WARNING] Could not convert TeX math %s, rendering as TeX\n", tex)
}

// texMathFallback returns inlines for math, with fallback to raw TeX
func texMathInlines(m *Math) []Inline {
	ils := texToInlines(m.Text, m.Type == DisplayMath)
	if ils != nil {
		return ils
	}
	mathWarn(m.Text)
	if m.Type == DisplayMath {
		return []Inline{&Str{"$$" + m.Text + "$$"}}
	}
	return []Inline{&Str{"$" + m.Text + "$"}}
}
